function erpRestoreKeyboard() {
    try { window.erpDesktop?.restoreKeyboard?.(); } catch (e) {}
    try {
        window.focus();
        const ae = document.activeElement;
        if (ae && ae !== document.body && typeof ae.focus === 'function') {
            try { ae.blur(); } catch (e) {}
            requestAnimationFrame(() => { try { ae.focus(); } catch (e) {} });
        }
    } catch (e) {}
}

(function erpNativeDialogGuard() {
    const nativeConfirm = window.confirm.bind(window);
    const nativeAlert = window.alert.bind(window);
    const nativePrompt = window.prompt.bind(window);
    window.confirm = function (msg) {
        try {
            if (window.erpDesktop?.confirmSync) {
                const ok = !!window.erpDesktop.confirmSync(String(msg ?? ''));
                erpRestoreKeyboard();
                return ok;
            }
        } catch (e) {}
        const r = nativeConfirm(msg);
        erpRestoreKeyboard();
        return r;
    };
    window.alert = function (msg) {
        try {
            if (window.erpDesktop?.alertSync) {
                window.erpDesktop.alertSync(String(msg ?? ''));
                erpRestoreKeyboard();
                return;
            }
        } catch (e) {}
        nativeAlert(msg);
        erpRestoreKeyboard();
    };
    window.prompt = function (msg, def) {
        const r = nativePrompt(msg, def);
        erpRestoreKeyboard();
        return r;
    };
})();

function erpAskConfirm(message) {
    return new Promise((resolve) => {
        try {
            const old = document.getElementById('erp-ask-overlay');
            if (old) old.remove();
        } catch (e) {}
        const ov = document.createElement('div');
        ov.id = 'erp-ask-overlay';
        ov.style.cssText = 'position:fixed;inset:0;z-index:2147483000;background:rgba(8,12,24,0.62);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box';
        const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        ov.innerHTML = `<div role="dialog" aria-modal="true" style="width:min(440px,100%);background:var(--surface,#12182a);border:1px solid var(--border,#2a3550);border-radius:16px;padding:22px;box-shadow:0 24px 60px rgba(0,0,0,.45)">
            <div style="font-size:13px;font-weight:650;color:var(--text,#e8ecf4);line-height:1.55;white-space:pre-wrap">${esc(message || 'Onaylıyor musunuz?')}</div>
            <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:18px">
                <button type="button" data-erp-ask="no" style="padding:8px 14px;border-radius:10px;border:1px solid var(--border,#2a3550);background:var(--surface2,#1a2236);color:var(--text2,#94a3b8);cursor:pointer;font-weight:600">Vazgeç</button>
                <button type="button" data-erp-ask="yes" style="padding:8px 14px;border-radius:10px;border:none;background:var(--accent,#6d71ff);color:#fff;cursor:pointer;font-weight:700">Onayla</button>
            </div>
        </div>`;
        const finish = (ok) => {
            try { document.removeEventListener('keydown', onKey, true); } catch (e) {}
            try { ov.remove(); } catch (e) {}
            resolve(!!ok);
            setTimeout(erpRestoreKeyboard, 0);
        };
        const onKey = (e) => {
            if (e.key === 'Escape') { e.preventDefault(); finish(false); }
            else if (e.key === 'Enter') { e.preventDefault(); finish(true); }
        };
        ov.addEventListener('click', (e) => {
            if (e.target === ov) { finish(false); return; }
            const btn = e.target.closest ? e.target.closest('[data-erp-ask]') : null;
            if (!btn) return;
            finish(btn.getAttribute('data-erp-ask') === 'yes');
        });
        document.addEventListener('keydown', onKey, true);
        document.body.appendChild(ov);
        try { ov.querySelector('[data-erp-ask="yes"]')?.focus(); } catch (e) {}
    });
}

function erpAskPrompt(message, defaultValue) {
    return new Promise((resolve) => {
        try {
            const old = document.getElementById('erp-prompt-overlay');
            if (old) old.remove();
        } catch (e) {}
        const ov = document.createElement('div');
        ov.id = 'erp-prompt-overlay';
        ov.style.cssText = 'position:fixed;inset:0;z-index:2147483001;background:rgba(8,12,24,0.62);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box';
        const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        ov.innerHTML = `<div role="dialog" aria-modal="true" style="width:min(440px,100%);background:var(--surface,#12182a);border:1px solid var(--border,#2a3550);border-radius:16px;padding:22px;box-shadow:0 24px 60px rgba(0,0,0,.45)">
            <div style="font-size:13px;font-weight:650;color:var(--text,#e8ecf4);line-height:1.55;white-space:pre-wrap;margin-bottom:12px">${esc(message || 'Değer girin:')}</div>
            <input type="text" id="erp-prompt-input" value="${esc(defaultValue || '')}" style="width:100%;box-sizing:border-box;padding:10px 12px;border-radius:10px;border:1px solid var(--border,#2a3550);background:var(--surface2,#1a2236);color:var(--text,#e8ecf4);font-size:13px;font-weight:600;text-transform:uppercase" />
            <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:18px">
                <button type="button" data-erp-prompt="cancel" style="padding:8px 14px;border-radius:10px;border:1px solid var(--border,#2a3550);background:var(--surface2,#1a2236);color:var(--text2,#94a3b8);cursor:pointer;font-weight:600">İptal</button>
                <button type="button" data-erp-prompt="ok" style="padding:8px 14px;border-radius:10px;border:none;background:var(--accent,#6d71ff);color:#fff;cursor:pointer;font-weight:700">Tamam</button>
            </div>
        </div>`;
        const finish = (val) => {
            try { document.removeEventListener('keydown', onKey, true); } catch (e) {}
            try { ov.remove(); } catch (e) {}
            resolve(val);
            setTimeout(erpRestoreKeyboard, 0);
        };
        const inp = () => ov.querySelector('#erp-prompt-input');
        const onKey = (e) => {
            if (e.key === 'Escape') { e.preventDefault(); finish(null); }
            else if (e.key === 'Enter') { e.preventDefault(); finish(inp()?.value ?? ''); }
        };
        ov.addEventListener('click', (e) => {
            if (e.target === ov) { finish(null); return; }
            const btn = e.target.closest ? e.target.closest('[data-erp-prompt]') : null;
            if (!btn) return;
            if (btn.getAttribute('data-erp-prompt') === 'cancel') finish(null);
            else finish(inp()?.value ?? '');
        });
        document.addEventListener('keydown', onKey, true);
        document.body.appendChild(ov);
        const el = inp();
        if (el) { el.focus(); el.select(); }
    });
}
window.erpAskPrompt = erpAskPrompt;

function erpPrintHtml(html, opts) {
    opts = opts || {};
    const title = String(opts.title || 'Yazdır');
    const w = window.open('', '_blank', 'width=900,height=1100');
    if (w) {
        try {
            w.document.open();
            w.document.write(html);
            w.document.close();
            if (opts.autoPrint !== false) {
                setTimeout(() => { try { w.focus(); w.print(); } catch (e) {} }, 250);
            }
            return true;
        } catch (e) {}
    }
    const iframe = document.createElement('iframe');
    iframe.setAttribute('title', title);
    iframe.style.cssText = 'position:fixed;left:-9999px;top:0;width:794px;height:1123px;border:0;visibility:hidden';
    document.body.appendChild(iframe);
    let printed = false;
    const done = () => {
        if (printed) return;
        printed = true;
        try {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();
        } catch (e) {
            if (typeof erpToast === 'function') erpToast('Yazdırma penceresi açılamadı.', 'error', 5000);
        }
        setTimeout(() => { try { iframe.remove(); } catch (e) {} }, 1500);
    };
    const doc = iframe.contentDocument || iframe.contentWindow.document;
    doc.open();
    doc.write(html);
    doc.close();
    if (iframe.contentDocument && iframe.contentDocument.readyState === 'complete') done();
    else iframe.onload = done;
    setTimeout(done, 400);
    return true;
}
window.erpPrintHtml = erpPrintHtml;

// ── OPTİMİZASYON: Debounce + Chart Instance Yönetimi ──
function yeniKartGiris() {
    if (archiveTab === 'IPLIK') setAppMode('IPLIK_KART_GIRIS');
    else if (archiveTab === 'MAMUL') setAppMode('MAMUL_KART_GIRIS');
    else setAppMode('KUMAS_KART_GIRIS');
}


const _chartInstances = {};
function safeChart(id, config) {
    if (_chartInstances[id]) {
        _chartInstances[id].destroy();
        delete _chartInstances[id];
    }
    const ctx = document.getElementById(id)?.getContext('2d');
    if (!ctx) return null;
    _chartInstances[id] = new Chart(ctx, config);
    return _chartInstances[id];
}

let _debounceTimers = {};
function debounce(key, fn, delay = 300) {
    clearTimeout(_debounceTimers[key]);
    _debounceTimers[key] = setTimeout(fn, delay);
}

let _erpDeferredUiRefresh = false;

function erpIsDetailModalOpen() {
    const modal = document.getElementById('detail-modal');
    return !!(modal && modal.style.display && modal.style.display !== 'none');
}

function erpIsUserEditingUi() {
    if (isSaveInProgress) return true;
    if (typeof editingId !== 'undefined' && editingId != null) return true;
    if (typeof uaSeciliSiparisId !== 'undefined' && uaSeciliSiparisId && typeof uaIsKdDirty === 'function' && uaIsKdDirty(uaSeciliSiparisId)) return true;
    const ae = document.activeElement;
    if (!ae) return false;
    const tag = String(ae.tagName || '').toUpperCase();
    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(tag)) return true;
    if (ae.isContentEditable) return true;
    return false;
}

function erpShouldDeferUiRefresh() {
    if (erpIsUserEditingUi() || erpIsDetailModalOpen()) return true;
    if (typeof dtIsUserEditingUi === 'function' && dtIsUserEditingUi()) return true;
    return false;
}

function erpScheduleDeferredUiRefresh() {
    _erpDeferredUiRefresh = true;
}

function erpFlushDeferredUiRefresh() {
    if (!_erpDeferredUiRefresh) return;
    _erpDeferredUiRefresh = false;
    if (erpShouldDeferUiRefresh()) {
        _erpDeferredUiRefresh = true;
        return;
    }
    erpRefreshCurrentScreen({ force: false });
}

function erpEkranSiparisListesiKullanir() {
    const m = typeof appMode === 'string' ? appMode : '';
    return ['DASHBOARD', 'PLANLAMA', 'SEVKIYAT', 'SIPARIS_LISTE', 'SIPARIS_KAPANAN', 'SIPARIS_GIRIS',
        'DOKUMA_TAKIP', 'DOKUMA_DEPO', 'KONFEKSIYON', 'KONFEKSIYON_KESIM', 'KONFEKSIYON_YIKAMA',
        'KONFEKSIYON_KALITE', 'KONFEKSIYON_PLANLAMA', 'FASON_TAKIP', 'RAPORLAR'].includes(m);
}

async function erpRefreshCurrentScreen(opts = {}) {
    const force = !!opts.force;
    const mode = appMode;
    if (!force && erpIsDetailModalOpen()) {
        erpScheduleDeferredUiRefresh();
        return;
    }
    try {
        if (mode === 'DASHBOARD') {
            if (typeof renderDashboard === 'function') renderDashboard();
            return;
        }
        if (mode === 'PLANLAMA') {
            if (typeof renderPlanlama === 'function') await renderPlanlama();
            return;
        }
        if (mode === 'YAPILACAKLAR') {
            if (typeof renderYapilacaklar === 'function') await renderYapilacaklar();
            return;
        }
        if (mode === 'SEVKIYAT') {
            if (!force && erpShouldDeferUiRefresh()) {
                erpScheduleDeferredUiRefresh();
                return;
            }
            if (document.getElementById('sevkiyat-out')) {
                if (typeof sevkiyatHafifYenile === 'function') await sevkiyatHafifYenile();
                else if (typeof sevkiyatRender === 'function') sevkiyatRender();
                return;
            }
            if (typeof renderSevkiyat === 'function') await renderSevkiyat();
            return;
        }
        if (mode === 'DOKUMA_TAKIP') {
            if (!force && erpShouldDeferUiRefresh()) {
                erpScheduleDeferredUiRefresh();
                return;
            }
            if (typeof renderDokumaTakip === 'function') await renderDokumaTakip();
            return;
        }
        if (mode === 'DOKUMA_DEPO') {
            if (typeof renderDokumaDepo === 'function') renderDokumaDepo();
            return;
        }
        if (mode === 'TEZGAH_PLANLAMA') {
            if (typeof tpCanliYenile === 'function') await tpCanliYenile({ force });
            else if (typeof renderTezgahPlanlama === 'function') await renderTezgahPlanlama();
            return;
        }
        if (mode === 'DOKUMA_SEVK_GECMIS') {
            if (typeof renderDokumaSevkGecmisi === 'function') renderDokumaSevkGecmisi();
            return;
        }
        if (mode === 'MUHASEBE_FIS') {
            if (!force && erpIsUserEditingUi()) {
                erpScheduleDeferredUiRefresh();
                return;
            }
            if (typeof renderMuhasebeFisListe === 'function') await renderMuhasebeFisListe({ force: !!force });
            return;
        }
        if (mode === 'STOK_SAYIM') {
            if (!force && typeof erpShouldDeferUiRefresh === 'function' && erpShouldDeferUiRefresh()) {
                if (typeof erpScheduleDeferredUiRefresh === 'function') erpScheduleDeferredUiRefresh();
                return;
            }
            if (!force && typeof sayimOturumAktifMi === 'function' && sayimOturumAktifMi()) {
                return;
            }
            if (typeof renderStokSayim === 'function') renderStokSayim();
            return;
        }
        if (mode === 'KONFEKSIYON' || mode === 'KONFEKSIYON_KESIM' || mode === 'KONFEKSIYON_YIKAMA' || mode === 'KONFEKSIYON_KALITE') {
            if (!force && typeof konfIsUserEditingForm === 'function' && konfIsUserEditingForm()) return;
            if (typeof renderKonfeksiyon === 'function') renderKonfeksiyon();
            return;
        }
        if (mode === 'RAPORLAR' || mode === 'RAPOR') {
            if (typeof renderRaporlar === 'function') renderRaporlar();
            return;
        }
        if (typeof loadData === 'function' && ['IPLIK', 'KUMAS', 'MAMUL_DEPO', 'SIPARIS_LISTE', 'SIPARIS_KAPANAN', 'KART_LISTE', 'DEPO_HAREKET_LISTE'].includes(mode)) {
            if (!force && erpIsUserEditingUi()) {
                erpScheduleDeferredUiRefresh();
                return;
            }
            loadData();
        }
    } catch (e) {
        console.warn('erpRefreshCurrentScreen:', e?.message || e);
    }
}

document.addEventListener('visibilitychange', () => {
    if (!document.hidden) erpFlushDeferredUiRefresh();
});

async function erpSuperYenile() {
    const btn = document.getElementById('erp-super-yenile-btn');
    if (btn) btn.classList.add('is-busy');
    try {
        if (typeof syncAllData === 'function') {
            await syncAllData(true, { skipScreenRefresh: true });
        }
        if (typeof erpRefreshCurrentScreen === 'function') {
            await erpRefreshCurrentScreen({ force: true });
        }
    } catch (e) {
        const msg = e?.message || String(e);
        if (typeof showToast === 'function') showToast('Yenileme hatası: ' + msg, 'error');
        else if (typeof erpToast === 'function') erpToast('Yenileme hatası: ' + msg, 'error');
    } finally {
        if (btn) btn.classList.remove('is-busy');
    }
}
window.erpSuperYenile = erpSuperYenile;

// --- SUPABASE — değerler erp-config.js (window.__ERP_SUPABASE) içindedir ---
let SB_URL = '';
let SB_KEY = '';
let sb = null;
const ERP_QUERY_TIMEOUT_MS = window.ERP_MOBIL_LITE ? 25000 : 15000; /* mobil: telefon şebekesi daha yavaş */


async function erpWithTimeout(promise, label = 'Sorgu', timeoutMs = ERP_QUERY_TIMEOUT_MS) {
    let timeoutId = null;
    const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(`${label} zaman aşımına uğradı (${timeoutMs}ms)`)), timeoutMs);
    });
    try {
        return await Promise.race([promise, timeoutPromise]);
    } finally {
        if (timeoutId) clearTimeout(timeoutId);
    }
}

/* ── Fotoğraf lazy yükleme ─────────────────────────────────────────────────
   Boot'ta fotoğraf çekilmez. Kart / detay açılınca bu fonksiyon çağrılır,
   Supabase'den o tek kaydın fotoğrafını alır ve modal'ı günceller.         */
function kartFotografNormalizeAday(v) {
    if (v == null || v === '') return '';
    if (Array.isArray(v)) return kartFotografNormalizeAday(v[0]);
    if (typeof v === 'object') return kartFotografNormalizeAday(v.src || v.url || v.fotograf || v.resim_url);
    const s = String(v).trim();
    if (!s || s === 'null' || s === 'undefined' || s === '[object Object]') return '';
    return s;
}

function kartFotografAdayToSrc(v) {
    const s = kartFotografNormalizeAday(v);
    if (!s) return '';
    if (/^(data:image\/|https?:\/\/|blob:|\/\/)/i.test(s)) return s;
    if (s.length > 80 && /^[A-Za-z0-9+/=\s]+$/.test(s.slice(0, 120))) {
        return 'data:image/jpeg;base64,' + s.replace(/\s/g, '');
    }
    return '';
}

function kartFotografListesi(rec) {
    if (!rec) return [];
    const out = [];
    const seen = new Set();
    const ekle = (v) => {
        if (v == null || v === '') return;
        if (Array.isArray(v)) {
            v.forEach(ekle);
            return;
        }
        if (typeof v === 'string') {
            const t = v.trim();
            if ((t.startsWith('[') || t.startsWith('{')) && t.length < 500000) {
                try { ekle(JSON.parse(t)); return; } catch (_) {}
            }
        }
        const s = kartFotografAdayToSrc(v);
        if (!s || seen.has(s)) return;
        seen.add(s);
        out.push(s);
    };
    ekle(rec.fotograf);
    ekle(rec.fotograf_url);
    ekle(rec.resim_url);
    ekle(rec.foto);
    ekle(rec.image);
    if (typeof kumasMetaAl === 'function') {
        const meta = kumasMetaAl(rec);
        if (meta) {
            ekle(meta.fotograf);
            ekle(meta.fotograf_url);
            ekle(meta.resim_url);
        }
    }
    return out;
}
window.kartFotografListesi = kartFotografListesi;

function kartFotografSrc(rec) {
    const list = kartFotografListesi(rec);
    return list[0] || '';
}
window.kartFotografSrc = kartFotografSrc;

function kartFotografSheetHtml(record) {
    const list = kartFotografListesi(record);
    const attr = (x) => String(x || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    if (list.length) {
        const imgs = list.map((src, i) =>
            `<button type="button" class="mamul-talimat-sheet__foto-btn" onclick="kartFotoBuyut(this.querySelector('img').src)" title="Büyüt">
                <img src="${attr(src)}" alt="Kumaş örneği ${i + 1}">
            </button>`
        ).join('');
        return `<div class="mamul-talimat-sheet__foto">
            <div class="mamul-talimat-sheet__foto-baslik">KUMAŞ ÖRNEĞİ</div>
            ${imgs}
            <div class="mamul-talimat-sheet__foto-ipucu">Tıklayınca büyüt</div>
        </div>`;
    }
    return `<div class="mamul-talimat-sheet__foto mamul-talimat-sheet__foto--bos">
        <div class="mamul-talimat-sheet__foto-baslik">KUMAŞ ÖRNEĞİ</div>
        <div class="mamul-talimat-sheet__foto-yok">${record?.id ? 'Fotoğraf yükleniyor…' : 'Fotoğraf yok'}</div>
    </div>`;
}
window.kartFotografSheetHtml = kartFotografSheetHtml;

function kartFotoLightboxEnsure() {
    if (document.getElementById('kart-foto-lightbox')) return;
    const lb = document.createElement('div');
    lb.id = 'kart-foto-lightbox';
    lb.setAttribute('role', 'dialog');
    lb.setAttribute('aria-modal', 'true');
    lb.onclick = (ev) => { if (ev.target === lb) kartFotoKapat(); };
    lb.innerHTML = '<button type="button" id="kart-foto-lightbox-kapat" onclick="kartFotoKapat()" aria-label="Kapat">&times;</button><img src="" alt="Kumaş örneği">';
    document.body.appendChild(lb);
    if (!window.__kartFotoLbEsc) {
        window.__kartFotoLbEsc = true;
        document.addEventListener('keydown', (e) => { if (e.key === 'Escape') kartFotoKapat(); });
    }
}
window.kartFotoBuyut = function (src) {
    const s = String(src || '').trim();
    if (!s) return;
    kartFotoLightboxEnsure();
    const lb = document.getElementById('kart-foto-lightbox');
    const img = lb && lb.querySelector('img');
    if (!lb || !img) return;
    img.src = s;
    lb.classList.add('is-open');
};
window.kartFotoKapat = function () {
    const lb = document.getElementById('kart-foto-lightbox');
    if (!lb) return;
    lb.classList.remove('is-open');
    const img = lb.querySelector('img');
    if (img) img.removeAttribute('src');
};

async function erpLazyLoadFotograf(kayit, idx, bodyEl) {
    if (!kayit || !kayit.id) return;
    if (kartFotografSrc(kayit)) return;
    const uygula = (data) => {
        if (!data) return '';
        if (data.fotograf) kayit.fotograf = data.fotograf;
        if (data.fotograf_url) kayit.fotograf_url = data.fotograf_url;
        if (data.resim_url) kayit.resim_url = data.resim_url;
        if (data.islem_gecmisi) kayit.islem_gecmisi = data.islem_gecmisi;
        const cached = (dataCache?.kumas_kutuphanesi || []).find(r => String(r.id) === String(kayit.id));
        if (cached) {
            if (data.fotograf) cached.fotograf = data.fotograf;
            if (data.fotograf_url) cached.fotograf_url = data.fotograf_url;
            if (data.resim_url) cached.resim_url = data.resim_url;
            if (data.islem_gecmisi) cached.islem_gecmisi = data.islem_gecmisi;
        }
        return kartFotografSrc({ ...kayit, ...data });
    };
    const modalYenile = () => {
        const modal = document.getElementById('detail-modal');
        if (!modal || modal.style.display === 'none') return;
        if (typeof selectedIndex !== 'undefined' && selectedIndex !== idx) return;
        if (!bodyEl || !bodyEl.closest('#detail-modal')) return;
        if (bodyEl.classList.contains('modal-body--kumas') && typeof renderKumasKartDetayModalHtml === 'function') {
            bodyEl.innerHTML = renderKumasKartDetayModalHtml(kayit, idx);
            return;
        }
        if (bodyEl.classList.contains('modal-body--mamul') && typeof renderMamulKartDetayModalHtml === 'function') {
            bodyEl.innerHTML = renderMamulKartDetayModalHtml(kayit, idx);
            return;
        }
        const src = kartFotografSrc(kayit);
        if (!src) return;
        const fotoDiv = document.createElement('div');
        fotoDiv.style.cssText = 'grid-column:1/-1;margin-bottom:4px';
        const attr = String(src).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
        fotoDiv.innerHTML = `<img src="${attr}" style="width:100%;max-height:min(42vh,320px);height:auto;object-fit:contain;border-radius:12px;border:1px solid var(--border);background:var(--surface2)">`;
        bodyEl.insertBefore(fotoDiv, bodyEl.firstChild);
    };
    try {
        let data = null;
        let error = null;
        const cek = async (cols) => {
            const q = sb.from('kumas_kutuphanesi').select(cols).eq('id', kayit.id).maybeSingle();
            return (typeof erpWithTimeout === 'function')
                ? erpWithTimeout(q, 'kart-foto', 16000)
                : q;
        };
        try {
            const res = await cek('fotograf,fotograf_url,resim_url,islem_gecmisi');
            data = res?.data || null;
            error = res?.error || null;
        } catch (e) {
            error = e;
        }
        if (error || !kartFotografSrc({ ...kayit, ...(data || {}) })) {
            try {
                const res2 = await cek('fotograf_url,resim_url,islem_gecmisi');
                if (res2?.data) data = { ...(data || {}), ...res2.data };
                error = res2?.error || null;
            } catch (e2) {
                error = e2;
            }
        }
        const src = uygula(data);
        if (src) {
            modalYenile();
            return;
        }
        const slot = bodyEl?.querySelector?.('.mamul-talimat-sheet__foto-yok');
        if (slot) slot.textContent = error ? 'Fotoğraf yüklenemedi' : 'Fotoğraf yok';
    } catch (e) {
        console.warn('erpLazyLoadFotograf', e?.message || e);
        const slot = bodyEl?.querySelector?.('.mamul-talimat-sheet__foto-yok');
        if (slot) slot.textContent = 'Fotoğraf yüklenemedi';
    }
}
window.erpLazyLoadFotograf = erpLazyLoadFotograf;

function erpIsSupabaseBillingError(msg) {
    const m = String(msg || '').toLowerCase();
    return m.includes('402') || m.includes('payment required') || m.includes('quota') || m.includes('exceed') || m.includes('paused') || m.includes('suspended');
}

function erpSyncFriendlyError(msg) {
    const m = String(msg || '').toLowerCase();
    if (m.includes('failed to fetch') || m.includes('networkerror') || m.includes('load failed') || m.includes('network request failed')) {
        return 'İnternet veya Supabase bağlantısı kurulamadı — bağlantınızı kontrol edip tekrar deneyin';
    }
    if (m.includes('zaman aşımı') || m.includes('timeout')) {
        return 'Sunucu yanıt vermedi (zaman aşımı) — tekrar deneyin';
    }
    return String(msg || 'Bilinmeyen hata');
}

function erpShowSupabaseServiceError(title, detail) {
    if (document.getElementById('erp-supabase-service-error')) return;
    const ov = document.createElement('div');
    ov.id = 'erp-supabase-service-error';
    ov.setAttribute('role', 'alert');
    ov.style.cssText = 'position:fixed;inset:0;z-index:2147483646;background:rgba(12,18,34,0.96);color:#e2e8f0;padding:clamp(1rem,4vw,2rem);font-family:system-ui,sans-serif;display:flex;align-items:center;justify-content:center;box-sizing:border-box';
    ov.innerHTML = `<div style="max-width:560px;text-align:center;line-height:1.65">
        <h1 style="font-size:1.2rem;margin:0 0 0.75rem;color:#fb7185">${title || 'Veritabanı bağlantısı kurulamadı'}</h1>
        <p style="margin:0 0 1rem;color:#94a3b8;font-size:0.92rem">${detail || 'Supabase sunucusu yanıt vermiyor. İnternet ve proje durumunu kontrol edin.'}</p>
        <p style="margin:0;color:#64748b;font-size:0.82rem">Yönetici: <a href="https://supabase.com/dashboard" style="color:#93c5fd" target="_blank" rel="noopener">supabase.com/dashboard</a> → Proje → Billing / Usage</p>
    </div>`;
    if (document.body) document.body.appendChild(ov);
}

async function erpCheckSupabaseHealth() {
    if (!sb?.from) return { ok: false, err: 'Supabase istemcisi yok' };
    try {
        const { error } = await erpWithTimeout(sb.from('siparisler').select('id').limit(1), 'sağlık', 12000);
        if (error) {
            const msg = error.message || String(error);
            if (erpIsSupabaseBillingError(msg) || String(error.code || '') === '402') {
                return { ok: false, billing: true, err: msg };
            }
            return { ok: false, err: msg };
        }
        return { ok: true };
    } catch (e) {
        const msg = e?.message || String(e);
        if (erpIsSupabaseBillingError(msg)) return { ok: false, billing: true, err: msg };
        return { ok: false, err: msg };
    }
}

function erpGetSupabaseConfig() {
    const fromConfig = window.__ERP_SUPABASE;
    if (fromConfig && fromConfig.url && fromConfig.anonKey) return fromConfig;
    const fromBuild = window.__ERP_BUILD && window.__ERP_BUILD.supabase;
    if (fromBuild && fromBuild.url && fromBuild.anonKey) return fromBuild;
    return null;
}

function erpInitSupabaseClient() {
    const c = erpGetSupabaseConfig();
    if (!c || !c.url || !c.anonKey) return false;
    SB_URL = String(c.url).trim();
    SB_KEY = String(c.anonKey).trim();
    if (SB_URL.includes('YOUR_PROJECT') || SB_KEY.includes('YOUR_SUPABASE')) return false;
    try {
        const opts = (typeof erpSupabaseClientOptions === 'function') ? erpSupabaseClientOptions() : {};
        sb = supabase.createClient(SB_URL, SB_KEY, opts);
        return true;
    } catch (e) {
        console.error('Supabase client oluşturulamadı:', e);
        return false;
    }
}

function erpShowSupabaseConfigError() {
    if (document.getElementById('erp-supabase-config-error')) return;
    const ov = document.createElement('div');
    ov.id = 'erp-supabase-config-error';
    ov.setAttribute('role', 'alert');
    ov.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:#0c1222;color:#e2e8f0;padding:clamp(1rem,4vw,2rem);font-family:system-ui,sans-serif;display:flex;align-items:center;justify-content:center;box-sizing:border-box';
    const isDesktop = !!(window.erpDesktop && window.erpDesktop.isElectron);
    const detail = isDesktop
        ? 'Masaüstü kurulumunda veritabanı ayarı eksik. IT biriminden güncel EXE kurulumunu isteyin veya uygulamayı yeniden kurun.'
        : 'Bu site <strong>erp-config.js</strong> dosyası ile Supabase’e bağlanır. <code style="background:#1e293b;padding:2px 8px;border-radius:6px;font-size:0.85em">erp-config.sample.js</code> dosyasını kopyalayıp <strong>erp-config.js</strong> adıyla kaydedin; Project URL ve anon (public) anahtarı girin. Statik hosting’e dosyayı birlikte yükleyin.';
    ov.innerHTML = `<div style="max-width:520px;text-align:center;line-height:1.65"><h1 style="font-size:1.15rem;margin:0 0 0.75rem">Yapılandırma eksik</h1><p style="margin:0;color:#94a3b8;font-size:0.9rem">${detail}</p></div>`;
    if (document.body) document.body.appendChild(ov);
}

function erpIsSupabaseReady() {
    if (sb) return true;
    erpShowSupabaseConfigError();
    return false;
}

erpInitSupabaseClient();

