/** Sipariş düzenleme formunu kayıtla doldurur (kalem + foto) */
function siparisFormEditDoldur(kayit) {
    if (!kayit) return;
    siparisFormKayitDurum = kayit.durum || 'BEKLEMEDE';
    const snoEl = document.getElementById('val-sno');
    const firmaEl = document.getElementById('val-firma');
    const starihEl = document.getElementById('val-starih');
    const ttarihEl = document.getElementById('val-ttarih');
    if (snoEl) snoEl.value = kayit.sno || '';
    if (firmaEl) firmaEl.value = kayit.firma || '';
    if (document.getElementById('val-siparis-grubu')) document.getElementById('val-siparis-grubu').value = kayit.siparis_grubu || 'EV_TEKSTILI';
    if (starihEl) starihEl.value = kayit.starih || '';
    if (ttarihEl) ttarihEl.value = kayit.ttarih || '';
    if (document.getElementById('val-notlar')) document.getElementById('val-notlar').value = kayit.notlar || '';
    const container = document.getElementById('siparis-kalemleri-container');
    if (container) {
        container.innerHTML = '';
        siparisKalemCount = 0;
        let kalemler = [];
        try { kalemler = typeof kayit.cins === 'string' ? JSON.parse(kayit.cins) : (kayit.cins || []); } catch (e) { kalemler = []; }
        if (!Array.isArray(kalemler)) kalemler = [];
        if (kalemler.length) {
            kalemler.forEach(k => addSiparisKalem({
                kod: k.kod, desen: k.desen, grup: k.grup, ad: k.ad, renk: k.renk,
                rkod: k.rkod, ebat: k.ebat, miktar: k.miktar, birim: k.birim || 'ADET'
            }));
        } else {
            addSiparisKalem();
        }
    }
    siparisFotograflar = siparisFotografListesiAl(kayit);
    if (!siparisFotograflar.length && kayit.id) {
        const ls = siparisFotoLsOku(kayit.id);
        if (ls.length) siparisFotograflar = ls;
    }
    siparisFotoRenderList();
    // Mamül karttan seçilmiş kalemleri güncel kart bilgisiyle hizala
    if (typeof siparisFormKalemleriniMamulKarttanYenile === 'function') {
        try { siparisFormKalemleriniMamulKarttanYenile({ silent: true }); } catch (e) {}
    }
    updateSiparisPreview();
    syncSiparisNoInput();
    siparisFormSiparisDurumUiSync();
}

/** Liste hafif senkron foto kolonunu getirmez — düzenleme / detayda lazy yükle */
async function siparisKayitFotolarLazyYukle(siparisId) {
    const sid = String(siparisId ?? '');
    if (!sid || !sb) return null;
    const idx = (dataCache.siparisler || []).findIndex(s => String(s.id) === sid);
    const kayit = idx >= 0 ? dataCache.siparisler[idx] : null;
    if (kayit && siparisFotograflarFromRaw(siparisKayitFotoAlani(kayit)).length) return kayit;
    const ls = siparisFotoLsOku(sid);
    if (ls.length) {
        const patchLs = { id: siparisId, [SIPARIS_FOTO_DB_COL]: ls };
        if (idx >= 0) dataCache.siparisler[idx] = { ...dataCache.siparisler[idx], ...patchLs };
        return { ...(kayit || {}), ...patchLs };
    }
    try {
        let data = null;
        let error = null;
        ({ data, error } = await sb.from('siparisler').select(SIPARIS_FOTO_DB_COL + ',islem_gecmisi').eq('id', siparisId).maybeSingle());
        if (error) {
            ({ data, error } = await sb.from('siparisler').select('fotograf,islem_gecmisi').eq('id', siparisId).maybeSingle());
        }
        if (error || !data) return kayit;
        const patch = { id: siparisId, ...data };
        if (idx >= 0) dataCache.siparisler[idx] = { ...dataCache.siparisler[idx], ...patch };
        return (dataCache.siparisler || []).find(s => String(s.id) === sid) || { ...(kayit || {}), ...patch };
    } catch (e) {
        return kayit;
    }
}

let isSaveInProgress = false;
/** Depo komuta: IPLIK | KUMAS | MAMUL_DEPO — sadece appMode === DEPO_HAREKET iken */
let depoKomutaHedef = null;
/** Sevkiyat merkezi: tek çıkış ekranında hangi stok grubu açık */
let sevkiyatMerkezGrup = null;
/** Depo hareket defteri: HEPSİ | IPLIK | KUMAS | MAMUL_DEPO | DOKUMA_TAKIP */
let depoHareketDefterGrup = 'HEPSİ';
/** Depo hareket defteri filtreleri */
let depoHareketDefterFiltre = { q: '', tip: 'HEPSİ', bas: '', bit: '' };
/** Açılır-kapanır bölümler: iplik / kumas / mamul / dokuma */
let depoHareketDefterBolumAcik = {};
/** Bölüm başına ekranda gösterilen hareket sayısı (10'ar artar) */
let depoHareketDefterBolumLimit = {};
const DEPO_DEFTER_SAYFA_ADIM = 10;
/** Sihirbaz: TIP = giriş/çıkış seç; GRUP = iplik/kumaş/mamül seç */
let depoKomutaAsama = 'TIP';

function depoBirimFromNotlar(s) {
    const m = String(s || '').match(/\[BİRİM:(KG|MT|AD)\]/i);
    return m ? m[1].toUpperCase() : 'KG';
}
/** Sadece görüntüleme için — TÜM [ANAHTAR:değer] etiketlerini temizler (SEVK_* dahil).
 *  Yazma akışında (depoNotlarWithBirim) KULLANILMAZ — kullanılırsa SEVK_* etiketleri
 *  BİRİM yeniden eklenirken silinir. Yazma tarafı depoNotlarStripBirim kullanır. */
function depoNotlarStripMeta(s) {
    let t = String(s || '');
    // CEKI etiketi iç içe köşeli parantez (JSON dizisi) içerebilir — önce onu ayıkla
    t = t.replace(/\s*\[CEKI:\[[\s\S]*?\]\]\s*\n?/gi, '');
    // Kalan basit [ANAHTAR:değer] etiketlerini (değer köşeli parantez içermez) temizle
    t = t.replace(/\s*\[[A-ZÇĞİÖŞÜ_]+:[^\[\]]*\]\s*\n?/gi, '');
    return t.replace(/\n{2,}/g, '\n').trim();
}
/** Yalnızca [BİRİM:...] etiketini temizler — depoNotlarWithBirim'in yeniden yazması içindir,
 *  diğer etiketleri (TESLIM_ALAN, SEVK_*, CEKI vb.) korur. */
function depoNotlarStripBirim(s) {
    return String(s || '').replace(/\s*\[BİRİM:(KG|MT|AD)\]\s*\n?/gi, '').trim();
}
function depoNotlarWithBirim(birim, notlar) {
    const b = (birim || 'KG').toUpperCase();
    const raw = depoNotlarStripBirim(notlar);
    return `[BİRİM:${b}]\n` + raw;
}
function depoNotlarTeslimOku(s) {
    const m = String(s || '').match(/\[TESLİM:([^\]]+)\]/i);
    return m ? m[1].trim() : '';
}
function depoNotlarWithTeslimDetay(notlar, teslim) {
    let out = String(notlar || '');
    const t = teslim || (typeof muhasebeFisTeslimFormOku === 'function' ? muhasebeFisTeslimFormOku() : null);
    if (!t) return out;
    const add = (k, v) => {
        const val = String(v || '').trim();
        if (val) out += (out && !out.endsWith('\n') ? '\n' : '') + `[${k}:${val}]`;
    };
    add('TESLIM_ALAN', t.teslim_alan);
    add('TESLIM_TEL', t.teslim_tel);
    add('PLAKA', t.plaka);
    add('SOFOR', t.sofor);
    add('TESLIM_ADRES', t.teslim_adres);
    return out;
}
function depoStokNetBakiyeHesapla(table, stokKodu, grup, excludeId, extra) {
    const kod = String(stokKodu || '').trim();
    if (!kod) return { kg: 0, mt: 0, adet: 0 };
    extra = extra || {};
    let rows;
    if (table === 'iplik_stok' && typeof iplikDepoStokHareketleriHazirla === 'function') {
        rows = iplikDepoStokHareketleriHazirla(dataCache.iplik_stok || [])
            .filter(r => String(r.stok_kodu || '').trim() === kod);
        if (excludeId) rows = rows.filter(r => r._fromKart || String(r.id) !== String(excludeId));
        const lot = String(extra.lot_no || '').trim();
        if (lot) {
            const lotU = lot.toLocaleLowerCase('tr-TR');
            rows = rows.filter(r => String(r.lot_no || 'LOTSUZ').trim().toLocaleLowerCase('tr-TR') === lotU);
        }
        const marka = String(extra.marka || '').trim();
        if (marka) {
            const markaU = marka.toLocaleLowerCase('tr-TR');
            rows = rows.filter(r => String(r.marka || 'GENEL').trim().toLocaleLowerCase('tr-TR') === markaU);
        }
    } else {
        rows = (dataCache[table] || []).filter(r => String(r.stok_kodu || '').trim() === kod);
        if (table === 'kumas_stok' && grup === 'MAMUL_DEPO') rows = rows.filter(kumasStokHareketiMamulDepoMu);
        else if (table === 'kumas_stok' && grup === 'KUMAS') rows = rows.filter(kumasStokHareketiKumasDepoMu);
        /* Siparişe bağlı hareketler (kumas_stok.siparis_id) genel Simteks bakiyesine karışmasın —
           o mal zaten belirli bir müşteri siparişine ayrılmış / o siparişten sevk edilmiş demektir. */
        if (table === 'kumas_stok') rows = rows.filter(r => r.siparis_id == null || r.siparis_id === '');
        if (excludeId) rows = rows.filter(r => String(r.id) !== String(excludeId));
    }
    return rows.reduce((acc, r) => {
        acc.kg += parseFloat(r.miktar_kg) || 0;
        acc.mt += parseFloat(r.miktar_mt) || 0;
        acc.adet += parseInt(r.cuval_sayisi || 0, 10) || 0;
        return acc;
    }, { kg: 0, mt: 0, adet: 0 });
}
function depoStokCikisBakiyeKontrol(grup, stokKodu, p, excludeId) {
    const g = String(grup || '').toUpperCase();
    /* Kumaş çıkışı stok üstü gönderilebilir — bakiye eksiye iner */
    if (g === 'KUMAS' || g === 'HAM_KUMAS' || g === 'MAMUL_KUMAS') return null;
    if (!grup || !stokKodu || !p) return null;
    const table = grup === 'IPLIK' ? 'iplik_stok' : 'kumas_stok';
    const extra = g === 'IPLIK' ? { lot_no: p.lot_no, marka: p.marka } : {};
    const bakiye = depoStokNetBakiyeHesapla(table, stokKodu, grup, excludeId, extra);
    const istenenKg = Math.abs(parseFloat(p.miktar_kg) || 0);
    const istenenMt = Math.abs(parseFloat(p.miktar_mt) || 0);
    const istenenAd = Math.abs(parseInt(p.cuval_sayisi || 0, 10) || 0);
    if (istenenKg > 0 && bakiye.kg + 1e-6 < istenenKg) {
        return `${stokKodu}: kg yetersiz (mevcut ${bakiye.kg.toLocaleString('tr-TR', { maximumFractionDigits: 2 })}, istenen ${istenenKg.toLocaleString('tr-TR', { maximumFractionDigits: 2 })})`;
    }
    if (istenenMt > 0 && bakiye.mt + 1e-6 < istenenMt) {
        return `${stokKodu}: mt yetersiz (mevcut ${bakiye.mt.toLocaleString('tr-TR', { maximumFractionDigits: 2 })}, istenen ${istenenMt.toLocaleString('tr-TR', { maximumFractionDigits: 2 })})`;
    }
    if (istenenAd > 0 && bakiye.adet + 1e-6 < istenenAd) {
        return `${stokKodu}: adet yetersiz (mevcut ${bakiye.adet}, istenen ${istenenAd})`;
    }
    return null;
}
function depoMamulStokKartiDogrula(stokKodu) {
    const kod = String(stokKodu || '').trim();
    if (!kod || kod === 'KODSUZ') return 'Stok kodu zorunludur — mamül kartından seçim yapın.';
    const ku = kod.toUpperCase();
    let kart = (dataCache.kumas_kutuphanesi || []).find(k =>
        String(k.desen_kodu || '').trim().toUpperCase() === ku
        || String(k.stok_kodu || '').trim().toUpperCase() === ku
    );
    if (!kart && typeof mamulKartBul === 'function') kart = mamulKartBul(kod);
    if (!kart) return `"${kod}" için mamül stok kartı yok. Önce mamül kartı oluşturun.`;
    if (!kumasKutuphanesiKartiMamulMu(kart)) return `"${kod}" mamül kartı değil — doğru kart türünü kullanın.`;
    return null;
}
function mamulHareketTipi(h) {
    const tip = String(h?.islem_turu || '').toUpperCase();
    if (tip === 'ÇIKIŞ' || tip === 'CIKIS') return 'ÇIKIŞ';
    if (tip === 'GİRİŞ' || tip === 'GIRIS') return 'GİRİŞ';
    const kg = parseFloat(h?.miktar_kg) || 0;
    const mt = parseFloat(h?.miktar_mt) || 0;
    const ad = parseInt(h?.cuval_sayisi || 0, 10) || 0;
    if (kg < 0 || mt < 0 || ad < 0) return 'ÇIKIŞ';
    return 'GİRİŞ';
}
// mamulDepoAdetBakiye … mamulDepoFormSabitle → assets/mamul-depo-toplu.js
function mamulHareketMiktarMetni(h, mamulCtx) {
    const ad = Math.abs(parseInt(h?.cuval_sayisi || 0, 10) || 0);
    if (mamulCtx !== false && (mamulCtx || depoBirimFromNotlar(h?.notlar) === 'AD') && ad > 0) {
        return `${ad} ad`;
    }
    const birim = depoBirimFromNotlar(h?.notlar);
    const kg = Math.abs(parseFloat(h?.miktar_kg) || 0);
    const mt = Math.abs(parseFloat(h?.miktar_mt) || 0);
    if (birim === 'AD' && ad > 0) return `${ad} ad`;
    if (birim === 'MT' && mt > 0) return `${mt.toLocaleString('tr-TR', { maximumFractionDigits: 2 })} mt`;
    if (kg > 0) return `${kg.toLocaleString('tr-TR', { maximumFractionDigits: 2 })} kg`;
    if (mt > 0) return `${mt.toLocaleString('tr-TR', { maximumFractionDigits: 2 })} mt`;
    if (ad > 0) return `${ad} ad`;
    return '—';
}
/** Depo hareket defterinde gösterilecek satırlar */
function stokKaydiDepoKomutaMerkeziMi(row) {
    const kb = String(row?.kaynak_birim || '').toUpperCase();
    return kb.startsWith('DEPO_HAREKET_') || kb === 'DOKUMA_TAKIP';
}
function depoKomutaKanalFromKaynak(kaynakBirim) {
    const kb = String(kaynakBirim || '').toUpperCase();
    if (kb === 'DEPO_HAREKET_IPLIK' || kb.startsWith('DEPO_HAREKET_IPLIK') || kb === 'IPLIK' || kb === 'IPLIK_KART_STOK') {
        return { kod: 'IPLIK', etiket: 'İplik' };
    }
    if (kb === 'DEPO_HAREKET_MAMUL_DEPO' || kb === 'MAMUL_DEPO') return { kod: 'MAMUL_DEPO', etiket: 'Mamül' };
    if (kb === 'DEPO_HAREKET_KUMAS' || kb === 'DEPO_HAREKET_KUMAS_TOPLU' || kb === 'DEPO_HAREKET_HAM_KUMAS' || kb === 'DEPO_HAREKET_MAMUL_KUMAS' || kb.startsWith('DEPO_HAREKET_KUMAS') || kb === 'KUMAS' || kb === 'HAM_KUMAS' || kb === 'MAMUL_KUMAS') {
        return { kod: 'KUMAS', etiket: 'Kumaş' };
    }
    if (kb === 'DOKUMA_TAKIP') return { kod: 'DOKUMA_TAKIP', etiket: 'Dokuma Takip' };
    return { kod: '', etiket: '—' };
}
/** Depo hareket defteri: satırın ürün kanalı (İplik / Kumaş / Mamül) */
function depoHareketDefterKanalBul(row) {
    if (!row) return { kod: '', etiket: '—' };
    if (row._tbl === 'iplik_stok' || (row.iplik_no != null && String(row.iplik_no).trim() !== '' && row._tbl !== 'kumas_stok')) {
        return { kod: 'IPLIK', etiket: 'İplik' };
    }
    const fromKb = depoKomutaKanalFromKaynak(row.kaynak_birim);
    if (fromKb.kod === 'IPLIK' || fromKb.kod === 'MAMUL_DEPO' || fromKb.kod === 'KUMAS' || fromKb.kod === 'DOKUMA_TAKIP') {
        return fromKb;
    }
    if (row._tbl === 'kumas_stok' || !row._tbl) {
        if (typeof kumasStokHareketiMamulDepoMu === 'function' && kumasStokHareketiMamulDepoMu(row)) {
            return { kod: 'MAMUL_DEPO', etiket: 'Mamül' };
        }
        return { kod: 'KUMAS', etiket: 'Kumaş' };
    }
    return fromKb;
}
window.depoHareketDefterKanalBul = depoHareketDefterKanalBul;
function depoHareketDefterIslemTip(row) {
    let tip = String(row?.islem_turu || '').trim().toUpperCase()
        .replace('GIRIS', 'GİRİŞ').replace('CIKIS', 'ÇIKIŞ');
    if (tip === 'GİRİŞ' || tip === 'ÇIKIŞ') return tip;
    const kg = parseFloat(row?.miktar_kg) || 0;
    const mt = parseFloat(row?.miktar_mt) || 0;
    const ad = parseInt(row?.cuval_sayisi, 10) || 0;
    if (kg < 0 || mt < 0 || ad < 0) return 'ÇIKIŞ';
    if (kg > 0 || mt > 0 || ad > 0) return 'GİRİŞ';
    return '';
}
window.depoHareketDefterIslemTip = depoHareketDefterIslemTip;
/** Deftere alınacak satır mı? */
function stokKaydiDepoHareketDefterineAl(row, tbl) {
    if (tbl === 'iplik_stok') {
        if (typeof iplikDepoHareketiMi === 'function') return iplikDepoHareketiMi(row);
        const kb = String(row?.kaynak_birim || '').toUpperCase();
        if (kb === 'IPLIK_KART_GIRIS' || kb === 'KART_GIRIS') return false;
        const kg = parseFloat(row?.miktar_kg);
        return Number.isFinite(kg) && kg !== 0;
    }
    if (tbl === 'kumas_stok') {
        if (stokKaydiDepoKomutaMerkeziMi(row)) return true;
        const kg = Math.abs(parseFloat(row?.miktar_kg) || 0);
        const mt = Math.abs(parseFloat(row?.miktar_mt) || 0);
        const ad = Math.abs(parseInt(row?.cuval_sayisi || 0, 10) || 0);
        if (!(kg > 0 || mt > 0 || ad > 0)) return false;
        const kb = String(row?.kaynak_birim || '').toUpperCase();
        return kb === 'KUMAS' || kb === 'HAM_KUMAS' || kb === 'MAMUL_KUMAS' || kb === 'MAMUL_DEPO';
    }
    return stokKaydiDepoKomutaMerkeziMi(row);
}
function depoDokumaSevkeHazirMi(row) {
    const kb = String(row?.kaynak_birim || '').toUpperCase();
    if (kb !== 'DOKUMA_TAKIP') return false;
    const tip = String(row?.islem_turu || '').toUpperCase();
    if (tip && tip !== 'GİRİŞ' && tip !== 'GIRIS') return false;
    const notlar = String(row?.notlar || '').toUpperCase();
    if (notlar.includes('[SEVK_KAPANDI]')) return false;
    const kg = Math.abs(parseFloat(row?.miktar_kg) || 0);
    const mt = Math.abs(parseFloat(row?.miktar_mt) || 0);
    const adet = Math.abs(parseInt(row?.cuval_sayisi || 0, 10) || 0);
    return (kg > 0 || mt > 0 || adet > 0);
}
function depoDokumaSevkKaynakIdFromNotlar(notlar) {
    const s = String(notlar || '');
    const m = s.match(/KAYNAK\s*#\s*(\d+)/i);
    if (!m) return null;
    const id = String(m[1] || '').trim();
    return id || null;
}
/** Tamamen sevk edilmiş kaynak satır id'leri.
 * Kısmi çıkış (kalan mt/kg/adet > 0) listeden düşürmez — tekrar sevk edilebilir. */
function depoDokumaSevkEdilmisKaynakIdSet(rows) {
    const list = rows || [];
    const byId = new Map();
    list.forEach((r) => {
        if (r?.id != null) byId.set(String(r.id), r);
    });
    const dokunulan = new Set();
    list.forEach((r) => {
        const kb = String(r?.kaynak_birim || '').toUpperCase();
        const tip = String(r?.islem_turu || '').toUpperCase();
        if (kb !== 'DEPO_HAREKET_KUMAS') return;
        if (tip !== 'ÇIKIŞ' && tip !== 'CIKIS') return;
        const srcId = depoDokumaSevkKaynakIdFromNotlar(r?.notlar);
        if (srcId) dokunulan.add(String(srcId));
    });
    const out = new Set();
    dokunulan.forEach((srcId) => {
        const src = byId.get(srcId);
        if (!src) {
            out.add(srcId);
            return;
        }
        const not = String(src.notlar || '').toUpperCase();
        if (not.includes('[SEVK_KAPANDI]')) {
            out.add(srcId);
            return;
        }
        const kg = Math.abs(parseFloat(src.miktar_kg) || 0);
        const mt = Math.abs(parseFloat(src.miktar_mt) || 0);
        const adet = Math.abs(parseInt(src.cuval_sayisi || 0, 10) || 0);
        if (kg <= 0 && mt <= 0 && adet <= 0) out.add(srcId);
        /* Kalan varsa kısmi sevk — "edilmis" setine alma */
    });
    return out;
}
function depoSevkeHazirSayaçOzet(rows) {
    const all = rows || dataCache.kumas_stok || [];
    const dokumaGirisToplam = all.filter(r => String(r?.kaynak_birim || '').toUpperCase() === 'DOKUMA_TAKIP').length;
    const sevkSet = depoDokumaSevkEdilmisKaynakIdSet(all);
    /* Bekleyen = kalan miktarı olan sevke hazır (kısmi sevk dahil) */
    const bekleyen = all.filter(r => depoDokumaSevkeHazirMi(r)).length;
    return { dokumaGirisToplam, sevkEdilen: sevkSet.size, bekleyen };
}
async function depoSevkeHazirSatiriSevkEt(rowId, sevkOpts = {}) {
    if (appMode !== 'SEVKIYAT') {
        sevkiyatMerkezGrup = 'KUMAS';
        saveUiState({ sevkiyatMerkezGrup });
        if (typeof erpSevkAdetGirisAc === 'function') {
            erpSevkAdetGirisAc({ toast: 'Kumaş sevkiyatı artık sadece Sevkiyat ekranından yapılır.' });
        } else {
            setAppMode('SEVKIYAT');
        }
        return;
    }
    if (!rowId) return;
    const row = (dataCache.kumas_stok || []).find(r => String(r.id) === String(rowId));
    if (!row) { erpToast('Sevke hazır satır bulunamadı.', 'error'); return; }
    if (!depoDokumaSevkeHazirMi(row)) { erpToast('Satır sevke hazır değil veya daha önce sevk edilmiş.', 'error'); return; }
    const kalanKg = Math.abs(parseFloat(row.miktar_kg) || 0);
    const kalanMt = Math.abs(parseFloat(row.miktar_mt) || 0);
    const kalanAdet = Math.abs(parseInt(row.cuval_sayisi || 0, 10) || 0);
    const inKg = parseFloat(document.getElementById(`sevk-kg-${row.id}`)?.value || 0) || 0;
    const inMt = parseFloat(document.getElementById(`sevk-mt-${row.id}`)?.value || 0) || 0;
    const inAd = parseInt(document.getElementById(`sevk-adet-${row.id}`)?.value || 0, 10) || 0;
    const kg = Math.min(Math.max(inKg, 0), kalanKg);
    const mt = Math.min(Math.max(inMt, 0), kalanMt);
    const adet = Math.min(Math.max(inAd, 0), kalanAdet);
    if (kg <= 0 && mt <= 0 && adet <= 0) { erpToast('Sevk edilecek miktar girin.', 'error'); return; }
    const user = dtCurrentUserLabel();
    const ts = new Date().toLocaleString('tr-TR', { year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit' });
    const stokKodu = String(row.stok_kodu || row.lot_no || '').trim();
    const payload = {
        stok_kodu: stokKodu,
        kumas_cinsi: row.kumas_cinsi || '',
        lot_no: row.lot_no || '',
        marka: row.marka || '',
        renk: row.renk || '',
        firma: row.firma || '',
        miktar_kg: kg > 0 ? -kg : 0,
        miktar_mt: mt > 0 ? -mt : 0,
        cuval_sayisi: adet > 0 ? adet : 0,
        islem_turu: 'ÇIKIŞ',
        kaynak_birim: 'DEPO_HAREKET_KUMAS',
        updated_by: user,
        notlar: `[DOKUMA_SEVKE_HAZIR] Kaynak #${row.id} · ${ts} · ${user}`,
        islem_gecmisi: `✨ ${ts} — Sevke Hazır Havuzu üzerinden kısmi sevk · Kaynak: #${row.id} · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`
    };
    const { error: insErr } = await sb.from('kumas_stok').insert([payload]);
    if (insErr) { erpToast(`Sevk kaydı oluşturulamadı: ${insErr.message}`, 'error'); return; }
    const prevNot = String(row.notlar || '').trim();
    const yeniKg = Math.max(0, kalanKg - kg);
    const yeniMt = Math.max(0, kalanMt - mt);
    const yeniAdet = Math.max(0, kalanAdet - adet);
    const kapandi = yeniKg <= 0 && yeniMt <= 0 && yeniAdet <= 0;
    const yeniNot = `${prevNot ? `${prevNot}\n` : ''}${kapandi ? '[SEVK_KAPANDI]' : '[SEVK_PARCALI]'} ${ts} · ${user} · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`;
    const { error: updErr } = await sb.from('kumas_stok').update({
        miktar_kg: yeniKg,
        miktar_mt: yeniMt,
        cuval_sayisi: yeniAdet,
        notlar: yeniNot,
        updated_by: user
    }).eq('id', row.id);
    if (updErr) { erpToast(`Kaynak satır güncellenemedi: ${updErr.message}`, 'error'); return; }
    try {
        if (Array.isArray(dataCache.kumas_stok)) {
            const ix = dataCache.kumas_stok.findIndex(r => String(r.id) === String(row.id));
            if (ix >= 0) {
                dataCache.kumas_stok[ix] = {
                    ...dataCache.kumas_stok[ix],
                    miktar_kg: yeniKg,
                    miktar_mt: yeniMt,
                    cuval_sayisi: yeniAdet,
                    notlar: yeniNot,
                    updated_by: user
                };
            }
        }
    } catch (e) {}
    if (!sevkOpts.skipSync) erpSyncTablesBackground(['kumas_stok']);
    if (!sevkOpts.silentToast) {
        erpToast(kapandi ? 'Sevk tamamlandı ve satır kapandı.' : 'Kısmi sevk oluşturuldu, kalan miktar havuzda.', 'success');
    }
    if (!sevkOpts.skipReload) loadData();
}
function depoSevkSecimOzetiGuncelle(groupKey, rowIdsCsv) {
    const ids = String(rowIdsCsv || '').split(',').map(x => String(x).trim()).filter(Boolean);
    let kg = 0, mt = 0, adet = 0;
    ids.forEach(id => {
        kg += parseFloat(document.getElementById(`sevk-kg-${id}`)?.value || 0) || 0;
        mt += parseFloat(document.getElementById(`sevk-mt-${id}`)?.value || 0) || 0;
        adet += parseInt(document.getElementById(`sevk-adet-${id}`)?.value || 0, 10) || 0;
    });
    const el = document.getElementById(`sevk-ozet-${groupKey}`);
    if (!el) return;
    el.textContent = `Seçilen: ${kg.toFixed(2)} kg · ${mt.toFixed(2)} mt · ${adet} adet`;
}
async function depoSevkeHazirTopluSevkEt(rowIdsCsv) {
    if (appMode !== 'SEVKIYAT') {
        sevkiyatMerkezGrup = 'KUMAS';
        saveUiState({ sevkiyatMerkezGrup });
        if (typeof erpSevkAdetGirisAc === 'function') {
            erpSevkAdetGirisAc({ toast: 'Toplu kumaş sevkiyatı artık sadece Sevkiyat ekranından yapılır.' });
        } else {
            setAppMode('SEVKIYAT');
        }
        return;
    }
    const ids = String(rowIdsCsv || '').split(',').map(x => String(x).trim()).filter(Boolean);
    if (!ids.length) return;
    let basarili = 0;
    for (const id of ids) {
        const inKg = parseFloat(document.getElementById(`sevk-kg-${id}`)?.value || 0) || 0;
        const inMt = parseFloat(document.getElementById(`sevk-mt-${id}`)?.value || 0) || 0;
        const inAd = parseInt(document.getElementById(`sevk-adet-${id}`)?.value || 0, 10) || 0;
        if (inKg <= 0 && inMt <= 0 && inAd <= 0) continue;
        await depoSevkeHazirSatiriSevkEt(id, { skipSync: true, silentToast: true, skipReload: true });
        basarili += 1;
    }
    if (!basarili) {
        erpToast('Toplu sevk için önce miktar girin.', 'error');
        return;
    }
    erpSyncTablesBackground(['kumas_stok']);
    erpToast(`${basarili} satır sevk edildi.`, 'success');
    loadData();
}

const DOKUMA_DEPO_SEVK_HEDEFLER = [
    ['KONFEKSIYON', 'Konfeksiyon'],
    ['BOYAHANE', 'Terbiye'],
    ['GENEL_DEPO', 'Genel Depo'],
    ['MUSTERI', 'Müşteri'],
];

/** Sevkiyat Merkezi — Dokuma Depo toplu sevk sepeti */
let dokumaDepoTopluSevkSepet = [];

function dokumaDepoTopluSepetSatirBul(rowId) {
    const id = String(rowId || '');
    return (dokumaDepoTopluSevkSepet || []).find(x => String(x.rowId) === id) || null;
}

function dokumaDepoTopluSepetOzet() {
    const list = dokumaDepoTopluSevkSepet || [];
    return list.reduce((acc, x) => {
        acc.kg += parseFloat(x.kg) || 0;
        acc.mt += parseFloat(x.mt) || 0;
        acc.ad += parseInt(x.adet, 10) || 0;
        return acc;
    }, { adet: 0, kg: 0, mt: 0, n: list.length });
}

function dokumaDepoTopluSepetHtml() {
    const list = dokumaDepoTopluSevkSepet || [];
    const oz = dokumaDepoTopluSepetOzet();
    const hedefOpts = DOKUMA_DEPO_SEVK_HEDEFLER.map(([k, l]) =>
        `<option value="${k}">${pdfEsc(l)}</option>`
    ).join('');
    const satirlar = list.length
        ? list.map((x, i) => `<tr>
            <td class="mono" style="font-size:9px;color:var(--text3)">${pdfEsc(x.sno || '—')}</td>
            <td>${pdfEsc(x.urun || '—')}${x.renk ? `<span style="color:var(--rose-c);margin-left:4px;font-size:9px">${pdfEsc(x.renk)}</span>` : ''}</td>
            <td class="mono" style="text-align:right;color:var(--cyan-c)">${x.mt > 0 ? Number(x.mt).toFixed(1) : '—'}</td>
            <td class="mono" style="text-align:right;color:var(--accent2)">${x.kg > 0 ? Number(x.kg).toFixed(1) : '—'}</td>
            <td class="mono" style="text-align:right;color:var(--emerald-c)">${x.adet > 0 ? x.adet : '—'}</td>
            <td style="text-align:center"><button type="button" class="btn-pro btn-ghost-pro" style="padding:2px 6px;font-size:9px" onclick="dokumaDepoTopluSepettenCikar(${i})" title="Listeden çıkar">✕</button></td>
        </tr>`).join('')
        : '';
    return `<div id="dokuma-depo-toplu-sepet-wrap" class="dd-toplu-sepet panel-box" style="margin-bottom:14px">
        <div class="dd-toplu-sepet-head">
            <div style="flex:1;min-width:140px">
                <div style="font-size:9px;font-weight:700;color:var(--accent);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.06em">Toplu sevk listesi</div>
                <div style="font-size:9px;color:var(--text3);margin-top:2px">${oz.n} kalem · ${oz.mt.toFixed(1)} m · ${oz.kg.toFixed(1)} kg · ${oz.adet} ad</div>
            </div>
            <div>
                <label class="pro-label" style="margin-bottom:3px;font-size:8px">Sevk hedefi</label>
                <select id="dd-toplu-sevk-hedef" class="pro-input" style="min-width:128px;padding:6px 8px;font-size:10px;font-weight:700">
                    <option value="">Hedef seçin…</option>
                    ${hedefOpts}
                </select>
            </div>
            <button type="button" class="btn-pro btn-primary-pro" style="padding:8px 14px;font-size:10px;align-self:flex-end" onclick="dokumaDepoTopluSevkKaydet()" ${list.length ? '' : 'disabled'}>🚚 Toplu Sevk Et (${oz.n})</button>
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:8px 10px;font-size:10px;align-self:flex-end" onclick="dokumaDepoTopluSepetTemizle()" ${list.length ? '' : 'disabled'}>Temizle</button>
        </div>
        ${list.length
            ? `<div style="overflow:auto;max-height:220px"><table class="dd-toplu-sepet-table"><thead><tr>
                <th>Sipariş</th><th>Ürün</th><th style="text-align:right">m</th><th style="text-align:right">kg</th><th style="text-align:right">ad</th><th></th>
            </tr></thead><tbody>${satirlar}</tbody></table></div>`
            : `<div class="dd-toplu-sepet-empty">Satırlardaki miktarları girip <b>+ Ekle</b> ile listeye ekleyin. Tüm kalemler hazır olunca tek hedef seçip <b>Toplu Sevk Et</b> ile gönderin.</div>`}
    </div>`;
}

function dokumaDepoTopluSepetDomGuncelle() {
    const wrap = document.getElementById('dokuma-depo-toplu-sepet-wrap');
    if (!wrap) return;
    const parent = wrap.parentElement;
    if (!parent) return;
    const hedefVal = document.getElementById('dd-toplu-sevk-hedef')?.value || '';
    const tmp = document.createElement('div');
    tmp.innerHTML = dokumaDepoTopluSepetHtml();
    const neu = tmp.firstElementChild;
    if (neu) parent.replaceChild(neu, wrap);
    const sel = document.getElementById('dd-toplu-sevk-hedef');
    if (sel && hedefVal) sel.value = hedefVal;
}

function dokumaDepoTopluSepettenCikar(idx) {
    const i = parseInt(idx, 10);
    if (!Number.isFinite(i) || i < 0) return;
    dokumaDepoTopluSevkSepet = (dokumaDepoTopluSevkSepet || []).filter((_, j) => j !== i);
    dokumaDepoTopluSepetDomGuncelle();
}

function dokumaDepoTopluSepetTemizle() {
    if (!(dokumaDepoTopluSevkSepet || []).length) return;
    if (typeof confirm === 'function' && !confirm('Toplu sevk listesi temizlensin mi?')) return;
    dokumaDepoTopluSevkSepet = [];
    dokumaDepoTopluSepetDomGuncelle();
}

function dokumaDepoTopluSepeteEkle(rowId) {
    const id = String(rowId || '');
    if (!id) return;
    const cacheRow = (_dokumaDepoKdSatirlariCache || []).find(r => String(r.id) === id);
    let row = (dataCache.kumas_stok || []).find(r => String(r.id) === id) || cacheRow;
    if (!row) { erpToast('Satır bulunamadı.', 'error'); return; }
    if (!dokumaDepoSevkEdilebilirMi(row)) { erpToast('Bu satır sevk edilemez.', 'error'); return; }

    const kalanKg = Math.abs(parseFloat(row.miktar_kg) || 0);
    const kalanMt = Math.abs(parseFloat(row.miktar_mt) || 0);
    const kalanAd = Math.abs(parseInt(row.cuval_sayisi || 0, 10) || 0);
    const inKg = parseFloat(document.getElementById(`dd-sevk-kg-${id}`)?.value || 0) || 0;
    const inMt = parseFloat(document.getElementById(`dd-sevk-mt-${id}`)?.value || 0) || 0;
    const inAd = parseInt(document.getElementById(`dd-sevk-adet-${id}`)?.value || 0, 10) || 0;
    const kg = Math.min(Math.max(inKg, 0), kalanKg);
    const mt = Math.min(Math.max(inMt, 0), kalanMt);
    const adet = Math.min(Math.max(inAd, 0), kalanAd);
    if (kg <= 0 && mt <= 0 && adet <= 0) { erpToast('Sevk miktarı girin.', 'error'); return; }

    const mevcutSepet = dokumaDepoTopluSepetSatirBul(id);
    const mevcutKg = mevcutSepet ? (parseFloat(mevcutSepet.kg) || 0) : 0;
    const mevcutMt = mevcutSepet ? (parseFloat(mevcutSepet.mt) || 0) : 0;
    const mevcutAd = mevcutSepet ? (parseInt(mevcutSepet.adet, 10) || 0) : 0;
    if (mevcutKg + kg > kalanKg + 0.001 || mevcutMt + mt > kalanMt + 0.001 || mevcutAd + adet > kalanAd) {
        erpToast('Sepetteki toplam miktar depo bakiyesini aşamaz.', 'error');
        return;
    }

    const urunAd = typeof dtDokumaStokSatirUrunNorm === 'function'
        ? (dtDokumaStokSatirUrunNorm(row) || row.kumas_cinsi || row.stok_kodu || '—')
        : (row.kumas_cinsi || row.stok_kodu || '—');
    const kayit = {
        rowId: id,
        sno: typeof dokumaDepoSatirKayitSno === 'function' ? dokumaDepoSatirKayitSno(row) : (row.siparis_sno || ''),
        urun: urunAd,
        renk: String(row.renk || '').trim(),
        firma: String(row.firma || '').trim(),
        kg: mevcutKg + kg,
        mt: mevcutMt + mt,
        adet: mevcutAd + adet
    };
    dokumaDepoTopluSevkSepet = (dokumaDepoTopluSevkSepet || []).filter(x => String(x.rowId) !== id).concat([kayit]);
    dokumaDepoTopluSepetDomGuncelle();
    erpToast(`Listeye eklendi (${dokumaDepoTopluSevkSepet.length} kalem).`, 'success', 1800);
}
try { window.dokumaDepoTopluSepeteEkle = dokumaDepoTopluSepeteEkle; } catch (e) {}

async function dokumaDepoTopluSevkKaydet() {
    const list = dokumaDepoTopluSevkSepet || [];
    if (!list.length) { erpToast('Toplu sevk listesi boş.', 'error'); return; }
    const hedef = document.getElementById('dd-toplu-sevk-hedef')?.value || '';
    if (!hedef) { erpToast('Toplu sevk için hedef seçin.', 'error'); return; }
    const hedefLabel = DOKUMA_DEPO_SEVK_HEDEFLER.find(h => h[0] === hedef)?.[1] || hedef;
    if (typeof confirm === 'function' && !confirm(`${list.length} kalem ${hedefLabel} hedefine toplu sevk edilsin mi?`)) return;

    let basarili = 0;
    const kalan = [];
    for (const item of list) {
        const ok = await dokumaDepoSevkEt(item.rowId, {
            hedef,
            kg: item.kg,
            mt: item.mt,
            adet: item.adet,
            skipReload: true,
            silentToast: true
        });
        if (ok) basarili += 1;
        else kalan.push(item);
    }
    erpSyncTablesBackground(['kumas_stok', 'iplik_stok']);
    if (basarili > 0) {
        dokumaDepoTopluSevkSepet = kalan;
        const hatali = kalan.length;
        erpToast(`${basarili} kalem sevk edildi.${hatali ? ` ${hatali} kalem başarısız — listede kaldı.` : ''}`, hatali ? 'warn' : 'success');
    } else {
        erpToast('Toplu sevk tamamlanamadı.', 'error');
    }
    if (appMode === 'DOKUMA_DEPO' || (appMode === 'SEVKIYAT' && sevkiyatMerkezGrup === 'DOKUMA_DEPO')) {
        await dokumaDepoYenileAktifEkran({ filterOnly: false });
    } else {
        loadData();
    }
}
try { window.dokumaDepoTopluSevkKaydet = dokumaDepoTopluSevkKaydet; } catch (e) {}
try { window.dokumaDepoTopluSepetTemizle = dokumaDepoTopluSepetTemizle; } catch (e) {}
try { window.dokumaDepoTopluSepettenCikar = dokumaDepoTopluSepettenCikar; } catch (e) {}

let _dokumaSevkGecmisAkisCache = null;

function dokumaSevkHedefEtiket(kod) {
    const k = String(kod || '').trim().toUpperCase();
    const h = DOKUMA_DEPO_SEVK_HEDEFLER.find(x => x[0] === k);
    return h ? h[1] : (kod || '—');
}

function dokumaSevkKdIdFromNotlar(notlar) {
    const m = String(notlar || '').match(/KD:([^\s·]+)/i);
    return m ? String(m[1]).trim() : null;
}

function dokumaSevkSiparisBul(siparisId, lotNo) {
    if (siparisId) {
        const s = (dataCache.siparisler || []).find(x => String(x.id) === String(siparisId));
        if (s) return s;
    }
    const sno = String(lotNo || '').trim().split(',')[0].trim();
    if (!sno) return null;
    return (dataCache.siparisler || []).find(s => String(s.sno || '').trim() === sno) || null;
}

function dokumaSevkGecmisHamSatirlari() {
    const out = [];
    const seen = new Set();
    const push = (item) => {
        const key = `${item.tarihMs}|${item.hedef}|${item.kaynak_id || ''}|${item.kg}|${item.mt}|${item.adet}|${item.stok_kodu}|${item.kaynak_tipi}`;
        if (seen.has(key)) return;
        seen.add(key);
        out.push(item);
    };

    (dataCache.kumas_stok || []).forEach(r => {
        const not = String(r.notlar || '');
        if (!not.includes('[DOKUMA_DEPO_SEVK]')) return;
        const kb = String(r.kaynak_birim || '').toUpperCase();
        const tip = String(r.islem_turu || '').toUpperCase().replace('İ', 'I');
        if (kb !== 'DEPO_HAREKET_KUMAS' || (tip !== 'ÇIKIŞ' && tip !== 'CIKIS')) return;
        const hedef = depoNotEtiketOku(not, 'SEVK_YER');
        const siparisId = depoNotEtiketOku(not, 'SEVK_HEDEF_SIPARIS');
        const lot = r.lot_no || depoNotEtiketOku(not, 'LOT_NO') || '';
        const sip = dokumaSevkSiparisBul(siparisId, lot);
        push({
            id: r.id,
            kaynak_tipi: 'cikis',
            tarihMs: new Date(r.created_at || 0).getTime() || 0,
            tarih: r.created_at,
            hedef,
            hedefLabel: dokumaSevkHedefEtiket(hedef),
            kaynak_id: depoDokumaSevkKaynakIdFromNotlar(not),
            siparis_id: siparisId || sip?.id || null,
            siparis_sno: sip?.sno || String(lot || '').split(',')[0].trim(),
            musteri: sip?.firma || sip?.musteri || r.firma || '',
            stok_kodu: r.stok_kodu || '',
            urun: r.kumas_cinsi || r.urun_adi || '',
            renk: r.renk || '',
            kg: Math.abs(parseFloat(r.miktar_kg) || 0),
            mt: Math.abs(parseFloat(r.miktar_mt) || 0),
            adet: Math.abs(parseInt(r.cuval_sayisi, 10) || 0),
            kullanici: r.updated_by || '',
            notlar: not,
            islem_gecmisi: r.islem_gecmisi || ''
        });
    });

    (dataCache.kumas_stok || []).forEach(r => {
        const not = String(r.notlar || '');
        if (!not.includes('[SEVK_YER:')) return;
        if (not.includes('[DOKUMA_DEPO_SEVK]')) return;
        const kb = String(r.kaynak_birim || '').toUpperCase();
        if (kb !== 'DOKUMA_DEPO_SEVK' && kb !== 'DEPO_HAREKET_KUMAS') return;
        if (depoDokumaSevkKaynakIdFromNotlar(not)) return;
        const hedef = depoNotEtiketOku(not, 'SEVK_YER');
        const kdId = dokumaSevkKdIdFromNotlar(not);
        if (!kdId) return;
        const lot = r.lot_no || depoNotEtiketOku(not, 'LOT_NO') || '';
        const sip = dokumaSevkSiparisBul(null, lot);
        push({
            id: r.id,
            kaynak_tipi: 'kd_giris',
            tarihMs: new Date(r.created_at || 0).getTime() || 0,
            tarih: r.created_at,
            hedef,
            hedefLabel: dokumaSevkHedefEtiket(hedef),
            kaynak_id: kdId,
            siparis_id: sip?.id || null,
            siparis_sno: sip?.sno || String(lot || '').split(',')[0].trim(),
            musteri: sip?.firma || sip?.musteri || r.firma || '',
            stok_kodu: r.stok_kodu || '',
            urun: r.kumas_cinsi || r.urun_adi || '',
            renk: r.renk || '',
            kg: Math.abs(parseFloat(r.miktar_kg) || 0),
            mt: Math.abs(parseFloat(r.miktar_mt) || 0),
            adet: Math.abs(parseInt(r.cuval_sayisi, 10) || 0),
            kullanici: r.updated_by || '',
            notlar: not,
            islem_gecmisi: r.islem_gecmisi || ''
        });
    });

    (_dokumaSevkGecmisAkisCache || []).forEach(r => {
        const j = r.not_json || {};
        if (String(j.pipeline || '') !== 'DOKUMA_DEPO_SEVK') return;
        const sip = dokumaSevkSiparisBul(r.siparis_id, j.lot_no);
        push({
            id: r.akis_id || r.id,
            kaynak_tipi: 'konf_akis',
            tarihMs: new Date(r.created_at || j.ts || 0).getTime() || 0,
            tarih: r.created_at || j.ts,
            hedef: 'KONFEKSIYON',
            hedefLabel: 'Konfeksiyon',
            kaynak_id: j.kaynak_id || null,
            siparis_id: r.siparis_id || sip?.id || null,
            siparis_sno: sip?.sno || String(j.lot_no || '').split(',')[0].trim(),
            musteri: sip?.firma || sip?.musteri || j.firma || '',
            stok_kodu: j.stok_kodu || r.kalem_ad || '',
            urun: j.kumas_cinsi || r.kalem_ad || '',
            renk: j.renk || '',
            kg: Math.abs(parseFloat(j.kg) || 0),
            mt: Math.abs(parseFloat(j.mt) || 0),
            adet: Math.abs(parseInt(j.adet, 10) || 0),
            kullanici: j.user || '',
            notlar: j.note || '',
            islem_gecmisi: ''
        });
    });

    const cikisKeys = new Set(out.filter(x => x.kaynak_tipi === 'cikis').map(x =>
        `${x.kaynak_id}|${String(x.hedef || '').toUpperCase()}|${Math.floor((x.tarihMs || 0) / 60000)}`
    ));
    return out.filter(x => {
        if (x.kaynak_tipi !== 'konf_akis') return true;
        const dk = `${x.kaynak_id}|KONFEKSIYON|${Math.floor((x.tarihMs || 0) / 60000)}`;
        return !cikisKeys.has(dk);
    }).sort((a, b) => (b.tarihMs || 0) - (a.tarihMs || 0));
}

async function dokumaSevkGecmisAkisYukle() {
    try {
        const { data, error } = await sb.from('siparis_akis')
            .select('id,created_at,siparis_id,islem,kalem_ad,miktar,notlar')
            .eq('islem', 'KUMAS_GELIS')
            .order('created_at', { ascending: false })
            .limit(2000);
        if (error) { _dokumaSevkGecmisAkisCache = []; return; }
        _dokumaSevkGecmisAkisCache = (data || []).map(raw => {
            let j = {};
            try { j = JSON.parse(raw.notlar || '{}'); } catch (e) {}
            return { ...konfPipelineSatirFromRaw(raw), not_json: j };
        }).filter(r => String(r.not_json?.pipeline || '') === 'DOKUMA_DEPO_SEVK');
    } catch (e) {
        _dokumaSevkGecmisAkisCache = [];
    }
}

function dokumaSevkGecmisFiltreleriSifirla() {
    window._dokumaSevkGecmisFiltre = { hedef: 'HEPSI', bas: '', bit: '', musteri: '', q: '' };
    const searchInput = document.getElementById('search');
    if (searchInput) searchInput.value = '';
    const qEl = document.getElementById('dokuma-sevk-f-q');
    if (qEl) qEl.value = '';
    renderDokumaSevkGecmisi();
}

async function renderDokumaSevkGecmisi() {
    const list = document.getElementById('main-list');
    if (!list) return;

    // Filtreleri HTML silinmeden önce oku (loading ekranı input'ları yok eder)
    if (!window._dokumaSevkGecmisFiltre) window._dokumaSevkGecmisFiltre = { hedef: 'HEPSI', bas: '', bit: '', musteri: '', q: '' };
    const fPrev = window._dokumaSevkGecmisFiltre;
    const qLive = document.getElementById('dokuma-sevk-f-q')?.value;
    const q = String(qLive != null ? qLive : (fPrev.q || '')).toLocaleLowerCase('tr-TR').trim();
    const fHedef = document.getElementById('dokuma-sevk-f-hedef')?.value || fPrev.hedef || 'HEPSI';
    const fBas = document.getElementById('dokuma-sevk-f-bas')?.value || fPrev.bas || '';
    const fBit = document.getElementById('dokuma-sevk-f-bit')?.value || fPrev.bit || '';
    const fMusteriRaw = document.getElementById('dokuma-sevk-f-musteri')?.value ?? fPrev.musteri ?? '';
    const fMusteri = String(fMusteriRaw).toLocaleLowerCase('tr-TR').trim();
    window._dokumaSevkGecmisFiltre = { hedef: fHedef, bas: fBas, bit: fBit, musteri: fMusteriRaw, q: qLive != null ? qLive : (fPrev.q || '') };

    if (!(list.innerHTML || '').trim()) {
        list.innerHTML = `<div style="padding:24px;text-align:center;color:var(--text3);font-size:11px">Sevk geçmişi yükleniyor…</div>`;
    }
    await dokumaSevkGecmisAkisYukle();
    // Sync sonrası stok cache güncellenmiş olabilir
    try {
        if ((!dataCache.kumas_stok || !dataCache.kumas_stok.length) && typeof syncAllData === 'function') {
            /* no-op — syncAllData ağır; geçmiş akış + mevcut cache yeterli */
        }
    } catch (e) {}

    const f = window._dokumaSevkGecmisFiltre;

    const ham = dokumaSevkGecmisHamSatirlari();
    const rows = ham.filter(row => {
        if (fHedef !== 'HEPSI' && String(row.hedef || '').toUpperCase() !== fHedef) return false;
        if (fMusteri && !String(row.musteri || '').toLocaleLowerCase('tr-TR').includes(fMusteri)
            && !String(row.musteri || row.firma || '').toLocaleLowerCase('tr-TR').includes(fMusteri)) return false;
        if (fBas || fBit) {
            const ds = row.tarih ? new Date(row.tarih).toISOString().slice(0, 10) : '';
            if (!ds) return false;
            if (fBas && ds < fBas) return false;
            if (fBit && ds > fBit) return false;
        }
        if (!q) return true;
        const blob = [
            row.hedefLabel, row.hedef, row.musteri, row.siparis_sno, row.stok_kodu, row.urun, row.renk,
            row.kullanici, row.notlar, row.islem_gecmisi, row.kaynak_id
        ].map(x => String(x || '').toLocaleLowerCase('tr-TR')).join(' ');
        return blob.includes(q);
    });

    currentData = rows;
    const ozet = rows.reduce((acc, r) => {
        acc.kg += r.kg; acc.mt += r.mt; acc.ad += r.adet;
        acc.hedef[r.hedef || '?'] = (acc.hedef[r.hedef || '?'] || 0) + 1;
        return acc;
    }, { kg: 0, mt: 0, ad: 0, hedef: {} });

    const sel = (v, cur) => (v === cur ? 'selected' : '');
    const fmtTarih = (iso) => {
        if (!iso) return '—';
        const d = new Date(iso);
        if (isNaN(d.getTime())) return '—';
        return d.toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    };
    const miktarStr = (r) => {
        const p = [];
        if (r.mt > 0) p.push(`${r.mt.toLocaleString('tr-TR', { maximumFractionDigits: 1 })} m`);
        if (r.kg > 0) p.push(`${r.kg.toLocaleString('tr-TR', { maximumFractionDigits: 1 })} kg`);
        if (r.adet > 0) p.push(`${r.adet} ad`);
        return p.length ? p.join(' · ') : '—';
    };

    const filtHtml = `
    <div class="panel-box" style="padding:14px 16px;margin-bottom:14px;border:1px solid var(--border)">
      <div style="display:flex;flex-wrap:wrap;align-items:flex-end;gap:10px">
        <div style="flex:1;min-width:160px">
          <label class="pro-label" style="margin-bottom:4px">Ara</label>
          <input type="text" id="dokuma-sevk-f-q" class="pro-input" style="width:100%;padding:8px 10px;font-size:11px" placeholder="Sipariş, müşteri, ürün, stok kodu…" value="${pdfEsc(f.q || '')}" oninput="debounce('dokuma-sevk-f', () => renderDokumaSevkGecmisi(), 220)">
        </div>
        <div>
          <label class="pro-label" style="margin-bottom:4px">Hedef</label>
          <select id="dokuma-sevk-f-hedef" class="pro-input" style="min-width:128px;padding:8px 10px;font-size:11px" onchange="renderDokumaSevkGecmisi()">
            <option value="HEPSI" ${sel('HEPSI', fHedef)}>Hepsi</option>
            ${DOKUMA_DEPO_SEVK_HEDEFLER.map(([k, l]) => `<option value="${k}" ${sel(k, fHedef)}>${pdfEsc(l)}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="pro-label" style="margin-bottom:4px">Müşteri</label>
          <input type="text" id="dokuma-sevk-f-musteri" class="pro-input" style="min-width:120px;padding:8px 10px;font-size:11px" placeholder="Firma adı" value="${pdfEsc(fMusteriRaw)}" oninput="debounce('dokuma-sevk-m', () => renderDokumaSevkGecmisi(), 280)">
        </div>
        <div>
          <label class="pro-label" style="margin-bottom:4px">Başlangıç</label>
          <input type="date" id="dokuma-sevk-f-bas" class="pro-input" style="padding:8px 10px;font-size:11px" value="${pdfEsc(fBas)}" onchange="renderDokumaSevkGecmisi()">
        </div>
        <div>
          <label class="pro-label" style="margin-bottom:4px">Bitiş</label>
          <input type="date" id="dokuma-sevk-f-bit" class="pro-input" style="padding:8px 10px;font-size:11px" value="${pdfEsc(fBit)}" onchange="renderDokumaSevkGecmisi()">
        </div>
        <button type="button" class="pro-input" style="cursor:pointer;padding:8px 14px;font-weight:600;border-radius:8px;background:var(--surface2)" onclick="dokumaSevkGecmisFiltreleriSifirla()">Sıfırla</button>
        <button type="button" class="pro-input" style="cursor:pointer;padding:8px 14px;font-weight:600;border-radius:8px;background:rgba(99,102,241,0.12);color:var(--accent)" onclick="renderDokumaSevkGecmisi()">↻ Yenile</button>
      </div>
      <div style="font-size:10px;color:var(--text3);margin-top:10px;line-height:1.45">Dokuma Depo'dan yapılan tüm sevkler: <b>nereye</b>, <b>ne kadar</b>, <b>hangi ürün</b>, <b>hangi müşteri/sipariş</b>, <b>ne zaman</b>. Üstteki hızlı arama da kullanılabilir.</div>
    </div>`;

    const ozetHtml = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:14px">
      <div style="padding:12px 14px;border-radius:10px;background:rgba(109,113,255,0.06);border:1px solid rgba(109,113,255,0.2)">
        <div style="font-size:8px;color:var(--accent);font-family:'DM Mono',monospace;text-transform:uppercase">Sevk satırı</div>
        <div style="font-family:'Instrument Serif',serif;font-size:20px;color:var(--text)">${rows.length}</div>
      </div>
      <div style="padding:12px 14px;border-radius:10px;background:rgba(52,211,153,0.08);border:1px solid rgba(52,211,153,0.2)">
        <div style="font-size:8px;color:var(--emerald-c);font-family:'DM Mono',monospace;text-transform:uppercase">Toplam mt / kg</div>
        <div style="font-size:11px;font-weight:700;color:var(--text);margin-top:4px">${ozet.mt.toLocaleString('tr-TR', { maximumFractionDigits: 0 })} m · ${ozet.kg.toLocaleString('tr-TR', { maximumFractionDigits: 0 })} kg</div>
      </div>
      ${DOKUMA_DEPO_SEVK_HEDEFLER.map(([k, l]) => {
        const n = ozet.hedef[k] || 0;
        if (!n && fHedef !== k) return '';
        return `<div style="padding:10px 12px;border-radius:10px;background:var(--surface2);border:1px solid var(--border)">
          <div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">${pdfEsc(l)}</div>
          <div style="font-size:16px;font-weight:700;color:var(--text)">${n}</div>
        </div>`;
      }).join('')}
    </div>`;

    const satirlar = rows.map(r => {
        const hedefRenk = {
            KONFEKSIYON: 'rgba(139,92,246,0.15)',
            BOYAHANE: 'rgba(245,158,11,0.15)',
            GENEL_DEPO: 'rgba(59,130,246,0.12)',
            MUSTERI: 'rgba(16,185,129,0.12)'
        }[String(r.hedef || '').toUpperCase()] || 'var(--surface2)';
        return `<tr style="border-bottom:1px solid var(--border)">
          <td style="padding:8px 10px;font-size:10px;font-family:'DM Mono',monospace;white-space:nowrap;color:var(--text2)">${pdfEsc(fmtTarih(r.tarih))}</td>
          <td style="padding:8px 10px"><span style="display:inline-block;padding:3px 8px;border-radius:6px;font-size:9px;font-weight:700;background:${hedefRenk}">${pdfEsc(r.hedefLabel)}</span></td>
          <td style="padding:8px 10px;font-size:10px;font-weight:600;color:var(--text)">${pdfEsc(r.musteri || '—')}</td>
          <td style="padding:8px 10px;font-size:10px;font-family:'DM Mono',monospace;color:var(--accent2)">${pdfEsc(r.siparis_sno || '—')}</td>
          <td style="padding:8px 10px;font-size:10px;color:var(--text2)">${pdfEsc(r.urun || r.stok_kodu || '—')}</td>
          <td style="padding:8px 10px;font-size:10px;color:var(--text3)">${pdfEsc(r.renk || '—')}</td>
          <td style="padding:8px 10px;font-size:10px;font-weight:600;color:var(--text)">${pdfEsc(miktarStr(r))}</td>
          <td style="padding:8px 10px;font-size:9px;color:var(--text3)">${pdfEsc(r.kullanici || '—')}</td>
          <td style="padding:8px 10px;font-size:9px;font-family:'DM Mono',monospace;color:var(--text3)" title="${pdfEsc(r.notlar || '')}">${pdfEsc(r.kaynak_id ? '#' + r.kaynak_id : '—')}</td>
        </tr>`;
    }).join('');

    const tabloHtml = rows.length
        ? `<div class="panel-box" style="padding:0;overflow:hidden">
            <div style="overflow-x:auto">
              <table style="width:100%;border-collapse:collapse;min-width:920px">
                <thead>
                  <tr style="background:var(--surface2);border-bottom:1px solid var(--border)">
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">TARİH</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">HEDEF</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">MÜŞTERİ</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">SİPARİŞ</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">ÜRÜN</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">RENK</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">MİKTAR</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">KULLANICI</th>
                    <th style="padding:8px 10px;text-align:left;font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">KAYNAK</th>
                  </tr>
                </thead>
                <tbody>${satirlar}</tbody>
              </table>
            </div>
          </div>`
        : `<div class="panel-box" style="padding:36px 16px;text-align:center;color:var(--text3);font-size:11px;line-height:1.6">
            Filtrelere uygun sevk kaydı yok.<br><span style="font-size:10px">Dokuma Depo'dan sevk yaptıkça burada birikir.</span>
          </div>`;

    list.innerHTML = filtHtml + ozetHtml + tabloHtml;
}

function depoNotEtiketOku(notlar, anahtar) {
    const s = String(notlar || '');
    const esc = String(anahtar).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = s.match(new RegExp(`\\[${esc}:([^\\]]*)\\]`, 'i'));
    return m ? String(m[1] || '').trim() : '';
}

function dokumaDepoSevkEdilebilirMi(row) {
    const kg = Math.abs(parseFloat(row.miktar_kg) || 0);
    const mt = Math.abs(parseFloat(row.miktar_mt) || 0);
    const ad = Math.abs(parseInt(row.cuval_sayisi || 0, 10) || 0);
    if (kg <= 0 && mt <= 0 && ad <= 0) return false;
    if (row._kdOnly || row._kaynak === 'KD_DOKUMA') return true;
    if (!dtKaliteGecenKumasMi(row)) return false;
    const not = String(row.notlar || '').toUpperCase();
    if (not.includes('[SEVK_KAPANDI]')) return false;
    return true;
}

function dokumaDepoSiparisIdBul(row) {
    if (row?.siparis_id) return row.siparis_id;
    const sno = String(row.lot_no || '').trim().split(',')[0].trim();
    if (!sno) return null;
    const sip = (dataCache.siparisler || []).find(s => String(s.sno || '').trim() === sno);
    return sip?.id ?? null;
}

async function dtDokumaDepoKdSevkMiktarDus(row, miktar) {
    // Depo sevk: yalnızca girisler (depo kalan) güncellenir.
    // toplam_metre/kg/adet = Dokuma Takip brüt üretim — sevk ile düşürülmez (sipariş detay).
    const refs = Array.isArray(row?.kalem_refs) && row.kalem_refs.length
        ? row.kalem_refs
        : [{ siparis_id: row.siparis_id || row.siparis_ids?.[0], kalem_idx: row.kalem_idx }].filter(r => r.siparis_id != null);
    if (!refs.length) return false;

    let kalanMt = parseFloat(miktar.mt) || 0;
    let kalanKg = parseFloat(miktar.kg) || 0;
    let kalanAd = parseInt(miktar.adet, 10) || 0;
    if (kalanMt <= 0 && kalanKg <= 0 && kalanAd <= 0) return false;

    for (const ref of refs) {
        if (kalanMt <= 0 && kalanKg <= 0 && kalanAd <= 0) break;
        const sipId = ref.siparis_id;
        let kalemIdx = ref.kalem_idx;
        const sip = (dataCache.siparisler || []).find(s => String(s.id) === String(sipId));
        let kalemler = [];
        try { kalemler = typeof sip?.cins === 'string' ? JSON.parse(sip.cins) : (sip?.cins || []); } catch (e) {}
        if (kalemIdx == null && row.kalem) {
            kalemIdx = kalemler.findIndex(k => dtDokumaStokBirlestirmeAnahtari(sip, k) === row._birlestirKey);
        }
        if (!Number.isFinite(kalemIdx) || kalemIdx < 0) continue;

        const kd = await dtGetKd(sipId);
        const u = kd?.urunler?.[kalemIdx];
        if (!u) continue;

        const yeniGirisler = [];
        let dusMt = 0;
        let dusKg = 0;
        let dusAd = 0;
        for (const g of (u.girisler || [])) {
            if (!dtDokumaDepoTarihBugunVeSonrasi(dtDokumaDepoGirisTarihDegeri(g))) {
                yeniGirisler.push(g);
                continue;
            }
            if (kalanMt <= 0 && kalanKg <= 0 && kalanAd <= 0) {
                yeniGirisler.push(g);
                continue;
            }
            let gm = parseFloat(g.metre || 0) || 0;
            let gk = parseFloat(g.kg || 0) || 0;
            let ga = parseInt(g.adet || 0, 10) || 0;
            const dm = Math.min(gm, kalanMt);
            const dk = Math.min(gk, kalanKg);
            const da = Math.min(ga, kalanAd);
            gm -= dm;
            gk -= dk;
            ga -= da;
            dusMt += dm;
            dusKg += dk;
            dusAd += da;
            kalanMt -= dm;
            kalanKg -= dk;
            kalanAd -= da;
            if (gm > 0 || gk > 0 || ga > 0) {
                yeniGirisler.push({ ...g, metre: gm || null, kg: gk || null, adet: ga || null });
            }
        }
        u.girisler = yeniGirisler;
        await dtSetKd(sipId, kd);
        _kdCache[`KD_DOKUMA_${sipId}`] = kd;
    }
    const istenenMt = parseFloat(miktar.mt) || 0;
    const istenenKg = parseFloat(miktar.kg) || 0;
    const istenenAd = parseInt(miktar.adet, 10) || 0;
    const dusulenMt = istenenMt - Math.max(0, kalanMt);
    const dusulenKg = istenenKg - Math.max(0, kalanKg);
    const dusulenAd = istenenAd - Math.max(0, kalanAd);
    return (istenenMt <= 0 || dusulenMt >= istenenMt - 0.001)
        && (istenenKg <= 0 || dusulenKg >= istenenKg - 0.001)
        && (istenenAd <= 0 || dusulenAd >= istenenAd - 0.001)
        && (dusulenMt > 0 || dusulenKg > 0 || dusulenAd > 0);
}

function dokumaDepoKdSatirMi(row) {
    return !!(row?._kdOnly || String(row?.id || '').startsWith('kd-'));
}

async function sbInsertRetryDropMissing(table, rows) {
    let payload = (Array.isArray(rows) ? rows : [rows]).map(r => ({ ...r }));
    const dropped = [];
    const tried = new Set();
    while (true) {
        const res = await sb.from(table).insert(payload);
        if (!res.error) return { data: res.data, error: null, dropped };
        const msg = String(res.error?.message || '');
        const m = msg.match(/Could not find the '([^']+)' column/i);
        const missingCol = m?.[1];
        if (!missingCol || tried.has(missingCol)) return { data: null, error: res.error, dropped };
        tried.add(missingCol);
        dropped.push(missingCol);
        payload = payload.map(row => {
            const r = { ...row };
            delete r[missingCol];
            return r;
        });
        if (!payload[0] || Object.keys(payload[0]).length === 0) return { data: null, error: res.error, dropped };
    }
}

function dokumaDepoSevkMusteriAdiCoz(row, opts) {
    const { hedef, siparisId } = opts || {};
    if (hedef !== 'MUSTERI') return String(row?.firma || '').trim();
    let musteri = String(row?.firma || '').trim();
    if (!musteri) {
        const lotNo = String(row?.lot_no || '').trim();
        const sip = dokumaSevkSiparisBul(siparisId, lotNo);
        musteri = String(sip?.firma || sip?.musteri || '').trim();
    }
    if (!musteri && typeof prompt === 'function') {
        musteri = String(prompt('Müşteri / alıcı firma (sevkiyat fişi için):') || '').trim();
    }
    return musteri;
}

async function dokumaDepoSevkMuhasebeFisHazirla(cikisPayload, hareketId) {
    if (!cikisPayload || String(cikisPayload.islem_turu || '').toUpperCase().replace(/İ/g, 'I') !== 'CIKIS') return null;
    const yer = typeof depoNotEtiketOku === 'function'
        ? depoNotEtiketOku(cikisPayload.notlar, 'SEVK_YER')
        : '';
    if (String(yer || '').toUpperCase() !== 'MUSTERI') return null;
    if (!String(cikisPayload.firma || '').trim()) return null;
    if (typeof muhasebeFisKumasCikisKaydet !== 'function') return null;
    try {
        return await muhasebeFisKumasCikisKaydet({
            payloads: [cikisPayload],
            hareketIds: hareketId ? [hareketId] : []
        });
    } catch (e) {
        console.warn('dokumaDepoSevkMuhasebeFisHazirla', e);
        return null;
    }
}

async function dokumaDepoSevkEtKd(rowId, row, opts) {
    const { hedef, siparisId, kg, mt, adet, user, ts, hedefLabel, kalanKg, kalanMt, kalanAd, skipReload, silentToast } = opts;
    const stokKodu = String(row.stok_kodu || row.lot_no || '').trim();
    const lotNo = String(row.lot_no || '').trim();
    const kapandi = Math.max(0, kalanKg - kg) <= 0 && Math.max(0, kalanMt - mt) <= 0 && Math.max(0, kalanAd - adet) <= 0;
    const musteriAd = dokumaDepoSevkMusteriAdiCoz(row, { hedef, siparisId });
    if (hedef === 'MUSTERI' && !musteriAd) {
        if (!silentToast) erpToast('Müşteri sevkiyatı için firma adı zorunludur (sevkiyat fişi).', 'error');
        return false;
    }

    const dusOk = await dtDokumaDepoKdSevkMiktarDus(row, { mt, kg, adet });
    if (!dusOk) {
        if (!silentToast) erpToast('Dokuma Takip kaydı güncellenemedi.', 'error');
        return false;
    }

    // Sevk geçmişi için kalıcı ÇIKIŞ kaydı (KD satırları da geçmişte görünsün)
    const sevkNotExtra = hedef === 'KONFEKSIYON' && siparisId ? ` [SEVK_HEDEF_SIPARIS:${siparisId}]` : '';
    const lotTag = lotNo ? `[LOT_NO:${lotNo}]` : '';
    const histNot = `[DOKUMA_DEPO_SEVK][SEVK_YER:${hedef}]${lotTag} KD:${rowId} · ${ts} · ${user}${sevkNotExtra}`;
    const histPayload = {
        stok_kodu: stokKodu,
        kumas_cinsi: row.kumas_cinsi || '',
        lot_no: lotNo,
        marka: row.marka || '',
        renk: row.renk || '',
        firma: hedef === 'MUSTERI' ? musteriAd.toUpperCase() : (row.firma || ''),
        miktar_kg: kg > 0 ? -kg : 0,
        miktar_mt: mt > 0 ? -mt : 0,
        cuval_sayisi: adet > 0 ? adet : 0,
        islem_turu: 'ÇIKIŞ',
        kaynak_birim: 'DEPO_HAREKET_KUMAS',
        updated_by: user,
        notlar: histNot,
        islem_gecmisi: `✨ ${ts} — Dokuma Depo → ${hedefLabel} · KD:${rowId} · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`
    };
    const histRes = await sbInsertRetryDropMissing('kumas_stok', [histPayload]);
    let histId = null;
    if (histRes.error) {
        console.warn('dokumaDepoSevkEtKd geçmiş kaydı', histRes.error, histRes.dropped);
        erpToast('Sevk yapıldı ama geçmiş kaydı yazılamadı: ' + histRes.error.message, 'warn');
    } else if (Array.isArray(dataCache.kumas_stok)) {
        const cacheRow = { ...histPayload };
        (histRes.dropped || []).forEach(c => { try { delete cacheRow[c]; } catch (e) {} });
        histId = 'tmp-sevk-' + Date.now();
        dataCache.kumas_stok.unshift({
            ...cacheRow,
            id: histId,
            created_at: new Date().toISOString()
        });
    }

    if (hedef === 'KONFEKSIYON') {
        const kalemMeta = konfPipelineKalemNotMeta(siparisId, row);
        const kalemler = konfGetSiparisKalemlerById(siparisId);
        const kalem = (kalemMeta.kalem_idx != null && kalemMeta.kalem_idx >= 0)
            ? (kalemler[kalemMeta.kalem_idx] || row?.kalem || {})
            : (row?.kalem || {});
        const ikinciTip = dtKalemIkinciBirimTip(kalem);
        const sevkKg = ikinciTip === 'KG' ? kg : 0;
        const sevkAdet = ikinciTip === 'ADET' ? adet : 0;
        const miktarEtiket = dokumaSevkMiktarEtiket(kalem, mt, kg, adet);
        const notPayload = {
            ts: new Date().toISOString(),
            user,
            kaynak_id: rowId,
            stok_kodu: stokKodu,
            lot_no: row.lot_no || '',
            kumas_cinsi: row.kumas_cinsi || '',
            kg: sevkKg,
            mt,
            adet: sevkAdet,
            siparis_birim: siparisKalemBirim(kalem),
            ikinci_birim: ikinciTip,
            renk: row.renk || '',
            firma: row.firma || '',
            ...kalemMeta,
            durum: 'KESIM_BEKLIYOR',
            kesilen_kg: 0,
            kesilen_mt: 0,
            kesilen_adet: 0,
            hedef: 'KONFEKSIYON',
            konf_panel: true,
            pipeline: 'DOKUMA_DEPO_SEVK',
            note: `Dokuma Depo → Konfeksiyon sevk · ${miktarEtiket || '—'}`
        };
        const { error: akisErr } = await sb.from('siparis_akis').insert([{
            siparis_id: siparisId,
            islem: 'KUMAS_GELIS',
            kalem_ad: stokKodu || row.lot_no || 'Kumaş',
            miktar: dokumaSevkAnaMiktar(kalem, mt, kg, adet),
            notlar: JSON.stringify(notPayload)
        }]);
        if (akisErr) {
            if (!silentToast) erpToast(`Konfeksiyon kaydı oluşturulamadı: ${akisErr.message}`, 'error');
            return false;
        }
        try {
            await konfPipelineSiparisDurumSenkron(siparisId);
            await konfDurumTabYenile(siparisId);
        } catch (e) { console.warn('konfPipelineSiparisDurumSenkron', e); }
    } else if (hedef === 'BOYAHANE') {
        const bhPayload = {
            stok_kodu: stokKodu,
            kumas_cinsi: row.kumas_cinsi || '',
            lot_no: lotNo,
            renk: row.renk || '',
            firma: row.firma || '',
            miktar_kg: kg,
            miktar_mt: mt,
            cuval_sayisi: adet,
            islem_turu: 'GİRİŞ',
            kaynak_birim: 'DOKUMA_DEPO_SEVK',
            updated_by: user,
            notlar: `[SEVK_YER:BOYAHANE][BOYAHANE_BEKLEYEN]${lotTag} KD:${rowId} · ${ts}`
        };
        const bhRes = await sbInsertRetryDropMissing('kumas_stok', [bhPayload]);
        if (bhRes.error) erpToast(`Boyahane kaydı oluşturulamadı: ${bhRes.error.message}`, 'warn');
    } else if (hedef === 'GENEL_DEPO') {
        const genelPayload = {
            stok_kodu: stokKodu,
            kumas_cinsi: row.kumas_cinsi || '',
            lot_no: lotNo,
            renk: row.renk || '',
            firma: row.firma || '',
            miktar_kg: kg,
            miktar_mt: mt,
            cuval_sayisi: adet,
            islem_turu: 'GİRİŞ',
            kaynak_birim: 'DEPO_HAREKET_KUMAS',
            notlar: `[SEVK_YER:GENEL_DEPO]${lotTag} KD:${rowId} · ${ts}`
        };
        const gdRes = await sbInsertRetryDropMissing('kumas_stok', [genelPayload]);
        if (gdRes.error) erpToast(`Genel Depo kaydı oluşturulamadı: ${gdRes.error.message}`, 'warn');
    } else if (hedef === 'MUSTERI') {
        const msPayload = {
            stok_kodu: stokKodu,
            kumas_cinsi: row.kumas_cinsi || '',
            lot_no: lotNo,
            renk: row.renk || '',
            firma: row.firma || '',
            miktar_kg: kg,
            miktar_mt: mt,
            cuval_sayisi: adet,
            islem_turu: 'GİRİŞ',
            kaynak_birim: 'DOKUMA_DEPO_SEVK',
            notlar: `[SEVK_YER:MUSTERI]${lotTag} KD:${rowId} · ${ts}`
        };
        const msRes = await sbInsertRetryDropMissing('kumas_stok', [msPayload]);
        if (msRes.error) erpToast(`Müşteri sevk kaydı oluşturulamadı: ${msRes.error.message}`, 'warn');
    }

    if (!skipReload) _dokumaDepoKdSatirlariCache = [];
    if (!skipReload) erpSyncTablesBackground(['kumas_stok', 'iplik_stok']);
    let mfNo = '';
    if (hedef === 'MUSTERI') {
        const fis = await dokumaDepoSevkMuhasebeFisHazirla(histPayload, histId);
        if (fis?.fis_no) mfNo = fis.fis_no;
        try {
            if (typeof sevkiyatKumasCikisSiparisYuklemeIsle === 'function') {
                const ki = row.kalem_idx ?? row.not_json?.kalem_idx
                    ?? (Array.isArray(row.kalem_refs) && row.kalem_refs[0] ? row.kalem_refs[0].kalem_idx : null);
                await sevkiyatKumasCikisSiparisYuklemeIsle([{
                    ...histPayload,
                    siparis_id: siparisId || dokumaDepoSiparisIdBul(row),
                    kalem_idx: ki,
                    lot_no: lotNo,
                    islem_turu: 'ÇIKIŞ'
                }], { kaynak: 'DOKUMA_DEPO_MUSTERI' });
            }
        } catch (e) { console.warn('dokuma KD müşteri→sipariş yükleme', e); }
    }
    if (!silentToast) {
        erpToast(
            `${hedefLabel} sevki tamamlandı.${kapandi ? '' : ' Kalan miktar depoda.'}${mfNo ? ' Sevkiyat fişi ' + mfNo + ' asıldı.' : ''}`,
            'success'
        );
    }
    if (!skipReload) {
        if (appMode === 'DOKUMA_DEPO' || (appMode === 'SEVKIYAT' && sevkiyatMerkezGrup === 'DOKUMA_DEPO')) dokumaDepoYenileAktifEkran();
        else loadData();
    }
    return true;
}

async function dokumaDepoSevkSatirHazirla(rowId) {
    const cacheRow = (_dokumaDepoKdSatirlariCache || []).find(r => String(r.id) === String(rowId));
    let row = (dataCache.kumas_stok || []).find(r => String(r.id) === String(rowId));
    if (row) return row;
    if (!cacheRow) return null;
    const sipId = cacheRow.siparis_id || (cacheRow.siparis_ids && cacheRow.siparis_ids[0]);
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === String(sipId));
    if (!sip) return cacheRow;
    const kalem = cacheRow.kalem || {};
    const res = await dtDokumaDepoStokUpsert(sip, kalem, {
        metre: Math.abs(parseFloat(cacheRow.miktar_mt) || 0),
        kg: Math.abs(parseFloat(cacheRow.miktar_kg) || 0),
        adet: Math.abs(parseInt(cacheRow.cuval_sayisi, 10) || 0),
        birlestir: 'set',
        kaynak: 'DOKUMA_DEPO_SEVK',
        urunEtiket: cacheRow.kalem?.ad || cacheRow.kalem?.kod || '',
        sessiz: true
    });
    if (res?.id) {
        await erpSyncAllDataBekle({ silent: true, tables: ['kumas_stok'], light: true });
        row = (dataCache.kumas_stok || []).find(r => String(r.id) === String(res.id));
        if (row) return row;
    }
    return cacheRow;
}

async function dokumaDepoSevkEt(rowId, opts = {}) {
    if (!rowId) return false;
    const cacheRow = (_dokumaDepoKdSatirlariCache || []).find(r => String(r.id) === String(rowId));
    let row = (dataCache.kumas_stok || []).find(r => String(r.id) === String(rowId));
    const kdSatir = dokumaDepoKdSatirMi(row) || dokumaDepoKdSatirMi(cacheRow) || (!row && !!cacheRow);
    if (!row && cacheRow) row = cacheRow;
    if (!row) { if (!opts.silentToast) erpToast('Satır bulunamadı.', 'error'); return false; }

    const hedef = opts.hedef != null ? String(opts.hedef) : (document.getElementById(`dd-sevk-hedef-${rowId}`)?.value || '');
    if (!hedef) { if (!opts.silentToast) erpToast('Sevk hedefi seçin.', 'error'); return false; }

    let siparisId = row.siparis_id || dokumaDepoSiparisIdBul(row) || '';
    if (!siparisId && row.siparis_ids?.length) siparisId = row.siparis_ids[0];
    if (hedef === 'KONFEKSIYON' && !siparisId) {
        if (!opts.silentToast) erpToast('Konfeksiyon sevki için sipariş bilgisi bulunamadı.', 'error');
        return false;
    }

    const kalanKg = Math.abs(parseFloat(row.miktar_kg) || 0);
    const kalanMt = Math.abs(parseFloat(row.miktar_mt) || 0);
    const kalanAd = Math.abs(parseInt(row.cuval_sayisi || 0, 10) || 0);
    const inKg = opts.kg != null ? opts.kg : (parseFloat(document.getElementById(`dd-sevk-kg-${rowId}`)?.value || 0) || 0);
    const inMt = opts.mt != null ? opts.mt : (parseFloat(document.getElementById(`dd-sevk-mt-${rowId}`)?.value || 0) || 0);
    const inAd = opts.adet != null ? opts.adet : (parseInt(document.getElementById(`dd-sevk-adet-${rowId}`)?.value || 0, 10) || 0);
    const kg = Math.min(Math.max(inKg, 0), kalanKg);
    const mt = Math.min(Math.max(inMt, 0), kalanMt);
    const adet = Math.min(Math.max(inAd, 0), kalanAd);
    if (kg <= 0 && mt <= 0 && adet <= 0) { if (!opts.silentToast) erpToast('Sevk miktarı girin.', 'error'); return false; }

    if (!dokumaDepoSevkEdilebilirMi(row)) { if (!opts.silentToast) erpToast('Satır sevk edilemez.', 'error'); return false; }

    const user = dtCurrentUserLabel();
    const ts = new Date().toLocaleString('tr-TR', { year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit' });
    const hedefLabel = DOKUMA_DEPO_SEVK_HEDEFLER.find(h => h[0] === hedef)?.[1] || hedef;

    if (kdSatir) {
        return await dokumaDepoSevkEtKd(rowId, cacheRow || row, { hedef, siparisId, kg, mt, adet, user, ts, hedefLabel, kalanKg, kalanMt, kalanAd, skipReload: opts.skipReload, silentToast: opts.silentToast });
    }

    row = await dokumaDepoSevkSatirHazirla(rowId);
    if (!row || dokumaDepoKdSatirMi(row)) {
        if (!opts.silentToast) erpToast('Depo kaydı oluşturulamadı. Sayfayı yenileyip tekrar deneyin.', 'error');
        return false;
    }
    if (!dokumaDepoSevkEdilebilirMi(row)) { if (!opts.silentToast) erpToast('Satır sevk edilemez.', 'error'); return false; }
    const stokKodu = String(row.stok_kodu || row.lot_no || '').trim();
    const lotNo = String(row.lot_no || '').trim();
    const lotTag = lotNo ? `[LOT_NO:${lotNo}]` : '';
    const sevkNotExtra = hedef === 'KONFEKSIYON' && siparisId ? ` [SEVK_HEDEF_SIPARIS:${siparisId}]` : '';
    const musteriAd = dokumaDepoSevkMusteriAdiCoz(row, { hedef, siparisId });
    if (hedef === 'MUSTERI' && !musteriAd) {
        if (!opts.silentToast) erpToast('Müşteri sevkiyatı için firma adı zorunludur (sevkiyat fişi).', 'error');
        return false;
    }
    const cikisPayload = {
        stok_kodu: stokKodu,
        kumas_cinsi: row.kumas_cinsi || '',
        lot_no: lotNo,
        marka: row.marka || '',
        renk: row.renk || '',
        firma: hedef === 'MUSTERI' ? musteriAd.toUpperCase() : (row.firma || ''),
        miktar_kg: kg > 0 ? -kg : 0,
        miktar_mt: mt > 0 ? -mt : 0,
        cuval_sayisi: adet > 0 ? adet : 0,
        islem_turu: 'ÇIKIŞ',
        kaynak_birim: 'DEPO_HAREKET_KUMAS',
        updated_by: user,
        notlar: `[DOKUMA_DEPO_SEVK][SEVK_YER:${hedef}]${lotTag} Kaynak #${row.id} · ${ts} · ${user}${sevkNotExtra}`,
        islem_gecmisi: `✨ ${ts} — Dokuma Depo → ${hedefLabel} · Kaynak: #${row.id} · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`
    };
    const cikisRes = await sbInsertRetryDropMissing('kumas_stok', [cikisPayload]);
    if (cikisRes.error) { if (!opts.silentToast) erpToast(`Sevk kaydı oluşturulamadı: ${cikisRes.error.message}`, 'error'); return false; }
    let cikisId = null;
    if (Array.isArray(dataCache.kumas_stok)) {
        const cacheRow = { ...cikisPayload };
        (cikisRes.dropped || []).forEach(c => { try { delete cacheRow[c]; } catch (e) {} });
        cikisId = 'tmp-sevk-' + Date.now();
        dataCache.kumas_stok.unshift({
            ...cacheRow,
            id: cikisId,
            created_at: new Date().toISOString()
        });
    }

    const prevNot = String(row.notlar || '').trim();
    const yeniKg = Math.max(0, kalanKg - kg);
    const yeniMt = Math.max(0, kalanMt - mt);
    const yeniAdet = Math.max(0, kalanAd - adet);
    const kapandi = yeniKg <= 0 && yeniMt <= 0 && yeniAdet <= 0;
    const yeniNot = `${prevNot ? `${prevNot}\n` : ''}${kapandi ? '[SEVK_KAPANDI]' : '[SEVK_PARCALI]'} ${ts} · ${hedefLabel} · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`;
    const { error: updErr } = await sb.from('kumas_stok').update({
        miktar_kg: yeniKg,
        miktar_mt: yeniMt,
        cuval_sayisi: yeniAdet,
        notlar: yeniNot,
        updated_by: user
    }).eq('id', row.id);
    if (updErr) { if (!opts.silentToast) erpToast(`Kaynak güncellenemedi: ${updErr.message}`, 'error'); return false; }

    if (!opts.skipReload) _dokumaDepoKdSatirlariCache = [];

    if (hedef === 'KONFEKSIYON') {
        const kalemMeta = konfPipelineKalemNotMeta(siparisId, row);
        const kalemler = konfGetSiparisKalemlerById(siparisId);
        const kalem = (kalemMeta.kalem_idx != null && kalemMeta.kalem_idx >= 0)
            ? (kalemler[kalemMeta.kalem_idx] || row?.kalem || {})
            : (row?.kalem || {});
        const ikinciTip = dtKalemIkinciBirimTip(kalem);
        const sevkKg = ikinciTip === 'KG' ? kg : 0;
        const sevkAdet = ikinciTip === 'ADET' ? adet : 0;
        const miktarEtiket = dokumaSevkMiktarEtiket(kalem, mt, kg, adet);
        const notPayload = {
            ts: new Date().toISOString(),
            user,
            kaynak_id: row.id,
            stok_kodu: stokKodu,
            lot_no: row.lot_no || '',
            kumas_cinsi: row.kumas_cinsi || '',
            kg: sevkKg,
            mt,
            adet: sevkAdet,
            siparis_birim: siparisKalemBirim(kalem),
            ikinci_birim: ikinciTip,
            renk: row.renk || '',
            firma: row.firma || '',
            ...kalemMeta,
            durum: 'KESIM_BEKLIYOR',
            kesilen_kg: 0,
            kesilen_mt: 0,
            kesilen_adet: 0,
            hedef: 'KONFEKSIYON',
            konf_panel: true,
            pipeline: 'DOKUMA_DEPO_SEVK',
            note: `Dokuma Depo → Konfeksiyon sevk · ${miktarEtiket || '—'}`
        };
        const { error: akisErr } = await sb.from('siparis_akis').insert([{
            siparis_id: siparisId,
            islem: 'KUMAS_GELIS',
            kalem_ad: stokKodu || row.lot_no || 'Kumaş',
            miktar: dokumaSevkAnaMiktar(kalem, mt, kg, adet),
            notlar: JSON.stringify(notPayload)
        }]);
        if (akisErr) erpToast(`Konfeksiyon kaydı oluşturulamadı: ${akisErr.message}`, 'warn');
        else {
            try {
                await konfPipelineSiparisDurumSenkron(siparisId);
                await konfDurumTabYenile(siparisId);
            } catch (e) { console.warn('konfPipelineSiparisDurumSenkron', e); }
        }
    } else if (hedef === 'BOYAHANE') {
        const bhRes = await sbInsertRetryDropMissing('kumas_stok', [{
            stok_kodu: stokKodu,
            kumas_cinsi: row.kumas_cinsi || '',
            lot_no: lotNo,
            marka: row.marka || '',
            renk: row.renk || '',
            firma: row.firma || '',
            miktar_kg: kg,
            miktar_mt: mt,
            cuval_sayisi: adet,
            islem_turu: 'GİRİŞ',
            kaynak_birim: 'DOKUMA_DEPO_SEVK',
            updated_by: user,
            notlar: `[SEVK_YER:BOYAHANE][BOYAHANE_BEKLEYEN][BOYAHANE_ALAN:KUMAS_BOYA]${lotTag} Kaynak #${row.id} · ${ts}`,
            islem_gecmisi: `✨ ${ts} — Dokuma Depo sevki · Boyahane bekliyor · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`
        }]);
        if (bhRes.error) erpToast(`Boyahane giriş kaydı oluşturulamadı: ${bhRes.error.message}`, 'warn');
    } else if (hedef === 'GENEL_DEPO') {
        const genelPayload = {
            stok_kodu: stokKodu,
            kumas_cinsi: row.kumas_cinsi || '',
            lot_no: lotNo,
            marka: row.marka || '',
            renk: row.renk || '',
            firma: row.firma || '',
            miktar_kg: kg,
            miktar_mt: mt,
            cuval_sayisi: adet,
            islem_turu: 'GİRİŞ',
            kaynak_birim: 'DEPO_HAREKET_KUMAS',
            depo: 'GENEL DEPO',
            updated_by: user,
            notlar: `[SEVK_YER:GENEL_DEPO][GENEL_DEPO_GIRIS]${lotTag} Dokuma Depo → Kumaş Stok · Kaynak #${row.id} · ${ts}`,
            islem_gecmisi: `✨ ${ts} — Dokuma Depo → Genel Depo (Kumaş Stok) · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet · Kaynak #${row.id}`
        };
        const gdRes = await sbInsertRetryDropMissing('kumas_stok', [genelPayload]);
        if (gdRes.error) erpToast(`Genel Depo giriş kaydı oluşturulamadı: ${gdRes.error.message}`, 'warn');
    } else if (hedef === 'MUSTERI') {
        const msRes = await sbInsertRetryDropMissing('kumas_stok', [{
            stok_kodu: stokKodu,
            kumas_cinsi: row.kumas_cinsi || '',
            lot_no: lotNo,
            marka: row.marka || '',
            renk: row.renk || '',
            firma: row.firma || '',
            miktar_kg: kg,
            miktar_mt: mt,
            cuval_sayisi: adet,
            islem_turu: 'GİRİŞ',
            kaynak_birim: 'DOKUMA_DEPO_SEVK',
            updated_by: user,
            notlar: `[SEVK_YER:MUSTERI][MUSTERI_SEVK]${lotTag} Kaynak #${row.id} · ${ts}`,
            islem_gecmisi: `✨ ${ts} — Dokuma Depo sevki · Müşteri · ${kg.toFixed(2)} kg / ${mt.toFixed(2)} mt / ${adet} adet`
        }]);
        if (msRes.error) erpToast(`Müşteri sevk kaydı oluşturulamadı: ${msRes.error.message}`, 'warn');
    }

    if (!opts.skipReload) erpSyncTablesBackground(['kumas_stok', 'iplik_stok']);
    let mfNo = '';
    if (hedef === 'MUSTERI') {
        const fis = await dokumaDepoSevkMuhasebeFisHazirla(cikisPayload, cikisId);
        if (fis?.fis_no) mfNo = fis.fis_no;
        try {
            if (typeof sevkiyatKumasCikisSiparisYuklemeIsle === 'function') {
                await sevkiyatKumasCikisSiparisYuklemeIsle([{
                    ...cikisPayload,
                    siparis_id: siparisId || dokumaDepoSiparisIdBul(row),
                    kalem_idx: row.kalem_idx ?? row.not_json?.kalem_idx,
                    lot_no: lotNo,
                    islem_turu: 'ÇIKIŞ'
                }], { kaynak: 'DOKUMA_DEPO_MUSTERI' });
            }
        } catch (e) { console.warn('dokuma müşteri→sipariş yükleme', e); }
    }
    if (!opts.silentToast) {
        erpToast(
            `${hedefLabel} sevki tamamlandı.${kapandi ? '' : ' Kalan miktar depoda.'}${mfNo ? ' Sevkiyat fişi ' + mfNo + ' asıldı.' : ''}`,
            'success'
        );
    }
    if (!opts.skipReload) {
        if (appMode === 'DOKUMA_DEPO' || (appMode === 'SEVKIYAT' && sevkiyatMerkezGrup === 'DOKUMA_DEPO')) dokumaDepoYenileAktifEkran();
        else loadData();
    }
    return true;
}

function depoHareketDefterGrupEtiket(grup) {
    return {
        HEPSİ: 'Tümü',
        IPLIK: 'İplik',
        KUMAS: 'Kumaş',
        MAMUL_DEPO: 'Mamül',
        DOKUMA_TAKIP: 'Dokuma Takip'
    }[grup] || grup;
}
function depoHareketDefterListeBaslik(grup) {
    const g = grup || depoHareketDefterGrup || 'HEPSİ';
    if (g === 'IPLIK') return 'İplik Depo Hareketleri';
    if (g === 'KUMAS') return 'Kumaş Depo Hareketleri';
    if (g === 'MAMUL_DEPO') return 'Mamül Depo Hareketleri';
    if (g === 'DOKUMA_TAKIP') return 'Dokuma Takip Hareketleri';
    return 'Depo Hareketleri';
}
function depoHareketListeAc(grup) {
    depoDefterKanalFiltrele(grup || 'HEPSİ');
}
function depoDefterKanalFiltrele(grup) {
    depoHareketDefterGrup = grup || 'HEPSİ';
    saveUiState({ depoHareketDefterGrup });
    if (typeof setAppMode === 'function') setAppMode('DEPO_HAREKET_LISTE');
    else if (typeof loadData === 'function') loadData();
}
window.depoDefterKanalFiltrele = depoDefterKanalFiltrele;
function depoHareketDefterGrupSec(grup) {
    depoHareketDefterGrup = grup || 'HEPSİ';
    saveUiState({ depoHareketDefterGrup });
    depoHareketDefterBolumLimitSifirla();
    if (appMode === 'DEPO_HAREKET_LISTE') renderDepoHareketDefteri();
    else loadData();
}
function depoHareketDefterTabHtml(aktifGrup) {
    const mk = (grup, emoji, etiket, cls) => {
        const on = aktifGrup === grup ? ' active' : '';
        return `<button type="button" class="depo-defter-tab depo-defter-tab--${cls}${on}" onclick="depoHareketDefterGrupSec('${grup}')">${emoji} ${etiket}</button>`;
    };
    return `<div class="depo-defter-tabs">
        ${mk('HEPSİ', '📋', 'Tümü', 'all')}
        ${mk('IPLIK', '🧶', 'İplik', 'iplik')}
        ${mk('KUMAS', '🏁', 'Kumaş', 'kumas')}
        ${mk('MAMUL_DEPO', '🧥', 'Mamül', 'mamul')}
    </div>`;
}
function depoHareketDefterDetayTip(row, fallback) {
    const fb = String(fallback || '').toUpperCase();
    if (fb === 'KUMAS' || fb === 'MAMUL' || fb === 'IPLIK') return fb;
    if (fb === 'MAMUL_DEPO') return 'MAMUL';
    if (fb === 'DOKUMA_TAKIP') return 'KUMAS';
    const kod = (typeof depoKomutaKanalFromKaynak === 'function'
        ? depoKomutaKanalFromKaynak(row && row.kaynak_birim)
        : {}).kod || '';
    if (kod === 'MAMUL_DEPO') return 'MAMUL';
    if (kod === 'KUMAS' || kod === 'DOKUMA_TAKIP') return 'KUMAS';
    if (kod === 'IPLIK') return 'IPLIK';
    if ((row && row._tbl) === 'iplik_stok' || (row && row.iplik_no != null && String(row.iplik_no).trim() !== '')) return 'IPLIK';
    return 'KUMAS';
}
function depoHareketDefterKalem(row, detayTip) {
    const tip = depoHareketDefterDetayTip(row, detayTip);
    if (tip === 'IPLIK') return null;
    if (typeof muhasebeFisKalemFromPayload === 'function') {
        return muhasebeFisKalemFromPayload(row, tip === 'MAMUL' ? 'MAMUL' : 'KUMAS');
    }
    const kod = String((row && row.stok_kodu) || '').trim();
    return {
        depo_grup: tip === 'MAMUL' ? 'MAMUL' : 'KUMAS',
        stok_kodu: kod,
        urun_adi: (row && (row.urun_adi || row.kumas_cinsi)) || kod,
        urun_grubu: String((row && (row.urun_grubu || row.ana_grup)) || '').trim(),
        kumas_cinsi: String((row && row.kumas_cinsi) || '').trim(),
        terbiye: String((row && row.terbiye) || '').trim(),
        tarak_eni: String((row && row.tarak_eni) || '').trim(),
        atki_sikligi: String((row && row.atki_sikligi) || '').trim(),
        cozgu_sikligi: String((row && row.cozgu_sikligi) || '').trim(),
        atki_ipi: String((row && row.atki_ipi) || '').trim(),
        cozgu_ipi: String((row && row.cozgu_ipi) || '').trim(),
        renk: String((row && row.renk) || '').trim(),
        ebat: String((row && row.ebat) || '').trim(),
        adet: Math.abs(parseInt(row && row.cuval_sayisi, 10) || 0),
        mt: Math.abs(parseFloat(row && row.miktar_mt) || 0),
        kg: Math.abs(parseFloat(row && row.miktar_kg) || 0)
    };
}
function depoHareketDefterTanim(row, detayTip) {
    const tip = depoHareketDefterDetayTip(row, detayTip);
    if (tip === 'IPLIK') {
        return [row && row.iplik_no, row && row.cins].filter(x => x && String(x).trim()).join(' · ') || '—';
    }
    const k = depoHareketDefterKalem(row, tip);
    if (k) {
        if (tip === 'KUMAS') {
            return [k.urun_adi, k.kumas_cinsi, k.terbiye].filter(x => x && String(x).trim()).join(' · ') || '—';
        }
        return [k.urun_adi, k.urun_grubu, k.renk, k.ebat].filter(x => x && String(x).trim()).join(' · ') || '—';
    }
    if (row && row.iplik_no != null && String(row.iplik_no).trim() !== '') {
        return [row.iplik_no, row.cins].filter(x => x && String(x).trim()).join(' · ');
    }
    return [row && (row.kumas_cinsi || row.urun_adi), row && row.renk].filter(x => x && String(x).trim()).join(' · ') || '—';
}
function depoHareketDefterMiktarStr(row, detayTip) {
    const k = depoHareketDefterKalem(row, detayTip);
    if (k && typeof muhasebeFisKalemMiktarYazi === 'function') return muhasebeFisKalemMiktarYazi(k);
    const kg = parseFloat(row && row.miktar_kg) || 0;
    const mt = parseFloat(row && row.miktar_mt) || 0;
    const ad = parseInt(row && row.cuval_sayisi, 10) || 0;
    const parts = [];
    if (Math.abs(mt) > 1e-9) parts.push(`${mt.toLocaleString('tr-TR', { maximumFractionDigits: 3 })} mt`);
    if (Math.abs(kg) > 1e-9) parts.push(`${kg.toLocaleString('tr-TR', { maximumFractionDigits: 3 })} kg`);
    if (Math.abs(ad) > 0) parts.push(`${Math.abs(ad)} top/adet`);
    return parts.join(' · ') || '—';
}
function stokGrupSonHareketTarih(g) {
    const ts = Math.max(g?.son_giris_at || 0, g?.son_cikis_at || 0);
    if (!ts) return '';
    const d = new Date(ts);
    return !isNaN(d.getTime()) ? d.toISOString().slice(0, 10) : '';
}
function stokGrupSonHareketTip(g) {
    const giris = g?.son_giris_at || 0;
    const cikis = g?.son_cikis_at || 0;
    if (cikis > giris) return 'ÇIKIŞ';
    if (giris > cikis) return 'GİRİŞ';
    if (cikis) return 'ÇIKIŞ';
    if (giris) return 'GİRİŞ';
    return '';
}
function stokGrupFiltreEslesir(g, f) {
    f = f || { q: '', tip: 'HEPSİ', bas: '', bit: '' };
    if (f.tip === 'GİRİŞ' || f.tip === 'ÇIKIŞ') {
        if (stokGrupSonHareketTip(g) !== f.tip) return false;
    }
    if (f.bas || f.bit) {
        const ds = stokGrupSonHareketTarih(g);
        if (!ds) return false;
        if (f.bas && ds < f.bas) return false;
        if (f.bit && ds > f.bit) return false;
    }
    return true;
}
