// ── Etkileşim ──
function erpAdminSec(un) {
    erpAdminDurum.secili = un;
    erpAdminDurum.yeniMod = false;
    erpAdminListeCiz();
    erpAdminDetayCiz();
}

function erpAdminAra(val) {
    erpAdminDurum.arama = String(val || '');
    erpAdminListeCiz();
}

function erpAdminYeniAc() {
    erpAdminDurum.yeniMod = true;
    erpAdminDetayCiz();
}

function erpAdminYeniKapat() {
    erpAdminDurum.yeniMod = false;
    erpAdminDetayCiz();
}

function erpAdminRolDegisti(sel) {
    const alan = document.getElementById('kya-yetki-alan');
    if (alan) alan.style.display = sel.value === 'admin' ? 'none' : '';
}

function erpAdminYeniRolDegisti(sel) {
    const alan = document.getElementById('kya-y-yetki');
    if (alan) alan.style.display = sel.value === 'admin' ? 'none' : '';
}

function erpAdminDurumYaz(id, metin, hata) {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = metin || '';
    el.style.color = hata ? '#fca5a5' : 'var(--accent2)';
}

/** p_role destekli kayıt; eski sürüm SQL'de bu parametre yoksa otomatik geri düşer. */
async function erpAdminKayitRpc(gonderi) {
    let r = await sb.rpc('erp_admin_user_save', gonderi);
    if (r.error && /p_role|schema cache|could not find/i.test(r.error.message || '')) {
        const { p_role, ...eski } = gonderi;
        r = await sb.rpc('erp_admin_user_save', eski);
    }
    return r;
}

async function erpAdminKaydet(un) {
    if (!erpCurrentUser || erpCurrentUser.role !== 'admin') return;
    const kok = document.querySelector('.kya-detay[data-kya-user]');
    if (!kok) return;

    const rol = document.getElementById('kya-rol')?.value || 'user';
    const aktif = document.getElementById('kya-aktif')?.checked !== false;
    const ad = (document.getElementById('kya-ad')?.value || '').trim();
    const modlar = rol === 'admin' ? [] : [...kok.querySelectorAll('input.kya-chk:checked')].map(c => c.value);

    erpAdminDurumYaz('kya-durum', 'Kaydediliyor…');
    const { data, error } = await erpAdminKayitRpc({
        p_token: erpGetToken(),
        p_target_username: un,
        p_allowed_modes: modlar,
        p_active: aktif,
        p_display_name: ad || null,
        p_role: rol
    });

    if (error || !data?.ok) {
        const kod = data?.err || '';
        const mesaj = kod === 'kendi_rolu' ? 'Kendi yönetici rolünüzü kaldıramazsınız.'
            : kod === 'bulunamadı' ? 'Kullanıcı bulunamadı.'
            : kod === 'forbidden' ? 'Bu işlem için yönetici oturumu gerekiyor.'
            : (error?.message || kod || 'bilinmiyor');
        erpAdminDurumYaz('kya-durum', 'Hata: ' + mesaj, true);
        return;
    }

    // Kendi hesabıysa anında uygula; diğer kullanıcılara canlı yayın
    if (un.toLowerCase() === String(erpCurrentUser.username || '').toLowerCase()) {
        erpCurrentUser.display_name = ad || erpCurrentUser.username;
        erpCurrentUser.allowed_modes = rol === 'admin' ? [] : modlar;
        erpCurrentUser.role = rol === 'admin' ? 'admin' : 'user';
        erpCurrentUser.active = aktif;
        try { localStorage.setItem('erp_user_cache', JSON.stringify(erpCurrentUser)); } catch (e) {}
        erpUpdateSidebarUser();
        erpApplyNavPermissions();
        if (erpCurrentUser.role === 'admin') {
            erpInjectAdminNav();
            try {
                ['siparis', 'depo', 'sevkiyat', 'dokuma', 'terbiye', 'konfeksiyon', 'fason', 'planlama', 'yonetim']
                    .forEach((p) => erpNavGrupAc(p));
            } catch (e) {}
        }
        try {
            if (erpUserCan('PLANLAMA') || erpUserCan('SEVKIYAT') || erpUserCan('KONFEKSIYON')) erpNavGrupAc('planlama');
            if (erpUserCan('SEVKIYAT')) erpNavGrupAc('sevkiyat');
        } catch (e) {}
    }
    try { erpYetkiBumpYayinla(un); } catch (e) {}
    // Hedef oturum poll’u kaçırırsa diye kısa gecikmeli ikinci uyarı
    try { setTimeout(() => { try { erpYetkiBumpYayinla(un); } catch (e) {} }, 800); } catch (e) {}

    erpAdminDurumYaz('kya-durum', 'Kaydedildi — açık oturumda menü anında güncellenir.');
    const u = erpAdminKullaniciBul(un);
    if (u) { u.allowed_modes = modlar; u.active = aktif; u.display_name = ad; u.role = rol; }
    erpAdminListeCiz();
    setTimeout(() => erpAdminDurumYaz('kya-durum', ''), 4000);
}

async function erpAdminSifre(un) {
    const inp = document.getElementById('kya-sifre');
    const pw = inp?.value || '';
    if (pw.length < 8) { erpAdminDurumYaz('kya-durum', 'Şifre en az 8 karakter olmalı.', true); return; }
    erpAdminDurumYaz('kya-durum', 'Şifre güncelleniyor…');
    const { data, error } = await sb.rpc('erp_admin_user_password', {
        p_token: erpGetToken(),
        p_target_username: un,
        p_new_password: pw
    });
    if (inp) inp.value = '';
    if (error || !data?.ok) {
        erpAdminDurumYaz('kya-durum', 'Hata: ' + (error?.message || data?.err || 'bilinmiyor'), true);
        return;
    }
    erpAdminDurumYaz('kya-durum', 'Şifre güncellendi.');
    setTimeout(() => erpAdminDurumYaz('kya-durum', ''), 3000);
}

async function erpAdminSil(un) {
    const soru = `"${un}" kullanıcısı kalıcı olarak silinsin mi? Açık oturumu da kapanır.`;
    const onay = typeof erpAskConfirm === 'function' ? await erpAskConfirm(soru) : confirm(soru);
    if (!onay) return;

    erpAdminDurumYaz('kya-durum', 'Siliniyor…');
    const { data, error } = await sb.rpc('erp_admin_user_delete', {
        p_token: erpGetToken(),
        p_target_username: un
    });

    if (error && /could not find|schema cache/i.test(error.message || '')) {
        erpAdminDurumYaz('kya-durum', 'Silme özelliği için erp_auth_user_delete.sql çalıştırılmalı.', true);
        return;
    }
    if (error || !data?.ok) {
        const kod = data?.err || '';
        const mesaj = kod === 'son_yonetici' ? 'Son yönetici hesabı silinemez.'
            : kod === 'kendi_hesap' ? 'Kendi hesabınızı silemezsiniz.'
            : (error?.message || kod || 'bilinmiyor');
        erpAdminDurumYaz('kya-durum', 'Hata: ' + mesaj, true);
        return;
    }

    erpAdminDurum.secili = '';
    await renderKullaniciYonetimi();
    try { erpToast('Kullanıcı silindi.'); } catch (e) {}
}

async function erpAdminOlustur() {
    const un = (document.getElementById('kya-y-kadi')?.value || '').trim().toLowerCase();
    const pw = document.getElementById('kya-y-sifre')?.value || '';
    const ad = (document.getElementById('kya-y-ad')?.value || '').trim();
    const rol = document.getElementById('kya-y-rol')?.value || 'user';
    const modlar = rol === 'admin' ? [] : [...document.querySelectorAll('input.kya-yeni-chk:checked')].map(c => c.value);

    if (un.length < 2) { erpAdminDurumYaz('kya-y-durum', 'Kullanıcı adı en az 2 karakter olmalı.', true); return; }
    if (pw.length < 8) { erpAdminDurumYaz('kya-y-durum', 'Şifre en az 8 karakter olmalı.', true); return; }

    erpAdminDurumYaz('kya-y-durum', 'Oluşturuluyor…');
    const { data, error } = await sb.rpc('erp_admin_user_create', {
        p_token: erpGetToken(),
        p_username: un,
        p_password: pw,
        p_display_name: ad || un,
        p_role: rol,
        p_allowed_modes: modlar
    });
    if (error || !data?.ok) {
        /* PGRST203: veritabanında fonksiyonun iki sürümü var (24.09.2026'da yaşandı) —
           ham İngilizce mesaj yerine ne yapılacağını söyle. */
        const ikiSurum = error && (error.code === 'PGRST203' || /could not choose the best candidate/i.test(error.message || ''));
        const mesaj = ikiSurum
            ? 'Veritabanında kullanıcı oluşturma fonksiyonunun iki sürümü var. Supabase SQL Editor\'da supabase/migrations/erp_admin_user_create_tek_surum.sql çalıştırılmalı.'
            : (error?.message || data?.err || 'bilinmiyor');
        erpAdminDurumYaz('kya-y-durum', 'Hata: ' + mesaj, true);
        return;
    }

    erpAdminDurum.yeniMod = false;
    erpAdminDurum.secili = un;
    await renderKullaniciYonetimi();
    try { erpToast('Kullanıcı oluşturuldu.'); } catch (e) {}
}

// Diagnostics log
window._diagLog = window._diagLog || [];
function diagLog(msg, level='INFO') {
    const ts = new Date().toLocaleTimeString('tr-TR');
    const line = `[${ts}] ${level === 'ERR' ? '❌' : level === 'OK' ? '✅' : level === 'WARN' ? '⚠️' : 'ℹ'} ${msg}`;
    window._diagLog.unshift(line);
    if (window._diagLog.length > 100) window._diagLog.pop();
    const logEl = document.getElementById('diag-log');
    if (logEl) logEl.textContent = window._diagLog.join('\n');
}

function diagClearLog() {
    window._diagLog = [];
    const logEl = document.getElementById('diag-log');
    if (logEl) logEl.textContent = '— Log temizlendi —';
}


let _erpDesktopUpdateUnsub = null;
let _erpDesktopUpdateState = { phase: 'idle', version: '', percent: 0, message: '' };
let _erpUpdateModalInfo = null;
let _erpUpdateModalDismissed = false;
let _erpUpdateApplying = false;
let _erpUpdateAutoInstallTimer = null;
let _erpUpdateExpectExe = false;
let _erpUpdatePollTimer = null;
const ERP_UPDATE_POLL_MS = 3 * 60 * 1000;

/** Tek API: Supabase güncellemesi var mı? (EXE + arayüz birlikte) */
async function erpDesktopCheckUpdates() {
    if (!window.erpDesktop?.isElectron) return null;
    try {
        if (typeof window.erpDesktop.checkAllUpdates === 'function') {
            return await window.erpDesktop.checkAllUpdates();
        }
        if (typeof window.erpDesktop.checkForUpdates === 'function') {
            const r = await window.erpDesktop.checkForUpdates();
            return {
                ok: !!r?.ok,
                current: r?.current,
                version: r?.version,
                hasUpdate: !!(r?.updateAvailable || r?.hasUpdate),
                content: r?.content || { available: false },
                exe: r?.exe || {
                    available: !!r?.updateAvailable,
                    version: r?.version,
                    current: r?.current,
                    via: r?.via || null
                },
                message: r?.message || null
            };
        }
    } catch (e) {
        console.warn('erpDesktopCheckUpdates', e);
        return { ok: false, hasUpdate: false, message: e?.message || String(e) };
    }
    return null;
}

async function erpDesktopStartDownload(info) {
    const content = !!info?.content?.available;
    const exe = !!info?.exe?.available;
    if (typeof window.erpDesktop?.startUpdateDownload === 'function') {
        return window.erpDesktop.startUpdateDownload({ content, exe });
    }
    if (content && typeof window.erpDesktop?.syncContent === 'function') {
        return window.erpDesktop.syncContent();
    }
    throw new Error('Güncelleme indirme desteklenmiyor — uygulamayı yeniden kurun');
}

function erpUpdateModalEnsure() {
    let el = document.getElementById('erp-update-modal');
    if (el) return el;
    el = document.createElement('div');
    el.id = 'erp-update-modal';
    el.setAttribute('role', 'dialog');
    el.setAttribute('aria-modal', 'true');
    el.style.cssText = 'display:none;position:fixed;inset:0;z-index:2147483000;background:rgba(6,10,20,0.78);backdrop-filter:blur(10px);align-items:center;justify-content:center;padding:16px;box-sizing:border-box';
    el.innerHTML = `
    <div style="background:var(--surface,#12182a);border:1px solid var(--border,#2a3550);border-radius:16px;padding:28px 32px;max-width:420px;width:100%;box-shadow:0 24px 60px rgba(0,0,0,0.45);text-align:center">
        <div style="font-size:11px;font-weight:700;color:var(--accent,#6d71ff);letter-spacing:0.12em;text-transform:uppercase;margin-bottom:8px;font-family:'DM Mono',monospace">Simteks Tekstil ERP</div>
        <h2 style="margin:0 0 8px;font-size:1.15rem;color:var(--text,#e8ecf4)">Güncelleme mevcut</h2>
        <p id="erp-update-modal-desc" style="margin:0 0 6px;font-size:0.9rem;color:var(--text2,#94a3b8);line-height:1.55"></p>
        <p id="erp-update-modal-ver" style="margin:0 0 20px;font-size:0.82rem;color:var(--text3,#64748b);font-family:'DM Mono',monospace"></p>
        <div id="erp-update-modal-progress" style="display:none;margin-bottom:18px">
            <div style="height:6px;background:var(--surface2,#1a2236);border-radius:99px;overflow:hidden">
                <div id="erp-update-modal-bar" style="height:100%;width:0%;background:linear-gradient(90deg,var(--accent,#6d71ff),#22c55e);transition:width 0.25s"></div>
            </div>
            <div id="erp-update-modal-progress-text" style="font-size:10px;color:var(--text3);margin-top:8px;font-family:'DM Mono',monospace">—</div>
        </div>
        <div id="erp-update-modal-actions" style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap">
            <button type="button" id="erp-update-btn-yukle" style="padding:10px 22px;background:var(--accent,#6d71ff);color:#fff;border:none;border-radius:9px;font-size:11px;font-weight:700;cursor:pointer;font-family:'DM Mono',monospace">Güncelleme yükle</button>
            <button type="button" id="erp-update-btn-later" style="padding:10px 20px;background:transparent;color:var(--text2);border:1px solid var(--border);border-radius:9px;font-size:11px;font-weight:600;cursor:pointer;font-family:'DM Mono',monospace">Daha sonra</button>
        </div>
        <div id="erp-update-modal-install" style="display:none;margin-top:4px">
            <p id="erp-update-modal-install-hint" style="margin:0 0 12px;font-size:0.82rem;color:var(--text2,#94a3b8);line-height:1.5">Güncelleme uygulanıyor, uygulama kapanıp yeniden açılacak…</p>
            <button type="button" id="erp-update-btn-install" style="padding:10px 22px;background:#22c55e;color:#fff;border:none;border-radius:9px;font-size:11px;font-weight:700;cursor:pointer;font-family:'DM Mono',monospace;width:100%">Şimdi uygula ve yeniden aç</button>
        </div>
    </div>`;
    document.body.appendChild(el);
    el.querySelector('#erp-update-btn-later').addEventListener('click', () => {
        _erpUpdateModalDismissed = true;
        erpUpdateModalHide();
    });
    el.querySelector('#erp-update-btn-yukle').addEventListener('click', () => erpApplyDesktopUpdate());
    el.querySelector('#erp-update-btn-install').addEventListener('click', () => erpUpdateRunInstall());
    return el;
}

function erpUpdateModalHide() {
    const el = document.getElementById('erp-update-modal');
    if (el) el.style.display = 'none';
}

function erpUpdateModalShow(info) {
    const el = erpUpdateModalEnsure();
    _erpUpdateModalInfo = info;
    const cur = info?.current || '?';
    const neu = info?.version || '?';
    el.querySelector('#erp-update-modal-desc').textContent = 'Sunucuya yeni sürüm yüklendi. Güncellemeyi şimdi yükleyebilirsiniz.';
    el.querySelector('#erp-update-modal-ver').textContent = `Kurulu: v${cur}  →  Yeni: v${neu}`;
    el.querySelector('#erp-update-modal-progress').style.display = 'none';
    el.querySelector('#erp-update-modal-actions').style.display = 'flex';
    el.querySelector('#erp-update-modal-install').style.display = 'none';
    el.querySelector('#erp-update-btn-yukle').disabled = false;
    el.style.display = 'flex';
}

function erpUpdateModalSetProgress(text, pct) {
    const el = document.getElementById('erp-update-modal');
    if (!el) return;
    el.querySelector('#erp-update-modal-actions').style.display = 'none';
    el.querySelector('#erp-update-modal-install').style.display = 'none';
    el.querySelector('#erp-update-modal-progress').style.display = 'block';
    const bar = el.querySelector('#erp-update-modal-bar');
    const txt = el.querySelector('#erp-update-modal-progress-text');
    if (bar) bar.style.width = `${Math.max(0, Math.min(100, pct || 0))}%`;
    if (txt) txt.textContent = text || '—';
    el.style.display = 'flex';
}

function erpUpdateAutoInstallCancel() {
    if (_erpUpdateAutoInstallTimer) {
        clearInterval(_erpUpdateAutoInstallTimer);
        _erpUpdateAutoInstallTimer = null;
    }
}

async function erpUpdateRunInstall() {
    erpUpdateAutoInstallCancel();
    const hint = document.getElementById('erp-update-modal-install-hint');
    if (hint) hint.textContent = 'Güncelleme uygulanıyor, uygulama kapanıp yeni sürümle açılacak…';
    const btn = document.getElementById('erp-update-btn-install');
    if (btn) btn.disabled = true;
    try {
        await window.erpDesktop?.installUpdate?.();
    } catch (e) {
        if (btn) btn.disabled = false;
        if (hint) hint.textContent = 'Uygulanamadı — «Şimdi uygula ve yeniden aç» ile tekrar deneyin.';
        erpToast(`Güncelleme hatası: ${e?.message || e}`, 'error', 6000);
    }
}

function erpUpdateModalShowInstall(version) {
    const el = erpUpdateModalEnsure();
    const ver = version || '?';
    el.querySelector('#erp-update-modal-desc').textContent = `Güncelleme indirildi (v${ver}). Sıfırdan kurulum yok; uygulama kapanıp yeni sürümle açılacak.`;
    el.querySelector('#erp-update-modal-progress').style.display = 'none';
    el.querySelector('#erp-update-modal-actions').style.display = 'none';
    el.querySelector('#erp-update-modal-install').style.display = 'block';
    const hint = el.querySelector('#erp-update-modal-install-hint');
    const btn = el.querySelector('#erp-update-btn-install');
    if (btn) btn.disabled = false;
    el.style.display = 'flex';

    erpUpdateAutoInstallCancel();
    let kalan = 2;
    if (hint) hint.textContent = `Uygulama ${kalan} saniye içinde kapanıp yeni sürümle açılacak…`;
    _erpUpdateAutoInstallTimer = setInterval(() => {
        kalan -= 1;
        if (kalan > 0) {
            if (hint) hint.textContent = `Uygulama ${kalan} saniye içinde kapanıp yeni sürümle açılacak…`;
            return;
        }
        erpUpdateRunInstall();
    }, 1000);
}

async function erpOfferDesktopUpdateOnStart() {
    if (!window.erpDesktop?.isElectron || _erpUpdateModalDismissed || _erpUpdateApplying) return;
    try {
        const info = await erpDesktopCheckUpdates();
        if (!info?.hasUpdate) return;
        erpUpdateModalShow(info);
    } catch (e) {}
}

async function erpApplyDesktopUpdate() {
    if (_erpUpdateApplying || !_erpUpdateModalInfo) return;
    _erpUpdateApplying = true;
    const info = _erpUpdateModalInfo;
    _erpUpdateExpectExe = !!info?.exe?.available;
    const btn = document.getElementById('erp-update-btn-yukle');
    if (btn) btn.disabled = true;
    erpUpdateModalSetProgress('Güncelleme indiriliyor…', 2);
    try {
        await erpDesktopStartDownload(info);
    } catch (e) {
        erpToast(`Güncelleme hatası: ${e?.message || e}`, 'error', 5000);
        _erpUpdateApplying = false;
        _erpUpdateExpectExe = false;
        if (btn) btn.disabled = false;
        erpUpdateModalShow(info);
    }
}

function erpDesktopUpdateHandleStatus(p) {
    if (!p || !window.erpDesktop?.isElectron) return;
    const phase = String(p.phase || '');
    if (phase === 'downloading' || phase === 'content-downloading') {
        const pct = Math.round(p.percent || 0);
        erpUpdateModalSetProgress(`Güncelleme indiriliyor… %${pct}`, pct);
    } else if ((phase === 'ready' && p.kind === 'content') || phase === 'content-ready') {
        if (_erpUpdateExpectExe) {
            erpUpdateModalSetProgress('Dosyalar güncellendi, kurulum paketi indiriliyor…', 55);
            return;
        }
        _erpUpdateApplying = false;
        erpUpdateModalSetProgress('Güncelleme uygulandı, yenileniyor…', 100);
        setTimeout(() => { try { window.erpDesktop?.reloadWindow?.(); } catch (e) { location.reload(); } }, 700);
    } else if (phase === 'ready' && (p.kind === 'exe' || !p.kind)) {
        _erpUpdateApplying = false;
        _erpUpdateExpectExe = false;
        erpUpdateModalShowInstall(p.version);
    } else if (phase === 'error' || phase === 'content-error') {
        _erpUpdateApplying = false;
        _erpUpdateExpectExe = false;
        erpToast(`Güncelleme hatası: ${p.message || ''}`, 'error', 5500);
        if (_erpUpdateModalInfo) erpUpdateModalShow(_erpUpdateModalInfo);
    }
}


async function erpInitDesktopAutoUpdate() {
    if (!window.erpDesktop?.isElectron) return;
    if (_erpDesktopUpdateUnsub) {
        try { _erpDesktopUpdateUnsub(); } catch (e) {}
    }
    if (typeof window.erpDesktop.onUpdateStatus === 'function') {
        _erpDesktopUpdateUnsub = window.erpDesktop.onUpdateStatus((payload) => {
            const p = payload || {};
            _erpDesktopUpdateState = { ..._erpDesktopUpdateState, ...p };
            erpDesktopUpdateHandleStatus(p);
        });
    }
    await erpOfferDesktopUpdateOnStart();
    if (_erpUpdatePollTimer) clearInterval(_erpUpdatePollTimer);
    _erpUpdatePollTimer = setInterval(() => {
        if (document.hidden || _erpUpdateApplying || _erpUpdateModalDismissed) return;
        const open = document.getElementById('erp-update-modal');
        if (open && open.style.display === 'flex') return;
        erpOfferDesktopUpdateOnStart();
    }, ERP_UPDATE_POLL_MS);
}


async function runAllDiagnostics() {
    diagLog('Tanılama başlatıldı…');

    // ── ① Bağlantı ──
    const connEl = document.getElementById('diag-conn');
    try {
        const t0 = performance.now();
        const { data, error } = await sb.from('siparisler').select('id').limit(1);
        const ms = Math.round(performance.now() - t0);
        if (error) throw error;
        if (connEl) connEl.innerHTML = `<div style="width:8px;height:8px;border-radius:50%;background:#22c55e"></div><span style="font-size:11px;color:#22c55e;font-weight:600">Bağlı</span><span style="font-size:10px;color:var(--text3);margin-left:6px">${ms} ms</span>`;
        diagLog(`Supabase bağlantısı OK (${ms}ms)`, 'OK');
    } catch(e) {
        if (connEl) connEl.innerHTML = `<div style="width:8px;height:8px;border-radius:50%;background:#ef4444"></div><span style="font-size:11px;color:#ef4444;font-weight:600">BAĞLANTI HATASI</span><span style="font-size:10px;color:var(--text3);margin-left:8px">${e.message}</span>`;
        diagLog(`Bağlantı hatası: ${e.message}`, 'ERR');
    }

    // ── ② Tablo erişimleri ──
    const tables = ['iplik_stok','kumas_stok','kumas_kutuphanesi','siparisler','tezgahlar','siparis_akis'];
    let siparisAkisOk = false;
    for (const tbl of tables) {
        const rowEl = document.getElementById(`diag-tbl-${tbl}`);
        const statusEl = document.getElementById(`diag-tbl-${tbl}-status`);
        try {
            const t0 = performance.now();
            const { data, error, count } = await sb.from(tbl).select('*', {count:'exact',head:true});
            const ms = Math.round(performance.now() - t0);
            if (error) throw error;
            if (tbl === 'siparis_akis') siparisAkisOk = true;
            const dot = rowEl?.querySelector('div[style*="border-radius:50%"]');
            if (dot) dot.style.background = '#22c55e';
            if (statusEl) statusEl.innerHTML = `<span style="color:#22c55e;font-weight:700">${count ?? '?'} kayıt</span> <span style="color:var(--text3)">${ms}ms</span>`;
            diagLog(`${tbl}: ${count} kayıt (${ms}ms)`, 'OK');
        } catch(e) {
            const dot = rowEl?.querySelector('div[style*="border-radius:50%"]');
            if (dot) dot.style.background = '#ef4444';
            if (statusEl) statusEl.innerHTML = `<span style="color:#ef4444;font-weight:700">HATA</span>`;
            diagLog(`${tbl} hatası: ${e.message}`, 'ERR');
        }
    }

    const fixPanel = document.getElementById('diag-fix-panel');
    if (fixPanel) {
        fixPanel.style.display = siparisAkisOk ? 'none' : '';
    }

    // ── ③ localStorage & canlı senkron ──
    const localEl = document.getElementById('diag-local');
    if (localEl) {
        const lines = [];
        let lsOk = false;
        try {
            const probeKey = '__erp_diag_ls_probe__';
            const probeVal = String(Date.now());
            if (typeof erpLsSet === 'function') lsOk = erpLsSet(probeKey, probeVal);
            else { localStorage.setItem(probeKey, probeVal); lsOk = localStorage.getItem(probeKey) === probeVal; }
            localStorage.removeItem(probeKey);
        } catch (e) {
            lsOk = false;
            lines.push(`<span style="color:#ef4444">localStorage yazılamıyor: ${e.message || e}</span>`);
        }
        if (lsOk) lines.push('<span style="color:#22c55e">localStorage yazma OK</span>');

        try {
            const raw = localStorage.getItem(typeof ERP_DATA_CACHE_LS_KEY !== 'undefined' ? ERP_DATA_CACHE_LS_KEY : 'erp_data_cache_v3');
            if (raw) {
                const parsed = JSON.parse(raw);
                const ageMin = parsed._savedAt ? Math.round((Date.now() - parsed._savedAt) / 60000) : null;
                const sipN = Array.isArray(parsed.siparisler) ? parsed.siparisler.length : 0;
                lines.push(`Disk önbelleği: ${sipN} sipariş${ageMin != null ? ` · ${ageMin} dk önce` : ''}`);
            } else {
                lines.push('Disk önbelleği: boş (ilk açılış normal)');
            }
        } catch (e) {
            lines.push(`Disk önbelleği okunamadı: ${e.message || e}`);
        }

        const liveOn = typeof _erpLiveStarted !== 'undefined' && _erpLiveStarted;
        const pollOn = typeof _erpDataPollTimer !== 'undefined' && _erpDataPollTimer;
        lines.push(liveOn
            ? '<span style="color:#22c55e">Canlı senkron: REALTIME aktif</span>'
            : (pollOn ? '<span style="color:#f59e0b">Canlı senkron: POLL yedek</span>' : '<span style="color:var(--text3)">Canlı senkron: henüz başlamadı</span>'));

        if (typeof editingId !== 'undefined' && editingId != null) {
            lines.push('<span style="color:#f59e0b">Açık düzenleme formu var — arka plan yenilemesi bekletiliyor</span>');
        }

        localEl.innerHTML = lines.join('<br>');
        diagLog(lsOk ? 'localStorage OK' : 'localStorage sorunlu', lsOk ? 'OK' : 'WARN');
    }

    // ── ④ siparis_akis kolonu kontrol ──
    try {
        const { data, error } = await sb.from('siparis_akis').select('id,siparis_id,islem,kalem_ad,miktar,notlar').limit(1);
        if (error) throw error;
        diagLog('siparis_akis kolon yapısı OK (id, siparis_id, islem, kalem_ad, miktar, notlar)', 'OK');
    } catch(e) {
        diagLog(`siparis_akis kolon eksik: ${e.message}`, 'WARN');
    }

    diagLog('Tanılama tamamlandı.');
}

