async function konfYikamaKaydet() {
    if (!konfeksiyonSiparisId) return;
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    const yikEl = document.getElementById('kf-yikama');
    const sevkEl = document.getElementById('kf-yikama-sevk');
    const gelEl = document.getElementById('kf-yikama-gelen');
    const notEl = document.getElementById('kf-yikama-not');
    if (yikEl) kd.yikama_yapildi = yikEl.checked;
    if (sevkEl) kd.panel_yikama_sevk = parseInt(sevkEl.value || 0, 10) || 0;
    if (gelEl) kd.panel_yikama_gelen = parseInt(gelEl.value || 0, 10) || 0;
    if (notEl) kd.yikama_not = notEl.value;
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
    erpToast('Yıkama bilgileri kaydedildi.', 'success');
    renderKonfeksiyon();
}

function konfKalemKey(k = {}) {
    return [konfNormTxt(k.ad || k.kod || ''), konfNormTxt(k.renk || ''), konfNormTxt(k.ebat || k.olcu || '')].join('|');
}


function konfPipelineKalemIdxFromDepoRow(siparisId, row) {
    const kalemler = konfGetSiparisKalemlerById(siparisId);
    const tryIdx = (v) => {
        const i = parseInt(v, 10);
        return Number.isFinite(i) && i >= 0 && i < kalemler.length ? i : -1;
    };
    let idx = tryIdx(row?.kalem_idx);
    if (idx >= 0) return idx;
    const ref = (row?.kalem_refs || []).find(x => String(x.siparis_id) === String(siparisId));
    idx = tryIdx(ref?.kalem_idx);
    if (idx >= 0) return idx;
    const renk = konfNormTxt(row?.renk || '');
    const etiket = row?.kumas_cinsi || row?.stok_kodu || '';
    if (renk) {
        const renkEslesen = kalemler
            .map((k, i) => ({ k, i }))
            .filter(({ k }) => konfNormTxt(k.renk) === renk);
        if (renkEslesen.length === 1) return renkEslesen[0].i;
        if (renkEslesen.length > 1 && etiket) {
            const dar = renkEslesen.find(({ k }) => {
                const ad = konfNormTxt(k.ad || k.kod || '');
                const et = konfNormTxt(etiket);
                return ad && (et.includes(ad) || ad.includes(et.slice(0, 14)));
            });
            if (dar) return dar.i;
        }
    }
    return konfFindKalemIndexEsnek(kalemler, etiket);
}

function konfPipelineKalemMeta(siparisId, j, kalemAd) {
    const kalemler = konfGetSiparisKalemlerById(siparisId);
    let idx = parseInt(j?.kalem_idx, 10);
    if (!Number.isFinite(idx) || idx < 0 || idx >= kalemler.length) {
        if (j?.kalem_key) {
            idx = kalemler.findIndex(k => konfNormTxt(konfKalemKey(k)) === konfNormTxt(j.kalem_key));
        }
        if (idx < 0) idx = konfFindKalemIndexEsnek(kalemler, j?.kumas_cinsi || j?.stok_kodu || kalemAd || '');
    }
    if (idx < 0 || idx >= kalemler.length) return { idx: -1, kalem: null };
    return { idx, kalem: kalemler[idx] };
}

function konfPipelineKalemNotMeta(siparisId, row) {
    const kalemIdx = konfPipelineKalemIdxFromDepoRow(siparisId, row);
    const kalemler = konfGetSiparisKalemlerById(siparisId);
    const kalem = kalemIdx >= 0 ? kalemler[kalemIdx] : (row?.kalem || null);
    return {
        kalem_idx: kalemIdx >= 0 ? kalemIdx : null,
        kalem_renk: kalem?.renk || row?.renk || '',
        kalem_ebat: kalem?.ebat || kalem?.olcu || '',
        kalem_key: kalem ? konfKalemKey(kalem) : ''
    };
}

/**
 * Sevkiyat + konfeksiyon + depo verilerini birleştirir — sipariş durum ekranı için tek hazırlık noktası.
 */
async function siparisDurumVerileriniHazirla(siparisId, opts = {}) {
    const sid = String(siparisId || '').trim();
    if (!sid) return;
    const force = !!(opts && opts.force);

    /* Bu dort yukleme birbirinden bagimsiz. Sirali beklendiginde her biri ayri
       bir gidis-gelis ekliyor ve ekran gec aciliyor; tek turda calistiriyoruz. */
    const kdTtl = force ? 0 : (typeof KD_SOFT_TTL_MS === 'number' ? KD_SOFT_TTL_MS : 90000);
    await Promise.all([
        (async () => {
            try {
                if (typeof sevkiyatSiparisDepoHareketleriYukle === 'function') {
                    await sevkiyatSiparisDepoHareketleriYukle(sid);
                }
            } catch (e) { console.warn('siparisDurumVerileriniHazirla depo', e); }
        })(),
        (async () => {
            try {
                if (typeof sbKdGetTipler === 'function') {
                    await sbKdGetTipler(sid, ['KD_KONFEKSIYON', 'KD_DOKUMA', 'KD_URUN_AGACI', 'KD_FASON_TAKIP'], { ttl: kdTtl });
                }
            } catch (e) {}
        })(),
        (async () => {
            /* skipRotaDuzelt: rota onarimi bir veri duzeltme isi, konfeksiyon
               ekranlarinda calisiyor. Durum incelemesi salt okuma — burada
               butun siparislerin urun agacini indirip yazma yapmasin. */
            try {
                if (typeof konfLoadKesimGecmis === 'function') {
                    await konfLoadKesimGecmis({ force, skipRotaDuzelt: true });
                }
            } catch (e) {}
        })(),
        (async () => {
            /* skipUa: urun agaci isitmasi yalniz pipeline ekrani icin gerekli. */
            try {
                if (typeof konfLoadGlobalKumasGelis === 'function') {
                    await konfLoadGlobalKumasGelis({ force, skipUa: true });
                }
            } catch (e) {}
        })(),
        (async () => {
            try {
                if (typeof konfLoadIslemLog === 'function') {
                    await konfLoadIslemLog(sid);
                }
            } catch (e) { console.warn('siparisDurumVerileriniHazirla islem log', e); }
        })()
    ]);

    /* Bu ikisi yukaridaki veriye dayanir, sirali kalmali. */
    let yazildi = false;
    try {
        if (typeof konfPipelineSiparisDurumSenkron === 'function') {
            yazildi = await konfPipelineSiparisDurumSenkron(sid, { sevkMutlak: false, skipLogYenile: true }) || yazildi;
        }
    } catch (e) { console.warn('siparisDurumVerileriniHazirla sync', e); }
    try {
        if (typeof sevkiyatSiparisYuklemeKdDepodanOnar === 'function') {
            yazildi = await sevkiyatSiparisYuklemeKdDepodanOnar(sid, { hazirVeri: true }) || yazildi;
        }
    } catch (e) { console.warn('siparisDurumVerileriniHazirla yukleme onar', e); }

    /* Islem logu bastan okundu; yalnizca gercekten bir yazma olduysa tazele. */
    if (yazildi) {
        try {
            if (typeof konfLoadIslemLog === 'function') await konfLoadIslemLog(sid);
        } catch (e) { console.warn('siparisDurumVerileriniHazirla islem log 2', e); }
    }
}
try { window.siparisDurumVerileriniHazirla = siparisDurumVerileriniHazirla; } catch (e) {}

/**
 * Açık sipariş detay modalında konfeksiyon toplamlarını yenile (özet + durum).
 * Kesim / yıkama / kalite / dikim / yükleme — Konfeksiyon veya Sevkiyat kaydı sonrası.
 */
async function siparisDetayYuklemeYenile(siparisId) {
    const sid = String(siparisId || '').trim();
    if (!sid) return;
    const modal = document.getElementById('detail-modal');
    if (!modal || modal.style.display === 'none') return;
    const sip = (typeof currentData !== 'undefined' && selectedIndex != null && currentData[selectedIndex]
        && String(currentData[selectedIndex].id) === sid)
        ? currentData[selectedIndex]
        : (dataCache.siparisler || []).find(s => String(s.id) === sid);
    if (!sip || !sip.sno) return;
    try {
        if (typeof siparisDurumVerileriniHazirla === 'function') {
            await siparisDurumVerileriniHazirla(sid);
        }
    } catch (e) { console.warn('siparisDetayYuklemeYenile hazirla', e); }
    const oz = document.getElementById('siparis-modal-tab-ozet');
    if (oz && typeof buildSiparisDetailModalHtml === 'function') {
        try { oz.innerHTML = buildSiparisDetailModalHtml(sip, { embedKonf: true }); } catch (e) {}
    }
    const du = document.getElementById('siparis-modal-tab-durum');
    if (du && du.style.display !== 'none' && typeof siparisDetailModalBaslatDurumTab === 'function') {
        try { await siparisDetailModalBaslatDurumTab(sip, true); } catch (e) {}
    }
}
try { window.siparisDetayYuklemeYenile = siparisDetayYuklemeYenile; } catch (e) {}
/** Alias — konf manuel kayıt sonrası aynı yenileme */
try { window.siparisDetayKonfYenile = siparisDetayYuklemeYenile; } catch (e) {}

async function konfDurumTabYenile(siparisId) {
    if (typeof siparisDetayYuklemeYenile === 'function') {
        await siparisDetayYuklemeYenile(siparisId);
        return;
    }
    const du = document.getElementById('siparis-modal-tab-durum');
    if (!du || du.style.display === 'none') return;
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (sip) await siparisDetailModalBaslatDurumTab(sip, true);
}

/** Akış notundan silinmiş / iptal satır mı? (panel soft-delete) */
function konfAkisSatirSilindiMi(r) {
    const j = r?.not_json || (() => {
        try { return JSON.parse(r?.notlar || '{}') || {}; } catch (e) { return {}; }
    })();
    return !!(j.panel_silindi || j.silindi);
}

/**
 * Dokuma Depo pipeline + ana ERP + konfeksiyon paneli manuel girişlerini
 * KD_KONFEKSIYON'a birleştirir. İki programdan girilen adetler toplanır (çift sayım yok:
 * pipeline çocuk satırları kumas_gelis_id ile atlanır, KUMAS_GELIS kümülatifi kullanılır).
 * Sevk: KUMAS_GELIS varsa sevkMutlak ile mutlak (düşürme geri şişmez); detay açılışında Math.max.
 * opts.sevkMutlak: panel_sevk_toplam mutlak yaz (yalnızca Sevkiyat yazımı). Non-mutlak her zaman Math.max —
 *   anyGelisSevk iken sevkTop düşük kalsa bile Sevkiyat yüklemesini silme.
 */
async function konfPipelineSiparisDurumSenkron(siparisId, opts = {}) {
    if (!siparisId) return;
    const sevkMutlak = !!opts.sevkMutlak;
    const kalemler = konfGetSiparisKalemlerById(siparisId);
    const { data, error } = await sb.from('siparis_akis')
        .select('id,islem,kalem_ad,miktar,notlar')
        .eq('siparis_id', siparisId)
        .in('islem', [
            'KUMAS_GELIS', 'KESIM', 'KESİM', 'DIKIM', 'DİKİM', 'YIKAMA_SEVK', 'YIKAMA_GELEN', 'YIKAMA',
            'KK_GECEN', 'KALITE', 'KALİTE', 'KALİTE KONTROL', 'KALITE KONTROL', 'KOLI', 'KOLİ', 'KONF_SEVK', 'SEVK'
        ]);
    if (error) return;

    const per = {};
    kalemler.forEach((_, i) => {
        per[i] = {
            kesilen: 0, dikilen: 0, yikSevk: 0, yikGel: 0, kkGec: 0, koli: 0,
            sevkGelis: 0, sevkLog: 0, hasGelisSevk: false
        };
    });
    let panelYikSevk = 0;
    let panelYikGel = 0;

    (data || []).forEach(r => {
        let j = {};
        try { j = JSON.parse(r.notlar || '{}') || {}; } catch (e) {}
        if (j.panel_silindi || j.silindi) return;
        const islem = String(r.islem || '').toUpperCase().replace(/İ/g, 'I');
        const meta = konfPipelineKalemMeta(siparisId, j, r.kalem_ad);
        const ki = meta.idx;
        const mik = parseFloat(r.miktar) || 0;

        if (islem === 'KUMAS_GELIS') {
            if (ki >= 0) {
                per[ki].kesilen += parseInt(j.kesilen_adet || 0, 10) || 0;
                per[ki].yikSevk += parseInt((j.yikama_sevk_adet ?? j.yikama_bekleyen_adet) || 0, 10) || 0;
                per[ki].yikGel += parseInt(j.yikama_gelen_adet || 0, 10) || 0;
                per[ki].kkGec += parseInt(j.kalite_gecen_adet || 0, 10) || 0;
                per[ki].sevkGelis += parseInt(j.sevk_edilen_adet || 0, 10) || 0;
                per[ki].hasGelisSevk = true;
            }
            panelYikSevk += parseInt((j.yikama_sevk_adet ?? j.yikama_bekleyen_adet) || 0, 10) || 0;
            panelYikGel += parseInt(j.yikama_gelen_adet || 0, 10) || 0;
            return;
        }
        /* Pipeline çocuk satırları KUMAS_GELIS kümülatifinde (kesim/yıkama/kk) var.
           KONF_SEVK/SEVK için toplam_sevk veya miktar yine yüklemeye yazılır — atlama. */
        if (j.kumas_gelis_id && islem !== 'KONF_SEVK' && islem !== 'SEVK') return;
        if (ki < 0) return;
        /* GEÇİCİ eşleme satırları yikSevk üzerinden max ile gelir — çift sayma */
        if (islem === 'KESIM' && !j.gecici_yikama_kesim_esle) per[ki].kesilen += mik;
        else if (islem === 'DIKIM') per[ki].dikilen += mik;
        else if (islem === 'YIKAMA_SEVK' || islem === 'YIKAMA') {
            per[ki].yikSevk += mik;
            panelYikSevk += mik;
        } else if (islem === 'YIKAMA_GELEN') {
            per[ki].yikGel += mik;
            panelYikGel += mik;
        } else if (islem === 'KK_GECEN' || islem === 'KALITE' || islem === 'KALITE KONTROL') per[ki].kkGec += mik;
        else if (islem === 'KOLI') per[ki].koli += mik;
        else if (islem === 'KONF_SEVK' || islem === 'SEVK') {
            const toplamSevk = parseInt(j.toplam_sevk, 10);
            if (Number.isFinite(toplamSevk) && toplamSevk >= 0) {
                per[ki].sevkLog = Math.max(per[ki].sevkLog, Math.round(toplamSevk));
            } else {
                per[ki].sevkLog += mik;
            }
        }
    });

    /* Yeni konf_kesim_yikama tablosu — kesim adetlerinin asıl kaynağı (çift sayma: max) */
    try {
        const kyBuSiparis = (_konfKesimGecmisCache || []).some((k) => String(k.siparis_id) === String(siparisId));
        if ((!kyBuSiparis || !(_konfKesimGecmisCache || []).length) && typeof konfLoadKesimGecmis === 'function') {
            await konfLoadKesimGecmis({ force: true });
        }
        const kyPer = {};
        let kyYikSevk = 0;
        let kyYikGel = 0;
        (_konfKesimGecmisCache || []).forEach((k) => {
            if (String(k.siparis_id) !== String(siparisId)) return;
            if (k.aktif === false) return;
            let ki = parseInt(k.kalem_idx, 10);
            if (!Number.isFinite(ki) || ki < 0) {
                ki = konfUaKalemIdxCoz(siparisId, k.kalem_idx, k.desen);
            }
            if (ki == null || ki < 0 || !per[ki]) return;
            if (!kyPer[ki]) kyPer[ki] = { kesilen: 0, yikSevk: 0, yikGel: 0 };
            kyPer[ki].kesilen += parseInt(k.kesilen_adet || k.miktar || 0, 10) || 0;
            const sevk = parseInt(k.yikama_sevk_adet, 10) || 0;
            const gel = parseInt(k.yikama_gelen_adet, 10) || 0;
            kyPer[ki].yikSevk += sevk;
            kyPer[ki].yikGel += gel;
            kyYikSevk += sevk;
            kyYikGel += gel;
        });
        Object.keys(kyPer).forEach((kiStr) => {
            const ki = parseInt(kiStr, 10);
            const p = per[ki];
            const ky = kyPer[ki];
            if (!p || !ky) return;
            p.kesilen = Math.max(p.kesilen, ky.kesilen);
            p.yikSevk = Math.max(p.yikSevk, ky.yikSevk);
            p.yikGel = Math.max(p.yikGel, ky.yikGel);
        });
        panelYikSevk = Math.max(panelYikSevk, kyYikSevk);
        panelYikGel = Math.max(panelYikGel, kyYikGel);
    } catch (e) { console.warn('konfPipelineSiparisDurumSenkron ky', e); }

    const kd = (await sbKdGet(siparisId, 'KD_KONFEKSIYON')) || {};
    /* Yazmadan once ki hali: hesap ayni ciktiysa gereksiz UPDATE atmayalim. */
    const kdOncekiJson = JSON.stringify(kd);
    let kesimTop = 0, dikimTop = 0, kkTop = 0, koliTop = 0, sevkTop = 0, yikSevkKalem = 0;
    let anyGelisSevk = false;
    let orphanKes = 0, orphanKk = 0;
    (data || []).forEach(r => {
        let j = {};
        try { j = JSON.parse(r.notlar || '{}') || {}; } catch (e) {}
        if (j.panel_silindi || j.silindi) return;
        const islem = String(r.islem || '').toUpperCase().replace(/İ/g, 'I');
        if (islem !== 'KUMAS_GELIS') return;
        const meta = konfPipelineKalemMeta(siparisId, j, r.kalem_ad);
        if (meta.idx >= 0) return;
        orphanKes += parseInt(j.kesilen_adet || 0, 10) || 0;
        orphanKk += parseInt(j.kalite_gecen_adet || 0, 10) || 0;
    });
    kalemler.forEach((_, i) => {
        const key = `kalem_${i}`;
        if (!kd[key]) kd[key] = {};
        const p = per[i];

        if (p.kesilen > 0) kd[key].kesilen = Math.max(parseInt(kd[key].kesilen || 0, 10) || 0, Math.round(p.kesilen));
        if (p.dikilen > 0) kd[key].dikilen = Math.max(parseInt(kd[key].dikilen || 0, 10) || 0, Math.round(p.dikilen));
        if (p.yikSevk > 0) kd[key].yikama_sevk = Math.max(parseInt(kd[key].yikama_sevk || 0, 10) || 0, Math.round(p.yikSevk));
        if (p.yikGel > 0) kd[key].yikama_gelen = Math.max(parseInt(kd[key].yikama_gelen || 0, 10) || 0, Math.round(p.yikGel));
        if (p.kkGec > 0) kd[key].kk_gecen = Math.max(parseInt(kd[key].kk_gecen || 0, 10) || 0, Math.round(p.kkGec));
        if (p.koli > 0) kd[key].kolide = Math.max(parseInt(kd[key].kolide || 0, 10) || 0, Math.round(p.koli));
        if (p.hasGelisSevk) {
            /* Sevkiyat yüklemesi KD'de; pipeline gecikmeli/0 gelebilir.
               Eski sevkMutlak + sevPipe=0 KD'yi siliyordu. Düşürme: opts.sevkKalemMutlak[i]. */
            anyGelisSevk = true;
            const sevPipe = Math.max(0, Math.round(p.sevkGelis));
            const sevKd = Math.max(
                parseInt(kd[key].sevk_edilen || 0, 10) || 0,
                parseInt(kd[key].sevk_adet || 0, 10) || 0
            );
            const sevLog = Math.round(p.sevkLog) || 0;
            let sev;
            if (opts.sevkKalemMutlak && Object.prototype.hasOwnProperty.call(opts.sevkKalemMutlak, i)) {
                sev = Math.max(0, Math.round(Number(opts.sevkKalemMutlak[i]) || 0));
            } else {
                sev = Math.max(sevKd, sevPipe, sevLog);
            }
            kd[key].sevk_edilen = sev;
            kd[key].sevk_adet = sev;
        } else if (opts.sevkKalemMutlak && Object.prototype.hasOwnProperty.call(opts.sevkKalemMutlak, i)) {
            const sev = Math.max(0, Math.round(Number(opts.sevkKalemMutlak[i]) || 0));
            kd[key].sevk_edilen = sev;
            kd[key].sevk_adet = sev;
        } else if (p.sevkLog > 0) {
            const sev = Math.max(
                parseInt(kd[key].sevk_edilen || 0, 10) || 0,
                parseInt(kd[key].sevk_adet || 0, 10) || 0,
                Math.round(p.sevkLog)
            );
            kd[key].sevk_edilen = sev;
            kd[key].sevk_adet = sev;
        }
        kesimTop += parseInt(kd[key].kesilen || 0, 10) || 0;
        dikimTop += parseInt(kd[key].dikilen || 0, 10) || 0;
        kkTop += parseInt(kd[key].kk_gecen || 0, 10) || 0;
        koliTop += parseInt(kd[key].kolide || 0, 10) || 0;
        sevkTop += Math.max(parseInt(kd[key].sevk_edilen || 0, 10) || 0, parseInt(kd[key].sevk_adet || 0, 10) || 0);
        yikSevkKalem += parseInt(kd[key].yikama_sevk || 0, 10) || 0;
    });
    /* Elle girilmiş KD / eşleşmeyen pipeline — asla sıfırlama (Math.max) */
    kd.kesim_toplam = Math.max(parseInt(kd.kesim_toplam || 0, 10) || 0, kesimTop, orphanKes);
    kd.dikim_toplam = Math.max(parseInt(kd.dikim_toplam || 0, 10) || 0, dikimTop);
    kd.kk_gecen = Math.max(parseInt(kd.kk_gecen || 0, 10) || 0, kkTop, orphanKk);
    kd.koli_toplam = Math.max(parseInt(kd.koli_toplam || 0, 10) || 0, koliTop);
    /* Non-mutlak: asla düşürme — anyGelisSevk + kalem_idx/meta mismatch sevkTop'u düşük bırakıp
       Sevkiyat yazılmış panel_sevk_toplam / yüklemeyi siliyordu (Durum inceleme açılışı). */
    if (sevkMutlak) {
        kd.panel_sevk_toplam = sevkTop;
    } else {
        kd.panel_sevk_toplam = Math.max(parseInt(kd.panel_sevk_toplam || 0, 10) || 0, sevkTop);
    }
    kd.panel_yikama_sevk = Math.max(parseInt(kd.panel_yikama_sevk || 0, 10) || 0, panelYikSevk, yikSevkKalem);
    if (panelYikGel > 0 || yikSevkKalem > 0 || panelYikSevk > 0) {
        kd.panel_yikama_gelen = Math.max(parseInt(kd.panel_yikama_gelen || 0, 10) || 0, panelYikGel);
        kd.yikama_yapildi = true;
    }
    /* Sipariş durum ekrani her acilista kosulsuz UPDATE atiyordu (sbKdSet
       icinde select + update, ustune log okumasi). Hesap KD ile birebir ayni
       ise hicbir sey yazma; degistiyse yaz ve degistigini bildir. */
    if (JSON.stringify(kd) === kdOncekiJson) return false;
    kd.konf_pipeline_son_senkron = new Date().toISOString();
    await sbKdSet(siparisId, 'KD_KONFEKSIYON', kd);
    if (!opts.skipLogYenile) await konfLoadIslemLog(siparisId);
    return true;
}


/**
 * KD_KONFEKSIYON bloğu + üretim tablolarındaki güncel adetler (yalnız GÖSTERİM).
 *
 * Kesim adetleri konf_kesim_yikama'da, kalite/yıkama/sevk adetleri KUMAS_GELIS
 * satırlarında toplanır. Bunlar KD_KONFEKSIYON'a yalnızca
 * konfPipelineSiparisDurumSenkron çalıştığında yazılır; senkron o sipariş için
 * henüz çalışmadıysa Konfeksiyon Panel'den girilen kesim ekranda hiç
 * görünmüyordu. 18.09.2026'da canlı veride ölçüldü: 40 kalemde 2.065 adet
 * kesim panelde vardı, ana programda görünmüyordu.
 *
 * Birleştirme Math.max ile yapılır — mevcut değeri asla düşürmez.
 * Kayıt yolları (konfKaydet, konfPipelineSiparisDurumSenkron) ham bloğu
 * sbKdGet ile ayrıca okur, bu fonksiyondan etkilenmez; çifte sayım riski yok.
 * MOBİLLE BİREBİR AYNI OLMAK ZORUNDA (assets/mobil/mobil-app.js).
 */
function konfGetKdForSiparis(siparisId) {
    const base = _kdCache[`KD_KONFEKSIYON_${siparisId}`] || {};
    const sid = String(siparisId);

    const kesPer = {}, kyYikSevk = {}, kyYikGel = {};
    (typeof _konfKesimGecmisCache !== 'undefined' ? _konfKesimGecmisCache || [] : []).forEach((k) => {
        if (String(k.siparis_id) !== sid || k.aktif === false) return;
        let ki = parseInt(k.kalem_idx, 10);
        if (!Number.isFinite(ki) || ki < 0) {
            ki = typeof konfUaKalemIdxCoz === 'function' ? konfUaKalemIdxCoz(siparisId, k.kalem_idx, k.desen) : -1;
        }
        if (ki == null || ki < 0) return;
        kesPer[ki] = (kesPer[ki] || 0) + (parseInt(k.kesilen_adet || k.miktar || 0, 10) || 0);
        /* Panel yıkama fişi yalnız bu tabloya yazar — yıkama sayısı buradan da okunmalı. */
        kyYikSevk[ki] = (kyYikSevk[ki] || 0) + (parseInt(k.yikama_sevk_adet || 0, 10) || 0);
        kyYikGel[ki] = (kyYikGel[ki] || 0) + (parseInt(k.yikama_gelen_adet || 0, 10) || 0);
    });

    const pipePer = {};
    (typeof _konfGlobalKumasGelisCache !== 'undefined' ? _konfGlobalKumasGelisCache || [] : []).forEach((r) => {
        if (String(r.siparis_id) !== sid) return;
        const ki = parseInt(r.kalem_idx, 10);
        if (!Number.isFinite(ki) || ki < 0) return;
        const p = pipePer[ki] || (pipePer[ki] = { kesilen: 0, yikSevk: 0, yikGel: 0, kkGec: 0, sevk: 0 });
        p.kesilen += parseInt(r.kesilen_adet || 0, 10) || 0;
        p.yikSevk += parseInt(r.yikama_sevk_adet || 0, 10) || 0;
        p.yikGel += parseInt(r.yikama_gelen_adet || 0, 10) || 0;
        p.kkGec += parseInt(r.kalite_gecen_adet || 0, 10) || 0;
        p.sevk += parseInt(r.sevk_edilen_adet || 0, 10) || 0;
    });

    const idxler = new Set([...Object.keys(kesPer), ...Object.keys(pipePer)]);
    if (!idxler.size) return base;

    const merged = { ...base };
    let degisti = false;
    idxler.forEach((ki) => {
        const key = `kalem_${ki}`;
        const satir = { ...(base[key] || {}) };
        const p = pipePer[ki] || {};
        let satirDegisti = false;
        [
            ['kesilen', Math.max(kesPer[ki] || 0, p.kesilen || 0)],
            ['yikama_sevk', Math.max(kyYikSevk[ki] || 0, p.yikSevk || 0)],
            ['yikama_gelen', Math.max(kyYikGel[ki] || 0, p.yikGel || 0)],
            ['kk_gecen', p.kkGec || 0],
            ['sevk_edilen', p.sevk || 0],
            ['sevk_adet', p.sevk || 0]
        ].forEach(([alan, aday]) => {
            const mevcut = parseInt(satir[alan] || 0, 10) || 0;
            if (aday > mevcut) { satir[alan] = aday; satirDegisti = true; }
        });
        if (satirDegisti) { merged[key] = satir; degisti = true; }
    });
    return degisti ? merged : base;
}

/**
 * TEK KURAL — bir kalemin üretim sayıları. Konfeksiyon Panel, mobil ve ana program aynı sayıyı gösterir.
 * Kaynaklar: KD_KONFEKSIYON (Veri Girişi) + konf_kesim_yikama tablosu (Ürün Ara kesim, yıkama fişi)
 * + KUMAS_GELIS pipeline (ana program manuel girişleri); her alan için en büyüğü.
 * siparis_akis günlüğü İZ kaydıdır, toplama GİRMEZ: günlük toplamı şişebiliyor
 * (SP391 günlük 673 / panel 161) ya da eksik kalabiliyor. Doğruluk referansı panel (kullanıcı, 19.09.2026).
 * kdKonf verilirse (ör. fason birleştirilmiş KD) onun satırı da hesaba katılır.
 */
function konfKalemUretimSayilari(siparisId, kalemIdx, kdKonf) {
    const n = (v) => parseInt(v || 0, 10) || 0;
    const a = ((kdKonf || {})[`kalem_${kalemIdx}`]) || {};
    const b = ((konfGetKdForSiparis(siparisId) || {})[`kalem_${kalemIdx}`]) || {};
    const m = (alan) => Math.max(n(a[alan]), n(b[alan]));
    return {
        kesim: m('kesilen'), dikim: m('dikilen'), kalite: m('kk_gecen'), koli: m('kolide'),
        yikSevk: m('yikama_sevk'), yikGel: m('yikama_gelen'),
        tamir: m('tamir'), imha: m('imha'), ikiKalite: m('iki_kalite'),
        fireKesim: m('fire_kesim'), fireDikim: m('fire_dikim')
    };
}

/** Sipariş toplamı = kalemlerin konfKalemUretimSayilari toplamı (aynı tek kural). */
function konfSiparisUretimToplam(siparisId, kdKonf, kalemSayisi) {
    const kd = konfGetKdForSiparis(siparisId) || {};
    const idx = new Set();
    for (let i = 0; i < (parseInt(kalemSayisi, 10) || 0); i++) idx.add(i);
    [...Object.keys(kd), ...Object.keys(kdKonf || {})].forEach((k) => {
        const mm = /^kalem_(\d+)$/.exec(k);
        if (mm) idx.add(parseInt(mm[1], 10));
    });
    const t = { kesim: 0, dikim: 0, kalite: 0, koli: 0, yikSevk: 0, yikGel: 0, tamir: 0, imha: 0, ikiKalite: 0, fireKesim: 0, fireDikim: 0 };
    idx.forEach((i) => {
        const o = konfKalemUretimSayilari(siparisId, i, kdKonf);
        Object.keys(t).forEach((k) => { t[k] += o[k]; });
    });
    return t;
}



// ════════════════════════════════════════════════════════
//  DOKUMA TAKİP MODÜLÜ
// ════════════════════════════════════════════════════════

let dtSeciliSiparisId = null;
let dtDosyaAktif = 'SIPARIS';
let dokumaDepoFiltre = { q: '', durum: 'HEPSI', siparisId: '' };
let _dokumaDepoKdSatirlariCache = [];
const DT_OPS_LS_KEY = 'erp_dt_ops_v3';
const DT_HAREKET_MAX = 3000;
let dtHareketFiltre = {
    tarih_bas: '',
    tarih_bit: '',
    kullanici: '',
    birim: '',
    surec: '',
    dosya: '',
    islem: '',
    siparis: '',
    urun: '',
    detay: ''
};

// dtGetKd/dtSetKd — Supabase'e geçildi (sbKdGet/sbKdSet)
async function dtGetKd(id) { return await sbKdGet(id, 'KD_DOKUMA'); }
async function dtSetKd(id, kd) { await sbKdSet(id, 'KD_DOKUMA', kd); }

let _dtRenderToken = 0;

function dtIsUserEditingUi() {
    if (appMode !== 'DOKUMA_TAKIP') return false;
    const root = document.getElementById('dt-root');
    if (!root) return false;
    const ae = document.activeElement;
    if (ae && root.contains(ae)) {
        const tag = String(ae.tagName || '').toUpperCase();
        if (['INPUT', 'TEXTAREA', 'SELECT'].includes(tag)) return true;
        if (ae.isContentEditable) return true;
    }
    for (const inp of root.querySelectorAll('input[id^="dt-input-metre-"], input[id^="dt-input-kg-"], input[id^="dt-input-adet-"]')) {
        const raw = String(inp.value || '').trim();
        if (raw && (parseFloat(raw.replace(',', '.')) || 0) !== 0) return true;
    }
    return false;
}

function dtToplamMetreFromKd(kd) {
    if (!kd || !kd.urunler) return 0;
    return Object.values(kd.urunler).reduce((a, u) => a + (parseFloat(u?.toplam_metre) || 0), 0);
}

function dtSiparisOptionHtml(s) {
    const kd = _kdCache[`KD_DOKUMA_${s.id}`];
    const topMetre = kd ? dtToplamMetreFromKd(kd) : null;
    const mark = topMetre != null ? (topMetre > 0 ? '✓' : '○') : '○';
    const sel = String(dtSeciliSiparisId) === String(s.id) ? 'selected' : '';
    return `<option value="${s.id}" ${sel}>${mark} ${pdfEsc(s.sno || '?')} — ${pdfEsc(s.firma || '?')}</option>`;
}

function dtRefreshSiparisSelMarks() {
    const sel = document.getElementById('dt-siparis-sel');
    if (!sel || appMode !== 'DOKUMA_TAKIP') return;
    const siparisler = (dataCache.siparisler || []).filter(s => String(s.durum || '').toUpperCase() !== 'TAMAMLANDI');
    const cur = sel.value;
    sel.innerHTML = '<option value="">— Seçin —</option>' + siparisler.map(dtSiparisOptionHtml).join('');
    if (cur) sel.value = cur;
}

function dtPrefetchSeciliKd() {
    const sid = dtSeciliSiparisId;
    if (!sid || _kdCache[`KD_DOKUMA_${sid}`] !== undefined) return;
    dtGetKd(sid).then(() => {
        if (appMode === 'DOKUMA_TAKIP' && !dtIsUserEditingUi()) dtRefreshSiparisSelMarks();
    }).catch(() => {});
}

async function dtEnsureSeciliKdLoaded() {
    if (!dtSeciliSiparisId) return;
    const sid = dtSeciliSiparisId;
    const jobs = [];
    if (_kdCache[`KD_DOKUMA_${sid}`] === undefined) jobs.push(dtGetKd(sid));
    if (_kdCache[`KD_KONFEKSIYON_${sid}`] === undefined) jobs.push(sbKdGet(sid, 'KD_KONFEKSIYON'));
    if (jobs.length) await Promise.all(jobs);
}

function dtCurrentUserLabel() {
    try {
        const d = String(erpCurrentUser?.display_name || '').trim();
        const u = String(erpCurrentUser?.username || '').trim();
        if (d) return d;
        if (u) return u;
    } catch (e) {}
    return 'Sistem';
}

function dtNormTxt(v) {
    return String(v || '')
        .toLocaleUpperCase('tr-TR')
        .replaceAll('İ', 'I')
        .replaceAll('I', 'I')
        .replaceAll('Ş', 'S')
        .replaceAll('Ğ', 'G')
        .replaceAll('Ü', 'U')
        .replaceAll('Ö', 'O')
        .replaceAll('Ç', 'C')
        .trim();
}

function dtPushHareket(entry = {}) {
    const data = dtLoadOpsData();
    if (!Array.isArray(data.hareketler)) data.hareketler = [];
    const e = {
        ts: new Date().toISOString(),
        kullanici: dtCurrentUserLabel(),
        dosya: String(entry.dosya || '').trim() || 'DOKUMA',
        islem: String(entry.islem || '').trim() || 'Güncelleme',
        siparis: String(entry.siparis || '').trim(),
        detay: String(entry.detay || '').trim(),
        alan: String(entry.alan || '').trim(),
        eski: String(entry.eski ?? '').trim(),
        yeni: String(entry.yeni ?? '').trim()
    };
    data.hareketler.unshift(e);
    if (data.hareketler.length > DT_HAREKET_MAX) data.hareketler = data.hareketler.slice(0, DT_HAREKET_MAX);
    dtSaveOpsData(data);
}

/** Dokuma Takip > Hareket Kayıtları: siparis_akis satırı dokuma/tezgah ile ilgili mi? Konfeksiyon KD ve üretim adımları listelenmez. */
function dtSiparisAkisDokumaHareketindeGoster(r) {
    const islemRaw = String(r?.islem || '').trim();
    const kalemRaw = String(r?.kalem_ad || '').trim();
    const up = dtNormTxt(`${islemRaw} ${kalemRaw}`.replace(/\s+/g, ' ')).replace(/\s+/g, '');
    if (!up) return false;
    if (up.includes('KONFEKSIYON') || (up.includes('KONF') && up.includes('SIYON'))) return false;
    if (up.includes('KD_KONFEKSIYON')) return false;
    if (up.includes('URUNAGACI') || up.includes('URUN_AGACI')) return false;
    const konfAdim = /(KES(IM|İM)|DIKIM|DİKİM|KALITE|KALİTE|KOL[Iİ]M|PAKET|YIKAMA|(^|[^A-Z])SEVK|NAKI[ŞS]|BASK[Iİ]|(^|[^A-Z])KK|UTU|ÜTÜ|SA[ÇC]AK|SACAK)/i;
    if (konfAdim.test(islemRaw) && !up.includes('DOKUMA')) return false;
    if (up.includes('KD_DOKUMA') || kalemRaw === 'KD_DOKUMA') return true;
    if (up.includes('DOKUMA')) return true;
    if (up.includes('TEZGAH')) return true;
    return false;
}

async function renderDokumaHareketListesi() {
    const data = dtLoadOpsData();
    const localSrc = Array.isArray(data.hareketler) ? data.hareketler : [];
    let dbSrc = [];
    const sipMap = new Map((dataCache.siparisler || []).map(s => [String(s.id), s]));
    const konfIslemSet = new Set(['KESIM','DİKİM','DIKIM','KALITE','KALITE KONTROL','KK_GECEN','PAKET','KOLI','YIKAMA_SEVK','YIKAMA_GELEN','SEVK']);
    const birimLabel = (kb = '', fallback = 'GENEL') => {
        const n = dtNormTxt(kb || '');
        if (!n) return fallback;
        if (n.includes('DOKUMA')) return 'DOKUMA';
        if (n.includes('KONFEKSIYON') || n.includes('KONF')) return 'KONFEKSIYON';
        if (n.includes('BOYAHANE')) return 'BOYAHANE';
        if (n.includes('IPLIK')) return 'IPLIK';
        if (n.includes('MAMUL')) return 'MAMUL';
        if (n.includes('DEPO_HAREKET')) return 'DEPO';
        if (n.includes('SIPARIS')) return 'SIPARIS';
        if (n.includes('TEZGAH')) return 'TEZGAH';
        return n;
    };
    const parseLogHead = (txt = '') => {
        const first = String(txt || '').split('\n').map(s => s.trim()).find(Boolean) || '';
        const m = first.match(/\[(.*?)\]/);
        return m?.[1] || '';
    };
    const pushGenRows = (rows = [], table = '', opts = {}) => {
        const out = [];
        (rows || []).forEach(r => {
            const recId = String(r?.id || '').trim();
            const recCode = String(
                r?.stok_kodu || r?.sno || r?.desen_kodu || r?.iplik_no || r?.tezgah_no || r?.task || recId || '—'
            ).trim();
            const urun = String(
                r?.urun_adi || r?.desen_adi || r?.kumas_cinsi || r?.kalem_ad || r?.task || r?.firma || recCode || '—'
            ).trim();
            const miktar = parseFloat(r?.miktar || r?.miktar_kg || r?.miktar_mt || 0) || 0;
            const kb = String(r?.kaynak_birim || opts.kaynak_birim || table || '').trim();
            const userFromLog = parseLogHead(r?.islem_gecmisi || '');
            const user = String(r?.updated_by || userFromLog || '—').trim() || '—';
            out.push({
                ts: r?.updated_at || r?.created_at || '',
                kullanici: user,
                birim: birimLabel(kb, birimLabel(table, 'GENEL')),
                surec: opts.surec || (birimLabel(kb, '').includes('KONFEKSIYON') ? 'KONFEKSIYON' : (birimLabel(kb, '').includes('DOKUMA') ? 'DOKUMA' : 'DIGER')),
                dosya: String(table || 'SIPARIS').toUpperCase(),
                islem: String(r?.islem_turu || opts.islem || 'Güncelleme'),
                siparis: recCode,
                urun,
                miktar,
                detay: [String(r?.islem_gecmisi || '').trim(), String(r?.notlar || '').trim()].filter(Boolean).join(' · ')
            });
        });
        return out;
    };
    try {
        if (typeof sb !== 'undefined' && sb?.from) {
            const { data: rows, error } = await sb
                .from('kumas_stok')
                .select('created_at,updated_by,islem_gecmisi,notlar,stok_kodu,kaynak_birim,islem_turu,firma,miktar_kg,miktar_mt')
                .order('created_at', { ascending: false })
                .limit(5000);
            if (!error && Array.isArray(rows)) {
                dbSrc = rows.map(r => ({
                    ts: r.created_at || '',
                    kullanici: String(r.updated_by || '').trim() || '—',
                    birim: birimLabel(r.kaynak_birim, 'DEPO'),
                    dosya: 'SIPARIS',
                    islem: String(r.islem_turu || 'Stok hareketi'),
                    siparis: String(r.stok_kodu || '').trim(),
                    surec: String(r.kaynak_birim || '').toUpperCase().includes('DOKUMA') ? 'DOKUMA' : 'DIGER',
                    urun: String(r.stok_kodu || '').trim() || String(r.firma || '').trim() || '—',
                    miktar: parseFloat(r.miktar_kg || r.miktar_mt || 0) || 0,
                    detay: [String(r.kaynak_birim || '').trim(), String(r.firma || '').trim(), String(r.islem_gecmisi || r.notlar || '').trim()].filter(Boolean).join(' · ')
                }));
            }

            // Sipariş akışındaki operasyonları da tek listede göster.
            const { data: akisRows, error: akisErr } = await sb
                .from('siparis_akis')
                .select('created_at,siparis_id,islem,kalem_ad,miktar,notlar')
                .order('created_at', { ascending: false })
                .limit(3000);
            if (!akisErr && Array.isArray(akisRows)) {
                dbSrc = dbSrc.concat(akisRows.filter(dtSiparisAkisDokumaHareketindeGoster).map(r => {
                    const sip = sipMap.get(String(r.siparis_id || ''));
                    const sipNo = String(sip?.sno || r.siparis_id || '').trim();
                    const islem = String(r.islem || 'Sipariş akışı').trim();
                    const islemNorm = dtNormTxt(islem).replaceAll('İ', 'I');
                    let j = {};
                    try { j = JSON.parse(r.notlar || '{}') || {}; } catch (e) {}
                    const surec = konfIslemSet.has(islemNorm)
                        ? 'KONFEKSIYON'
                        : (islemNorm.includes('DOKUMA') ? 'DOKUMA' : 'DIGER');
                    return {
                        ts: r.created_at || '',
                        kullanici: String(j.user || j.kullanici || '').trim() || '—',
                        birim: surec === 'KONFEKSIYON' ? 'KONFEKSIYON' : 'SIPARIS',
                        dosya: 'SIPARIS',
                        islem,
                        siparis: sipNo,
                        surec,
                        urun: String(r.kalem_ad || '').trim() || '—',
                        miktar: parseFloat(r.miktar || 0) || 0,
                        detay: [String(r.notlar || '').trim()].filter(Boolean).join(' · ')
                    };
                }));
            }

            const [iplikRes, kutuphaneRes, tezgahRes] = await Promise.all([
                sb.from('iplik_stok').select('*').order('created_at', { ascending: false }).limit(2000),
                sb.from('kumas_kutuphanesi').select('id,created_at,updated_at,updated_by,islem_gecmisi,notlar,desen_kodu,desen_adi,urun_adi,kaynak_birim,firma').order('created_at', { ascending: false }).limit(1500),
                // tezgahlar tablosunda updated_at / islem_gecmisi kolonu yok.
                sb.from('tezgahlar').select('*').order('created_at', { ascending: false }).limit(1000)
            ]);
            if (!iplikRes.error && Array.isArray(iplikRes.data)) dbSrc = dbSrc.concat(pushGenRows(iplikRes.data, 'iplik_stok'));
            if (!kutuphaneRes.error && Array.isArray(kutuphaneRes.data)) dbSrc = dbSrc.concat(pushGenRows(kutuphaneRes.data, 'kumas_kutuphanesi'));
            if (!tezgahRes.error && Array.isArray(tezgahRes.data)) dbSrc = dbSrc.concat(pushGenRows(tezgahRes.data, 'tezgahlar', { surec: 'DOKUMA' }));
        }
    } catch (e) {}
    const konfKayitDisi = row => {
        const sur = dtNormTxt(row?.surec || '');
        const bir = dtNormTxt(row?.birim || '');
        if (sur === 'KONFEKSIYON' || bir.includes('KONFEKSIYON')) return false;
        return true;
    };
    const src = [...dbSrc, ...localSrc].filter(konfKayitDisi).sort((a, b) => String(b?.ts || '').localeCompare(String(a?.ts || '')));
    const sayac = depoSevkeHazirSayaçOzet(dataCache.kumas_stok || []);
    const f = dtHareketFiltre || {};
    const fTarihBas = String(f.tarih_bas || '').trim();
    const fTarihBit = String(f.tarih_bit || '').trim();
    const fKul = dtNormTxt(f.kullanici || '');
    const fBir = dtNormTxt(f.birim || '');
    const fSur = dtNormTxt(f.surec || '');
    const fDos = dtNormTxt(f.dosya || '');
    const fIsl = dtNormTxt(f.islem || '');
    const fSip = dtNormTxt(f.siparis || '');
    const fUrun = dtNormTxt(f.urun || '');
    const fDet = dtNormTxt(f.detay || '');
    const rows = src.filter(r => {
        const d = String(r?.ts || '').slice(0, 10);
        const k = dtNormTxt(r?.kullanici || '');
        const bir = dtNormTxt(r?.birim || '');
        const sur = dtNormTxt(r?.surec || '');
        const dos = dtNormTxt(r?.dosya || '');
        const isl = dtNormTxt(r?.islem || '');
        const sip = dtNormTxt(r?.siparis || '');
        const urun = dtNormTxt(r?.urun || '');
        const det = dtNormTxt([r?.detay, r?.alan, r?.eski, r?.yeni].join(' '));
        if (fTarihBas && d < fTarihBas) return false;
        if (fTarihBit && d > fTarihBit) return false;
        if (fKul && !k.includes(fKul)) return false;
        if (fBir && !bir.includes(fBir)) return false;
        if (fSur && sur !== fSur) return false;
        if (fDos && dos !== fDos) return false;
        if (fIsl && !isl.includes(fIsl)) return false;
        if (fSip && !sip.includes(fSip)) return false;
        if (fUrun && !urun.includes(fUrun)) return false;
        if (fDet && !det.includes(fDet)) return false;
        return true;
    });
    return `
    <div class="panel-box" style="padding:10px 12px;margin-bottom:10px;border:1px solid rgba(16,185,129,0.35);background:rgba(16,185,129,0.06)">
        <div style="font-size:9px;font-weight:700;color:var(--emerald-c);text-transform:uppercase;letter-spacing:.08em;font-family:'DM Mono',monospace">Sevke Hazır Sayaç</div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">Dokuma giriş: ${sayac.dokumaGirisToplam} · Sevk edilen: ${sayac.sevkEdilen} · Bekleyen: ${sayac.bekleyen}</div>
        <div style="font-size:9px;color:var(--text3);margin-top:2px">Dokuma ve dokuma kaynaklı stok hareketleri; konfeksiyon paneli kayıtları bu listede yer almaz.</div>
    </div>
    <div class="panel-box" style="padding:0;overflow:hidden">
        <div class="panel-head">
            <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent2)"></span>Hareket Kayıtları</span>
            <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">${rows.length} kayıt</span>
        </div>
        <div style="overflow:auto;max-height:68vh">
            <table class="dt-table" style="min-width:1200px">
                <thead>
                    <tr>
                        <th style="text-align:left">Tarih/Saat</th>
                        <th style="text-align:left">Kullanıcı</th>
                        <th style="text-align:left">Birim</th>
                        <th style="text-align:left">Süreç</th>
                        <th style="text-align:left">Dosya</th>
                        <th style="text-align:left">İşlem</th>
                        <th style="text-align:left">Stok / Sipariş</th>
                        <th style="text-align:left">Ürün</th>
                        <th style="text-align:right">Miktar</th>
                        <th style="text-align:left">Detay</th>
                    </tr>
                    <tr>
                        <th>
                            <div style="display:flex;gap:4px;align-items:center">
                                <input type="date" value="${pdfEsc(f.tarih_bas || '')}" onchange="dtSetHareketFiltre('tarih_bas', this.value)" class="pro-input" style="padding:4px 6px;font-size:10px;min-width:132px" title="Başlangıç tarihi">
                                <span style="font-size:10px;color:var(--text3)">→</span>
                                <input type="date" value="${pdfEsc(f.tarih_bit || '')}" onchange="dtSetHareketFiltre('tarih_bit', this.value)" class="pro-input" style="padding:4px 6px;font-size:10px;min-width:132px" title="Bitiş tarihi">
                            </div>
                        </th>
                        <th><input id="dt-hf-kullanici" value="${pdfEsc(f.kullanici || '')}" oninput="dtSetHareketFiltre('kullanici', this.value)" class="pro-input" placeholder="Kullanıcı" style="padding:4px 6px;font-size:10px"></th>
                        <th><input id="dt-hf-birim" value="${pdfEsc(f.birim || '')}" oninput="dtSetHareketFiltre('birim', this.value)" class="pro-input" placeholder="Birim" style="padding:4px 6px;font-size:10px"></th>
                        <th>
                            <select class="pro-input" onchange="dtSetHareketFiltre('surec', this.value)" style="padding:4px 6px;font-size:10px">
                                <option value="" ${!f.surec ? 'selected' : ''}>Tümü</option>
                                <option value="DOKUMA" ${f.surec==='DOKUMA'?'selected':''}>Dokuma</option>
                                <option value="KONFEKSIYON" ${f.surec==='KONFEKSIYON'?'selected':''}>Konfeksiyon</option>
                                <option value="DIGER" ${f.surec==='DIGER'?'selected':''}>Diğer</option>
                            </select>
                        </th>
                        <th>
                            <select class="pro-input" onchange="dtSetHareketFiltre('dosya', this.value)" style="padding:4px 6px;font-size:10px">
                                <option value="" ${!f.dosya ? 'selected' : ''}>Tümü</option>
                                <option value="SIPARIS" ${f.dosya==='SIPARIS'?'selected':''}>Sipariş Takip</option>
                            </select>
                        </th>
                        <th><input id="dt-hf-islem" value="${pdfEsc(f.islem || '')}" oninput="dtSetHareketFiltre('islem', this.value)" class="pro-input" placeholder="İşlem" style="padding:4px 6px;font-size:10px"></th>
                        <th><input id="dt-hf-siparis" value="${pdfEsc(f.siparis || '')}" oninput="dtSetHareketFiltre('siparis', this.value)" class="pro-input" placeholder="Sipariş No" style="padding:4px 6px;font-size:10px"></th>
                        <th><input id="dt-hf-urun" value="${pdfEsc(f.urun || '')}" oninput="dtSetHareketFiltre('urun', this.value)" class="pro-input" placeholder="Ürün" style="padding:4px 6px;font-size:10px"></th>
                        <th></th>
                        <th><input id="dt-hf-detay" value="${pdfEsc(f.detay || '')}" oninput="dtSetHareketFiltre('detay', this.value)" class="pro-input" placeholder="Detay ara" style="padding:4px 6px;font-size:10px"></th>
                    </tr>
                </thead>
                <tbody>
                    ${rows.length ? rows.map(r => {
                        const dt = r.ts ? new Date(r.ts) : null;
                        const dtTxt = (dt && !isNaN(dt.getTime()))
                            ? dt.toLocaleString('tr-TR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })
                            : '—';
                        return `
                    <tr>
                        <td class="mono">${pdfEsc(dtTxt)}</td>
                        <td>${pdfEsc(r.kullanici || '—')}</td>
                        <td><span class="pill pill-gray" style="font-size:9px">${pdfEsc(r.birim || '—')}</span></td>
                        <td><span class="pill pill-gray" style="font-size:9px">${pdfEsc(r.surec || '—')}</span></td>
                        <td><span class="pill pill-gray" style="font-size:9px">${pdfEsc(r.dosya || '—')}</span></td>
                        <td>${pdfEsc(r.islem || '—')}</td>
                        <td class="mono">${pdfEsc(r.siparis || '—')}</td>
                        <td>${pdfEsc(r.urun || '—')}</td>
                        <td class="mono" style="text-align:right">${Number.isFinite(parseFloat(r.miktar)) ? Number(r.miktar).toLocaleString('tr-TR') : '—'}</td>
                        <td style="font-size:11px;color:var(--text2)">${pdfEsc(r.detay || [r.alan, r.eski, r.yeni].filter(Boolean).join(' · ') || '—')}</td>
                    </tr>`;
                    }).join('') : `<tr><td colspan="9" style="padding:16px;color:var(--text3)">Kayıt bulunamadı. Tarih filtresini temizleyin veya senkronize edin.</td></tr>`}
                </tbody>
            </table>
        </div>
    </div>`;
    if (dtDosyaAktif === 'HAREKET' && window._dtHareketFocus?.key) {
        const map = {
            kullanici: 'dt-hf-kullanici',
            birim: 'dt-hf-birim',
            islem: 'dt-hf-islem',
            siparis: 'dt-hf-siparis',
            urun: 'dt-hf-urun',
            detay: 'dt-hf-detay'
        };
        const id = map[window._dtHareketFocus.key];
        const el = id ? document.getElementById(id) : null;
        if (el) {
            el.focus();
            const p = window._dtHareketFocus.pos;
            if (typeof p === 'number') {
                const safe = Math.max(0, Math.min(p, String(el.value || '').length));
                el.setSelectionRange(safe, safe);
            }
        }
    }
}

async function renderDokumaTakip() {
    const list = document.getElementById('main-list');
    if (!list) return;
    dtDosyaAktif = dtMigrateDosyaAktif(dtDosyaAktif);
    const token = ++_dtRenderToken;
    const siparisler = (dataCache.siparisler||[]).filter(s => s.durum !== 'TAMAMLANDI');
    const dosyaBtn = (id, label) => `
        <button onclick="dtSetDosya('${id}')"
            style="padding:6px 10px;border-radius:8px;border:1px solid ${dtDosyaAktif===id?'rgba(109,113,255,0.45)':'var(--border)'};background:${dtDosyaAktif===id?'rgba(109,113,255,0.12)':'var(--surface2)'};color:${dtDosyaAktif===id?'var(--text)':'var(--text2)'};font-size:10px;font-weight:700;cursor:pointer">
            ${label}
        </button>
    `;

    let icerikHtml = '';
    if (dtDosyaAktif === 'HAREKET') {
        icerikHtml = await renderDokumaHareketListesi();
        if (token !== _dtRenderToken) return;
    } else {
        const sipOpts = siparisler.map(s => dtSiparisOptionHtml(s));

        let dtFormHtml = `
                <div class="empty-pro" style="padding:60px 20px">
                    <div class="empty-pro-icon">🧵</div>
                    <div class="empty-pro-title">Sipariş seçin</div>
                    <div class="empty-pro-sub">Yukarıdan aktif bir sipariş seçerek dokuma girişi yapın</div>
                </div>`;
        if (dtSeciliSiparisId) {
            await dtEnsureSeciliKdLoaded();
            if (token !== _dtRenderToken) return;
            dtFormHtml = await renderDtForm();
            if (token !== _dtRenderToken) return;
        }

        icerikHtml = `
            <div class="panel-box" style="padding:12px 16px">
                <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
                    <div style="font-size:9px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace">Sipariş</div>
                    <select id="dt-siparis-sel" onchange="dtSelectSiparis(this.value)"
                        class="pro-input" style="min-width:220px;width:auto;padding:6px 10px">
                        <option value="">— Seçin —</option>
                        ${sipOpts.join('')}
                    </select>
                    ${dtSeciliSiparisId ? (() => {
                        const s = siparisler.find(x => x.id == dtSeciliSiparisId);
                        return `<span class="pill pill-cyan" style="margin-left:auto">${pdfEsc(s?.sno || '')}${s?.sno && s?.firma ? ' · ' : ''}${pdfEsc(s?.firma || '—')}</span>`;
                    })() : ''}
                    <button type="button" onclick="openDtExcelImport()" class="btn-pro btn-primary-pro" style="padding:5px 12px;font-size:9px;background:var(--cyan-c);border-color:var(--cyan-c)" title="Genel Durum: ürün+renk+ebat → J m, K ad/kg">⬆ Excel'den aktar</button>
                    <button type="button" id="dt-excel-undo-btn" onclick="dtExcelSonImportGeriAl()" class="btn-pro btn-danger-pro" style="display:none;padding:5px 10px;font-size:9px" title="Son Excel importunu geri al">↩ Son Excel'i geri al</button>
                </div>
            </div>
            <div id="dt-content">${dtFormHtml}</div>
        `;
    }

    list.innerHTML = `
    <div id="dt-root" style="display:flex;flex-direction:column;gap:12px">
        <div class="panel-box" style="padding:12px 16px">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                <div style="font-size:9px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace;margin-right:4px">Dokuma</div>
                ${dosyaBtn('SIPARIS', '📁 Sipariş Takip')}
                ${dosyaBtn('HAREKET', '📁 Hareket Kayıtları')}
            </div>
        </div>
        ${icerikHtml}
    </div>`;
    dtExcelUndoBtnGuncelle();
    dtPrefetchSeciliKd();
}

function dtKaliteGecenKumasMi(row) {
    if (!row) return false;
    if (String(row.kaynak_birim || '').toUpperCase() !== 'DOKUMA_TAKIP') return false;
    const tip = String(row.islem_turu || '').toUpperCase().replace(/İ/g, 'I');
    if (tip && tip !== 'GIRIS' && tip !== 'GİRİŞ') return false;
    const not = String(row.notlar || '').toUpperCase();
    if (not.includes('[SEVK_KAPANDI]')) return false;
    const kg = Math.abs(parseFloat(row.miktar_kg) || 0);
    const mt = Math.abs(parseFloat(row.miktar_mt) || 0);
    const ad = Math.abs(parseInt(row.cuval_sayisi || 0, 10) || 0);
    return kg > 0 || mt > 0 || ad > 0;
}

async function erpSyncAllDataBekle(opts = {}) {
    for (let i = 0; i < 30; i++) {
        if (!_syncAllDataBusy) break;
        await new Promise(r => setTimeout(r, 80));
    }
    const full = opts.full === true || (!!opts.manual && opts.light !== true && !opts.tables);
    await syncAllData(!!opts.manual, {
        silent: !!opts.silent,
        light: !full,
        siparisFirstPageOnly: opts.siparisFirstPageOnly !== false && !full,
        ...opts,
        full: full || undefined
    });
}

/** Mutasyon sonrası UI'yi bekletmeden ilgili tabloları sessizce tazele (birleştirilmiş) */
let _erpBgSyncTables = new Set();
let _erpBgSyncTimer = null;
let _erpBgSyncSkipSummary = false;
function erpSyncTablesBackground(tables, opts = {}) {
    const list = (Array.isArray(tables) ? tables : [tables]).map(t => String(t || '').trim()).filter(Boolean);
    if (!list.length || typeof syncAllData !== 'function') return;
    list.forEach(t => _erpBgSyncTables.add(t));
    if (opts.skipSummary) _erpBgSyncSkipSummary = true;
    const delay = Number.isFinite(opts.delayMs) ? opts.delayMs : 280;
    if (_erpBgSyncTimer) clearTimeout(_erpBgSyncTimer);
    _erpBgSyncTimer = setTimeout(() => {
        _erpBgSyncTimer = null;
        const merged = Array.from(_erpBgSyncTables);
        _erpBgSyncTables.clear();
        const skipSummary = _erpBgSyncSkipSummary;
        _erpBgSyncSkipSummary = false;
        if (!merged.length) return;
        syncAllData(false, {
            silent: true,
            light: true,
            tables: merged,
            siparisFirstPageOnly: merged.includes('siparisler'),
            skipSummary
        }).catch(() => {});
    }, delay);
}
window.erpSyncTablesBackground = erpSyncTablesBackground;

function dtKumasStokCacheEkle(payload, id) {
    if (!id) return;
    const row = { ...payload, id: String(id), created_at: new Date().toISOString(), updated_at: new Date().toISOString() };
    if (!Array.isArray(dataCache.kumas_stok)) dataCache.kumas_stok = [];
    const ix = dataCache.kumas_stok.findIndex(r => String(r.id) === String(id));
    if (ix >= 0) dataCache.kumas_stok[ix] = { ...dataCache.kumas_stok[ix], ...row };
    else dataCache.kumas_stok.unshift(row);
    try { if (typeof erpDuzHareketYansit === 'function') erpDuzHareketYansit(row); } catch (e) {}
}

function dtDokumaStokRenkNorm(siparis, kalem) {
    return dtNormTxt(kalem?.renk || '');
}

function dtDokumaStokUrunNorm(kalem) {
    const kod = dtKalemStokKodu(kalem);
    if (kod) return dtNormTxt(kod);
    return dtNormTxt(kalem?.ad || kalem?.kod || '');
}

function dtDokumaStokFirmaNorm(siparis) {
    return dtNormTxt(siparis?.firma || '');
}

function dtDokumaStokBirlestirmeAnahtari(siparis, kalem) {
    // Aynı sipariş + müşteri + ürün + renk → tek satır (farklı siparişler karışmaz)
    const sno = normalizeSiparisNo(siparis?.sno || '') || String(siparis?.id || '');
    return `${sno}|${dtDokumaStokFirmaNorm(siparis)}|${dtDokumaStokUrunNorm(kalem)}|${dtDokumaStokRenkNorm(siparis, kalem)}`;
}

function dtDokumaStokBirlestirEtiket(siparis, kalem) {
    return `[DT_BIRLESTIR:${dtDokumaStokBirlestirmeAnahtari(siparis, kalem)}]`;
}

function dtDokumaStokSatirUrunNorm(row) {
    const kod = String(row?.stok_kodu || '').trim();
    const lotNorm = normalizeSiparisNo(row?.lot_no || '');
    if (kod && dtNormTxt(kod) !== lotNorm && normalizeSiparisNo(kod) !== lotNorm) {
        return dtNormTxt(kod);
    }
    const cins = String(row?.kumas_cinsi || '');
    const parts = cins.split('—').map(p => p.trim()).filter(Boolean);
    if (parts.length >= 3) return dtNormTxt(parts[1]);
    if (parts.length >= 2) return dtNormTxt(parts[1] || parts[parts.length - 1]);
    return dtNormTxt(kod || cins);
}

function dtDokumaStokSatirBirlestirAnahtari(row) {
    const not = String(row?.notlar || '');
    const m = not.match(/\[DT_BIRLESTIR:([^\]]+)\]/i);
    if (m) return String(m[1] || '').trim().toUpperCase();
    const sno = normalizeSiparisNo(String(row?.lot_no || '').split(',')[0].trim())
        || normalizeSiparisNo(row?.siparis_sno || '')
        || String(row?.siparis_id || '');
    return `${sno}|${dtNormTxt(row?.firma || '')}|${dtDokumaStokSatirUrunNorm(row)}|${dtNormTxt(row?.renk || '')}`;
}

/** Depo satırının kaydedildiği sipariş no (birleşik lot_no listesinden değil, siparis_id'den) */
function dokumaDepoSatirKayitSno(row) {
    const sipMap = new Map((dataCache.siparisler || []).map(s => [String(s.id), s]));
    if (row?.siparis_id != null && row.siparis_id !== '') {
        const sip = sipMap.get(String(row.siparis_id));
        if (sip?.sno) return String(sip.sno).trim();
    }
    const ids = Array.isArray(row?.siparis_ids) ? row.siparis_ids.filter(Boolean) : [];
    if (ids.length === 1) {
        const sip = sipMap.get(String(ids[0]));
        if (sip?.sno) return String(sip.sno).trim();
    }
    if (Array.isArray(row?.lot_nos) && row.lot_nos.length === 1) {
        return String(row.lot_nos[0] || '').trim();
    }
    const lot = String(row?.lot_no || '').trim();
    if (lot && !lot.includes(',')) return lot;
    // Eski birleşik satırlar: mümkünse siparis_id, yoksa ilk no
    return lot.split(',')[0].trim() || '—';
}

function dtDokumaDepoAcikStokSatirBul(siparis, kalem) {
    const sevkSet = depoDokumaSevkEdilmisKaynakIdSet(dataCache.kumas_stok || []);
    const hedefAnahtar = dtDokumaStokBirlestirmeAnahtari(siparis, kalem);
    return (dataCache.kumas_stok || []).find(r => {
        if (!dtKaliteGecenKumasMi(r)) return false;
        if (sevkSet.has(String(r.id))) return false;
        const not = String(r.notlar || '').toUpperCase();
        if (not.includes('[SEVK_KAPANDI]')) return false;
        if (dtDokumaStokSatirBirlestirAnahtari(r).toUpperCase() !== hedefAnahtar.toUpperCase()) return false;
        const kg = Math.abs(parseFloat(r.miktar_kg) || 0);
        const mt = Math.abs(parseFloat(r.miktar_mt) || 0);
        const ad = Math.abs(parseInt(r.cuval_sayisi || 0, 10) || 0);
        return kg > 0 || mt > 0 || ad > 0;
    }) || null;
}

function dtDokumaDepoStokBaslik(siparis, kalem, urunEtiket) {
    const firma = String(siparis?.firma || '').trim();
    const renk = String(kalem?.renk || '').trim();
    const urun = urunEtiket || kalem?.ad || kalem?.kod || 'Kumaş';
    const sno = String(siparis?.sno || '').trim();
    const ana = [firma, urun, renk].filter(Boolean).join(' — ');
    return sno ? `${ana} (${sno})` : ana;
}

function dtDokumaDepoStokKodu(kalem) {
    return dtKalemStokKodu(kalem) || String(kalem?.ad || kalem?.kod || '').trim().slice(0, 48);
}

async function dtDokumaDepoStokUpsert(siparis, kalem, opts = {}) {
    const metre = parseFloat(opts.metre) || 0;
    const kg = parseFloat(opts.kg) || 0;
    const adet = parseInt(opts.adet, 10) || 0;
    if (metre <= 0 && kg <= 0 && adet <= 0) return { ok: false, reason: 'empty' };

    const birlestir = opts.birlestir === 'set' ? 'set' : 'add';
    const simteksOto = !!(opts.simteksOtomatik || dtKalemOtomatikStokaMi(siparis, kalem));
    const stokKodu = dtDokumaDepoStokKodu(kalem);
    const urunEtiket = opts.urunEtiket || kalem?.ad || kalem?.kod || '';
    const kumasCinsi = dtDokumaDepoStokBaslik(siparis, kalem, urunEtiket);
    const birlestirEtiket = dtDokumaStokBirlestirEtiket(siparis, kalem);
    const userLabel = dtCurrentUserLabel();
    const tarih = new Date().toLocaleString('tr-TR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const kaynak = opts.kaynak || 'DOKUMA_GIRIS';
    const genelDurum = kaynak === 'GENEL_DURUM_EXCEL';
    const notBase = genelDurum
        ? `[GENEL_DURUM_STOK][SEVKE_HAZIR][DOKUMA_DEPO] Genel Durum Excel — sipariş+ürün+renk ${birlestirEtiket}`
        : (simteksOto ? `[SIMTEKS_STOK][SEVKE_HAZIR][DOKUMA_DEPO] Otomatik · ${stokKodu} ${birlestirEtiket}` : `[SEVKE_HAZIR][DOKUMA_DEPO] Dokuma depo ${birlestirEtiket}`);
    const undoInfo = { createdIds: [], updatedBefore: {} };
    const mevcut = dtDokumaDepoAcikStokSatirBul(siparis, kalem);

    if (mevcut) {
        if (opts.undoCapture) {
            undoInfo.updatedBefore[String(mevcut.id)] = {
                miktar_kg: mevcut.miktar_kg,
                miktar_mt: mevcut.miktar_mt,
                cuval_sayisi: mevcut.cuval_sayisi,
                kumas_cinsi: mevcut.kumas_cinsi,
                notlar: mevcut.notlar,
                islem_gecmisi: mevcut.islem_gecmisi,
                renk: mevcut.renk
            };
        }
        const eskiKg = Math.abs(parseFloat(mevcut.miktar_kg) || 0);
        const eskiMt = Math.abs(parseFloat(mevcut.miktar_mt) || 0);
        const eskiAd = Math.abs(parseInt(mevcut.cuval_sayisi || 0, 10) || 0);
        const yeniKg = birlestir === 'set' ? kg : eskiKg + kg;
        const yeniMt = birlestir === 'set' ? metre : eskiMt + metre;
        const yeniAd = birlestir === 'set' ? adet : eskiAd + adet;
        const yeniCins = urunEtiket && String(urunEtiket).includes(' / ')
            ? dtDokumaDepoStokBaslik(siparis, kalem, urunEtiket)
            : (mevcut.kumas_cinsi || kumasCinsi);
        const prevNot = String(mevcut.notlar || '').trim();
        const yeniNot = prevNot.includes('[DT_BIRLESTIR:') ? prevNot : `${prevNot ? prevNot + ' ' : ''}${birlestirEtiket}`.trim();
        const ekGecmis = birlestir === 'set'
            ? `↻ ${tarih} — Dokuma stok güncellendi (${kaynak}) · ${yeniMt.toFixed(2)} m / ${yeniKg.toFixed(2)} kg / ${yeniAd} ad · ${userLabel}`
            : `+ ${tarih} — Dokuma stok birleştirildi · +${metre.toFixed(2)} m · ${userLabel}`;
    const { error } = await sb.from('kumas_stok').update({
        miktar_kg: yeniKg,
        miktar_mt: yeniMt,
        cuval_sayisi: yeniAd,
        kumas_cinsi: yeniCins,
        renk: kalem?.renk || mevcut.renk || '',
        firma: siparis?.firma || mevcut.firma || '',
        stok_kodu: stokKodu || mevcut.stok_kodu || '',
        notlar: yeniNot,
        islem_gecmisi: `${String(mevcut.islem_gecmisi || '').trim()}\n${ekGecmis}`.trim(),
        updated_by: userLabel
    }).eq('id', mevcut.id);
    if (error) {
        const updSlim = {
            miktar_kg: yeniKg,
            miktar_mt: yeniMt,
            cuval_sayisi: yeniAd,
            kumas_cinsi: yeniCins,
            renk: kalem?.renk || mevcut.renk || '',
            firma: siparis?.firma || mevcut.firma || '',
            stok_kodu: stokKodu || mevcut.stok_kodu || '',
            notlar: `${yeniNot}\n${ekGecmis}`.trim()
        };
        const { error: err2 } = await sb.from('kumas_stok').update(updSlim).eq('id', mevcut.id);
        if (err2) return { ok: false, error: err2 };
    }
        return { ok: true, id: mevcut.id, merged: true, undo: undoInfo };
    }

    const insertPayload = {
        kumas_cinsi: kumasCinsi,
        miktar_kg: kg,
        miktar_mt: metre,
        cuval_sayisi: adet,
        firma: siparis?.firma || '',
        stok_kodu: stokKodu,
        lot_no: siparis?.sno || '',
        renk: kalem?.renk || '',
        kaynak_birim: 'DOKUMA_TAKIP',
        islem_turu: 'GIRIS',
        notlar: notBase,
        islem_gecmisi: `✨ ${tarih} — Dokuma stoka alındı (${urunEtiket || kalem?.ad || '—'}) · ${metre.toFixed(2)} m · ${userLabel}`,
        updated_by: userLabel
    };
    let newId = null;
    {
        const { data, error } = await sb.from('kumas_stok').insert([insertPayload]).select('id');
        if (!error) {
            newId = data?.[0]?.id || null;
        } else {
            await erpSyncAllDataBekle({ silent: true, tables: ['kumas_stok'], light: true });
            const mevcutSatir = dtDokumaDepoAcikStokSatirBul(siparis, kalem);
            if (mevcutSatir?.id) {
                newId = mevcutSatir.id;
            } else {
                const slim = { ...insertPayload };
                delete slim.islem_gecmisi;
                delete slim.updated_by;
                const r2 = await sb.from('kumas_stok').insert([slim]).select('id');
                if (r2.error) {
                    const r3 = await sb.from('kumas_stok').insert([slim]);
                    if (r3.error) return { ok: false, error: r3.error };
                    await erpSyncAllDataBekle({ silent: true, tables: ['kumas_stok'], light: true });
                    newId = dtDokumaDepoAcikStokSatirBul(siparis, kalem)?.id || null;
                } else {
                    newId = r2.data?.[0]?.id || null;
                }
            }
        }
    }
    if (opts.undoCapture && newId) undoInfo.createdIds.push(newId);
    if (newId) {
        dtKumasStokCacheEkle(insertPayload, newId);
        return { ok: true, id: newId, merged: false, undo: undoInfo };
    }
    return { ok: false, error: { message: 'Dokuma depo kaydı oluşturulamadı. Supabase bağlantısını kontrol edin.' }, undo: undoInfo };
}

async function dtDokumaDepoSiparisToplamSenkron(siparisId) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (!siparis) return 0;
    const kd = await dtGetKd(siparisId);
    let kalemler = [];
    try { kalemler = typeof siparis?.cins === 'string' ? JSON.parse(siparis.cins) : (siparis?.cins || []); } catch (e) { kalemler = []; }
    let ok = 0;
    for (const [key, u] of Object.entries(kd?.urunler || {})) {
        const idx = parseInt(key, 10);
        if (!Number.isFinite(idx)) continue;
        const mt = parseFloat(u?.toplam_metre) || 0;
        const kalem = kalemler[idx] || {};
        const o = dokumaUrunIkinciOzet(u, kalem);
        if (mt <= 0 && o.ikinci <= 0) continue;
        if (dtDokumaDepoAcikStokSatirBul(siparis, kalem)) continue;
        const res = await dtDokumaDepoStokUpsert(siparis, kalem, {
            metre: mt,
            kg: o.kg,
            adet: o.adet,
            birlestir: 'set',
            kaynak: 'DOKUMA_KD_SENKRON',
            urunEtiket: kalem.ad || kalem.kod || '',
            sessiz: true
        });
        if (res?.ok) ok++;
    }
    return ok;
}

async function dtGenelDurumDokumaDepoStokSenkron(siparisId, kalemler, opts = {}) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (!siparis) return { ok: 0, createdIds: [], updatedBefore: {} };
    const kd = await dtGetKd(siparisId);
    const gruplar = new Map();

    // Tercihen KD güncellemesinden gelen farklar (Excel − önceki toplam)
    const deltalar = Array.isArray(opts.deltalar) ? opts.deltalar : null;
    if (deltalar && deltalar.length) {
        for (const d of deltalar) {
            const idx = parseInt(d.idx, 10);
            if (!Number.isFinite(idx)) continue;
            const mt = parseFloat(d.metre) || 0;
            const kgVal = parseFloat(d.kg) || 0;
            const adVal = parseInt(d.adet, 10) || 0;
            if (mt <= 0 && kgVal <= 0 && adVal <= 0) continue;
            const kalem = kalemler[idx] || {};
            const gKey = dtDokumaStokBirlestirmeAnahtari(siparis, kalem);
            if (!gruplar.has(gKey)) gruplar.set(gKey, { kalem, kalemIdxler: [], metre: 0, kg: 0, adet: 0, urunAdlar: [] });
            const g = gruplar.get(gKey);
            g.metre += mt;
            g.kg += kgVal;
            g.adet += adVal;
            if (!g.kalemIdxler.includes(idx)) g.kalemIdxler.push(idx);
            const ad = kalem.ad || kalem.kod;
            if (ad && !g.urunAdlar.includes(ad)) g.urunAdlar.push(ad);
        }
    } else {
        // Eski çağrılar: brüt toplam yazma — depo sevkini ezmesin diye atla
        console.warn('dtGenelDurumDokumaDepoStokSenkron: deltalar yok, depo set atlandı');
        return { ok: 0, createdIds: [], updatedBefore: {} };
    }

    let ok = 0;
    const allUndo = { createdIds: [], updatedBefore: {} };
    for (const g of gruplar.values()) {
        const res = await dtDokumaDepoStokUpsert(siparis, g.kalem, {
            metre: g.metre,
            kg: g.kg,
            adet: g.adet,
            birlestir: 'add',
            kaynak: 'GENEL_DURUM_EXCEL',
            urunEtiket: g.urunAdlar.join(' / '),
            undoCapture: opts.undoCapture,
            sessiz: true
        });
        if (res?.ok) {
            ok++;
            if (res.undo) {
                allUndo.createdIds.push(...(res.undo.createdIds || []));
                Object.assign(allUndo.updatedBefore, res.undo.updatedBefore || {});
            }
            (g.kalemIdxler || []).forEach(idx => {
                const u = kd.urunler[idx] || kd.urunler[String(idx)];
                (u?.girisler || []).forEach(ug => {
                    if (ug.kaynak === 'GENEL_DURUM_EXCEL' && !ug.stok_id) {
                        ug.stok_id = res.id || null;
                        ug.stok_durumu = 'STOK';
                        ug.stok_otomatik = true;
                    }
                });
            });
        }
    }
    if (ok > 0) {
        await dtSetKd(siparisId, kd);
        erpSyncTablesBackground(['kumas_stok']);
        dtPushHareket({
            dosya: 'SIPARIS',
            islem: 'Genel Durum → Dokuma Depo (fark)',
            siparis: siparis?.sno || String(siparisId),
            detay: `${ok} kalem depoya fark eklendi (sipariş+ürün+renk birleşik)`
        });
        if (appMode === 'DOKUMA_DEPO') renderDokumaDepo();
    }
    return { ok, ...allUndo };
}


function dtDokumaDepoKdRowId(bKey) {
    let h = 0;
    const s = String(bKey || '');
    for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
    return 'kd-' + Math.abs(h).toString(36);
}

/** Dokuma Depo listesi: bu tarihten önceki girişler gösterilmez (eski dönem kontrolü kapalı) */
const DOKUMA_DEPO_LISTE_BASLANGIC_ISO = '2026-07-31';

function dtDokumaDepoListeBaslangic() {
    const d = new Date(DOKUMA_DEPO_LISTE_BASLANGIC_ISO + 'T00:00:00');
    d.setHours(0, 0, 0, 0);
    return d;
}

function dtDokumaDepoGirisTarihDegeri(g) {
    if (!g) return null;
    return g.tarih_iso || g.tarih || null;
}

function dtDokumaDepoTarihParse(val) {
    if (!val) return null;
    if (val instanceof Date && !isNaN(val.getTime())) return val;
    if (typeof val === 'number' && Number.isFinite(val)) {
        const d = new Date(val);
        return isNaN(d.getTime()) ? null : d;
    }
    const s = String(val).trim();
    if (!s) return null;
    const tr = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})(?:[,\s]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
    if (tr) {
        const d = new Date(
            parseInt(tr[3], 10),
            parseInt(tr[2], 10) - 1,
            parseInt(tr[1], 10),
            parseInt(tr[4] || '0', 10),
            parseInt(tr[5] || '0', 10),
            parseInt(tr[6] || '0', 10)
        );
        if (!isNaN(d.getTime())) return d;
    }
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
        const d = new Date(s);
        if (!isNaN(d.getTime())) return d;
    }
    return null;
}

function dtDokumaDepoTarihBugunVeSonrasi(val) {
    const d = dtDokumaDepoTarihParse(val);
    if (!d) return false;
    return d.getTime() >= dtDokumaDepoListeBaslangic().getTime();
}

function dtDokumaDepoBugunkuGirisler(u) {
    const girisler = Array.isArray(u?.girisler) ? u.girisler : [];
    const bugunku = girisler.filter(g => dtDokumaDepoTarihBugunVeSonrasi(dtDokumaDepoGirisTarihDegeri(g)));
    if (bugunku.length) return bugunku;
    return [];
}

function dtDokumaDepoStokSatirBul(bKey) {
    const hedef = String(bKey || '').toUpperCase();
    return (dataCache.kumas_stok || []).find(r =>
        dtKaliteGecenKumasMi(r) &&
        dtDokumaStokSatirBirlestirAnahtari(r).toUpperCase() === hedef
    ) || null;
}

function dtKdDokumaVeriSkoru(v) {
    if (!v?.urunler) return 0;
    let s = 0;
    Object.values(v.urunler).forEach(u => {
        if ((parseFloat(u?.toplam_metre) || 0) > 0) s += 3;
        if ((parseFloat(u?.toplam_kg) || 0) > 0) s += 2;
        s += (u?.girisler || []).length;
    });
    return s;
}

async function dtDokumaDepoKdTopluYukle() {
    const siparisler = dataCache.siparisler || [];
    const sipMap = new Map(siparisler.map(s => [String(s.id), s]));
    const kdBySiparis = new Map();

    try {
        const { data, error } = await erpWithTimeout(
            sb.from('siparis_akis')
                .select('siparis_id,notlar,created_at,kalem_ad')
                .eq('islem', 'KD_DOKUMA')
                .order('created_at', { ascending: false }),
            'dtDokumaDepoKdBulk'
        );
        if (!error && Array.isArray(data)) {
            const grouped = new Map();
            data.forEach(r => {
                const sid = String(r.siparis_id || '');
                if (!sid) return;
                if (!grouped.has(sid)) grouped.set(sid, []);
                grouped.get(sid).push(r);
            });
            grouped.forEach((rows, sid) => {
                const candidates = rows
                    .filter(r => !r?.kalem_ad || String(r.kalem_ad) === 'KD_DOKUMA')
                    .map(r => {
                        try {
                            const parsed = JSON.parse(r?.notlar || '{}') || {};
                            return { row: r, parsed, score: dtKdDokumaVeriSkoru(parsed) };
                        } catch (e) {
                            return null;
                        }
                    })
                    .filter(Boolean)
                    .sort((a, b) => {
                        const ta = new Date(a.row.created_at || 0).getTime();
                        const tb = new Date(b.row.created_at || 0).getTime();
                        if (tb !== ta) return tb - ta;
                        return (b.score || 0) - (a.score || 0);
                    });
                const best = candidates[0]?.parsed;
                if (best?.urunler) {
                    kdBySiparis.set(sid, best);
                    _kdCache[`KD_DOKUMA_${sid}`] = best;
                }
            });
        }
    } catch (e) {
        console.warn('dtDokumaDepoKdTopluYukle bulk', e);
    }

    const eksik = siparisler.filter(s => !kdBySiparis.has(String(s.id)) && _kdCache[`KD_DOKUMA_${s.id}`] === undefined);
    await Promise.all(eksik.slice(0, 80).map(s => sbKdGet(s.id, 'KD_DOKUMA').then(kd => {
        if (kd?.urunler) kdBySiparis.set(String(s.id), kd);
    })));

    siparisler.forEach(s => {
        const sid = String(s.id);
        if (kdBySiparis.has(sid)) return;
        const cached = _kdCache[`KD_DOKUMA_${sid}`];
        if (cached?.urunler) kdBySiparis.set(sid, cached);
    });

    const birlestirMap = new Map();
    kdBySiparis.forEach((kd, sid) => {
        const sip = sipMap.get(sid) || { id: sid, firma: '', sno: '' };
        let kalemler = [];
        try { kalemler = typeof sip.cins === 'string' ? JSON.parse(sip.cins) : (sip.cins || []); } catch (e) { kalemler = []; }
        Object.entries(kd.urunler || {}).forEach(([key, u]) => {
            const idx = parseInt(key, 10);
            if (!Number.isFinite(idx)) return;
            const hasGenelDurum = (u.girisler || []).some(g => g.kaynak === 'GENEL_DURUM_EXCEL');
            let mt = 0;
            let kg = 0;
            let ad = 0;
            let sonTarih = null;
            // Geçici depo sıfırlama: sipariş dokuma toplamları durur, depo listesinde görünmez
            if (u.depo_kalan_sifir) return;
            if (hasGenelDurum) {
                // Depo kalan = girisler (sevk sonrası düşülmüş). Brüt toplam_* kullanılmaz.
                (u.girisler || []).forEach(g => {
                    mt += parseFloat(g.metre || 0) || 0;
                    kg += parseFloat(g.kg || 0) || 0;
                    ad += parseInt(g.adet || 0, 10) || 0;
                    const gd = dtDokumaDepoTarihParse(dtDokumaDepoGirisTarihDegeri(g));
                    if (gd && (!sonTarih || gd > sonTarih)) sonTarih = gd;
                });
            } else {
                const bugunkuGirisler = dtDokumaDepoBugunkuGirisler(u);
                if (!bugunkuGirisler.length) return;
                bugunkuGirisler.forEach(g => {
                    mt += parseFloat(g.metre || 0) || 0;
                    kg += parseFloat(g.kg || 0) || 0;
                    ad += parseInt(g.adet || 0, 10) || 0;
                    const gd = dtDokumaDepoTarihParse(dtDokumaDepoGirisTarihDegeri(g));
                    if (gd && (!sonTarih || gd > sonTarih)) sonTarih = gd;
                });
            }
            if (mt <= 0 && kg <= 0 && ad <= 0) return;
            const kalem = kalemler[idx] || {};
            const bKey = dtDokumaStokBirlestirmeAnahtari(sip, kalem);
            const stokKodu = dtDokumaDepoStokKodu(kalem);
            const urunEtiket = kalem.ad || kalem.kod || '';
            if (!birlestirMap.has(bKey)) {
                birlestirMap.set(bKey, {
                    _birlestirKey: bKey,
                    _kaynak: 'KD_DOKUMA',
                    _kdOnly: true,
                    firma: sip.firma || '',
                    renk: kalem.renk || '',
                    stok_kodu: stokKodu,
                    kumas_cinsi: dtDokumaDepoStokBaslik(sip, kalem, urunEtiket),
                    lot_no: sip.sno || '',
                    miktar_mt: 0,
                    miktar_kg: 0,
                    cuval_sayisi: 0,
                    siparis_id: sip.id,
                    siparis_ids: [],
                    lot_nos: [],
                    kalem,
                    kalem_idx: idx,
                    kalem_refs: [{ siparis_id: sid, kalem_idx: idx }],
                    created_at: null
                });
            }
            const row = birlestirMap.get(bKey);
            row.miktar_mt += mt;
            row.miktar_kg += kg;
            row.cuval_sayisi += ad;
            if (!row.kalem_refs.some(x => String(x.siparis_id) === sid)) {
                row.kalem_refs.push({ siparis_id: sid, kalem_idx: idx });
            }
            if (!row.siparis_ids.includes(sid)) {
                row.siparis_ids.push(sid);
                if (sip.sno && !row.lot_nos.includes(sip.sno)) row.lot_nos.push(sip.sno);
                row.lot_no = row.lot_nos.join(', ');
            }
            if (sonTarih && (!row.created_at || sonTarih > dtDokumaDepoTarihParse(row.created_at))) {
                row.created_at = sonTarih.toISOString();
            }
        });
    });

    const result = [];
    birlestirMap.forEach((kdRow, bKey) => {
        const stok = dtDokumaDepoStokSatirBul(bKey);
        const satir = {
            ...kdRow,
            _birlestirKey: bKey,
            _kaynak: 'KD_DOKUMA',
            _kdOnly: !stok?.id,
            id: stok?.id || dtDokumaDepoKdRowId(bKey),
            miktar_mt: stok?.id ? Math.abs(parseFloat(stok.miktar_mt) || 0) : kdRow.miktar_mt,
            miktar_kg: stok?.id ? Math.abs(parseFloat(stok.miktar_kg) || 0) : kdRow.miktar_kg,
            cuval_sayisi: stok?.id ? Math.abs(parseInt(stok.cuval_sayisi || 0, 10) || 0) : kdRow.cuval_sayisi,
            created_at: kdRow.created_at,
            stok_kodu: kdRow.stok_kodu || stok?.stok_kodu || '',
            kumas_cinsi: kdRow.kumas_cinsi || stok?.kumas_cinsi || '',
            firma: kdRow.firma || stok?.firma || '',
            renk: kdRow.renk || stok?.renk || '',
            lot_no: kdRow.lot_no || stok?.lot_no || '',
            notlar: stok?.notlar || ''
        };
        if (satir.created_at && !dtDokumaDepoTarihBugunVeSonrasi(satir.created_at)) return;
        result.push(satir);
    });

    _dokumaDepoKdSatirlariCache = result;
    return result;
}


function dokumaDepoSetFiltre(key, value) {
    if (!dokumaDepoFiltre || typeof dokumaDepoFiltre !== 'object') return;
    if (!(key in dokumaDepoFiltre)) return;
    dokumaDepoFiltre[key] = value;
    if (key === 'q') {
        const el = document.activeElement;
        window._dokumaDepoFocus = {
            key: 'q',
            pos: (el && el.id === 'dokuma-depo-f-q' && typeof el.selectionStart === 'number') ? el.selectionStart : null
        };
        debounce('dokuma-depo-filtre', () => dokumaDepoYenileAktifEkran({ filterOnly: true }), 180);
        return;
    }
    dokumaDepoYenileAktifEkran({ filterOnly: true });
}

function dokumaDepoFirmaToggle(firmaKey) {
    const key = String(firmaKey || '');
    if (!key) return;
    const tablo = document.getElementById('dokuma-depo-tablo');
    const root = tablo || document;
    const head = root.querySelector('tr.dd-firma-head[data-firma="' + key + '"]');
    const rows = root.querySelectorAll('tr.dd-firma-row[data-firma="' + key + '"]');
    if (!head) return;
    const open = !head.classList.contains('is-open');
    head.classList.toggle('is-open', open);
    rows.forEach(tr => {
        if (open) tr.classList.remove('is-collapsed');
        else tr.classList.add('is-collapsed');
    });
    const hint = head.querySelector('.dd-firma-hint');
    if (hint) hint.textContent = open ? 'kapatmak için tıkla' : 'açmak için tıkla';
}

function renderDokumaDepo() {
    const list = document.getElementById('main-list');
    if (!list) return;

    if (!(list.innerHTML || '').trim()) {
        list.innerHTML = '<div class="panel-box" style="padding:24px;text-align:center;color:var(--text3);font-size:11px">Dokuma Depo yükleniyor…</div>';
    }
    renderDokumaDepoIcerik({ filterOnly: false });
}

async function dtDokumaDepoYenile() {
    _dokumaDepoKdSatirlariCache = [];
    await dokumaDepoYenileAktifEkran({ filterOnly: false });
}

async function renderDokumaDepoIcerik(opts) {
    opts = opts || {};
    const filterOnly = !!opts.filterOnly;
    const embed = !!opts.embed;
    const sevkGirisAktif = opts.sevkGirisAktif === true
        || (opts.sevkGirisAktif == null && appMode === 'SEVKIYAT' && sevkiyatMerkezGrup === 'DOKUMA_DEPO');
    const list = opts.targetId
        ? document.getElementById(opts.targetId)
        : document.getElementById('main-list');
    if (!list) return;

    if (!filterOnly) _dokumaDepoKdSatirlariCache = [];
    const f = dokumaDepoFiltre || { q: '', durum: 'HEPSI', siparisId: '' };
    let rows = [];
    try {
        if (filterOnly && (_dokumaDepoKdSatirlariCache || []).length) {
            rows = _dokumaDepoKdSatirlariCache.slice();
        } else {
            rows = await dtDokumaDepoKdTopluYukle();
        }
    } catch (e) {
        console.warn('renderDokumaDepoIcerik', e);
        rows = [];
    }

    rows = rows.filter(r => dtDokumaDepoTarihBugunVeSonrasi(r.created_at));

    const sevkSet = depoDokumaSevkEdilmisKaynakIdSet(dataCache.kumas_stok || []);

    if (f.siparisId) {
        const sid = String(f.siparisId);
        rows = rows.filter(r =>
            (r.siparis_ids || []).includes(sid) ||
            String(r.siparis_id || '') === sid
        );
    }

    rows.sort((a, b) => {
        const fa = String(a.firma || '').localeCompare(String(b.firma || ''), 'tr', { sensitivity: 'base' });
        if (fa !== 0) return fa;
        const ua = dtDokumaStokSatirUrunNorm(a).localeCompare(dtDokumaStokSatirUrunNorm(b), 'tr', { sensitivity: 'base' });
        if (ua !== 0) return ua;
        const ra = String(a.renk || '').localeCompare(String(b.renk || ''), 'tr', { sensitivity: 'base' });
        if (ra !== 0) return ra;
        return new Date(b.created_at || 0) - new Date(a.created_at || 0);
    });

    const q = String(f.q || '').trim().toLowerCase();
    if (q) {
        rows = rows.filter(r => {
            const sno = (typeof dokumaDepoSatirKayitSno === 'function') ? dokumaDepoSatirKayitSno(r) : (r.siparis_sno || '');
            const blob = [r.lot_no, r.stok_kodu, r.kumas_cinsi, r.firma, r.marka, r.renk, sno, r.siparis_id]
                .map(x => String(x || '').toLowerCase()).join(' ');
            return q.split(/\s+/).filter(Boolean).every(t => blob.includes(t));
        });
    }
    if (f.durum === 'DEPO') rows = rows.filter(r => r._kdOnly || !sevkSet.has(String(r.id)));
    else if (f.durum === 'SEVK') rows = rows.filter(r => !r._kdOnly && sevkSet.has(String(r.id)));

    const ozetMt = rows.reduce((a, r) => a + Math.abs(parseFloat(r.miktar_mt) || 0), 0);
    const ozetKg = rows.reduce((a, r) => a + Math.abs(parseFloat(r.miktar_kg) || 0), 0);
    const ozetAd = rows.reduce((a, r) => a + Math.abs(parseInt(r.cuval_sayisi || 0, 10) || 0), 0);
    const bekleyen = rows.filter(r => r._kdOnly || !sevkSet.has(String(r.id))).length;
    const sevkEdilen = rows.filter(r => !r._kdOnly && sevkSet.has(String(r.id))).length;

    const siparisOpts = (() => {
        const ids = new Set();
        (_dokumaDepoKdSatirlariCache || rows).forEach(r => {
            (r.siparis_ids || []).forEach(id => ids.add(String(id)));
            if (r.siparis_id) ids.add(String(r.siparis_id));
            const sno = String(r.lot_no || '').trim().split(',')[0].trim();
            if (sno) {
                const sip = (dataCache.siparisler || []).find(s => String(s.sno || '').trim() === sno);
                if (sip) ids.add(String(sip.id));
            }
        });
        return Array.from(ids)
            .map(id => (dataCache.siparisler || []).find(s => String(s.id) === id))
            .filter(Boolean)
            .sort((a, b) => String(a.sno || '').localeCompare(String(b.sno || ''), 'tr', { numeric: true, sensitivity: 'base' }));
    })();

    const sel = (v, cur) => (v === cur ? 'selected' : '');
    const filtHtml = `
    <div class="panel-box" style="padding:14px 16px;margin-bottom:14px;border:1px solid var(--border)">
      <div style="display:flex;flex-wrap:wrap;align-items:flex-end;gap:10px">
        <div style="flex:1;min-width:180px">
          <label class="pro-label" style="margin-bottom:4px">Arama</label>
          <input type="text" id="dokuma-depo-f-q" class="pro-input" style="width:100%;padding:8px 10px;font-size:11px" placeholder="Sipariş, stok kodu, ürün, firma…" value="${pdfEsc(f.q || '')}" oninput="dokumaDepoSetFiltre('q', this.value)">
        </div>
        <div>
          <label class="pro-label" style="margin-bottom:4px">Sipariş</label>
          <select id="dokuma-depo-f-siparis" class="pro-input" style="min-width:148px;padding:8px 10px;font-size:11px" onchange="dokumaDepoSetFiltre('siparisId', this.value)">
            <option value="" ${sel('', f.siparisId || '')}>Tüm siparişler</option>
            ${siparisOpts.map(s => `<option value="${s.id}" ${sel(String(s.id), String(f.siparisId || ''))}>${pdfEsc(s.sno || s.id)}</option>`).join('')}
          </select>
        </div>
        <div>
          <label class="pro-label" style="margin-bottom:4px">Durum</label>
          <select id="dokuma-depo-f-durum" class="pro-input" style="min-width:128px;padding:8px 10px;font-size:11px" onchange="dokumaDepoSetFiltre('durum', this.value)">
            <option value="HEPSI" ${sel('HEPSI', f.durum)}>Hepsi</option>
            <option value="DEPO" ${sel('DEPO', f.durum)}>Depoda</option>
            <option value="SEVK" ${sel('SEVK', f.durum)}>Sevk edildi</option>
          </select>
        </div>
        <button type="button" class="pro-input" style="cursor:pointer;padding:8px 14px;font-weight:600;border-radius:8px;background:var(--surface2)" onclick="dokumaDepoFiltre={q:'',durum:'HEPSI',siparisId:''};dokumaDepoYenileAktifEkran()">Filtreleri sıfırla</button>
        <button type="button" class="btn-pro btn-primary-pro" style="padding:8px 14px;font-size:10px" onclick="dtDokumaDepoYenile()">↻ Yenile</button>
        ${embed ? '' : `<button type="button" onclick="erpGeciciDokumaDepoSifirla()" class="btn-pro" title="Geçici — sipariş dokuma toplamına dokunmaz" style="padding:8px 12px;font-size:10px;background:rgba(239,68,68,0.12);color:#f87171;border:1px solid rgba(239,68,68,0.35);font-weight:700">🗑 Depo mallarını sıfırla</button>`}
        <button type="button" class="pro-input" style="cursor:pointer;padding:8px 14px;font-weight:600;border-radius:8px;background:rgba(99,102,241,0.1);color:var(--accent)" onclick="setAppMode('DOKUMA_SEVK_GECMIS')">📋 Sevk geçmişi</button>
        ${!sevkGirisAktif ? `<button type="button" class="btn-pro btn-primary-pro" style="padding:8px 14px;font-size:10px" onclick="sevkiyatMerkezAc('DOKUMA_DEPO')">🚚 Sevkiyat Genel Merkezi</button>` : ''}
      </div>
      <div style="font-size:10px;color:var(--text3);margin-top:10px;line-height:1.45">Güncel dönem Dokuma Takip kayıtları listelenir. Sevkiyat Merkezi'nde kalemleri <strong>+ Ekle</strong> ile toplu listeye alıp tek seferde sevk edebilirsiniz. <strong>Aynı sipariş + ürün + renk</strong> tek satırda toplanır.</div>
    </div>`;

    const ozetHtml = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-bottom:14px">
      <div style="padding:12px 14px;border-radius:10px;background:rgba(52,211,153,0.08);border:1px solid rgba(52,211,153,0.2)">
        <div style="font-size:8px;color:var(--emerald-c);font-family:'DM Mono',monospace;text-transform:uppercase">Depoda</div>
        <div style="font-family:'Instrument Serif',serif;font-size:18px;color:var(--emerald-c)">${bekleyen}</div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">bekleyen kalem</div>
      </div>
      <div style="padding:12px 14px;border-radius:10px;background:rgba(109,113,255,0.06);border:1px solid rgba(109,113,255,0.2)">
        <div style="font-size:8px;color:var(--accent);font-family:'DM Mono',monospace;text-transform:uppercase">Sevk edildi</div>
        <div style="font-family:'Instrument Serif',serif;font-size:18px;color:var(--text)">${sevkEdilen}</div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">kalem</div>
      </div>
      <div style="padding:12px 14px;border-radius:10px;background:rgba(34,211,238,0.06);border:1px solid rgba(34,211,238,0.2)">
        <div style="font-size:8px;color:var(--cyan-c);font-family:'DM Mono',monospace;text-transform:uppercase">Toplam metre</div>
        <div style="font-family:'Instrument Serif',serif;font-size:18px;color:var(--cyan-c)">${ozetMt.toFixed(1)}</div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">m</div>
      </div>
      <div style="padding:12px 14px;border-radius:10px;background:rgba(251,191,36,0.08);border:1px solid rgba(251,191,36,0.2)">
        <div style="font-size:8px;color:var(--amber-c);font-family:'DM Mono',monospace;text-transform:uppercase">Toplam kg</div>
        <div style="font-family:'Instrument Serif',serif;font-size:18px;color:var(--amber-c)">${ozetKg.toFixed(1)}</div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">kg</div>
      </div>
      <div style="padding:12px 14px;border-radius:10px;background:rgba(16,185,129,0.08);border:1px solid rgba(16,185,129,0.25)">
        <div style="font-size:8px;color:var(--emerald-c);font-family:'DM Mono',monospace;text-transform:uppercase">Ürün adedi</div>
        <div style="font-family:'Instrument Serif',serif;font-size:18px;color:var(--emerald-c)">${ozetAd.toLocaleString('tr-TR')}</div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">ad</div>
      </div>
    </div>`;

    const satirlar = rows.length ? (() => {
        // Sipariş bazlı grup: kaydın yazıldığı sno · müşteri
        const sorted = [...rows].sort((a, b) => {
            const sa = dokumaDepoSatirKayitSno(a);
            const sb = dokumaDepoSatirKayitSno(b);
            const c1 = String(sa).localeCompare(String(sb), 'tr', { numeric: true, sensitivity: 'base' });
            if (c1) return c1;
            const c2 = String(a.firma || '').localeCompare(String(b.firma || ''), 'tr');
            if (c2) return c2;
            return String(dtDokumaStokSatirUrunNorm(a) || '').localeCompare(String(dtDokumaStokSatirUrunNorm(b) || ''), 'tr');
        });
        let sonGrup = null;
        const out = [];
        let grupIdx = 0;
        sorted.forEach(r => {
            const kayitSno = dokumaDepoSatirKayitSno(r);
            const firma = String(r.firma || '—').trim() || '—';
            const grupKey = `${kayitSno}||${firma}`;
            if (grupKey !== sonGrup) {
                sonGrup = grupKey;
                grupIdx += 1;
                const grupRows = sorted.filter(x => dokumaDepoSatirKayitSno(x) === kayitSno && (String(x.firma || '—').trim() || '—') === firma);
                const firmaMt = grupRows.reduce((a, x) => a + Math.abs(parseFloat(x.miktar_mt) || 0), 0);
                const dataKey = 'g' + grupIdx;
                const adet = grupRows.length;
                out.push(`<tr class="dd-firma-head" data-firma="${dataKey}" onclick="dokumaDepoFirmaToggle('${dataKey}')">
                    <td colspan="8" style="padding:8px 10px;font-size:10px;font-weight:700;color:var(--accent);letter-spacing:0.04em">
                        <span class="dd-firma-chevron">▶</span>
                        <span style="font-family:'DM Mono',monospace;font-weight:800;margin-right:6px">${pdfEsc(kayitSno)}</span>${pdfEsc(firma)}
                        <span style="font-weight:400;color:var(--text3);margin-left:6px">${firmaMt.toFixed(1)} m · ${adet} kalem</span>
                        <span class="dd-firma-hint" style="font-weight:400;color:var(--text3);margin-left:8px;font-size:8px;font-family:'DM Mono',monospace">açmak için tıkla</span>
                    </td>
                </tr>`);
            }
            const dataKey = 'g' + grupIdx;
            const mt = Math.abs(parseFloat(r.miktar_mt) || 0);
            const kg = Math.abs(parseFloat(r.miktar_kg) || 0);
            const ad = Math.abs(parseInt(r.cuval_sayisi || 0, 10) || 0);
            const sevkEdildi = !r._kdOnly && sevkSet.has(String(r.id));
            const sevkEdilebilir = !sevkEdildi && dokumaDepoSevkEdilebilirMi(r);
            const urunAd = dtDokumaStokSatirUrunNorm(r) || String(r.kumas_cinsi || r.stok_kodu || '—');
            const tarih = r.created_at ? new Date(r.created_at).toLocaleDateString('tr-TR') : '—';
            const tarihKisa = (() => {
                const p = String(tarih || '').split('.');
                if (p.length >= 3 && p[2].length === 4) return `${p[0]}.${p[1]}.${p[2].slice(-2)}`;
                return tarih;
            })();
            const stokKod = String(r.stok_kodu || '').trim();
            const durumPill = sevkEdildi
                ? '<span class="pill pill-gray" style="font-size:7px;padding:1px 5px">Sevk</span>'
                : '<span class="pill pill-green" style="font-size:7px;padding:1px 5px">Depo</span>';
            const sevkHucre = sevkEdilebilir
                ? (sevkGirisAktif
                    ? `<div class="dd-sevk-row">
                    ${mt > 0 ? `<span class="dd-sevk-qty-wrap"><input id="dd-sevk-mt-${r.id}" type="number" min="0" step="0.01" class="pro-input dd-sevk-qty" value="${mt}"><span class="dd-sevk-unit dd-sevk-unit--m">m</span></span>` : `<input type="hidden" id="dd-sevk-mt-${r.id}" value="0">`}
                    ${kg > 0 ? `<span class="dd-sevk-qty-wrap"><input id="dd-sevk-kg-${r.id}" type="number" min="0" step="0.01" class="pro-input dd-sevk-qty" value="${kg}"><span class="dd-sevk-unit dd-sevk-unit--kg">kg</span></span>` : `<input type="hidden" id="dd-sevk-kg-${r.id}" value="0">`}
                    ${ad > 0 ? `<span class="dd-sevk-qty-wrap"><input id="dd-sevk-adet-${r.id}" type="number" min="0" step="1" class="pro-input dd-sevk-qty" value="${ad}"><span class="dd-sevk-unit dd-sevk-unit--ad">ad</span></span>` : `<input type="hidden" id="dd-sevk-adet-${r.id}" value="0">`}
                    <button type="button" onclick="dokumaDepoTopluSepeteEkle('${r.id}')" class="btn-pro btn-primary-pro dd-sevk-btn" title="Toplu sevk listesine ekle"${dokumaDepoTopluSepetSatirBul(r.id) ? ' style="background:var(--emerald-c)"' : ''}>+ Ekle</button>
                </div>`
                    : `<button type="button" class="btn-pro btn-primary-pro" style="padding:4px 8px;font-size:9px" onclick="sevkiyatMerkezAc('DOKUMA_DEPO')">Sevk →</button>`)
                : (sevkEdildi ? '<span style="font-size:8px;color:var(--text3)">—</span>' : '<span style="font-size:8px;color:var(--text3)">—</span>');
            out.push(`<tr class="dd-firma-row is-collapsed" data-firma="${dataKey}">
                <td class="mono" style="font-size:10px;color:var(--text3);white-space:nowrap;padding:6px 8px">${pdfEsc(tarihKisa)}</td>
                <td class="mono" style="font-size:10px;color:var(--rose-c);max-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:6px 8px" title="${pdfEsc(r.renk || '')}">${pdfEsc(r.renk || '—')}</td>
                <td style="max-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:6px 8px" title="${pdfEsc([urunAd, stokKod].filter(Boolean).join(' · '))}">
                    <span style="font-size:11px;font-weight:500">${pdfEsc(urunAd)}</span>${stokKod ? `<span style="font-size:9px;color:var(--text3);margin-left:4px">${pdfEsc(stokKod)}</span>` : ''}
                </td>
                <td class="mono" style="text-align:right;color:var(--cyan-c);font-size:10px;white-space:nowrap;padding:6px 8px">${mt > 0 ? mt.toFixed(0) : '—'}</td>
                <td class="mono" style="text-align:right;color:var(--accent2);font-size:10px;white-space:nowrap;padding:6px 8px">${kg > 0 ? kg.toFixed(0) : '—'}</td>
                <td class="mono" style="text-align:right;color:var(--emerald-c);font-size:10px;white-space:nowrap;padding:6px 8px">${ad > 0 ? ad : '—'}</td>
                <td style="text-align:center;padding:6px 6px">${durumPill}</td>
                <td style="padding:4px 6px;min-width:0;overflow:hidden">${sevkHucre}</td>
            </tr>`);
        });
        return out.join('');
    })() : '';

    const tabloHtml = rows.length
        ? `<div class="panel-box" style="overflow:hidden">
            <div class="panel-head">
                <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--emerald-c)"></span>${embed ? 'Dokuma Depo Sevkiyat' : 'Dokuma Depo Stokları'}</span>
                <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;margin-left:auto">${rows.length} kayıt</span>
            </div>
            <div style="width:100%;overflow:hidden">
                <table class="dt-table" id="dokuma-depo-tablo" style="width:100%;table-layout:fixed;border-collapse:collapse">
                    <colgroup>
                        <col style="width:8%">
                        <col style="width:13%">
                        <col style="width:24%">
                        <col style="width:6%">
                        <col style="width:6%">
                        <col style="width:6%">
                        <col style="width:7%">
                        <col style="width:33%">
                    </colgroup>
                    <thead><tr>
                        <th style="font-size:9px;padding:5px 8px">Tarih</th>
                        <th style="font-size:9px;padding:5px 8px">Renk</th>
                        <th style="font-size:9px;padding:5px 8px">Ürün</th>
                        <th style="font-size:9px;padding:5px 8px;text-align:right">m</th>
                        <th style="font-size:9px;padding:5px 8px;text-align:right">kg</th>
                        <th style="font-size:9px;padding:5px 8px;text-align:right">ad</th>
                        <th style="font-size:9px;padding:5px 8px;text-align:center">Durum</th>
                        <th style="font-size:9px;padding:5px 8px">Sevk</th>
                    </tr></thead>
                    <tbody>${satirlar}</tbody>
                </table>
            </div>
        </div>`
        : `<div class="panel-box" style="padding:36px 16px;text-align:center;color:var(--text3);font-size:11px;line-height:1.6">
            ${f.siparisId || q || f.durum !== 'HEPSI'
                ? 'Filtrelere uygun kayıt yok.'
                : `Güncel dönem Dokuma Depo kaydı yok.<br><span style="font-size:10px">Dokuma Takip'te <strong>Kaydet</strong> ile girilen yeni kumaşlar burada listelenir.<br>Aynı <strong>sipariş + ürün + renk</strong> tek satırda birleştirilir.</span>`}
        </div>`;

    list.innerHTML = filtHtml + (sevkGirisAktif ? dokumaDepoTopluSepetHtml() : '') + ozetHtml + tabloHtml;
    currentData = rows;

    if (window._dokumaDepoFocus?.key === 'q') {
        const el = document.getElementById('dokuma-depo-f-q');
        if (el) {
            el.focus();
            const p = window._dokumaDepoFocus.pos;
            if (typeof p === 'number') {
                const safe = Math.max(0, Math.min(p, String(el.value || '').length));
                try { el.setSelectionRange(safe, safe); } catch (e) {}
            }
        }
    }
}

function dtSelectSiparis(id) {
    dtSeciliSiparisId = id || null;
    saveUiState({ dtSeciliSiparisId });
    if (id) {
        dtGetKd(id).finally(() => renderDokumaTakip());
    } else {
        renderDokumaTakip();
    }
}

function dtMigrateDosyaAktif(id) {
    if (['LEVENT', 'HASIL', 'YEDEK'].includes(id)) return 'SIPARIS';
    return id === 'HAREKET' ? 'HAREKET' : (id || 'SIPARIS');
}

function dtSetDosya(dosya) {
    dtDosyaAktif = dtMigrateDosyaAktif(dosya);
    saveUiState({ dtDosyaAktif });
    renderDokumaTakip();
}

function dtSetHareketFiltre(key, value) {
    if (!dtHareketFiltre || typeof dtHareketFiltre !== 'object') return;
    if (!(key in dtHareketFiltre)) return;
    dtHareketFiltre[key] = String(value ?? '');
    const el = document.activeElement;
    window._dtHareketFocus = {
        key,
        pos: (el && typeof el.selectionStart === 'number') ? el.selectionStart : null
    };
    debounce('dt-hareket-filtre', () => renderDokumaTakip(), 180);
}

function dtLoadOpsData() {
    try {
        const raw = localStorage.getItem(DT_OPS_LS_KEY);
        const p = raw ? JSON.parse(raw) : null;
        const hareketler = Array.isArray(p?.hareketler) ? p.hareketler : [];
        return { hareketler };
    } catch (e) {
        return { hareketler: [] };
    }
}

function dtSaveOpsData(data) {
    try { localStorage.setItem(DT_OPS_LS_KEY, JSON.stringify(data || {})); } catch (e) {}
}

// ── Dokuma → Kumaş Depo stok kararı ──
function dtSiparisSimteksMi(siparis) {
    const firma = String(siparis?.firma || '').trim().toLocaleLowerCase('tr-TR');
    return firma.includes('simteks');
}

function dtKalemStokKodu(kalem) {
    return String(kalem?.kod || kalem?.stok_kodu || '').trim();
}

function dtKalemOtomatikStokaMi(siparis, kalem) {
    return dtSiparisSimteksMi(siparis) && !!dtKalemStokKodu(kalem);
}

/**
 * Sipariş kalemi hangi birimle açıldıysa dokumadan itibaren o veri girilir (kullanıcı, 20.09.2026):
 *   ADET → metre + adet  ('ADET')
 *   KG   → metre + kg    ('KG')
 *   MT   → YALNIZ metre  ('MT' — ikinci birim yok)
 * Dokuma Paneli (dokuma-mobil.html ikinciBirimTip), Konfeksiyon Panel ve mobil aynı kuralı taşır.
 */
function dtKalemIkinciBirimTip(kalem) {
    const birim = siparisKalemBirim(kalem);
    if (birim === 'KG') return 'KG';
    if (birim === 'MT') return 'MT';
    return 'ADET';
}

/** Girişte istenen alanlar — formlar ve yazma kapıları bunu kullanır. */
function dtKalemGirisAlanlari(kalem) {
    const tip = dtKalemIkinciBirimTip(kalem);
    return { tip, metre: true, kg: tip === 'KG', adet: tip === 'ADET' };
}

/**
 * Sipariş birimine göre dokunan özeti:
 * ADET → metre + adet | KG → metre + kg | MT → yalnız metre (ikinci = metre, sipariş birimiyle kıyas için)
 */
function dokumaUrunIkinciOzet(u, kalem) {
    const tip = dtKalemIkinciBirimTip(kalem);
    let metre = parseFloat(u?.toplam_metre) || 0;
    let kg = parseFloat(u?.toplam_kg) || 0;
    let adet = parseInt(u?.toplam_adet, 10) || 0;
    if (!(metre > 0 || kg > 0 || adet > 0) && Array.isArray(u?.girisler)) {
        u.girisler.forEach((g) => {
            metre += parseFloat(g?.metre) || 0;
            kg += parseFloat(g?.kg) || 0;
            adet += parseInt(g?.adet, 10) || 0;
        });
    }
    if (tip === 'KG') {
        return { tip: 'KG', metre, ikinci: kg, kg, adet: 0, etiket: 'kg' };
    }
    if (tip === 'MT') {
        return { tip: 'MT', metre, ikinci: metre, kg: 0, adet: 0, etiket: 'm' };
    }
    return { tip: 'ADET', metre, ikinci: adet, kg: 0, adet, etiket: 'adet' };
}

/** Depo → konf sevk: ana miktar sipariş birimine göre */
function dokumaSevkAnaMiktar(kalem, mt, kg, adet) {
    const tip = dtKalemIkinciBirimTip(kalem);
    const m = parseFloat(mt) || 0;
    const k = parseFloat(kg) || 0;
    const a = parseInt(adet, 10) || 0;
    if (tip === 'KG') return k > 0 ? k : (m > 0 ? m : a);
    if (tip === 'MT') return m;
    return a > 0 ? a : (m > 0 ? m : k);
}

/** Sevk not etiketi: her zaman metre + (kg|adet) sipariş birimine göre */
function dokumaSevkMiktarEtiket(kalem, mt, kg, adet) {
    const tip = dtKalemIkinciBirimTip(kalem);
    const m = parseFloat(mt) || 0;
    const k = parseFloat(kg) || 0;
    const a = parseInt(adet, 10) || 0;
    const parts = [];
    if (m > 0) parts.push(`${m.toFixed(1)} m`);
    if (tip === 'KG') {
        if (k > 0) parts.push(`${k.toFixed(1)} kg`);
    } else if (tip === 'ADET' && a > 0) {
        parts.push(`${a} ad`);
    }
    if (!parts.length) {
        if (k > 0) parts.push(`${k.toFixed(1)} kg`);
        if (a > 0) parts.push(`${a} ad`);
        if (m > 0) parts.push(`${m.toFixed(1)} m`);
    }
    return parts.join(' · ');
}

function dtGirisMiktarDogrula(kalem, metre, ikinciDeger, ikinciTip) {
    const ad = kalem?.ad || kalem?.kod || 'Ürün';
    if (metre <= 0) return { ok: false, mesaj: `${ad} için metre (m) zorunludur.` };
    /* Metre sipariş: yalnız metre girilir, ikinci birim istenmez. */
    if (dtKalemIkinciBirimTip(kalem) === 'MT') return { ok: true };
    if (ikinciDeger <= 0) return { ok: false, mesaj: `${ad} için hem metre hem ${ikinciTip} girilmelidir.` };
    return { ok: true };
}







/* ── Dokuma giriş denetim izi ─────────────────────────────────────
   Dokuma Paneli ile BİREBİR aynı biçim (bkz. mobil/dokuma-panel/dokuma-mobil.html
   → dokumaDenetimYaz). Bir kayıt silinince üstündeki gecmis[] de onunla gider;
   silmenin izi yalnızca bu ayrı satırda kalır.
   notlar JSON'ında üst düzey adet/metre/mt/kg anahtarı KULLANILMAZ — değerler
   eski/yeni içinde durur; yoksa siparisOpMiktarMetin bunları gerçek üretim
   miktarı sanıp günlükte sahte bir üretim satırı gösterir. */
function dtGirisMiktarOzet(g) {
    const parts = [];
    const m = parseFloat(g?.metre || 0) || 0;
    const kg = parseFloat(g?.kg || 0) || 0;
    const ad = parseInt(g?.adet || 0, 10) || 0;
    if (m) parts.push(m.toFixed(1) + ' m');
    if (kg) parts.push(kg.toFixed(1) + ' kg');
    if (ad) parts.push(ad + ' adet');
    return parts.join(' · ') || '—';
}

async function dtDokumaDenetimYaz(tip, ctx) {
    try {
        const kullanici = String((typeof erpCurrentUser !== 'undefined'
            && (erpCurrentUser?.display_name || erpCurrentUser?.username)) || '').trim() || '—';
        const norm = (v) => v ? {
            metre: parseFloat(v.metre || 0) || 0,
            kg: parseFloat(v.kg || 0) || 0,
            adet: parseInt(v.adet || 0, 10) || 0
        } : null;
        const note = tip === 'DOKUMA_SIL'
            ? `Dokuma kaydı silindi · ${dtGirisMiktarOzet(ctx.eski)} · giren: ${ctx.girisUser || '—'} (${ctx.girisTarih || '—'})`
            : `Dokuma kaydı düzeltildi · ${dtGirisMiktarOzet(ctx.eski)} → ${dtGirisMiktarOzet(ctx.yeni)} · giren: ${ctx.girisUser || '—'} (${ctx.girisTarih || '—'})`;
        await sb.from('siparis_akis').insert([{
            siparis_id: ctx.siparisId,
            islem: tip,
            kalem_ad: ctx.kalemAd || 'Dokuma',
            miktar: 0,
            notlar: JSON.stringify({
                kaynak: 'MASAUSTU_DOKUMA_TAKIP',
                user: kullanici,
                kullanici,
                ts: new Date().toISOString(),
                kalem_idx: ctx.kalemIdx,
                gid: ctx.gid || '',
                eski: norm(ctx.eski),
                yeni: norm(ctx.yeni),
                giris_user: ctx.girisUser || '',
                giris_ts: ctx.girisTarihIso || '',
                note
            })
        }]);
    } catch (e) {
        console.warn('dokuma denetim satırı yazılamadı', e);
        erpToast('İşlem yapıldı ama denetim kaydı yazılamadı.', 'warning');
    }
}

/** Giriş geçmişi satırının ürün etiketi — denetim satırında görünür. */
function dtGirisKalemEtiketi(siparis, urunIdx) {
    let kalemler = [];
    try { kalemler = typeof siparis?.cins === 'string' ? JSON.parse(siparis.cins) : (siparis?.cins || []); } catch (e) {}
    const k = kalemler[urunIdx] || {};
    return [k.ad || k.kod || `Kalem ${urunIdx + 1}`, k.renk, k.ebat || k.olcu].filter(Boolean).join(' · ') || 'Dokuma';
}

async function dtGirisSil(urunIdx, girisIdx) {
    if (!dtSeciliSiparisId) return;
    const kd = await dtGetKd(dtSeciliSiparisId);
    const u = kd?.urunler?.[urunIdx];
    if (!u || !Array.isArray(u.girisler) || !u.girisler[girisIdx]) return;
    const g = u.girisler[girisIdx];
    const m = parseFloat(g?.metre || 0) || 0;
    const kg = parseFloat(g?.kg || 0) || 0;
    const ad = parseInt(g?.adet || 0, 10) || 0;
    if (!confirm('Bu dokuma giriş satırı silinsin mi?\n(Dokuma Depo listesinden de düşer)\n\nSilme işlemi adınızla kayda geçer.')) return;
    u.girisler.splice(girisIdx, 1);
    u.toplam_metre = (parseFloat(u.toplam_metre || 0) - m);
    u.toplam_kg = (parseFloat(u.toplam_kg || 0) - kg);
    u.toplam_adet = (parseInt(u.toplam_adet || 0, 10) - ad);
    if (u.toplam_metre < 0) u.toplam_metre = 0;
    if (u.toplam_kg < 0) u.toplam_kg = 0;
    if (u.toplam_adet < 0) u.toplam_adet = 0;
    await dtSetKd(dtSeciliSiparisId, kd);
    _dokumaDepoKdSatirlariCache = [];
    const siparis = (dataCache.siparisler || []).find(s => s.id == dtSeciliSiparisId);
    dtPushHareket({
        dosya: 'SIPARIS',
        islem: 'Dokuma Girişi Silindi',
        siparis: siparis?.sno || String(dtSeciliSiparisId),
        detay: `Ürün #${urunIdx + 1} giriş silindi · -${m.toFixed(2)} m · -${kg.toFixed(2)} kg · -${ad} adet`
    });
    /* dtPushHareket yalnızca bu bilgisayarın localStorage'ına yazar — paylaşılan
       iz için denetim satırı şart. */
    await dtDokumaDenetimYaz('DOKUMA_SIL', {
        siparisId: dtSeciliSiparisId,
        kalemIdx: urunIdx,
        kalemAd: dtGirisKalemEtiketi(siparis, urunIdx),
        gid: g?.gid,
        eski: { metre: m, kg, adet: ad },
        yeni: null,
        girisUser: g?.user || g?.kullanici || '',
        girisTarih: g?.tarih || '',
        girisTarihIso: g?.tarih_iso || ''
    });
    erpToast('Dokuma giriş satırı silindi.', 'success');
    renderDokumaTakip();
}

async function dtGirisRevizePrompt(urunIdx, girisIdx) {
    if (!dtSeciliSiparisId) return;
    const kd = await dtGetKd(dtSeciliSiparisId);
    const u = kd?.urunler?.[urunIdx];
    if (!u || !Array.isArray(u.girisler) || !u.girisler[girisIdx]) return;
    const g = u.girisler[girisIdx];
    const om = parseFloat(g?.metre || 0) || 0;
    const okg = parseFloat(g?.kg || 0) || 0;
    const oad = parseInt(g?.adet || 0, 10) || 0;
    const nmRaw = prompt('Yeni metre değeri (boş=0):', String(om));
    if (nmRaw === null) return;
    const nkgRaw = prompt('Yeni kg değeri (boş=0):', String(okg));
    if (nkgRaw === null) return;
    const nadRaw = prompt('Yeni adet değeri (boş=0):', String(oad));
    if (nadRaw === null) return;
    const nm = parseFloat(String(nmRaw).replace(',', '.'));
    const nkg = parseFloat(String(nkgRaw).replace(',', '.'));
    const nad = parseInt(String(nadRaw), 10);
    const vm = Number.isFinite(nm) ? nm : 0;
    const vkg = Number.isFinite(nkg) ? nkg : 0;
    const vad = Number.isFinite(nad) ? nad : 0;
    g.metre = vm || null;
    g.kg = vkg || null;
    g.adet = vad || null;
    /* Düzeltme kaydın üstünde taşınır; panel de aynı alanı okur/yazar. */
    g.gecmis = [...(Array.isArray(g.gecmis) ? g.gecmis : []), {
        tip: 'DUZENLE',
        ts: new Date().toISOString(),
        user: String((typeof erpCurrentUser !== 'undefined'
            && (erpCurrentUser?.display_name || erpCurrentUser?.username)) || '').trim() || '—',
        eski: { metre: om, kg: okg, adet: oad },
        yeni: { metre: vm, kg: vkg, adet: vad }
    }];
    u.toplam_metre = (parseFloat(u.toplam_metre || 0) - om) + vm;
    u.toplam_kg = (parseFloat(u.toplam_kg || 0) - okg) + vkg;
    u.toplam_adet = (parseInt(u.toplam_adet || 0, 10) - oad) + vad;
    if (u.toplam_metre < 0) u.toplam_metre = 0;
    if (u.toplam_kg < 0) u.toplam_kg = 0;
    if (u.toplam_adet < 0) u.toplam_adet = 0;
    await dtSetKd(dtSeciliSiparisId, kd);
    _dokumaDepoKdSatirlariCache = [];
    const siparis = (dataCache.siparisler || []).find(s => s.id == dtSeciliSiparisId);
    dtPushHareket({
        dosya: 'SIPARIS',
        islem: 'Dokuma Girişi Revize Edildi',
        siparis: siparis?.sno || String(dtSeciliSiparisId),
        detay: `Ürün #${urunIdx + 1} giriş revize · m: ${om.toFixed(2)}→${vm.toFixed(2)} · kg: ${okg.toFixed(2)}→${vkg.toFixed(2)} · adet: ${oad}→${vad}`
    });
    await dtDokumaDenetimYaz('DOKUMA_DUZENLE', {
        siparisId: dtSeciliSiparisId,
        kalemIdx: urunIdx,
        kalemAd: dtGirisKalemEtiketi(siparis, urunIdx),
        gid: g?.gid,
        eski: { metre: om, kg: okg, adet: oad },
        yeni: { metre: vm, kg: vkg, adet: vad },
        girisUser: g?.user || g?.kullanici || '',
        girisTarih: g?.tarih || '',
        girisTarihIso: g?.tarih_iso || ''
    });
    erpToast('Dokuma giriş satırı revize edildi.', 'success');
    renderDokumaTakip();
}

/* ── Dokuma Takip ↔ Tezgah bağlantısı (ürün bazında) ─────────────────
   Masaüstü (05-dokuma-ops.js) ve mobil (mobil-app.js) BİREBİR AYNI blok.
   Bir sipariş kaleminin hangi tezgah(lar)da dokunduğu dokuma_levent_is
   tablosundaki (siparis_id, kalem_idx) bağından okunur — sipariş değil
   ÜRÜN bağlanır, çünkü aynı siparişin ürünleri farklı tezgahlarda dokunur.
   Dokuma girişi bir tezgah seçilerek yapılırsa KD_DOKUMA giriş kaydına
   tezgah_id / levent_id / is_id yazılır; tezgahın dokunan metresi bu
   kayıtlardan hesaplanır (ayrı sayaç tutulmaz, kayma olmaz). */
let _dtTezgahCache = { sid: null, isler: [], tezgahAd: {}, levent: {}, ts: 0 };

async function dtTezgahIsleriYukle(sid, force) {
    if (!sid) return _dtTezgahCache;
    if (!force && String(_dtTezgahCache.sid) === String(sid) && (Date.now() - _dtTezgahCache.ts) < 20000) {
        return _dtTezgahCache;
    }
    try {
        const { data: isler, error } = await sb.from('dokuma_levent_is')
            .select('id,tezgah_id,levent_id,siparis_id,kalem_idx,durum,sira,hedef_metre,hedef_adet,urun_adi')
            .eq('siparis_id', sid).eq('aktif', true);
        if (error) throw error;
        const tezIds = [...new Set((isler || []).map(i => i.tezgah_id).filter(v => v != null))];
        const tezgahAd = {};
        const levent = {};
        if (tezIds.length) {
            const [tz, lv] = await Promise.all([
                sb.from('tezgahlar').select('id,tezgah_no').in('id', tezIds),
                sb.from('dokuma_levent').select('id,tezgah_id').in('tezgah_id', tezIds)
                    .eq('durum', 'TEZGAHTA').eq('aktif', true)
            ]);
            (tz.data || []).forEach(t => { tezgahAd[t.id] = t.tezgah_no; });
            (lv.data || []).forEach(l => { levent[l.tezgah_id] = l.id; });
        }
        _dtTezgahCache = { sid, isler: isler || [], tezgahAd, levent, ts: Date.now() };
    } catch (e) {
        /* Tezgah tabloları yoksa ya da okunamazsa Dokuma Takip eskisi gibi çalışır. */
        console.warn('dtTezgahIsleriYukle', e?.message || e);
        _dtTezgahCache = { sid, isler: [], tezgahAd: {}, levent: {}, ts: Date.now() };
    }
    return _dtTezgahCache;
}

function dtKalemTezgahIsleri(sid, kalemIdx) {
    if (String(_dtTezgahCache.sid) !== String(sid)) return [];
    return _dtTezgahCache.isler
        .filter(x => x.kalem_idx !== null && x.kalem_idx !== undefined
            && Number(x.kalem_idx) === Number(kalemIdx)
            && !['BITTI', 'IPTAL'].includes(String(x.durum || '').toUpperCase()))
        .sort((a, b) => (String(b.durum).toUpperCase() === 'DOKUNUYOR') - (String(a.durum).toUpperCase() === 'DOKUNUYOR')
            || (parseInt(a.sira, 10) || 0) - (parseInt(b.sira, 10) || 0));
}

function dtTezgahBaglantiHtml(sid, kalemIdx) {
    const isler = dtKalemTezgahIsleri(sid, kalemIdx);
    if (!isler.length) {
        return `<div style="font-size:8.5px;color:var(--text3);margin-top:3px;opacity:.8">🧵 tezgaha bağlı değil</div>`;
    }
    const durumAd = (d) => String(d || '').toUpperCase() === 'DOKUNUYOR' ? 'dokunuyor' : 'kuyrukta';
    const secenekler = isler.map((x, n) => {
        const ad = _dtTezgahCache.tezgahAd[x.tezgah_id] || ('#' + x.tezgah_id);
        return `<option value="${x.id}" ${n === 0 ? 'selected' : ''}>${pdfEsc(ad)} · ${durumAd(x.durum)}</option>`;
    }).join('');
    return `<div style="display:flex;align-items:center;gap:5px;margin-top:4px" onclick="event.stopPropagation()">
        <span style="font-size:8.5px;color:var(--cyan-c)">🧵</span>
        <select id="dt-input-tezgah-${kalemIdx}" class="pro-input" title="Bu giriş hangi tezgahta dokundu"
            style="padding:2px 6px;font-size:9px;height:auto;width:auto;max-width:150px">
            <option value="">tezgahsız kaydet</option>
            ${secenekler}
        </select>
    </div>`;
}

/** Dokuma giriş kaydına eklenecek tezgah alanları (seçilmediyse boş). */
function dtTezgahGirisAlanlari(kalemIdx) {
    const el = document.getElementById(`dt-input-tezgah-${kalemIdx}`);
    const isId = el ? String(el.value || '') : '';
    if (!isId) return {};
    const is = _dtTezgahCache.isler.find(x => String(x.id) === isId);
    if (!is) return {};
    return {
        tezgah_id: is.tezgah_id,
        tezgah_no: _dtTezgahCache.tezgahAd[is.tezgah_id] || '',
        levent_id: _dtTezgahCache.levent[is.tezgah_id] || is.levent_id || null,
        is_id: is.id
    };
}

/**
 * Sipariş miktarına göre fazlalık / kalan. Fazla dokuma ENGELLENMEZ —
 * önceden "kalan" 0'a kırpılıyordu ve 850 m dokunmuş 800 m'lik kalem
 * "0 kalan" görünüyordu; fazlalık hiçbir yerde yazmıyordu.
 */
function dtFazlalikHtml(kalem, u) {
    const birim = siparisKalemBirim(kalem);
    const hedef = parseFloat(kalem?.miktar || 0) || 0;
    if (hedef <= 0) return '';
    let metre = parseFloat(u?.toplam_metre) || 0;
    let kg = parseFloat(u?.toplam_kg) || 0;
    let adet = parseInt(u?.toplam_adet, 10) || 0;
    /* Toplamlar boşsa girişlerden topla — dokumaUrunIkinciOzet ile aynı kural.
       O fonksiyon MOBİLDE YOK; blok iki platformda da bağımsız çalışmalı,
       yoksa mobil Dokuma Takip formu ReferenceError ile çöker. */
    if (!(metre > 0 || kg > 0 || adet > 0) && Array.isArray(u?.girisler)) {
        u.girisler.forEach(g => {
            metre += parseFloat(g?.metre) || 0;
            kg += parseFloat(g?.kg) || 0;
            adet += parseInt(g?.adet, 10) || 0;
        });
    }
    const yapilan = birim === 'MT' ? metre : (birim === 'KG' ? kg : adet);
    if (!(yapilan > 0)) return '';
    const fark = yapilan - hedef;
    const bas = birim === 'ADET' ? 0 : 1;
    const etiket = birim.toLowerCase();
    const sayi = (n) => (Math.abs(n)).toLocaleString('tr-TR', { minimumFractionDigits: bas, maximumFractionDigits: bas });
    if (fark > 0.0001) {
        const yuzde = Math.round(fark / hedef * 100);
        return `<div style="color:var(--amber-c);font-weight:700" title="Sipariş miktarından fazla dokundu">▲ +${sayi(fark)} ${etiket} fazla (%${yuzde})</div>`;
    }
    if (Math.abs(fark) <= 0.0001) return `<div style="color:var(--emerald-c)">✓ tamam</div>`;
    return `<div style="color:var(--text3)">kalan ${sayi(fark)} ${etiket}</div>`;
}

/** Girişi yapan kullanıcı — denetim izi için her dokuma girişine yazılır. */
function dtGirisKullaniciAlanlari() {
    const ad = String((typeof erpCurrentUser !== 'undefined' && erpCurrentUser
        && (erpCurrentUser.display_name || erpCurrentUser.username)) || '').trim();
    return ad ? { user: ad, kullanici: ad } : {};
}

async function renderDtForm() {
    const siparis = (dataCache.siparisler||[]).find(s=>s.id==dtSeciliSiparisId);
    if (!siparis) return '';
    let kalemler = [];
    try { kalemler = typeof siparis.cins==='string'?JSON.parse(siparis.cins):(siparis.cins||[]); } catch(e){}
    let kd = _kdCache[`KD_DOKUMA_${dtSeciliSiparisId}`];
    if (kd === undefined) kd = await dtGetKd(dtSeciliSiparisId);
    kd = kd || {};
    const urunler = kd.urunler || {};
    await dtTezgahIsleriYukle(dtSeciliSiparisId);

    const toplamMetre = Object.values(urunler).reduce((a,u)=>a+(parseFloat(u.toplam_metre)||0),0);
    const toplamKg    = Object.values(urunler).reduce((a,u)=>a+(parseFloat(u.toplam_kg)||0),0);
    const toplamAdetDokuma = Object.values(urunler).reduce((a,u)=>a+(parseInt(u.toplam_adet,10)||0),0);
    const siparisAdedi = (() => {
        let adet = 0;
        for (const k of (kalemler || [])) {
            const birim = siparisKalemBirim(k);
            if (birim === 'ADET') adet += parseFloat(k?.miktar || 0) || 0;
            else adet += parseFloat(k?.adet || 0) || 0;
        }
        if (adet > 0) return Math.round(adet);
        return (kalemler || []).length;
    })();
    const siparisKgMi = (kalemler || []).some(k => { const b = siparisKalemBirim(k); return b === 'KG' || b === 'MT'; });
    const ikinciToplamLabel = siparisKgMi ? 'Toplam KG' : 'Toplam Adet';
    const ikinciToplamDeger = siparisKgMi ? toplamKg.toFixed(1) : toplamAdetDokuma.toLocaleString('tr-TR');
    const ikinciToplamUnit = siparisKgMi ? 'kg' : 'adet';

    return `
    <div style="display:flex;flex-direction:column;gap:12px">

        <!-- Özet -->
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
            ${[
                {l:'Toplam Metre', v:toplamMetre.toFixed(1), unit:'m', color:'var(--cyan-c)', bg:'rgba(34,211,238,0.08)'},
                {l:ikinciToplamLabel, v:ikinciToplamDeger, unit:ikinciToplamUnit,color:'var(--accent2)',bg:'rgba(167,139,250,0.08)'},
                {l:'Sipariş Adedi',v:siparisAdedi.toLocaleString('tr-TR'),unit:'adet',color:'var(--text2)',bg:'var(--surface2)'},
            ].map(x=>`<div style="background:${x.bg};border:1px solid var(--border);border-radius:10px;padding:12px;text-align:center">
                <div style="font-family:'Instrument Serif',serif;font-size:24px;color:${x.color};line-height:1">${x.v}</div>
                <div style="font-size:8px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace;margin-top:4px">${x.l}</div>
            </div>`).join('')}
        </div>

        <!-- Ürün tablosu -->
        <div class="panel-box">
            <div class="panel-head">
                <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--cyan-c)"></span>Ürün Bazlı Giriş</span>
                <span style="font-size:10px;color:var(--text3);font-family:'DM Mono',monospace">${siparis.sno} · ${siparis.firma||'—'}</span>
            </div>

            <!-- Başlık -->
            <div style="display:grid;grid-template-columns:3fr 1fr 2fr 2fr 2fr 88px;gap:8px;padding:8px 16px;background:var(--surface2);border-bottom:1px solid var(--border);font-size:8px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.08em;font-family:'DM Mono',monospace">
                <div>Ürün</div>
                <div style="text-align:center">Sipariş</div>
                <div style="text-align:center;color:var(--cyan-c)">Metre (m) *</div>
                <div style="text-align:center;color:var(--accent2)">2. Birim (kg/ad) *</div>
                <div style="text-align:center">Toplam</div>
                <div style="text-align:center">Kaydet</div>
            </div>

            <div >
                ${kalemler.length === 0
                    ? '<p class="text-[9px] text-slate-400 italic p-6 text-center">Sipariş kalemi bulunamadı</p>'
                    : kalemler.map((k,i) => {
                        const u = urunler[i] || { toplam_metre:0, toplam_kg:0, toplam_adet:0 };
                        const birim = siparisKalemBirim(k);
                        const siparisMiktar = parseFloat(k.miktar || 0) || 0;
                        const siparisMiktarText = birim === 'ADET'
                            ? Math.round(siparisMiktar).toLocaleString('tr-TR')
                            : siparisMiktar.toFixed(1);
                        const ikinciTip = dtKalemIkinciBirimTip(k);
                        return `
                        <div style="display:grid;grid-template-columns:3fr 1fr 2fr 2fr 2fr 88px;gap:8px;align-items:center;padding:10px 16px;border-bottom:1px solid var(--border);transition:background 0.1s" onmouseover="this.style.background='var(--surface2)'" onmouseout="this.style.background='transparent'">
                            <div>
                                <div style="font-size:11px;font-weight:500;color:var(--text)">${k.ad||k.kod||'Ürün '+(i+1)}</div>
                                <div style="font-size:9px;color:var(--text3);margin-top:1px">${[k.kod&&dtKalemStokKodu(k),k.renk,k.ebat,birim].filter(Boolean).join(' · ')||'—'}</div>
                                ${dtTezgahBaglantiHtml(dtSeciliSiparisId, i)}
                            </div>
                            <div style="text-align:center;font-size:11px;font-weight:500;color:var(--text);font-family:'DM Mono',monospace">${siparisMiktarText} ${birim.toLowerCase()}</div>

                            <div style="display:flex;flex-direction:column;gap:3px">
                                <input type="number" step="0.1" placeholder="+m" id="dt-input-metre-${i}"
                                    class="pro-input" style="text-align:center;padding:5px 8px;font-size:10px;border-color:rgba(34,211,238,0.3);color:var(--cyan-c)">
                                <div style="text-align:center;font-size:8px;color:var(--cyan-c);font-family:'DM Mono',monospace">∑ ${parseFloat(u.toplam_metre||0).toFixed(1)} m</div>
                            </div>

                            <div style="display:flex;flex-direction:column;gap:3px">
                                ${ikinciTip === 'MT'
                                    ? `<div style="text-align:center;font-size:8px;color:var(--text3);line-height:1.3;padding-top:4px">Metre sipariş —<br>yalnız metre girilir</div>`
                                    : ikinciTip === 'KG'
                                    ? `
                                    <input type="number" step="0.1" placeholder="+kg" id="dt-input-kg-${i}"
                                        class="pro-input" style="text-align:center;padding:5px 8px;font-size:10px;border-color:rgba(167,139,250,0.3);color:var(--accent2)">
                                    <div style="text-align:center;font-size:8px;color:var(--accent2);font-family:'DM Mono',monospace">∑ ${parseFloat(u.toplam_kg||0).toFixed(1)} kg</div>
                                    `
                                    : `
                                    <input type="number" step="1" placeholder="+adet" id="dt-input-adet-${i}"
                                        class="pro-input" style="text-align:center;padding:5px 8px;font-size:10px;border-color:rgba(52,211,153,0.3);color:var(--emerald-c)">
                                    <div style="text-align:center;font-size:8px;color:var(--emerald-c);font-family:'DM Mono',monospace">∑ ${parseInt(u.toplam_adet||0)} adet</div>
                                    `
                                }
                            </div>

                            <div style="text-align:center;font-size:9px;font-family:'DM Mono',monospace;line-height:1.7">
                                <div style="color:var(--cyan-c)">${parseFloat(u.toplam_metre||0).toFixed(1)} m</div>
                                ${ikinciTip === 'MT' ? '' : `<div style="color:${ikinciTip === 'KG' ? 'var(--accent2)' : 'var(--emerald-c)'}">
                                    ${ikinciTip === 'KG' ? `${parseFloat(u.toplam_kg||0).toFixed(1)} kg` : `${parseInt(u.toplam_adet||0)} adet`}
                                </div>`}
                                ${dtFazlalikHtml(k, u)}
                            </div>
                            <div style="text-align:center">
                                <button type="button" id="dt-kaydet-kalem-${i}" onclick="dtKaydetTekKalem(${i})" class="btn-pro btn-primary-pro" style="padding:6px 10px;font-size:9px;white-space:nowrap;background:var(--cyan-c);border-color:var(--cyan-c)" title="Bu satırı tek tuşla kaydet">💾</button>
                            </div>
                        </div>`;
                    }).join('')}
            </div>

            <!-- Genel toplam -->
            ${kalemler.length > 0 ? `
            <div style="display:grid;grid-template-columns:3fr 1fr 2fr 2fr 2fr 88px;gap:8px;padding:10px 16px;background:var(--surface2);border-top:1px solid var(--border)">
                <div style="font-size:9px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:0.08em;font-family:'DM Mono',monospace;grid-column:1/3">Genel Toplam</div>
                <div style="text-align:center;font-size:10px;font-weight:600;color:var(--cyan-c);font-family:'DM Mono',monospace">∑ ${toplamMetre.toFixed(1)} m</div>
                <div style="text-align:center;font-size:10px;font-weight:600;color:var(--text2);font-family:'DM Mono',monospace">∑ ${ikinciToplamDeger} ${ikinciToplamUnit} / ${siparisAdedi.toLocaleString('tr-TR')} adet</div>
                <div></div>
            </div>` : ''}
        </div>

        ${Object.values(urunler).some(u=>(u.girisler||[]).length>0) ? `
        <div class="panel-box">
            <div class="panel-head">
                <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--text3)"></span>Giriş Geçmişi</span>
                <span style="font-size:9px;color:var(--text3)">Kayıtlar otomatik Dokuma Depo'da listelenir · sevk oradan yapılır</span>
            </div>
            <div style="max-height:220px;overflow-y:auto">
                ${kalemler.flatMap((k,i) => {
                    const u = urunler[i] || {};
                    const arr = Array.isArray(u.girisler) ? u.girisler.map((g, gi) => ({ g, gi })) : [];
                    return arr.slice().reverse().map(({ g, gi }) => `
                    <div style="display:flex;align-items:center;gap:8px;padding:8px 16px;border-bottom:1px solid var(--border);font-size:10px;flex-wrap:wrap">
                        <span style="font-weight:500;color:var(--text);width:100px;flex-shrink:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${k.ad||'Ürün '+(i+1)}</span>
                        <span style="color:var(--cyan-c);font-family:'DM Mono',monospace">${g.metre?'+'+parseFloat(g.metre).toFixed(1)+'m':''}</span>
                        <span style="color:var(--accent2);font-family:'DM Mono',monospace">${g.kg?'+'+parseFloat(g.kg).toFixed(1)+'kg':''}</span>
                        <span style="color:var(--emerald-c);font-family:'DM Mono',monospace">${g.adet?'+'+g.adet+' adet':''}</span>
                        <span style="color:var(--text3);font-family:'DM Mono',monospace;font-size:9px">${g.tarih||''}</span>
                        <span style="color:var(--text2);font-size:9px" title="Kaydı giren kullanıcı">${pdfEsc(g.user||g.kullanici||'—')}</span>
                        ${(() => {
                            /* Sonradan düzeltilmişse kim/ne zaman — panelden de masaüstünden de
                               aynı gecmis[] alanına yazılır. */
                            const h = Array.isArray(g.gecmis) ? g.gecmis[g.gecmis.length - 1] : null;
                            if (!h) return '';
                            const t = new Date(h.ts || '');
                            const zaman = Number.isNaN(t.getTime()) ? '' : t.toLocaleString('tr-TR');
                            return `<span class="pill pill-amber" style="font-size:8px" title="${pdfEsc(dtGirisMiktarOzet(h.eski))} → ${pdfEsc(dtGirisMiktarOzet(h.yeni))}">✏️ ${pdfEsc(h.user||'—')} · ${pdfEsc(zaman)}</span>`;
                        })()}
                        <span style="margin-left:auto;display:flex;gap:4px;flex-wrap:wrap">
                        <button onclick="dtGirisRevizePrompt(${i},${gi})" class="btn-pro btn-ghost-pro" title="Revize et" style="padding:3px 8px;font-size:10px">✏️</button>
                        <button onclick="dtGirisSil(${i},${gi})" class="btn-pro btn-ghost-pro" title="Sil" style="padding:3px 8px;font-size:10px;color:var(--rose-c)">🗑️</button>
                        </span>
                    </div>`);
                }).join('')}
            </div>
        </div>` : ''}

        <div class="panel-box" style="padding:12px 16px;position:sticky;bottom:0;z-index:5;border:2px solid rgba(34,211,238,0.35);background:var(--surface)">
            <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
                <div style="flex:1;min-width:180px;font-size:10px;color:var(--text2);line-height:1.45">
                    <b>Kaydet</b> ile girilen her ürün otomatik <strong style="color:var(--emerald-c)">Dokuma Depo</strong>'da görünür. Sevk (Konfeksiyon, Boyahane, Genel Depo, Müşteri) oradan yapılır.
                </div>
                <button type="button" onclick="dtKaydet(${kalemler.length})" class="btn-pro btn-primary-pro" style="min-width:200px;justify-content:center;padding:12px 20px;font-size:12px;font-weight:700;background:var(--cyan-c);border-color:var(--cyan-c)" onmouseover="this.style.filter='brightness(1.1)'" onmouseout="this.style.filter='none'">
                    💾 Tüm Girişleri Kaydet
                </button>
            </div>
        </div>
    </div>`;
}

async function dtKaydetKalemler(indices, opts = {}) {
    if (!dtSeciliSiparisId) return false;
    const idxList = (Array.isArray(indices) ? indices : []).filter(i => Number.isFinite(i) && i >= 0);
    if (!idxList.length) return false;
    const kd = await dtGetKd(dtSeciliSiparisId);
    if (!kd.urunler) kd.urunler = {};
    const siparis = (dataCache.siparisler||[]).find(s=>s.id==dtSeciliSiparisId);
    let kalemler = [];
    try { kalemler = typeof siparis?.cins === 'string' ? JSON.parse(siparis.cins) : (siparis?.cins || []); } catch(e) {}
    const now = new Date();
    const tarih = now.toLocaleString('tr-TR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const tarihIso = now.toISOString();
    const kayitUser = String((typeof erpCurrentUser !== 'undefined' && (erpCurrentUser?.display_name || erpCurrentUser?.username)) || '').trim();
    let toplamKgIslenecek = 0;
    let toplamMetre = 0;
    let toplamAdet = 0;
    let hareketSatiri = 0;
    let birSeyGirildi = false;
    const yeniGirisler = [];

    for (const i of idxList) {
        const kalem = kalemler[i] || {};
        const ikinciTip = dtKalemIkinciBirimTip(kalem);
        const metreEl = document.getElementById('dt-input-metre-'+i);
        const kgEl    = document.getElementById('dt-input-kg-'+i);
        const adetEl  = document.getElementById('dt-input-adet-'+i);
        const metre = parseFloat(metreEl?.value||0);
        const kg    = ikinciTip === 'KG' ? (parseFloat(kgEl?.value||0) || 0) : 0;
        const adet  = ikinciTip === 'ADET' ? (parseInt(adetEl?.value||0) || 0) : 0;
        const ikinciDeger = ikinciTip === 'KG' ? kg : (ikinciTip === 'MT' ? metre : adet); /* MT: yalnız metre */
        if (metre <= 0 && ikinciDeger <= 0) continue;
        const dogrula = dtGirisMiktarDogrula(kalem, metre, ikinciDeger, ikinciTip);
        if (!dogrula.ok) { if (!opts.sessiz) erpToast(dogrula.mesaj, 'error'); return false; }

        birSeyGirildi = true;
        if (!kd.urunler[i]) kd.urunler[i] = { toplam_metre:0, toplam_kg:0, toplam_adet:0, girisler:[] };
        kd.urunler[i].toplam_metre = (parseFloat(kd.urunler[i].toplam_metre)||0) + metre;
        kd.urunler[i].toplam_kg   = (parseFloat(kd.urunler[i].toplam_kg)||0)    + kg;
        kd.urunler[i].toplam_adet = (parseInt(kd.urunler[i].toplam_adet)||0)    + adet;
        kd.urunler[i].girisler.push({
            metre: metre || null,
            kg: kg || null,
            adet: adet || null,
            tarih,
            tarih_iso: tarihIso,
            gid: 'dt-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
            ...dtTezgahGirisAlanlari(i),
            ...(kayitUser ? { user: kayitUser, kullanici: kayitUser } : {})
        });
        yeniGirisler.push({ i, gi: kd.urunler[i].girisler.length - 1 });
        toplamKgIslenecek += kg;
        toplamMetre += metre;
        toplamAdet += adet;
        hareketSatiri += 1;

        if (metreEl) metreEl.value = '';
        if (ikinciTip === 'KG') {
            if (kgEl) kgEl.value = '';
        } else {
            if (adetEl) adetEl.value = '';
        }
    }

    if (!birSeyGirildi) {
        if (!opts.sessiz) erpToast(idxList.length === 1 ? 'Metre veya ikinci birim girin.' : 'En az bir değer girin (metre + kg veya adet).', 'error');
        return false;
    }

    await dtSetKd(dtSeciliSiparisId, kd);
    _dokumaDepoKdSatirlariCache = [];
    _dtTezgahCache.ts = 0;
    if (typeof _tpCache !== 'undefined') _tpCache.ts = 0;
    dtPushHareket({
        dosya: 'SIPARIS',
        islem: idxList.length === 1 ? 'Dokuma Girişi (tek kalem)' : 'Dokuma Girişi Kaydedildi',
        siparis: siparis?.sno || String(dtSeciliSiparisId),
        detay: `${hareketSatiri} satır · +${toplamMetre.toFixed(2)} m · +${toplamKgIslenecek.toFixed(2)} kg · +${toplamAdet} adet · Dokuma Depo'da listelenir`
    });

    if (!opts.sessiz) {
        erpToast(`${hareketSatiri} giriş kaydedildi · Dokuma Depo'da görünür (sipariş+ürün+renk birleşik).`, 'success');
    }
    return true;
}

async function dtKaydetTekKalem(i) {
    const btn = document.getElementById(`dt-kaydet-kalem-${i}`);
    const ok = await dtKaydetKalemler([i]);
    if (!ok) return;
    if (btn) {
        const o = btn.innerHTML;
        btn.innerHTML = '✅';
        btn.classList.add('opacity-75');
        setTimeout(() => { btn.innerHTML = o; btn.classList.remove('opacity-75'); renderDokumaTakip(); }, 900);
    } else {
        renderDokumaTakip();
    }
}

async function dtKaydet(kalemSayi) {
    const indices = [...Array(kalemSayi).keys()];
    const ok = await dtKaydetKalemler(indices);
    if (!ok) return;
    const btn = document.querySelector(`button[onclick="dtKaydet(${kalemSayi})"]`);
    if (btn) { const o=btn.innerHTML; btn.innerHTML='✅ KAYDEDİLDİ'; btn.classList.add('opacity-75'); setTimeout(()=>{ btn.innerHTML=o; btn.classList.remove('opacity-75'); renderDokumaTakip(); }, 1200); }
    else renderDokumaTakip();
}


// ════════════════════════════════════════════════════════
//  RAPORLAR & ANALİZ MODÜLÜ
// ════════════════════════════════════════════════════════


// ── Dokuma Takip · Günlük Excel içe aktarma ─────────────────────────────
const DT_EXCEL_MAP_LS = 'erp_dt_excel_kolon_map_v1';
const DT_EXCEL_UNDO_LS = 'erp_dt_excel_undo_v1';
let _dtExcelPending = null;

const DT_EXCEL_ALANLAR = [
    { key: 'siparis_no', label: 'Sipariş no', zorunlu: false, aliases: ['siparis no', 'siparisno', 'sno', 'siparis', 'order', 'siparis kodu'] },
    { key: 'urun_kod', label: 'Ürün kodu', zorunlu: false, aliases: ['kod', 'stok kodu', 'urun kodu', 'sku', 'model'] },
    { key: 'urun_ad', label: 'Ürün adı', zorunlu: false, aliases: ['urun', 'urun adi', 'ad', 'kalem', 'cins', 'aciklama', 'urun tanimi'] },
    { key: 'renk', label: 'Renk', zorunlu: false, aliases: ['renk', 'color', 'renk kodu'] },
    { key: 'ebat', label: 'Ebat / ölçü', zorunlu: false, aliases: ['ebat', 'olcu', 'olcu ebat', 'size', 'boyut'] },
    { key: 'bu_sefer_metre', label: 'Bu sefer (metre)', zorunlu: false, aliases: ['bu sefer m', 'bu sefer metre', 'bu sefer mt'] },
    { key: 'bu_sefer_kg', label: 'Bu sefer (kg)', zorunlu: false, aliases: ['bu sefer kg', 'kg', 'kilogram', 'agirlik', 'net kg'] },
    { key: 'bu_sefer_adet', label: 'Bu sefer (adet/çuval)', zorunlu: false, aliases: ['bu sefer adet', 'adet', 'cuval', 'cuvval', 'cuval sayisi', 'paket'] },
    { key: 'tarih', label: 'Tarih (opsiyonel)', zorunlu: false, aliases: ['tarih', 'date', 'gun', 'islem tarihi'] },
];

function dtExcelNormHeader(h) {
    return siparisExcelNormHeader(h);
}

function dtExcelMapYukle() {
    try {
        const p = JSON.parse(localStorage.getItem(DT_EXCEL_MAP_LS) || '{}');
        return p && typeof p === 'object' ? p : {};
    } catch (e) { return {}; }
}

function dtExcelMapKaydet(map) {
    try { localStorage.setItem(DT_EXCEL_MAP_LS, JSON.stringify(map || {})); } catch (e) {}
}

function dtExcelUndoYukle() {
    try {
        const p = JSON.parse(localStorage.getItem(DT_EXCEL_UNDO_LS) || 'null');
        return p?.siparisler && Object.keys(p.siparisler).length ? p : null;
    } catch (e) { return null; }
}

function dtExcelUndoBtnGuncelle() {
    const btn = document.getElementById('dt-excel-undo-btn');
    if (!btn) return;
    const pkg = dtExcelUndoYukle();
    btn.style.display = pkg ? 'inline-flex' : 'none';
    if (pkg?.at) btn.title = `Son Excel importu: ${new Date(pkg.at).toLocaleString('tr-TR')} · ${pkg.satir || 0} satır`;
}

async function dtExcelSonImportGeriAl() {
    const pkg = dtExcelUndoYukle();
    if (!pkg) { erpToast('Geri alınacak Excel işlemi yok.', 'error'); return; }
    const snolar = Object.keys(pkg.siparisler).map(sid => {
        const s = (dataCache.siparisler || []).find(x => String(x.id) === String(sid));
        return s?.sno || sid;
    }).join(', ');
    const tip = pkg.type === 'genel_durum' ? 'Genel Durum dokuma aktarımı' : 'Günlük dokuma Excel girişi';
    const ek = pkg.type === 'genel_durum'
        ? 'Dokuma toplamları ve dokuma depo stok satırları önceki değerlere döner.'
        : 'Dokuma toplamları ve sevk havuzundaki stok kaydı eski haline döner.';
    if (!confirm(`Son Excel işlemi geri alınsın mı?\n\n${tip}\n${pkg.satir || '?'} satır · ${pkg.sno || snolar}\n\n${ek}`)) return;
    try {
        for (const [sid, kd] of Object.entries(pkg.siparisler)) {
            await dtSetKd(sid, kd);
        }
        for (const [stokId, prev] of Object.entries(pkg.stokOnceki || {})) {
            const { error } = await sb.from('kumas_stok').update(prev).eq('id', stokId);
            if (error) console.warn('kumas_stok geri yükleme', stokId, error);
        }
        for (const stokId of (pkg.stokIds || [])) {
            const { error } = await sb.from('kumas_stok').delete().eq('id', stokId);
            if (error) console.warn('kumas_stok silme', stokId, error);
        }
        localStorage.removeItem(DT_EXCEL_UNDO_LS);
        dtPushHareket({ dosya: 'SIPARIS', islem: 'Excel işlemi geri alındı', siparis: pkg.sno || snolar, detay: tip });
        erpSyncTablesBackground(['kumas_stok', 'siparisler']);
        erpToast('Son Excel işlemi geri alındı.', 'success');
        dtExcelUndoBtnGuncelle();
        renderDokumaTakip();
        if (appMode === 'DOKUMA_DEPO') renderDokumaDepo();
    } catch (err) {
        erpToast('Geri alma başarısız: ' + (err?.message || err), 'error', 5000);
    }
}

let _dtExcelKdCache = null;

/** Kadir çalışma sayfası.xlsx — Siparişler sayfası (Üretilen MT/Adet/KG) */
function dtExcelEbatNorm(v) {
    return dtNormTxt(String(v || '')).replace(/\*/g, 'x').replace(/\s+/g, '').replace(/cm$/i, '');
}

function dtExcelKadirFormatMi(headers) {
    const norms = (headers || []).map(h => dtExcelNormHeader(h));
    const hasSno = norms.some(x => x === 'siparis no' || (x.includes('siparis') && x.includes('no')));
    const hasUrun = norms.some(x => x.includes('urun ad'));
    const hasUretimMt = norms.some(x => x.includes('uretilen mt'));
    return hasSno && hasUrun && hasUretimMt;
}

function dtExcelKadirKolonBul(headers, adaylar) {
    const hs = (headers || []).map(h => ({ raw: h, norm: dtExcelNormHeader(h) }));
    for (const ad of adaylar) {
        const an = dtExcelNormHeader(ad);
        const hit = hs.find(x => x.norm === an || x.raw === ad);
        if (hit) return hit.raw;
    }
    return '';
}

function dtExcelKadirMapOlustur(headers) {
    return {
        format: 'kadir',
        siparis_no: dtExcelKadirKolonBul(headers, ['Sipariş No', 'Siparis No']),
        urun_ad: dtExcelKadirKolonBul(headers, ['Ürün Adı', 'Urun Adi']),
        ebat: dtExcelKadirKolonBul(headers, ['Ebat']),
        renk: dtExcelKadirKolonBul(headers, ['Renk']),
        uretim_mt: dtExcelKadirKolonBul(headers, ['Üretilen MT', 'Uretilen MT']),
        uretim_adet: dtExcelKadirKolonBul(headers, ['Üretilen Adet', 'Uretilen Adet']),
        uretim_kg: dtExcelKadirKolonBul(headers, ['Üretilen KG', 'Uretilen KG']),
    };
}

function dtExcelOtomatikKolonMap(headers) {
    if (dtExcelKadirFormatMi(headers)) return dtExcelKadirMapOlustur(headers);
    const saved = dtExcelMapYukle();
    const map = { format: 'genel' };
    const hs = (headers || []).map(h => ({ raw: h, norm: dtExcelNormHeader(h) }));
    DT_EXCEL_ALANLAR.forEach(al => {
        if (saved[al.key]) {
            const hit = hs.find(x => x.raw === saved[al.key] || x.norm === dtExcelNormHeader(saved[al.key]));
            if (hit) { map[al.key] = hit.raw; return; }
        }
        const aliases = (al.aliases || []).map(dtExcelNormHeader);
        const hit = hs.find(x => aliases.some(a => x.norm === a || x.norm.includes(a) || a.includes(x.norm)));
        if (hit) map[al.key] = hit.raw;
    });
    return map;
}

function dtExcelSheetSec(wb) {
    const names = wb.SheetNames || [];
    if (!names.length) return null;
    const prefer = ['siparisler', 'siparis', 'gunluk', 'dokuma', 'uretim', 'takip', 'data', 'veri', 'sheet1'];
    for (const p of prefer) {
        const hit = names.find(n => dtExcelNormHeader(n).includes(p));
        if (hit) return hit;
    }
    return names[0];
}

function dtExcelRowsFromSheet(ws) {
    const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
    if (!aoa.length) return { headers: [], rows: [] };
    const score = (row) => {
        const hs = (row || []).map(c => dtExcelNormHeader(c));
        let s = 0;
        if (hs.some(x => x.includes('siparis') || x.includes('sno'))) s += 3;
        if (hs.some(x => x.includes('uretilen mt'))) s += 5;
        if (hs.some(x => x.includes('metre') || x === 'm' || x.includes('mt'))) s += 2;
        if (hs.some(x => x.includes('kg'))) s += 2;
        if (hs.some(x => x.includes('adet') || x.includes('cuval'))) s += 2;
        if (hs.some(x => x.includes('urun') || x.includes('kod') || x.includes('renk'))) s += 2;
        return s;
    };
    let headerIdx = 0;
    let best = score(aoa[0]);
    for (let i = 1; i < Math.min(aoa.length, 25); i++) {
        const sc = score(aoa[i]);
        if (sc > best) { best = sc; headerIdx = i; }
    }
    const headers = (aoa[headerIdx] || []).map(h => String(h ?? '').trim()).filter((h, i, arr) => h || arr.some(x => x));
    const rawHeaders = (aoa[headerIdx] || []).map(h => String(h ?? '').trim());
    const rows = [];
    for (let r = headerIdx + 1; r < aoa.length; r++) {
        const line = aoa[r] || [];
        if (!line.some(c => String(c ?? '').trim() !== '')) continue;
        const obj = {};
        rawHeaders.forEach((h, ci) => {
            if (!h) return;
            obj[h] = line[ci] ?? '';
        });
        rows.push(obj);
    }
    return { headers: rawHeaders.filter(Boolean), rows };
}

function dtExcelHucre(row, colName) {
    if (!colName || !row) return '';
    return row[colName] ?? '';
}

function dtExcelSayi(v) {
    return stokToNumber(v);
}

function dtExcelSiparisBul(snoRaw) {
    const q = dtNormTxt(String(snoRaw || '').trim());
    if (!q) return null;
    return (dataCache.siparisler || []).find(s => {
        const sn = dtNormTxt(s.sno || '');
        return sn === q || sn.includes(q) || q.includes(sn) || String(s.id) === String(snoRaw).trim();
    }) || null;
}

function dtExcelKalemBul(siparis, row, colMap) {
    let kalemler = [];
    try { kalemler = typeof siparis.cins === 'string' ? JSON.parse(siparis.cins) : (siparis.cins || []); } catch (e) { kalemler = []; }
    const kod = dtNormTxt(dtExcelHucre(row, colMap.urun_kod)).replace(/\s+/g, '');
    const ad = dtNormTxt(dtExcelHucre(row, colMap.urun_ad));
    const renk = dtNormTxt(dtExcelHucre(row, colMap.renk));
    const ebat = dtNormTxt(dtExcelHucre(row, colMap.ebat));
    let best = -1;
    let bestSk = 0;
    kalemler.forEach((k, i) => {
        let sk = 0;
        const kk = dtNormTxt(k.kod || '').replace(/\s+/g, '');
        const ka = dtNormTxt(k.ad || '');
        const kr = dtNormTxt(k.renk || '');
        const ke = dtExcelEbatNorm(k.ebat || k.olcu || '');
        const ebatN = dtExcelEbatNorm(ebat);
        if (kod && kk && (kk === kod || kk.includes(kod) || kod.includes(kk))) sk += 5;
        if (ad && ka && (ka.includes(ad) || ad.includes(ka))) sk += 3;
        if (renk && kr && (renk === kr || renk.includes(kr) || kr.includes(renk))) sk += 2;
        if (ebatN && ke && (ke === ebatN || ke.includes(ebatN) || ebatN.includes(ke))) sk += 2;
        if (sk > bestSk) { bestSk = sk; best = i; }
    });
    if (best >= 0 && bestSk >= 3) return best;
    if (kalemler.length === 1) return 0;
    return -1;
}

function dtExcelSatirlariIsle(rawRows, colMap) {
    const out = [];
    rawRows.forEach((row, ri) => {
        const metre = dtExcelSayi(dtExcelHucre(row, colMap.bu_sefer_metre));
        const kg = dtExcelSayi(dtExcelHucre(row, colMap.bu_sefer_kg));
        const adet = Math.round(dtExcelSayi(dtExcelHucre(row, colMap.bu_sefer_adet)));
        if (metre <= 0 && kg <= 0 && adet <= 0) return;

        let siparis = null;
        const snoCell = String(dtExcelHucre(row, colMap.siparis_no) || '').trim();
        if (snoCell) siparis = dtExcelSiparisBul(snoCell);
        if (!siparis && dtSeciliSiparisId) {
            siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(dtSeciliSiparisId));
        }
        if (!siparis) {
            out.push({ ri, durum: 'hata', mesaj: 'Sipariş bulunamadı', sno: snoCell || '—', urun: dtExcelHucre(row, colMap.urun_ad) || dtExcelHucre(row, colMap.urun_kod) || '—', metre, kg, adet });
            return;
        }
        const kalemIdx = dtExcelKalemBul(siparis, row, colMap);
        if (kalemIdx < 0) {
            out.push({ ri, durum: 'hata', mesaj: 'Kalem eşleşmedi', siparis, sno: siparis.sno, urun: dtExcelHucre(row, colMap.urun_ad) || dtExcelHucre(row, colMap.urun_kod) || '—', metre, kg, adet });
            return;
        }
        let kalemler = [];
        try { kalemler = typeof siparis.cins === 'string' ? JSON.parse(siparis.cins) : (siparis.cins || []); } catch (e) { kalemler = []; }
        const kalem = kalemler[kalemIdx] || {};
        const ikinciTip = dtKalemIkinciBirimTip(kalem);
        const ikinciDeger = ikinciTip === 'KG' ? kg : (ikinciTip === 'MT' ? metre : adet); /* MT: yalnız metre */
        if ((metre > 0 && ikinciDeger <= 0) || (metre <= 0 && ikinciDeger > 0)) {
            out.push({ ri, durum: 'hata', mesaj: `Hem metre hem ${ikinciTip} gerekli`, siparis, kalemIdx, kalem, sno: siparis.sno, metre, kg, adet });
            return;
        }
        out.push({
            ri, durum: 'ok', siparis, siparisId: siparis.id, kalemIdx, kalem,
            sno: siparis.sno, urun: kalem.ad || kalem.kod || `Kalem ${kalemIdx + 1}`,
            metre,
            kg: ikinciTip === 'KG' ? kg : 0,
            adet: ikinciTip === 'ADET' ? adet : 0,
            ikinciTip,
        });
    });
    return out;
}

async function dtExcelSatirlariIsleKadir(rawRows, colMap) {
    _dtExcelKdCache = {};
    const out = [];
    for (let ri = 0; ri < rawRows.length; ri++) {
        const row = rawRows[ri];
        const exMt = dtExcelSayi(dtExcelHucre(row, colMap.uretim_mt));
        const exAd = Math.round(dtExcelSayi(dtExcelHucre(row, colMap.uretim_adet)));
        const exKg = dtExcelSayi(dtExcelHucre(row, colMap.uretim_kg));
        if (exMt <= 0 && exAd <= 0 && exKg <= 0) continue;

        const snoCell = String(dtExcelHucre(row, colMap.siparis_no) || '').trim();
        let siparis = snoCell ? dtExcelSiparisBul(snoCell) : null;
        if (!siparis && dtSeciliSiparisId) {
            siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(dtSeciliSiparisId));
        }
        const urunLbl = dtExcelHucre(row, colMap.urun_ad) || '—';
        if (!siparis) {
            out.push({ ri, durum: 'hata', mesaj: 'Sipariş bulunamadı', sno: snoCell || '—', urun: urunLbl, metre: 0, kg: 0, adet: 0 });
            continue;
        }
        const kalemIdx = dtExcelKalemBul(siparis, row, colMap);
        if (kalemIdx < 0) {
            out.push({ ri, durum: 'hata', mesaj: 'Kalem eşleşmedi (ürün/renk/ebat)', siparis, sno: siparis.sno, urun: urunLbl, metre: 0, kg: 0, adet: 0 });
            continue;
        }
        const sid = String(siparis.id);
        if (!_dtExcelKdCache[sid]) _dtExcelKdCache[sid] = await dtGetKd(siparis.id);
        const kd = _dtExcelKdCache[sid];
        const u = (kd.urunler || {})[kalemIdx] || (kd.urunler || {})[String(kalemIdx)] || {};
        const kdMt = parseFloat(u.toplam_metre) || 0;
        const kdAd = parseInt(u.toplam_adet, 10) || 0;
        const kdKg = parseFloat(u.toplam_kg) || 0;
        const metre = Math.max(0, Math.round((exMt - kdMt) * 10) / 10);
        const adet = Math.max(0, exAd - kdAd);
        const kg = Math.max(0, Math.round((exKg - kdKg) * 10) / 10);

        let kalemler = [];
        try { kalemler = typeof siparis.cins === 'string' ? JSON.parse(siparis.cins) : (siparis.cins || []); } catch (e) { kalemler = []; }
        const kalem = kalemler[kalemIdx] || {};
        const ikinciTip = dtKalemIkinciBirimTip(kalem);
        const ikinciDeger = ikinciTip === 'KG' ? kg : (ikinciTip === 'MT' ? metre : adet); /* MT: yalnız metre */
        const ikinciEx = ikinciTip === 'KG' ? exKg : (ikinciTip === 'MT' ? exMt : exAd);
        const ikinciKd = ikinciTip === 'KG' ? kdKg : (ikinciTip === 'MT' ? kdMt : kdAd);

        if (metre <= 0 && ikinciDeger <= 0) {
            out.push({
                ri, durum: 'atla', mesaj: 'Yeni üretim yok (ERP güncel)', siparis, siparisId: siparis.id, kalemIdx, kalem,
                sno: siparis.sno, urun: kalem.ad || kalem.kod || urunLbl, metre: 0, kg: 0, adet: 0,
                exMt, exAd, exKg, kdMt, kdAd, kdKg, ikinciTip,
            });
            continue;
        }
        if (metre > 0 && ikinciEx > ikinciKd + 0.01 && ikinciDeger <= 0) {
            out.push({
                ri, durum: 'hata', mesaj: `Excel ${ikinciTip} ERP'den ileride; fark aktarılmalı`,
                siparis, sno: siparis.sno, urun: kalem.ad || urunLbl, metre, kg, adet, ikinciTip,
            });
            continue;
        }
        if (metre <= 0 && ikinciDeger > 0) {
            out.push({
                ri, durum: 'hata', mesaj: 'Metre farkı yok, yalnızca adet/kg aktarılamaz',
                siparis, sno: siparis.sno, urun: kalem.ad || urunLbl, metre, kg, adet, ikinciTip,
            });
            continue;
        }
        out.push({
            ri, durum: 'ok', siparis, siparisId: siparis.id, kalemIdx, kalem,
            sno: siparis.sno, urun: kalem.ad || kalem.kod || urunLbl,
            metre,
            kg: ikinciTip === 'KG' ? kg : 0,
            adet: ikinciTip === 'ADET' ? adet : 0,
            ikinciTip, exMt, exAd, exKg, kdMt, kdAd, kdKg,
        });
    }
    return out;
}

async function dtUygulaGirisPaketi(siparisId, satirlar) {
    const kd = await dtGetKd(siparisId);
    if (!kd.urunler) kd.urunler = {};
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    const now = new Date();
    const tarih = now.toLocaleString('tr-TR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const tarihIso = now.toISOString();
    const kayitUser = String((typeof erpCurrentUser !== 'undefined' && (erpCurrentUser?.display_name || erpCurrentUser?.username)) || '').trim();
    let toplamKgIslenecek = 0, toplamMetre = 0, toplamAdet = 0, hareketSatiri = 0;
    const yeniGirisler = [];
    let kalemler = [];
    try { kalemler = typeof siparis?.cins === 'string' ? JSON.parse(siparis.cins) : (siparis?.cins || []); } catch (e) { kalemler = []; }

    for (const s of satirlar) {
        const metre = parseFloat(s.metre) || 0;
        const i = s.kalemIdx;
        const kalem = kalemler[i] || s.kalem || {};
        const ikinciTip = s.ikinciTip || dtKalemIkinciBirimTip(kalem);
        const kg = ikinciTip === 'KG' ? (parseFloat(s.kg) || 0) : 0;
        const adet = ikinciTip === 'ADET' ? (parseInt(s.adet, 10) || 0) : 0;
        if (!kd.urunler[i]) kd.urunler[i] = { toplam_metre: 0, toplam_kg: 0, toplam_adet: 0, girisler: [] };
        kd.urunler[i].toplam_metre = (parseFloat(kd.urunler[i].toplam_metre) || 0) + metre;
        kd.urunler[i].toplam_kg = (parseFloat(kd.urunler[i].toplam_kg) || 0) + kg;
        kd.urunler[i].toplam_adet = (parseInt(kd.urunler[i].toplam_adet, 10) || 0) + adet;
        if (!Array.isArray(kd.urunler[i].girisler)) kd.urunler[i].girisler = [];
        kd.urunler[i].girisler.push({
            metre: metre || null,
            kg: ikinciTip === 'KG' ? (kg || null) : null,
            adet: ikinciTip === 'ADET' ? (adet || null) : null,
            tarih,
            tarih_iso: tarihIso,
            ...(kayitUser ? { user: kayitUser, kullanici: kayitUser } : {})
        });
        yeniGirisler.push({ i, gi: kd.urunler[i].girisler.length - 1 });
        toplamKgIslenecek += kg;
        toplamMetre += metre;
        toplamAdet += adet;
        hareketSatiri += 1;
    }

    await dtSetKd(siparisId, kd);
    _dokumaDepoKdSatirlariCache = [];
    if (hareketSatiri > 0) {
        dtPushHareket({
            dosya: 'SIPARIS',
            islem: 'Dokuma Girişi (Excel)',
            siparis: siparis?.sno || String(siparisId),
            detay: `${hareketSatiri} satır · +${toplamMetre.toFixed(2)} m · +${toplamKgIslenecek.toFixed(2)} kg · +${toplamAdet} adet · Dokuma Depo'da listelenir`,
        });
    }
    return { hareketSatiri, toplamMetre, toplamKgIslenecek, toplamAdet, stokId: null, otomatikStok: hareketSatiri, depoHatalar: [] };
}

function openDtExcelImport() {
    const el = document.getElementById('dt-excel-input');
    if (el) { el.value = ''; el.click(); }
}

function dtExcelModalKapat() {
    const m = document.getElementById('dt-excel-modal');
    if (m) m.remove();
    _dtExcelPending = null;
}

async function dtExcelOnizlemeCiz() {
    const st = _dtExcelPending;
    if (!st) return;
    const body = document.getElementById('dt-excel-modal-body');
    if (!body) return;
    const kadir = st.format === 'kadir' || st.colMap?.format === 'kadir';
    body.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text3)">Satırlar işleniyor…</div>';
    const mapOpts = (alanKey) => {
        const opts = ['<option value="">— Seçin —</option>']
            .concat((st.headers || []).map(h => `<option value="${pdfEsc(h)}" ${st.colMap[alanKey] === h ? 'selected' : ''}>${pdfEsc(h)}</option>`));
        return opts.join('');
    };
    const mapHtml = kadir ? `<div style="font-size:10px;line-height:1.7;color:var(--text2)">
            <b style="color:var(--cyan-c)">Çalışma sayfası formatı</b> (Siparişler): yalnızca
            <b>Üretilen MT / Adet / KG</b> okunur; Sevk ve Stok sütunları kullanılmaz.<br>
            ERP toplamından Excel üretilen fark «bu sefer» olarak eklenir.
        </div>` : DT_EXCEL_ALANLAR.map(al => `
        <div style="display:grid;grid-template-columns:140px 1fr;gap:8px;align-items:center;margin-bottom:6px">
            <label style="font-size:10px;color:var(--text2)">${al.label}</label>
            <select class="pro-input" style="padding:5px 8px;font-size:10px" onchange="dtExcelKolonSec('${al.key}', this.value)">${mapOpts(al.key)}</select>
        </div>`).join('');

    const islenmis = kadir
        ? await dtExcelSatirlariIsleKadir(st.rawRows, st.colMap)
        : dtExcelSatirlariIsle(st.rawRows, st.colMap);
    st.islenmis = islenmis;
    const okN = islenmis.filter(x => x.durum === 'ok').length;
    const errN = islenmis.filter(x => x.durum === 'hata').length;
    const atlaN = islenmis.filter(x => x.durum === 'atla').length;
    const durumIkon = (d) => (d === 'ok' ? '✅' : d === 'atla' ? '⏭' : '❌');

    const tbl = islenmis.length ? islenmis.slice(0, 500).map(r => {
        if (kadir) {
            const ex2 = r.ikinciTip === 'KG' ? r.exKg : (r.ikinciTip === 'MT' ? r.exMt : r.exAd);
            const kd2 = r.ikinciTip === 'KG' ? r.kdKg : (r.ikinciTip === 'MT' ? r.kdMt : r.kdAd);
            const d2 = r.ikinciTip === 'KG' ? (r.kg || 0) : (r.ikinciTip === 'MT' ? (r.metre || 0) : (r.adet || 0));
            return `<tr style="border-top:1px solid var(--border)">
                <td style="padding:6px 8px;font-size:10px">${durumIkon(r.durum)}</td>
                <td style="padding:6px 8px;font-size:10px;font-family:'DM Mono',monospace">${pdfEsc(r.sno || '—')}</td>
                <td style="padding:6px 8px;font-size:10px">${pdfEsc(r.urun || '—')}</td>
                <td style="padding:6px 8px;font-size:9px;text-align:right;font-family:'DM Mono',monospace">${r.exMt ?? '—'} / ${r.kdMt ?? '—'}</td>
                <td style="padding:6px 8px;font-size:9px;text-align:right;font-family:'DM Mono',monospace;color:var(--cyan-c)">+${r.metre || 0}</td>
                <td style="padding:6px 8px;font-size:9px;text-align:right;font-family:'DM Mono',monospace">${ex2 ?? '—'} / ${kd2 ?? '—'}</td>
                <td style="padding:6px 8px;font-size:9px;text-align:right;font-family:'DM Mono',monospace;color:var(--emerald-c)">+${d2}</td>
                <td style="padding:6px 8px;font-size:9px;color:${r.durum === 'ok' ? 'var(--emerald-c)' : r.durum === 'atla' ? 'var(--text3)' : 'var(--rose-c)'}">${pdfEsc(r.mesaj || '')}</td>
            </tr>`;
        }
        return `<tr style="border-top:1px solid var(--border)">
            <td style="padding:6px 8px;font-size:10px">${durumIkon(r.durum)}</td>
            <td style="padding:6px 8px;font-size:10px;font-family:'DM Mono',monospace">${pdfEsc(r.sno || '—')}</td>
            <td style="padding:6px 8px;font-size:10px">${pdfEsc(r.urun || '—')}</td>
            <td style="padding:6px 8px;font-size:10px;text-align:right;font-family:'DM Mono',monospace">${r.metre ? r.metre.toLocaleString('tr-TR') : '—'}</td>
            <td style="padding:6px 8px;font-size:10px;text-align:right;font-family:'DM Mono',monospace">${r.kg ? r.kg.toLocaleString('tr-TR') : (r.adet || '—')}</td>
            <td style="padding:6px 8px;font-size:9px;color:${r.durum === 'ok' ? 'var(--emerald-c)' : 'var(--rose-c)'}">${pdfEsc(r.mesaj || 'Hazır')}</td>
        </tr>`;
    }).join('') : `<tr><td colspan="${kadir ? 8 : 6}" style="padding:16px;text-align:center;color:var(--text3)">İşlenecek satır yok</td></tr>`;

    body.innerHTML = `
        <p style="font-size:10px;color:var(--text3);margin:0 0 12px;line-height:1.5">${kadir ? 'Kadir çalışma sayfasından okunan veriler.' : 'Günlük Excel formunuzdaki sütunları bir kez eşleştirin.'} Sayfa: <b>${pdfEsc(st.sheetName)}</b> · ${st.rawRows.length} satır</p>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:14px">
            <div class="panel-box" style="padding:12px">
                <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase">${kadir ? 'Okunan alanlar' : 'Kolon eşleştirme'}</div>
                ${mapHtml}
            </div>
            <div class="panel-box" style="padding:12px">
                <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase">Özet</div>
                <div style="font-size:11px;line-height:1.8">
                    <span style="color:var(--emerald-c)">✓ ${okN} satır aktarılacak</span><br>
                    <span style="color:var(--text3)">⏭ ${atlaN} satır atlandı (ERP güncel)</span><br>
                    <span style="color:var(--rose-c)">✗ ${errN} satır hatalı</span>
                </div>
            </div>
        </div>
        <div style="overflow:auto;max-height:min(45vh,380px);border:1px solid var(--border);border-radius:10px">
            <table class="dt-table" style="width:100%;font-size:10px">
                <thead><tr style="background:var(--surface2)">
                    <th style="padding:6px 8px;text-align:left">Durum</th>
                    <th style="padding:6px 8px;text-align:left">Sipariş</th>
                    <th style="padding:6px 8px;text-align:left">Ürün</th>
                    ${kadir ? `
                    <th style="padding:6px 8px;text-align:right">Excel/ERP m</th>
                    <th style="padding:6px 8px;text-align:right">+m</th>
                    <th style="padding:6px 8px;text-align:right">Excel/ERP birim</th>
                    <th style="padding:6px 8px;text-align:right">+adet/kg</th>` : `
                    <th style="padding:6px 8px;text-align:right">m</th>
                    <th style="padding:6px 8px;text-align:right">kg/adet</th>`}
                    <th style="padding:6px 8px;text-align:left">Not</th>
                </tr></thead>
                <tbody>${tbl}</tbody>
            </table>
        </div>
        <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;flex-wrap:wrap">
            <button type="button" class="btn-pro btn-ghost-pro" onclick="dtExcelModalKapat()">İptal</button>
            <button type="button" class="btn-pro btn-primary-pro" style="background:var(--cyan-c);border-color:var(--cyan-c)" ${okN ? '' : 'disabled'} onclick="dtExcelIceAktarOnayla()">✓ ${okN} satırı kaydet</button>
        </div>`;
}

function dtExcelKolonSec(alanKey, colRaw) {
    if (!_dtExcelPending) return;
    if (colRaw) _dtExcelPending.colMap[alanKey] = colRaw;
    else delete _dtExcelPending.colMap[alanKey];
    dtExcelMapKaydet(_dtExcelPending.colMap);
    dtExcelOnizlemeCiz();
}

async function dtExcelIceAktarOnayla() {
    const st = _dtExcelPending;
    if (!st || !st.islenmis) return;
    const okRows = st.islenmis.filter(r => r.durum === 'ok');
    if (!okRows.length) { erpToast('Aktarılacak geçerli satır yok.', 'error'); return; }

    const bySiparis = {};
    okRows.forEach(r => {
        const sid = String(r.siparisId);
        if (!bySiparis[sid]) bySiparis[sid] = [];
        bySiparis[sid].push({ kalemIdx: r.kalemIdx, metre: r.metre, kg: r.kg, adet: r.adet });
    });

    const undoPkg = { at: new Date().toISOString(), satir: 0, siparisler: {}, stokIds: [] };
    try {
        for (const sid of Object.keys(bySiparis)) {
            undoPkg.siparisler[sid] = JSON.parse(JSON.stringify(await dtGetKd(sid)));
        }
        let topSatir = 0;
        for (const [sid, satirlar] of Object.entries(bySiparis)) {
            const res = await dtUygulaGirisPaketi(sid, satirlar);
            topSatir += res.hareketSatiri || 0;
            if (res.stokId) undoPkg.stokIds.push(res.stokId);
        }
        undoPkg.satir = topSatir;
        try { localStorage.setItem(DT_EXCEL_UNDO_LS, JSON.stringify(undoPkg)); } catch (e) {}
        dtExcelModalKapat();
        erpToast(`${topSatir} satır kaydedildi. Deneme ise «Son Excel'i geri al» ile geri alabilirsiniz.`, 'success', 6500);
        if (Object.keys(bySiparis).length === 1) {
            const onlyId = Object.keys(bySiparis)[0];
            if (String(dtSeciliSiparisId) !== String(onlyId)) dtSelectSiparis(onlyId);
            else renderDokumaTakip();
        } else {
            renderDokumaTakip();
        }
        dtExcelUndoBtnGuncelle();
    } catch (err) {
        erpToast('Excel kayıt hatası: ' + (err?.message || err), 'error', 5000);
    }
}

async function dtExcelDosyaOku(input) {
    const file = input?.files?.[0];
    if (!file) return;
    try { await erpEnsureXLSX(); } catch (e) {}
    if (typeof XLSX === 'undefined') { erpToast('Excel kütüphanesi yüklenemedi.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = async (e) => {
        try {
            const wb = XLSX.read(e.target.result, { type: 'array' });
            if (typeof genelDurumSheetAdiBul === 'function' && genelDurumSheetAdiBul(wb)) {
                await genelDurumSheetDokumaIsle(wb, { kaynakDosya: file.name });
                input.value = '';
                dtExcelUndoBtnGuncelle();
                return;
            }
            const sheetName = dtExcelSheetSec(wb);
            if (!sheetName) { erpToast('Excel sayfası bulunamadı. Genel Durum veya günlük dokuma sayfası yükleyin.', 'error'); input.value = ''; return; }
            const ws = wb.Sheets[sheetName];
            const { headers, rows } = dtExcelRowsFromSheet(ws);
            if (!headers.length) { erpToast('Başlık satırı okunamadı.', 'error'); input.value = ''; return; }
            const colMap = dtExcelOtomatikKolonMap(headers);
            const format = colMap.format === 'kadir' ? 'kadir' : 'genel';
            _dtExcelPending = { sheetName, headers, rawRows: rows, colMap, format };

            const wrap = document.createElement('div');
            wrap.id = 'dt-excel-modal';
            wrap.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;padding:16px';
            wrap.onclick = (ev) => { if (ev.target === wrap) dtExcelModalKapat(); };
            wrap.innerHTML = `
                <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;width:min(960px,100%);max-height:92vh;display:flex;flex-direction:column;box-shadow:0 24px 48px rgba(0,0,0,0.35)" onclick="event.stopPropagation()">
                    <div style="padding:14px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px">
                        <span style="font-size:14px;font-weight:700">📊 Excel — Dokuma günlük giriş</span>
                        <span style="font-size:10px;color:var(--text3);font-family:'DM Mono',monospace">${pdfEsc(file.name)}</span>
                        <button type="button" onclick="dtExcelModalKapat()" style="margin-left:auto;border:none;background:transparent;color:var(--text3);font-size:18px;cursor:pointer">×</button>
                    </div>
                    <div id="dt-excel-modal-body" style="padding:16px 18px;overflow:auto;flex:1"></div>
                </div>`;
            document.body.appendChild(wrap);
            dtExcelOnizlemeCiz();
        } catch (err) {
            erpToast('Excel okunamadı: ' + (err.message || err), 'error');
        }
    };
    reader.readAsArrayBuffer(file);
}

let raporTab = 'YONETICI_OZET';
let raporFiltre = { donem: 'ay', bas: '', bitis: '', firma: '' };
let raporHareketOzet = { kesilenAdet: 0, kesimAkisAdet: 0, kesimKdLogAdet: 0 };
let raporHareketOzetCacheKey = '';
let raporTekSeciliSiparisId = null;
let raporArkaplanYuklemeCalisiyor = false;
let raporArkaplanYenidenCalistir = false;
let _raporTekSiparisChartAsama = null;
let _raporTekSiparisChartKalem = null;
/** Rapor > Ürün özeti: siparis_grubu (GIDA/HALI/EV_TEKSTILI/…), ürün arama, konfeksiyon üretim yeri */
let raporUrunOzetSiparisGrubu = '';
let raporUrunOzetUretimYeri = '';
let raporUrunOzetUrunArama = '';
/** Konfeksiyon işlem raporu: toplam (dönem içi birleşik) | gunluk */
let raporKonfIslemKirilim = 'toplam';
let raporKonfIslemCache = { key: '', rows: [], yukleniyor: false, hata: '' };

function raporLocalDateStr(v) {
    try {
        if (!v) return '';
        const d = (v instanceof Date) ? v : new Date(v);
        if (Number.isNaN(d.getTime())) return '';
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
    } catch (e) {
        return '';
    }
}

function raporParseAnyDate(v) {
    try {
        if (!v) return null;
        if (v instanceof Date) return Number.isNaN(v.getTime()) ? null : v;
        const s = String(v).trim();
        if (!s) return null;
        // tr-TR locale string: 14.04.2026 11:22:33
        const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$/);
        if (m) {
            const d = new Date(
                parseInt(m[3], 10),
                parseInt(m[2], 10) - 1,
                parseInt(m[1], 10),
                parseInt(m[4] || '0', 10),
                parseInt(m[5] || '0', 10),
                parseInt(m[6] || '0', 10)
            );
            return Number.isNaN(d.getTime()) ? null : d;
        }
        const d = new Date(s);
        return Number.isNaN(d.getTime()) ? null : d;
    } catch (e) {
        return null;
    }
}



