function uaEnsureIsEmri(ua) {
    if (!ua.is_emri) ua.is_emri = {};
    if (!ua.is_emri.kesim) ua.is_emri.kesim = {};
    if (!ua.is_emri.dikim) ua.is_emri.dikim = {};
    if (!ua.is_emri.dikim.urun_sekli || typeof ua.is_emri.dikim.urun_sekli !== 'object') {
        ua.is_emri.dikim.urun_sekli = { grid: 25, snap: true, sekiller: [] };
    }
    if (!Array.isArray(ua.is_emri.dikim.urun_sekli.sekiller)) ua.is_emri.dikim.urun_sekli.sekiller = [];
    if (!ua.is_emri.kalite_paket) ua.is_emri.kalite_paket = {};
    if (!ua.is_emri.pastal) ua.is_emri.pastal = { sekiller: [], snap: true, grid: 25, lock_all: false };
    if (!Array.isArray(ua.is_emri.pastal.sekiller)) ua.is_emri.pastal.sekiller = [];
    if (typeof ua.is_emri.pastal.snap !== 'boolean') ua.is_emri.pastal.snap = true;
    if (!ua.is_emri.pastal.grid) ua.is_emri.pastal.grid = 25;
    if (typeof ua.is_emri.pastal.lock_all !== 'boolean') ua.is_emri.pastal.lock_all = false;
    return ua.is_emri;
}

/** Simteks konfeksiyon / Fason konfeksiyon / Doğrudan sevk — eski SIMTEKS, FASON değerlerini taşır */
function uaNormalizeUretimYeri(v) {
    const s = String(v || '').trim().toUpperCase();
    if (!s) return 'SIMTEKS_KONF';
    if (s === 'SIMTEKS' || s === 'SIMTEKS_KONF' || s === 'SIMTEKS_KONFEKSIYON') return 'SIMTEKS_KONF';
    if (s === 'FASON' || s === 'FASON_KONF' || s === 'FASON_KONFEKSIYON') return 'FASON_KONF';
    if (s === 'DOGRUDAN_SEVK' || s === 'DOGRUDAN' || s === 'DIREKT' || s === 'DIREKT_SEVK') return 'DOGRUDAN_SEVK';
    return 'SIMTEKS_KONF';
}

function uaUretimYeriLabel(v) {
    const n = uaNormalizeUretimYeri(v);
    if (n === 'FASON_KONF') return 'Fason konfeksiyon';
    if (n === 'DOGRUDAN_SEVK') return 'Dogrudan sevk';
    return 'Simteks konfeksiyon';
}

function uaSiparisUretimYeriFromAll(all = {}, kalemler = []) {
    const siparisFoy = all['siparis_foy'] || {};
    const foyYerRaw = String(siparisFoy?.teknik_genel?.uretim_yeri || '').trim();
    const foyYer = foyYerRaw ? uaNormalizeUretimYeri(foyYerRaw) : '';
    // Siparis teknik foyde secim yapildiysa onu esas al.
    if (foyYerRaw) return foyYer;
    const sayim = { SIMTEKS_KONF: 0, FASON_KONF: 0, DOGRUDAN_SEVK: 0 };
    (kalemler || []).forEach((_, i) => {
        const ua = all[`u_${i}`] || {};
        const kalemYerRaw = String(
            ua?.urun_teknik_genel?.uretim_yeri ||
            ua?.teknik_genel?.uretim_yeri ||
            ''
        ).trim();
        if (!kalemYerRaw) return;
        const yer = uaNormalizeUretimYeri(kalemYerRaw);
        if (!sayim[yer]) sayim[yer] = 0;
        sayim[yer] += 1;
    });
    const dolu = Object.entries(sayim).filter(([, n]) => (parseInt(n, 10) || 0) > 0);
    if (!dolu.length) return foyYer || '';
    if (dolu.length === 1) return dolu[0][0];
    // Siparis tablosundaki constraint nedeniyle tek bir kanonik deger donmeliyiz.
    // Karisik durumda en yuksek adetli uretim yerini sec.
    dolu.sort((a, b) => b[1] - a[1]);
    return dolu[0][0] || foyYer;
}

function renderUaPastalSvg(sekiller, pastalMeta = {}, opts = {}) {
    const dragStart = opts.dragStart || 'uaPastalStartDrag';
    const svgH = opts.tall ? 340 : 200;
    const src = Array.isArray(sekiller) ? sekiller : [];
    if (!src.length) {
        const eh = opts.tall ? 300 : 180;
        return `<div style="height:${eh}px;display:flex;align-items:center;justify-content:center;font-size:10px;color:var(--text3);border:1px dashed var(--border);border-radius:10px;background:var(--surface2)">Önizleme için şekil ekleyin</div>`;
    }
    const clamp = (n, min, max) => Math.max(min, Math.min(max, n));
    const toNum = (v, d=0) => {
        const n = parseFloat(v);
        return Number.isFinite(n) ? n : d;
    };
    const shapes = src.map((s, i) => {
        const tip = s.tip || 'DIKDORTGEN';
        const x = clamp(toNum(s.x, 80), 0, 960);
        const y = clamp(toNum(s.y, 80), 0, 380);
        const w = clamp(toNum(s.w, 140), 20, 420);
        const h = clamp(toNum(s.h, 80), 20, 260);
        const rot = toNum(s.rot, 0);
        const color = ['#a78bfa','#34d399','#60a5fa','#f59e0b','#fb7185'][i % 5];
        const lockMark = s.locked ? `<text x="${x+10}" y="${y-10}" text-anchor="middle" font-size="12" fill="#fbbf24">🔒</text>` : '';
        if (tip === 'DAIRE') {
            const r = clamp(Math.min(w, h) / 2, 10, 100);
            return `<g data-idx="${i}" style="cursor:${pastalMeta.lock_all||s.locked?'not-allowed':'move'}" onmousedown="${dragStart}(event, ${i})" transform="rotate(${rot} ${x} ${y})"><circle cx="${x}" cy="${y}" r="${r}" fill="${color}33" stroke="${color}" stroke-width="2" stroke-dasharray="${s.locked?'4 3':'none'}" /><text x="${x}" y="${y+3}" text-anchor="middle" font-size="11" fill="#cbd5e1">D${i+1}</text>${lockMark}</g>`;
        }
        if (tip === 'UCGEN') {
            const p1 = `${x},${y-h/2}`;
            const p2 = `${x-w/2},${y+h/2}`;
            const p3 = `${x+w/2},${y+h/2}`;
            return `<g data-idx="${i}" style="cursor:${pastalMeta.lock_all||s.locked?'not-allowed':'move'}" onmousedown="${dragStart}(event, ${i})" transform="rotate(${rot} ${x} ${y})"><polygon points="${p1} ${p2} ${p3}" fill="${color}33" stroke="${color}" stroke-width="2" stroke-dasharray="${s.locked?'4 3':'none'}" /><text x="${x}" y="${y+4}" text-anchor="middle" font-size="11" fill="#cbd5e1">U${i+1}</text>${lockMark}</g>`;
        }
        return `<g data-idx="${i}" style="cursor:${pastalMeta.lock_all||s.locked?'not-allowed':'move'}" onmousedown="${dragStart}(event, ${i})" transform="rotate(${rot} ${x} ${y})"><rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="6" ry="6" fill="${color}33" stroke="${color}" stroke-width="2" stroke-dasharray="${s.locked?'4 3':'none'}" /><text x="${x}" y="${y+4}" text-anchor="middle" font-size="11" fill="#cbd5e1">R${i+1}</text>${lockMark}</g>`;
    }).join('');
    const gridSize = Math.max(5, parseFloat(pastalMeta.grid) || 25);
    return `
    <svg id="ua-pastal-svg" viewBox="0 0 1000 420" style="width:100%;height:${svgH}px;border:1px solid var(--border);border-radius:10px;background:linear-gradient(180deg,var(--surface2),var(--surface3));user-select:none">
        <defs>
            <pattern id="ua-grid" width="${gridSize}" height="${gridSize}" patternUnits="userSpaceOnUse">
                <path d="M ${gridSize} 0 L 0 0 0 ${gridSize}" fill="none" stroke="rgba(148,153,181,0.14)" stroke-width="1"/>
            </pattern>
        </defs>
        <rect x="0" y="0" width="1000" height="420" fill="url(#ua-grid)"></rect>
        <rect x="15" y="15" width="970" height="390" rx="8" fill="transparent" stroke="rgba(148,153,181,0.22)" stroke-width="1.5"/>
        ${shapes}
    </svg>`;
}

/** Ürün ağacı kaydında tek alan güncellenirken önceki veriyi silmemek için derin birleştirme (düz nesneler; diziler tamamen patch ile değişir). */
function uaDeepMergeUrunAgaci(existing, patch) {
    if (patch == null || typeof patch !== 'object' || Array.isArray(patch)) return existing;
    const base = existing != null && typeof existing === 'object' && !Array.isArray(existing) ? { ...existing } : {};
    Object.keys(patch).forEach(k => {
        const pv = patch[k];
        if (pv === undefined) return;
        if (Array.isArray(pv)) {
            base[k] = pv.slice();
            return;
        }
        if (pv !== null && typeof pv === 'object' && pv.constructor === Object) {
            const ev = base[k];
            base[k] = uaDeepMergeUrunAgaci(
                ev != null && typeof ev === 'object' && !Array.isArray(ev) ? ev : {},
                pv
            );
            return;
        }
        base[k] = pv;
    });
    return base;
}

function uaCloneAgacSnapshot(obj) {
    if (obj == null || typeof obj !== 'object') return {};
    try {
        return JSON.parse(JSON.stringify(obj));
    } catch (e) {
        return {};
    }
}

async function uaSetAgac(siparisId, urunIdx, agac) {
    return uaKdWriteLock(async () => {
        /* Cache referansını mutate etme — kopya üzerinde çalış */
        const all = uaCloneAgacSnapshot((await sbKdGet(siparisId, 'KD_URUN_AGACI', false)) || {});
        uaAgacTruthIntoDoc(siparisId, all);
        const key = urunIdx === 'SIPARIS' ? 'siparis_foy' : `u_${urunIdx}`;
        const seqKey = uaAgacTruthKey(siparisId, urunIdx);
        const truth = _uaAgacLocalTruth[seqKey];
        const incoming = uaCloneAgacSnapshot(agac || {});
        const live = truth && (!incoming._ua_edit_seq || truth.seq >= (incoming._ua_edit_seq || 0))
            ? uaCloneAgacSnapshot(truth.agac)
            : incoming;
        delete live._ua_edit_seq;
        const existing = uaCloneAgacSnapshot(all[key]);
        const merged = uaDeepMergeUrunAgaci(existing, live);
        if (urunIdx !== 'SIPARIS' && Array.isArray(live.asamalar)) {
            merged.asamalar = uaNormalizeAsamalar(live.asamalar, { forceSevk: false, preserveOrder: true });
        } else if (urunIdx !== 'SIPARIS' && Array.isArray(merged.asamalar)) {
            merged.asamalar = uaNormalizeAsamalar(merged.asamalar, { forceSevk: false, preserveOrder: true });
        }
        delete merged._ua_edit_seq;
        all[key] = merged;
        const seqBeforeWrite = truth?.seq || 0;
        const res = await sbKdSet(siparisId, 'KD_URUN_AGACI', all);
        if (res && res.error) return res;
        /* sbKdSet cache'i ezebilir — yerel seçimleri geri yaz */
        if (truth && truth.seq > seqBeforeWrite) {
            uaCacheAgacYaz(siparisId, urunIdx, truth.agac, { keepSeq: true });
        } else {
            uaCacheAgacYaz(siparisId, urunIdx, { ...merged, _ua_edit_seq: seqBeforeWrite || 1 }, { keepSeq: true });
        }
        uaAgacTruthCacheSenkron(siparisId);
        return { error: null };
    });
}

/** Aşama seçiminde sunucu yazımı UI'yi ezmesin diye yerel kaynak */
const _uaAgacLocalTruth = {};
let _uaAgacSaveTimer = null;
let _uaAgacSaveTarget = null;
let _uaAgacSaveInFlight = false;
let _uaAgacSaveAgain = false;
let _uaKdWriteChain = Promise.resolve();

function uaKdWriteLock(fn) {
    const run = _uaKdWriteChain.then(() => fn(), () => fn());
    _uaKdWriteChain = run.then(() => undefined, () => undefined);
    return run;
}

function uaAgacTruthKey(siparisId, urunIdx) {
    return `${String(siparisId || '')}|${urunIdx === 'SIPARIS' ? 'SIPARIS' : String(urunIdx)}`;
}

/** Yerel truth'taki tüm kalemleri dokümana işle (uygula / kaydet öncesi) */
function uaAgacTruthIntoDoc(siparisId, doc) {
    const sid = String(siparisId || '');
    if (!sid || !doc || typeof doc !== 'object') return doc;
    const prefix = sid + '|';
    Object.keys(_uaAgacLocalTruth).forEach((seqKey) => {
        if (!seqKey.startsWith(prefix)) return;
        const rest = seqKey.slice(prefix.length);
        const key = rest === 'SIPARIS' ? 'siparis_foy' : `u_${rest}`;
        const agac = uaCloneAgacSnapshot(_uaAgacLocalTruth[seqKey]?.agac || {});
        delete agac._ua_edit_seq;
        if (rest !== 'SIPARIS' && Array.isArray(agac.asamalar)) {
            agac.asamalar = uaNormalizeAsamalar(agac.asamalar, { forceSevk: false, preserveOrder: true });
        }
        doc[key] = agac;
    });
    return doc;
}

/** sbKdSet sonrası _kdCache'i yerel truth ile hizala — Tanımlı rozetleri buradan okunur */
function uaAgacTruthCacheSenkron(siparisId) {
    const sid = String(siparisId || '');
    if (!sid) return;
    const ck = `KD_URUN_AGACI_${sid}`;
    if (!_kdCache[ck] || typeof _kdCache[ck] !== 'object') _kdCache[ck] = {};
    const prefix = sid + '|';
    Object.keys(_uaAgacLocalTruth).forEach((seqKey) => {
        if (!seqKey.startsWith(prefix)) return;
        const rest = seqKey.slice(prefix.length);
        const key = rest === 'SIPARIS' ? 'siparis_foy' : `u_${rest}`;
        const agac = _uaAgacLocalTruth[seqKey]?.agac;
        if (!agac) return;
        _kdCache[ck][key] = agac;
    });
    if (typeof kdCacheStamp === 'function') kdCacheStamp(ck);
}

/** Yerel cache — UI anında güncellensin (ağ beklemeden) */
function uaCacheAgacYaz(siparisId, urunIdx, agac, opts = {}) {
    const sid = String(siparisId || '');
    if (!sid) return;
    const ck = `KD_URUN_AGACI_${sid}`;
    if (!_kdCache[ck] || typeof _kdCache[ck] !== 'object') _kdCache[ck] = {};
    const key = urunIdx === 'SIPARIS' ? 'siparis_foy' : `u_${urunIdx}`;
    const seqKey = uaAgacTruthKey(sid, urunIdx);
    const copy = uaCloneAgacSnapshot(agac || {});
    let seq;
    if (opts.keepSeq && copy._ua_edit_seq != null) {
        seq = copy._ua_edit_seq;
    } else if (opts.keepSeq && _uaAgacLocalTruth[seqKey]) {
        seq = _uaAgacLocalTruth[seqKey].seq;
        copy._ua_edit_seq = seq;
    } else {
        seq = (_uaAgacLocalTruth[seqKey]?.seq || 0) + 1;
        copy._ua_edit_seq = seq;
    }
    _uaAgacLocalTruth[seqKey] = { seq, agac: copy };
    _kdCache[ck][key] = copy;
    if (typeof kdCacheStamp === 'function') kdCacheStamp(ck);
}

/**
 * Birden fazla kaleme tek get/set — paralel uaSetAgac yarışında bazı kalemler kayboluyordu.
 * opts.replace: hedef kalemi tamamen kaynak kopyasıyla değiştir.
 */
async function uaSetAgacCoklu(siparisId, entries, opts = {}) {
    const list = Array.isArray(entries) ? entries : [];
    if (!siparisId || !list.length) return;
    const replace = !!opts.replace;
    return uaKdWriteLock(async () => {
        /* Bekleyen tekil kayıt bu yazımı ezmesin */
        if (_uaAgacSaveTimer) {
            clearTimeout(_uaAgacSaveTimer);
            _uaAgacSaveTimer = null;
        }
        _uaAgacSaveAgain = false;

        const all = uaCloneAgacSnapshot((await sbKdGet(siparisId, 'KD_URUN_AGACI', false)) || {});
        uaAgacTruthIntoDoc(siparisId, all);

        list.forEach((e) => {
            const urunIdx = e?.urunIdx != null ? e.urunIdx : e?.idx;
            if (urunIdx == null) return;
            const key = urunIdx === 'SIPARIS' ? 'siparis_foy' : `u_${urunIdx}`;
            if (replace) {
                const clone = uaCloneAgacSnapshot(e.agac || {});
                delete clone._ua_edit_seq;
                if (urunIdx !== 'SIPARIS' && Array.isArray(clone.asamalar)) {
                    clone.asamalar = uaNormalizeAsamalar(clone.asamalar, { forceSevk: false, preserveOrder: true });
                }
                all[key] = clone;
            } else {
                const existing = uaCloneAgacSnapshot(all[key]);
                const merged = uaDeepMergeUrunAgaci(existing, e.agac || {});
                if (urunIdx !== 'SIPARIS' && Array.isArray(merged.asamalar)) {
                    merged.asamalar = uaNormalizeAsamalar(merged.asamalar, { forceSevk: false, preserveOrder: true });
                }
                delete merged._ua_edit_seq;
                all[key] = merged;
            }
            uaCacheAgacYaz(siparisId, urunIdx, all[key]);
        });

        const res = await sbKdSet(siparisId, 'KD_URUN_AGACI', all);
        if (res && res.error) throw res.error;
        /* Set cache'i ezdiyse truth'u geri bas — ilk uygula sonrası “tanımsız” kalmasın */
        list.forEach((e) => {
            const urunIdx = e?.urunIdx != null ? e.urunIdx : e?.idx;
            if (urunIdx == null) return;
            const key = urunIdx === 'SIPARIS' ? 'siparis_foy' : `u_${urunIdx}`;
            uaCacheAgacYaz(siparisId, urunIdx, all[key], { keepSeq: false });
        });
        uaAgacTruthCacheSenkron(siparisId);
    });
}
try { window.uaSetAgacCoklu = uaSetAgacCoklu; } catch (e) {}

/** Aşama tıklamalarını birleştir — her tıkta ağ kaydı beklemesin; eski yazım yeniyi ezmesin */
function uaAgacKaydetErtele(siparisId, urunIdx) {
    _uaAgacSaveTarget = {
        siparisId: String(siparisId || ''),
        urunIdx
    };
    if (_uaAgacSaveTimer) clearTimeout(_uaAgacSaveTimer);
    _uaAgacSaveTimer = setTimeout(() => {
        _uaAgacSaveTimer = null;
        uaAgacPersistCalistir().catch((e) => console.warn('uaAgacPersistCalistir', e));
    }, 280);
}

async function uaAgacPersistCalistir() {
    if (_uaAgacSaveInFlight) {
        _uaAgacSaveAgain = true;
        return;
    }
    const target = _uaAgacSaveTarget;
    if (!target?.siparisId) return;
    _uaAgacSaveInFlight = true;
    try {
        do {
            _uaAgacSaveAgain = false;
            const { siparisId, urunIdx } = _uaAgacSaveTarget || target;
            const seqKey = uaAgacTruthKey(siparisId, urunIdx);
            const truth = _uaAgacLocalTruth[seqKey];
            const live = uaCloneAgacSnapshot(truth?.agac || uaGetCacheAgac(siparisId, urunIdx));
            const seqSaving = truth?.seq || live._ua_edit_seq || 0;
            delete live._ua_edit_seq;
            await uaSetAgac(siparisId, urunIdx, { ...live, _ua_edit_seq: seqSaving });
            const truthNow = _uaAgacLocalTruth[seqKey];
            if (truthNow && truthNow.seq > seqSaving) _uaAgacSaveAgain = true;
        } while (_uaAgacSaveAgain);
    } finally {
        _uaAgacSaveInFlight = false;
    }
}

async function uaAgacBekleyenKaydiFlush() {
    if (_uaAgacSaveTimer) {
        clearTimeout(_uaAgacSaveTimer);
        _uaAgacSaveTimer = null;
    }
    await uaAgacPersistCalistir();
}

function uaAgacKopyaHazirla(kaynakUa) {
    const clone = uaCloneAgacSnapshot(kaynakUa);
    delete clone.teknik_genel;
    delete clone.sekme_onay;
    delete clone._ua_edit_seq;
    if (Array.isArray(clone.asamalar)) {
        clone.asamalar = uaNormalizeAsamalar(clone.asamalar, { forceSevk: false, preserveOrder: true });
    }
    return clone;
}

function uaGetCacheAgac(siparisId, urunIdx) {
    const seqKey = uaAgacTruthKey(siparisId, urunIdx);
    if (_uaAgacLocalTruth[seqKey]?.agac) return _uaAgacLocalTruth[seqKey].agac;
    const key = urunIdx === 'SIPARIS' ? 'siparis_foy' : `u_${urunIdx}`;
    return _kdCache[`KD_URUN_AGACI_${siparisId}`]?.[key] || {};
}
async function uaSetSiparisAgac(siparisId, agac) {
    const all = await sbKdGet(siparisId, 'KD_URUN_AGACI');
    const existing = uaCloneAgacSnapshot(all['siparis']);
    all['siparis'] = uaDeepMergeUrunAgaci(existing, agac || {});
    await sbKdSet(siparisId, 'KD_URUN_AGACI', all);
}
function uaLegacyKalemAksesuarBirlestir(allUa, kalemler) {
    const out = {};
    const keys = new Set();
    (kalemler || []).forEach((_, i) => {
        const a = allUa[`u_${i}`]?.aksesuar || {};
        Object.keys(a).forEach(k => keys.add(k));
    });
    keys.forEach(k => {
        let best = 0;
        (kalemler || []).forEach((_, i) => {
            const v = parseFloat(allUa[`u_${i}`]?.aksesuar?.[k]) || 0;
            if (v > best) best = v;
        });
        if (best > 0) out[k] = best;
    });
    if (!out.dokuma_etiket && out.etiket) out.dokuma_etiket = out.etiket;
    return out;
}
function uaSiparisAksesuarGenelOku(siparisId, kalemler) {
    const allUa = _kdCache[`KD_URUN_AGACI_${siparisId}`] || {};
    const genel = { ...(allUa.siparis?.aksesuar_genel || {}) };
    const hasAny = UA_AKSESUARLAR.some(ak => (parseFloat(genel[ak.id]) || 0) > 0);
    if (!hasAny && kalemler?.length) {
        return { ...uaLegacyKalemAksesuarBirlestir(allUa, kalemler), ...genel };
    }
    return genel;
}
function renderUaAksesuarGenelPanel(siparis, kalemler) {
    const genel = uaSiparisAksesuarGenelOku(siparis.id, kalemler);
    const fasonKalemler = fasonTakipFasonKalemleri(siparis);
    const fasonAdet = fasonKalemler.reduce((a, { k }) => a + (parseInt(k.miktar, 10) || 0), 0);
    const dolu = UA_AKSESUARLAR.filter(ak => (parseFloat(genel[ak.id]) || 0) > 0);
    /* Telefonda açılır-kapanır, istenmedikçe kapalı; açık/kapalı durumu yeniden çizimde korunur. */
    const katlanir = !!window.ERP_MOBIL_LITE;
    const baslik = `<span class="panel-head-title"><span class="panel-head-dot" style="background:var(--amber-c)"></span>Genel aksesuar planı</span>`;
    return `
    ${katlanir
        ? `<details class="panel-box ua-aksesuar-katlanir" style="margin-top:12px"${window._uaAksesuarGenelAcik ? ' open' : ''} ontoggle="window._uaAksesuarGenelAcik = this.open">
        <summary class="panel-head">${baslik}<span class="ua-aksesuar-katlanir__ozet">${dolu.length ? `${dolu.length} kalem girili` : 'boş'}</span></summary>`
        : `<div class="panel-box" style="margin-top:12px">
        <div class="panel-head">${baslik}</div>`}
        <div style="padding:10px 14px;font-size:10px;color:var(--text3);line-height:1.45;border-bottom:1px solid var(--border)">
            Sipariş geneli — <b>adet/ürün</b> (veya metre/ürün). Fason Takip ve konfeksiyon özetinde fason kalemlerin sipariş adedi ile çarpılır.
            ${fasonAdet > 0 ? `<span style="display:block;margin-top:4px;color:var(--accent2);font-weight:600">Fason kalem toplamı: ${fasonAdet.toLocaleString('tr-TR')} adet</span>` : ''}
        </div>
        <div style="padding:10px 14px;max-height:280px;overflow-y:auto">
            <div class="ua-aksesuar-izgara" style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px">
                ${UA_AKSESUARLAR.map(ak => `
                <div style="display:flex;align-items:center;gap:6px;min-width:0">
                    <label style="font-size:9px;font-weight:600;color:var(--text2);width:72px;flex-shrink:0;line-height:1.2">${ak.label}</label>
                    <input type="number" step="0.01" min="0" placeholder="0" value="${genel[ak.id] || ''}"
                        id="ua-ak-genel-${ak.id}"
                        oninput="uaAksesuarGenelGuncelle('${ak.id}', this.value)"
                        class="pro-input" style="flex:1;padding:5px 8px;font-size:10px;text-align:center">
                    <span style="font-size:7px;color:var(--text3);width:52px;flex-shrink:0">${ak.birim}</span>
                </div>`).join('')}
            </div>
            ${fasonAdet > 0 && dolu.length ? `
            <div style="margin-top:12px;padding:10px 12px;border-radius:10px;background:rgba(251,191,36,0.12);border:1px solid rgba(251,191,36,0.35)">
                <div style="font-size:9px;font-weight:700;color:var(--amber-c);margin-bottom:6px">Fason için planlanan toplam</div>
                <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px">
                    ${dolu.map(ak => {
                        const birim = parseFloat(genel[ak.id]) || 0;
                        const top = Math.round(birim * fasonAdet * 10) / 10;
                        return `<div style="font-size:9px;color:var(--text2)"><b>${ak.label}</b>: ${top.toLocaleString('tr-TR')}</div>`;
                    }).join('')}
                </div>
            </div>` : ''}
        </div>
    ${katlanir ? '</details>' : '</div>'}`;
}

function uaNormalizeAsamalar(rawAsamalar = [], opts = {}) {
    const forceSevk = !!opts.forceSevk;
    /** false ise eski davranış: sabit UA_ASAMALAR sırasına göre sırala. true (varsayılan): kullanıcı sırasını koru. */
    const preserveOrder = opts.preserveOrder !== false;
    const order = UA_ASAMALAR.map(a => a.id);
    const valid = new Set(order);
    const uniq = [];
    (Array.isArray(rawAsamalar) ? rawAsamalar : []).forEach(id => {
        const n = String(id || '').trim().toLowerCase();
        if (!n || !valid.has(n) || uniq.includes(n)) return;
        uniq.push(n);
    });
    if (forceSevk && uniq.length && !uniq.includes('sevk')) uniq.push('sevk');
    if (!preserveOrder) {
        uniq.sort((a, b) => order.indexOf(a) - order.indexOf(b));
    }
    return uniq;
}

function uaAsamaLabel(id) {
    return (UA_ASAMALAR.find(a => a.id === id)?.label) || String(id || '').toUpperCase();
}

function uaAsamaBagimlilikKontrol(asamalar = [], opts = {}) {
    const set = new Set((asamalar || []).map(a => String(a || '').toLowerCase()));
    const allowBypassForDirect = !!opts.allowDirectSevkBypass;
    const eksikler = [];
    set.forEach(id => {
        const req = UA_ASAMA_GEREKSINIM[id] || [];
        req.forEach(r => {
            if (allowBypassForDirect && id === 'sevk' && r === 'kalite') return;
            if (!set.has(r)) {
                eksikler.push(`${uaAsamaLabel(id)} için ${uaAsamaLabel(r)} zorunlu`);
            }
        });
    });
    return [...new Set(eksikler)];
}

function uaStampKayitMeta(ua = {}, opts = {}) {
    const manual = !!opts.manual;
    const now = new Date();
    const rev = parseInt(ua.kayit_rev || 0, 10) || 0;
    ua.kayit_rev = rev + 1;
    ua.kayit_ts_iso = now.toISOString();
    ua.kayit_tarihi = now.toLocaleString('tr-TR');
    ua.kayit_kaynak = manual ? 'MANUEL' : 'OTOMATIK';
    if (manual) ua.kaydedildi = true;
    return ua;
}

function uaSiparisKalemAgacTamamMiFromAll(siparis, all = {}) {
    const kalemler = uaSiparisKalemleriGetir(siparis);
    if (!kalemler.length) return false;
    return kalemler.every((_, i) => {
        const u = all[`u_${i}`] || {};
        return Array.isArray(u.asamalar) && u.asamalar.length > 0;
    });
}

function uaTeknikGenelFoyTamam(foy) {
    const tg = foy.teknik_genel || {};
    const yer = uaNormalizeUretimYeri(tg.uretim_yeri);
    if (yer === 'FASON_KONF' && !String(tg.fason_firma || '').trim()) return false;
    return true;
}
function uaUrunTeknikGenelTamam(ua) {
    if (!ua || typeof ua !== 'object') return true;
    const tg = ua.urun_teknik_genel;
    if (!tg || typeof tg !== 'object') return true;
    const yer = uaNormalizeUretimYeri(tg.uretim_yeri);
    if (yer === 'FASON_KONF' && !String(tg.fason_firma || '').trim()) return false;
    return true;
}
function uaTeknikFoyTamamMiFromAll(all = {}) {
    const foy = all['siparis_foy'] || {};
    if (!uaTeknikGenelFoyTamam(foy)) return false;
    for (const k of Object.keys(all)) {
        if (!/^u_\d+$/.test(k)) continue;
        if (!uaUrunTeknikGenelTamam(all[k])) return false;
    }
    if (foy.kaydedildi) return true;
    const so = foy.sekme_onay || {};
    if (so.kesim && so.dikim && so.kalite) return true;
    const isEmri = foy.is_emri || {};
    const kesimRows = isEmri.kesim?.rows || [];
    const kesimDolu = Array.isArray(kesimRows) && kesimRows.some(r =>
        String(r?.birim_uzunluk || '').trim() !== '' ||
        String(r?.kesim_talimat || '').trim() !== '' ||
        (parseInt(r?.kesilecek_adet || 0) > 0) ||
        (Array.isArray(r?.pastal?.sekiller) && r.pastal.sekiller.length > 0)
    );
    const dikim = isEmri.dikim || {};
    const kalitePaket = isEmri.kalite_paket || {};
    const legacy = kesimDolu &&
        String(dikim.hat || '').trim() !== '' &&
        String(kalitePaket.kalite_seviye || '').trim() !== '';
    return legacy;
}

function uaSiparisTanimsizMi(siparis, all = {}) {
    const sipMeta = all['siparis'] || {};
    const agacTamam = !!sipMeta.tamamlandi || uaSiparisKalemAgacTamamMiFromAll(siparis, all);
    const teknikTamam = uaTeknikFoyTamamMiFromAll(all);
    return !(agacTamam || teknikTamam);
}

async function renderUrunAgaci() {
    const list = document.getElementById('main-list');
    if (!list) return;
    const teknikFoyModu = appMode === 'TEKNIK_FOY';
    const siparisler = (dataCache.siparisler || []).filter(s => s.durum !== 'TAMAMLANDI');

    /* Önce 40'lık gruplarla toplu çekim: aksi hâlde ekran her açılışta sipariş başına
       bir istek atıyordu (92 açık siparişte 92 eşzamanlı istek). sbKdGet önbellekte
       varsa ağa çıkmadığı için aşağıdaki döngü bundan sonra bedavaya gelir. */
    if (typeof sbKdGetMany === 'function') {
        try { await sbKdGetMany(siparisler.map(s => s.id).filter(Boolean), 'KD_URUN_AGACI'); } catch (e) {}
    }
    // Async: sipariş ağaç durumlarını topla
    const sipAgaclar = await Promise.all(siparisler.map(async s => {
        const all = await sbKdGet(s.id, 'KD_URUN_AGACI');
        const agac = all['siparis'] || {};
        const tanimsiz = uaSiparisTanimsizMi(s, all);
        return {
            id: s.id,
            sno: s.sno,
            firma: s.firma,
            agac,
            teknik: all['siparis_foy'] || {},
            tanimsiz
        };
    }));
    const bekleyenler = sipAgaclar.filter(x => x.tanimsiz);
    const sipOpts = sipAgaclar.map(x =>
        `<option value="${x.id}" ${uaSeciliSiparisId==x.id?'selected':''}>${x.tanimsiz?'○':'✓'} ${x.sno} — ${x.firma||'?'}</option>`
    ).join('');

    list.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px">

        <!-- Üst bar -->
        <div class="panel-box" style="padding:12px 16px">
            <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
                <div style="font-size:9px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace">${teknikFoyModu ? 'İş emri siparişi' : 'Sipariş'}</div>
                <select id="ua-siparis-sel" onchange="uaSelectSiparis(this.value)" class="pro-input" style="min-width:200px;width:auto;padding:6px 10px">
                    <option value="">— Seçin —</option>
                    ${sipOpts}
                </select>
                ${!teknikFoyModu && uaSeciliSiparisId ? `
                    <button type="button" onclick="uaSevkiyataGit()" class="btn-pro btn-ghost-pro" style="padding:6px 10px;font-size:10px;white-space:nowrap">
                        🚚 Sevkiyata Geç
                    </button>
                ` : ``}
                ${teknikFoyModu ? `<span class="pill pill-cyan" style="margin-left:8px">İş emirleri ürün ağacı basamaklarına göre hazırlanır</span>` : ``}
                ${bekleyenler.length > 0
                    ? `<span class="pill pill-amber" style="margin-left:auto">${bekleyenler.length} sipariş tanımsız</span>`
                    : `<span class="pill pill-green" style="margin-left:auto">Tümü tanımlı</span>`}
            </div>
        </div>

        <!-- İçerik -->
        <div id="ua-content">
            ${uaSeciliSiparisId ? renderUrunAgaciIcerik() : `
            <div class="empty-pro" style="padding:60px 20px">
                <div class="empty-pro-icon">${teknikFoyModu ? '📋' : '🌿'}</div>
                <div class="empty-pro-title">${teknikFoyModu ? 'Teknik Föy / İş Emri Hazırlama' : 'Ürün Ağacı Yönetimi'}</div>
                <div class="empty-pro-sub">${teknikFoyModu ? 'Bir sipariş seçin; ürün ağacı basamaklarına göre iş emirlerini hazırlayın' : 'Bir sipariş seçin ve ürün bazlı üretim akışını tanımlayın'}</div>
                ${bekleyenler.length > 0 ? `
                <div style="margin-top:16px;display:flex;flex-direction:column;gap:6px;align-items:center">
                    <div style="font-size:9px;color:var(--amber-c);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px">Tanımsız siparişler</div>
                    ${bekleyenler.map(s => `
                    <button onclick="uaSelectSiparis('${s.id}')"
                        style="padding:7px 16px;font-size:11px;font-weight:500;border-radius:8px;border:1px solid rgba(251,191,36,0.3);background:rgba(251,191,36,0.08);color:var(--amber-c);cursor:pointer;font-family:'DM Sans',sans-serif">
                        ${s.sno} — ${s.firma||'?'}
                    </button>`).join('')}
                </div>` : ''}
            </div>`}
        </div>

    </div>`;

    // select'i güncelle
    const sel = document.getElementById('ua-siparis-sel');
    if (sel && uaSeciliSiparisId) sel.value = uaSeciliSiparisId;
}

async function uaSelectSiparis(id) {
    uaSeciliSiparisId = id || null;
    uaCalismaModu = 'URUN';
    uaSeciliUrunIdx = null;
    if (uaSeciliSiparisId && !Array.isArray(uaSeciliKalemlerMap[uaSeciliSiparisId])) {
        uaSeciliKalemlerMap[uaSeciliSiparisId] = [];
    }
    // Cache'i doldur (renderUrunAgaci senkron map/every için)
    if (uaSeciliSiparisId) await sbKdGet(uaSeciliSiparisId, 'KD_URUN_AGACI');
    renderUrunAgaci();
}

async function uaSevkiyataGit() {
    await setAppMode('MAMUL_DEPO');
    changeType('ÇIKIŞ');
    if (typeof showToast === 'function') showToast('Mamül sevkiyat formu açıldı.');
}

function uaTumUrunAgaciTamamMi(kalemler = []) {
    if (!uaSeciliSiparisId) return false;
    if (!kalemler.length) return false;
    return kalemler.every((_, i) => {
        const u = typeof uaGetCacheAgac === 'function'
            ? uaGetCacheAgac(uaSeciliSiparisId, i)
            : (_kdCache[`KD_URUN_AGACI_${uaSeciliSiparisId}`]?.[`u_${i}`] || {});
        return Array.isArray(u.asamalar) && u.asamalar.length > 0;
    });
}

function uaSetCalismaModu(mod) {
    uaCalismaModu = 'URUN';
    if (uaSeciliUrunIdx === 'SIPARIS') uaSeciliUrunIdx = null;
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
}

function uaGetSeciliKalemler() {
    if (!uaSeciliSiparisId) return [];
    if (!Array.isArray(uaSeciliKalemlerMap[uaSeciliSiparisId])) uaSeciliKalemlerMap[uaSeciliSiparisId] = [];
    return uaSeciliKalemlerMap[uaSeciliSiparisId];
}

function uaKalemSecToggle(idx, checked) {
    const arr = uaGetSeciliKalemler();
    const exists = arr.includes(idx);
    if (checked && !exists) arr.push(idx);
    if (!checked && exists) uaSeciliKalemlerMap[uaSeciliSiparisId] = arr.filter(i => i !== idx);
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
}

function uaKalemAsamaVarMi(siparisId, kalemIdx, asamaId) {
    const ua = typeof uaGetCacheAgac === 'function'
        ? uaGetCacheAgac(siparisId, kalemIdx)
        : (_kdCache[`KD_URUN_AGACI_${siparisId}`]?.[`u_${kalemIdx}`] || {});
    return (ua.asamalar || []).map(a => String(a || '').toLowerCase()).includes(String(asamaId || '').toLowerCase());
}

function renderUaSeciliKalemIslemPanel(siparisId, kalemler) {
    let secili = uaGetSeciliKalemler().filter(i => i >= 0 && i < (kalemler || []).length);
    if (!secili.length) secili = (kalemler || []).map((_, i) => i);
    const asamaIds = new Set();
    secili.forEach(i => {
        const ua = typeof uaGetCacheAgac === 'function'
            ? uaGetCacheAgac(siparisId, i)
            : (_kdCache[`KD_URUN_AGACI_${siparisId}`]?.[`u_${i}`] || {});
        (ua.asamalar || []).forEach(a => asamaIds.add(String(a || '').toLowerCase()));
    });
    const sirali = UA_ASAMALAR.filter(a => asamaIds.has(a.id));
    if (!sirali.length) {
        return `<div style="padding:12px 14px;border-top:1px solid var(--border);font-size:10px;color:var(--text3)">Seçili kalemlerde tanımlı üretim aşaması yok.</div>`;
    }
    return `<div style="padding:10px 14px;border-top:1px solid var(--border);background:rgba(99,102,241,0.04)">
        <div style="font-size:9px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:0.06em;font-family:'DM Mono',monospace;margin-bottom:8px">Seçili kalemlerin işlemleri (${secili.length} kalem)</div>
        <div style="display:flex;flex-direction:column;gap:4px;max-height:min(36vh,280px);overflow:auto">
            ${sirali.map((a, n) => {
                const kalemSay = secili.filter(i => uaKalemAsamaVarMi(siparisId, i, a.id)).length;
                return `<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;border-radius:8px;background:var(--surface);border:1px solid var(--border)">
                    <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;min-width:18px">${n + 1}</span>
                    <span style="font-size:14px;line-height:1">${a.ikon}</span>
                    <span style="font-size:11px;font-weight:600;color:var(--text)">${pdfEsc(a.label)}</span>
                    <span style="margin-left:auto;font-size:9px;color:var(--accent2);font-family:'DM Mono',monospace">${kalemSay} kalem</span>
                </div>`;
            }).join('')}
        </div>
    </div>`;
}

function uaKalemSecToplu(sec, kalemSayi) {
    if (!uaSeciliSiparisId) return;
    uaSeciliKalemlerMap[uaSeciliSiparisId] = sec ? Array.from({ length: kalemSayi }, (_, i) => i) : [];
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
}

function uaParseEbat(ebatRaw) {
    const txt = String(ebatRaw || '').replace('*', 'x').toLowerCase();
    const p = txt.split('x').map(v => parseFloat(v.trim())).filter(v => Number.isFinite(v));
    return { en: p[0] || 0, boy: p[1] || 0 };
}

function uaNormalizeKalem(k, idx = 0) {
    if (k === null || k === undefined) return null;
    if (typeof k === 'string' || typeof k === 'number') {
        return { kod: '', ad: String(k), renk: '', ebat: '', miktar: 0 };
    }
    const o = (typeof k === 'object') ? k : {};
    const nested = o.urun || o.urun_detay || o.detay || o.data || {};
    const snap = o.snapshot || nested.snapshot || {};
    const ad = o.ad || o.urun_ad || o.urunAdi || o.name || nested.ad || nested.urun_adi || o.kod || nested.kod || `Ürün ${idx + 1}`;
    const miktarRaw = (o.miktar ?? o.adet ?? o.qty ?? nested.miktar ?? nested.adet ?? 0);
    const miktar = parseFloat(miktarRaw) || 0;
    const renk = o.renk || o.renk_adi || o.RENK || o.color || o.colour || o.rkod || nested.renk || nested.renk_adi || snap.renk || snap.renk_adi || '';
    const ebat = o.ebat || o.olcu || o.beden || o.size || nested.ebat || nested.olcu || nested.beden || snap.mamul_ebat || snap.olcu || '';
    return {
        ...o,
        kod: o.kod || nested.kod || '',
        ad,
        renk: o.renk || renk,
        ebat: o.ebat || ebat,
        miktar,
        snapshot: o.snapshot || snap || {}
    };
}

function uaSiparisKalemleriGetir(siparis) {
    if (!siparis) return [];
    let kalemler = [];
    try {
        kalemler = typeof siparis.cins === 'string' ? JSON.parse(siparis.cins) : (siparis.cins || siparis.kalemler || []);
    } catch (e) {
        kalemler = [];
    }
    if (!Array.isArray(kalemler)) return [];
    return kalemler.map((k, i) => uaNormalizeKalem(k, i)).filter(Boolean);
}

// Bir siparişin kalem listesine (mevcutlar aynen korunarak) yeni bir kalem
// ekler/siler — örn. sadece kumaş sipariş formu açılmış bir siparişe "Bornoz"
// gibi bitmiş-ürün kalemi eklemek için. uaSiparisKalemleriGetir ile Teknik Föy
// VE Sipariş Durum İnceleme aynı `siparis.cins` alanını okuduğundan, buraya
// eklenen kalem her iki ekranda da otomatik görünür.
function uaKalemEkleFormToggle() {
    uaKalemEkleFormAcik = !uaKalemEkleFormAcik;
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
}

function uaSiparisCinsRawOku(siparis) {
    let kalemler = [];
    try {
        kalemler = typeof siparis.cins === 'string' ? JSON.parse(siparis.cins) : (Array.isArray(siparis.cins) ? siparis.cins : []);
    } catch (e) {
        kalemler = [];
    }
    return Array.isArray(kalemler) ? kalemler : [];
}

async function uaSiparisKalemEkle() {
    if (!uaSeciliSiparisId) return;
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(uaSeciliSiparisId));
    if (!siparis) return;
    const ad = String(document.getElementById('ua-ke-ad')?.value || '').trim();
    const renk = String(document.getElementById('ua-ke-renk')?.value || '').trim();
    const ebat = String(document.getElementById('ua-ke-ebat')?.value || '').trim();
    const birim = String(document.getElementById('ua-ke-birim')?.value || 'ADET').trim();
    const miktar = parseFloat(document.getElementById('ua-ke-adet')?.value || 0) || 0;
    if (!ad) { erpToast('Ürün adı girin (örn. Bornoz).', 'error'); return; }
    if (miktar <= 0) { erpToast('Adet/miktar 0\'dan büyük olmalı.', 'error'); return; }

    const kalemler = uaSiparisCinsRawOku(siparis);
    kalemler.push({
        ad, renk, ebat, miktar, birim,
        kaynak: 'TEKNIK_FOY_EKLENDI',
        eklenme_ts: new Date().toISOString(),
        eklenme_kullanici: String(erpCurrentUser?.display_name || erpCurrentUser?.username || 'Sistem').trim() || 'Sistem'
    });
    const cinsJson = JSON.stringify(kalemler);
    const yeniMiktar = kalemler.reduce((a, k) => a + (parseFloat(k.miktar || 0) || 0), 0);
    try {
        if (typeof sb === 'undefined' || !sb?.from) throw new Error('Bağlantı yok');
        const { error } = await sb.from('siparisler').update({ cins: cinsJson, miktar: yeniMiktar }).eq('id', siparis.id);
        if (error) throw error;
        siparis.cins = cinsJson;
        siparis.miktar = yeniMiktar;
        const idx = (dataCache.siparisler || []).findIndex(s => String(s.id) === String(siparis.id));
        if (idx >= 0) { dataCache.siparisler[idx].cins = cinsJson; dataCache.siparisler[idx].miktar = yeniMiktar; }
        uaKalemEkleFormAcik = false;
        erpToast(`"${ad}" sipariş kalemlerine eklendi.`, 'success', 2400);
        const cont = document.getElementById('ua-content');
        if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    } catch (e) {
        erpToast('Kalem eklenemedi: ' + (e?.message || e), 'error');
    }
}

async function uaSiparisKalemSil(idx) {
    if (!uaSeciliSiparisId) return;
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(uaSeciliSiparisId));
    if (!siparis) return;
    const kalemler = uaSiparisCinsRawOku(siparis);
    const k = kalemler[idx];
    if (!k) return;
    if (k.kaynak !== 'TEKNIK_FOY_EKLENDI') { erpToast('Sadece Teknik Föy üzerinden eklenen kalemler silinebilir.', 'error'); return; }
    if (!confirm(`"${k.ad || 'Bu kalem'}" sipariş kalemlerinden silinsin mi?`)) return;
    kalemler.splice(idx, 1);
    const cinsJson = JSON.stringify(kalemler);
    const yeniMiktar = kalemler.reduce((a, kk) => a + (parseFloat(kk.miktar || 0) || 0), 0);
    try {
        if (typeof sb === 'undefined' || !sb?.from) throw new Error('Bağlantı yok');
        const { error } = await sb.from('siparisler').update({ cins: cinsJson, miktar: yeniMiktar }).eq('id', siparis.id);
        if (error) throw error;
        siparis.cins = cinsJson;
        siparis.miktar = yeniMiktar;
        const dcIdx = (dataCache.siparisler || []).findIndex(s => String(s.id) === String(siparis.id));
        if (dcIdx >= 0) { dataCache.siparisler[dcIdx].cins = cinsJson; dataCache.siparisler[dcIdx].miktar = yeniMiktar; }
        if (uaSeciliUrunIdx === idx) uaSeciliUrunIdx = null;
        erpToast('Kalem silindi.', 'success', 2000);
        const cont = document.getElementById('ua-content');
        if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    } catch (e) {
        erpToast('Kalem silinemedi: ' + (e?.message || e), 'error');
    }
}

function uaKalemEbatGetir(k) {
    if (!k) return '';
    const snap = k.snapshot || {};
    const aday = [
        k.ebat, k.EBAT, k.olcu, k.olcu_cm, k.olcu_ebat, k.ölçü, k.ölcu, k.size,
        k.beden, k.en_boy, k.urun_ebat, k.mamul_ebat,
        snap.ebat, snap.EBAT, snap.olcu, snap.mamul_ebat
    ].find(v => String(v || '').trim() !== '');
    if (aday) return String(aday).replace('*', 'x');
    const en = parseFloat(k.mamul_en || k.en || snap.mamul_en || snap.en || 0);
    const boy = parseFloat(k.mamul_boy || k.boy || snap.mamul_boy || snap.boy || 0);
    if (Number.isFinite(en) && Number.isFinite(boy) && en > 0 && boy > 0) return `${en}x${boy}`;
    const ad = String(k.ad || k.kod || '');
    const m = ad.match(/(\d{2,3})\s*[xX*]\s*(\d{2,3})/);
    if (m) return `${m[1]}x${m[2]}`;
    return '';
}

function uaKalemRenkGetir(k) {
    if (!k) return '';
    const snap = k.snapshot || {};
    const aday = [k.renk, k.RENK, k.rkod, k.renk_kodu, k.color, k.colour, snap.renk, snap.renk_adi, snap.renk_kodu].find(v => String(v || '').trim() !== '');
    if (aday) return String(aday);
    const ad = String(k.ad || '');
    const parts = ad.split('-').map(s => s.trim()).filter(Boolean);
    if (parts.length > 1) return parts[parts.length - 1];
    return '';
}

function uaIsSetUrun(urunAdi) {
    const t = String(urunAdi || '').toLowerCase();
    return t.includes('nevresim') || t.includes('pike') || t.includes('set');
}

function uaBuildKesimRows(kalemler, mevcutRows = []) {
    return (kalemler || []).map((k, i) => {
        const mevcut = mevcutRows[i] || {};
        const siparisAdet = parseInt(k?.miktar || 0) || 0;
        const fazlaPct = parseFloat(mevcut.fazla_pct);
        const extraPct = Number.isFinite(fazlaPct) ? fazlaPct : 3;
        const kesilecekAdet = Math.ceil(siparisAdet * (1 + (extraPct / 100)));
        const ebat = uaKalemEbatGetir(k);
        const isSet = uaIsSetUrun(k?.ad || k?.kod || '');
        const parsed = uaParseEbat(ebat);
        const parcalar = Array.isArray(mevcut.parcalar) && mevcut.parcalar.length
            ? mevcut.parcalar
            : (isSet ? [
                { tip: 'NEVRESIM', olcu: parsed.en && parsed.boy ? `${parsed.en}x${parsed.boy}` : '', adet: kesilecekAdet },
                { tip: 'ÇARŞAF', olcu: parsed.en && parsed.boy ? `${parsed.en}x${parsed.boy}` : '', adet: kesilecekAdet },
                { tip: 'YASTIK', olcu: '50x70', adet: kesilecekAdet * 2 },
            ] : []);
        return {
            urun_ad: k?.ad || k?.kod || `Ürün ${i + 1}`,
            renk: uaKalemRenkGetir(k),
            ebat,
            siparis_adet: siparisAdet,
            birim_uzunluk: mevcut.birim_uzunluk || '',
            fazla_pct: extraPct,
            kesilecek_adet: kesilecekAdet,
            parcalar,
            pastal: mevcut.pastal || { aktif: false, grid: 25, snap: true, sekiller: [] },
            kesim_talimat: mevcut.kesim_talimat || '',
        };
    });
}

function uaEnsureUrunTeknikGenel(ua) {
    if (!ua.urun_teknik_genel || typeof ua.urun_teknik_genel !== 'object') ua.urun_teknik_genel = {};
    const t = ua.urun_teknik_genel;
    t.uretim_yeri = uaNormalizeUretimYeri(t.uretim_yeri);
    if (typeof t.fason_firma !== 'string') t.fason_firma = '';
    return t;
}

async function uaUrunTeknikGenelGuncelle(aln, val, doRefresh) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx);
    uaEnsureUrunTeknikGenel(ua);
    if (aln === 'uretim_yeri') ua.urun_teknik_genel.uretim_yeri = uaNormalizeUretimYeri(val);
    else if (aln === 'fason_firma') ua.urun_teknik_genel.fason_firma = String(val || '');
    await uaSetAgac(uaSeciliSiparisId, uaSeciliUrunIdx, ua);
    const need = doRefresh !== false && aln === 'uretim_yeri';
    if (need) {
        const cont = document.getElementById('ua-content');
        if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    }
}

function renderUrunAgaciIcerik() {
    const siparis = (dataCache.siparisler||[]).find(s=>s.id==uaSeciliSiparisId);
    if (!siparis) return '';
    const kalemler = uaSiparisKalemleriGetir(siparis);
    const agac = _kdCache[`KD_URUN_AGACI_${uaSeciliSiparisId}`]?.['siparis'] || {};
    const toplamAdet = kalemler.reduce((a, k) => a + (parseInt(k?.miktar) || 0), 0);
    const tumUrunAgaciTamam = uaTumUrunAgaciTamamMi(kalemler);
    const seciliKalemler = uaGetSeciliKalemler();

    return `
    <div style="display:flex;flex-direction:column;gap:12px">

        <!-- Sipariş başlık -->
        <div class="panel-box" style="padding:12px 16px;display:flex;align-items:center;justify-content:space-between">
            <div style="display:flex;align-items:center;gap:10px">
                <span style="font-family:'Instrument Serif',serif;font-size:18px;color:var(--text)">${pdfEsc(siparis.sno || '—')} · ${pdfEsc(siparis.firma || '—')}</span>
                <span class="pill ${agac.tamamlandi?'pill-green':'pill-amber'}">${agac.tamamlandi?'Ağaç Tanımlı':'Tanımsız'}</span>
                <span style="font-size:10px;color:var(--text3)">${kalemler.length} kalem</span>
            </div>
            <div style="display:flex;align-items:center;gap:8px">
                ${agac.tamamlandi ? `<button onclick="uaAgaciSifirla()" class="btn-pro btn-danger-pro" style="padding:5px 12px;font-size:10px">Sıfırla</button>` : ''}
            </div>
        </div>

        <!-- İki kolon -->
        <div style="display:grid;grid-template-columns:minmax(320px,1.2fr) minmax(0,3fr);gap:12px">

            <!-- Sol: Ürün kalemleri -->
            <div class="panel-box">
                <div class="panel-head">
                    <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent2)"></span>Ürün Kalemleri</span>
                    <span style="display:inline-flex;gap:10px;align-items:center">
                        ${uaCalismaModu==='URUN' && kalemler.length > 1 ? `
                        <span class="panel-head-action" onclick="uaUygulaSecilenlere()" style="cursor:pointer">Seçilenlere Uygula</span>
                        <span class="panel-head-action" onclick="uaUygulaTumune()" style="cursor:pointer">Tümüne Uygula</span>
                        ` : ''}
                        <span class="panel-head-action" onclick="uaKalemEkleFormToggle()" style="cursor:pointer">${uaKalemEkleFormAcik ? '✕ Vazgeç' : '+ Ürün ekle'}</span>
                    </span>
                </div>
                ${uaKalemEkleFormAcik ? `
                <div style="padding:10px 14px;border-bottom:1px solid var(--border);background:rgba(167,139,250,0.07)">
                    <div style="font-size:10px;color:var(--text2);margin-bottom:8px">Bu siparişe, mevcut kalemler korunarak yeni bir ürün kalemi ekleyin — örn. sadece kumaş siparişi olarak açılmış bir siparişe bitmiş ürün olarak <b>Bornoz</b> eklemek gibi. Eklenen kalem Kesim/Dikim/Kalite iş emirlerinde ve Sipariş Durum İnceleme'de otomatik görünür.</div>
                    <div style="display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:6px;margin-bottom:6px">
                        <input id="ua-ke-ad" class="pro-input" placeholder="Ürün adı (örn. Bornoz)" style="padding:6px 8px;font-size:11px">
                        <input id="ua-ke-renk" class="pro-input" placeholder="Renk" style="padding:6px 8px;font-size:11px">
                        <input id="ua-ke-ebat" class="pro-input" placeholder="Ebat / Beden" style="padding:6px 8px;font-size:11px">
                    </div>
                    <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:6px">
                        <input id="ua-ke-adet" class="pro-input" type="number" min="0" step="1" placeholder="Adet" style="padding:6px 8px;font-size:11px">
                        <select id="ua-ke-birim" class="pro-input" style="padding:6px 8px;font-size:11px">
                            <option value="ADET">Adet</option>
                            <option value="METRE">Metre</option>
                            <option value="KG">Kg</option>
                            <option value="TAKIM">Takım</option>
                        </select>
                        <button class="btn-pro btn-primary-pro" style="padding:6px 14px;font-size:10px;white-space:nowrap" onclick="uaSiparisKalemEkle()">Ekle</button>
                    </div>
                </div>` : ''}
                <div>
                    ${uaCalismaModu==='URUN' && kalemler.length ? `
                    <div style="display:flex;align-items:center;gap:6px;padding:8px 12px;border-bottom:1px solid var(--border);background:var(--surface2)">
                        <button class="btn-pro btn-ghost-pro" style="padding:4px 8px;font-size:9px" onclick="uaKalemSecToplu(true, ${kalemler.length})">Tümünü Seç</button>
                        <button class="btn-pro btn-ghost-pro" style="padding:4px 8px;font-size:9px" onclick="uaKalemSecToplu(false, ${kalemler.length})">Temizle</button>
                        <span style="margin-left:auto;font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">${seciliKalemler.length} seçili${seciliKalemler.length ? '' : ' (boş = tümü)'}</span>
                    </div>` : ''}
                    ${kalemler.length === 0 ? '<div class="empty-pro" style="padding:30px 20px"><div class="empty-pro-title">Kalem yok</div></div>' :
                    kalemler.map((k,i) => {
                        const ua = (typeof uaGetCacheAgac === 'function')
                            ? uaGetCacheAgac(uaSeciliSiparisId, i)
                            : (_kdCache[`KD_URUN_AGACI_${uaSeciliSiparisId}`]?.[`u_${i}`] || {});
                        const tanimli = ua.asamalar && ua.asamalar.length > 0;
                        const aktif = uaSeciliUrunIdx===i;
                        const secili = seciliKalemler.includes(i);
                        const ebatTxt = uaKalemEbatGetir(k) || '—';
        const renkTxt = uaKalemRenkGetir(k) || '—';
                        return `<div onclick="uaSecUrun(${i})"
                            style="display:flex;align-items:center;gap:10px;padding:10px 16px;cursor:pointer;border-bottom:1px solid var(--border);border-left:3px solid ${aktif?'var(--accent2)':'transparent'};background:${aktif?'rgba(167,139,250,0.07)':'transparent'};transition:all 0.12s">
                            <input type="checkbox" ${secili?'checked':''} onclick="event.stopPropagation()" onchange="uaKalemSecToggle(${i}, this.checked)" style="accent-color:var(--accent2);width:14px;height:14px;flex-shrink:0">
                            <div style="flex:1;min-width:0">
                                <div style="font-size:11px;font-weight:500;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${k.ad||k.kod||'Ürün '+(i+1)}${k.kaynak==='TEKNIK_FOY_EKLENDI' ? ' <span style="font-size:8px;font-weight:700;color:var(--accent2);vertical-align:middle">TEKNİK FÖY</span>' : ''}</div>
                                <div style="display:grid;grid-template-columns:1.2fr 1fr auto;gap:8px;font-size:9px;color:var(--text3);margin-top:2px">
                    <span>Renk: ${renkTxt}</span>
                                    <span>Ebat: ${ebatTxt}</span>
                                    <span style="font-family:'DM Mono',monospace">Sipariş: ${k.miktar||0}</span>
                                </div>
                            </div>
                            <span class="pill ${tanimli?'pill-green':'pill-gray'}" style="flex-shrink:0">${tanimli?'✓ Tanımlı':'—'}</span>
                            ${k.kaynak==='TEKNIK_FOY_EKLENDI' ? `<span onclick="event.stopPropagation();uaSiparisKalemSil(${i})" title="Bu kalemi sil" style="flex-shrink:0;cursor:pointer;color:var(--text3);font-size:13px;padding:2px 4px">✕</span>` : ''}
                        </div>`;
                    }).join('')}
                </div>
                ${uaCalismaModu==='URUN' ? renderUaSeciliKalemIslemPanel(uaSeciliSiparisId, kalemler) : ''}
                ${uaCalismaModu==='URUN' && kalemler.length ? renderUaAksesuarGenelPanel(siparis, kalemler) : ''}
            </div>

            <!-- Sağ: Ağaç düzenleyici -->
            <div id="ua-editor-panel">
                ${uaSeciliUrunIdx !== null ? renderUaEditor(kalemler[uaSeciliUrunIdx], uaSeciliUrunIdx) : `
                <div class="empty-pro" style="padding:60px 20px">
                    <div class="empty-pro-icon">←</div>
                    <div class="empty-pro-title">Ürün kalemi seçin</div>
                    <div class="empty-pro-sub">Soldan bir ürün kalemi seçerek ağacı tanımlayın</div>
                </div>`}
            </div>

        </div>

        <!-- Kaydet / Tamamla -->
        ${uaSeciliUrunIdx !== null ? `
        <div style="display:flex;gap:8px">
            <button onclick="uaKaydet()" class="btn-pro btn-primary-pro" style="flex:1;justify-content:center;padding:10px">
                Ürün Ağacını Kaydet
            </button>
        </div>` : ''}

    </div>`;
}

function renderUaEditor(urun, idx) {
    if (!urun) return '';
    const ua = uaGetCacheAgac(uaSeciliSiparisId, idx);
    const utg = uaEnsureUrunTeknikGenel(ua);
    const seciliAsamalar = ua.asamalar || [];
    const asamaSirasi = seciliAsamalar.filter(id => UA_ASAMALAR.some(a => a.id === id));
    const sureler = ua.sureler || {};
    const siparisRef = (dataCache.siparisler || []).find(s => s.id == uaSeciliSiparisId);
    const tumKalemlerRef = uaSiparisKalemleriGetir(siparisRef);
    const tumUrunAgaciTamam = uaTumUrunAgaciTamamMi(tumKalemlerRef);

    return `
    <div class="panel-box">
        <div class="panel-head">
            <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent2)"></span>${urun.ad||urun.kod||'Ürün'}</span>
            <span style="font-size:10px;color:var(--text3);font-family:'DM Mono',monospace">${[urun.renk,urun.ebat].filter(Boolean).join(' · ')||'—'} · ${urun.miktar||0} adet</span>
        </div>
        <div style="padding:16px 20px;display:flex;flex-direction:column;gap:20px">

            <div style="padding:12px 14px;border:1px solid var(--border);border-radius:10px;background:var(--surface2)">
                <div style="font-size:9px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.08em;font-family:'DM Mono',monospace;margin-bottom:8px">Bu ürünün üretim yeri</div>
                <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center">
                    <label style="display:flex;align-items:center;gap:6px;font-size:11px;cursor:pointer">
                        <input type="radio" name="ua-utg-${idx}" ${utg.uretim_yeri==='SIMTEKS_KONF'?'checked':''} onchange="uaUrunTeknikGenelGuncelle('uretim_yeri','SIMTEKS_KONF')" style="accent-color:var(--accent2)"> Simteks konfeksiyon
                    </label>
                    <label style="display:flex;align-items:center;gap:6px;font-size:11px;cursor:pointer">
                        <input type="radio" name="ua-utg-${idx}" ${utg.uretim_yeri==='FASON_KONF'?'checked':''} onchange="uaUrunTeknikGenelGuncelle('uretim_yeri','FASON_KONF')" style="accent-color:var(--accent2)"> Fason konfeksiyon
                    </label>
                    <label style="display:flex;align-items:center;gap:6px;font-size:11px;cursor:pointer">
                        <input type="radio" name="ua-utg-${idx}" ${utg.uretim_yeri==='DOGRUDAN_SEVK'?'checked':''} onchange="uaUrunTeknikGenelGuncelle('uretim_yeri','DOGRUDAN_SEVK')" style="accent-color:var(--accent2)"> Doğrudan sevk
                    </label>
                </div>
                <div style="${utg.uretim_yeri==='FASON_KONF'?'margin-top:10px':'display:none'}">
                    <label class="pro-label">Fason firma / atölye</label>
                    <input class="pro-input" placeholder="Hangi fasona gidecek" value="${pdfEsc(utg.fason_firma)}"
                        oninput="uaUrunTeknikGenelGuncelle('fason_firma', this.value, false)">
                </div>
            </div>


            <!-- AŞAMALAR — kompakt rozet (tıkla aç/kapa) + seçili aşamalarda detay -->
            <div>
                <div style="font-size:9px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace;margin-bottom:8px">Üretim aşamaları</div>
                <div style="font-size:10px;color:var(--text3);margin-bottom:8px;line-height:1.4">Aşamayı eklemek veya çıkarmak için rozetlere tıklayın. <span style="color:var(--accent2)">*</span> zorunlu aşamalardır.</div>
                <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center">
                    ${UA_ASAMALAR.map(a => {
                        const secili = seciliAsamalar.includes(a.id);
                        return `<button type="button" onclick="uaAsamaKucukTikla('${a.id}')" title="${a.zorunlu?'Zorunlu aşama':'Opsiyonel'}"
                            style="display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:999px;border:1px solid ${secili?'transparent':'var(--border)'};background:${secili?'var(--accent2)':'var(--surface2)'};color:${secili?'#fff':'var(--text)'};cursor:pointer;font-size:11px;font-weight:600;box-shadow:${secili?'0 2px 8px rgba(109,113,255,0.25)':'none'};transition:transform .1s,box-shadow .12s">
                            <span style="font-size:14px;line-height:1">${a.ikon}</span>
                            <span>${a.label}</span>
                            ${a.zorunlu ? '<span style="font-size:9px;opacity:.9;font-family:\'DM Mono\',monospace">*</span>' : ''}
                        </button>`;
                    }).join('')}
                </div>
                ${seciliAsamalar.length === 0 ? `<div style="margin-top:10px;padding:12px 14px;border:1px dashed var(--border);border-radius:10px;font-size:11px;color:var(--text3)">Henüz aşama seçilmedi. Rozetlere tıklayın.</div>` : ''}
                ${asamaSirasi.length ? `
                <div style="margin-top:14px;padding:12px 14px;border:1px solid var(--border);border-radius:10px;background:var(--surface2)">
                    <div style="font-size:10px;font-weight:700;color:var(--text2);margin-bottom:4px">Aşama sırası</div>
                    <div style="font-size:9px;color:var(--text3);margin-bottom:10px;line-height:1.4">Konfeksiyon ve sipariş özetinde bu sıra kullanılır. Yukarı / aşağı ile üretim akışına göre düzenleyin.</div>
                    <div style="display:flex;flex-direction:column;gap:4px">
                        ${asamaSirasi.map((id, si) => {
                            const asama = UA_ASAMALAR.find(a => a.id === id);
                            if (!asama) return '';
                            const upOk = si > 0;
                            const downOk = si < asamaSirasi.length - 1;
                            return `<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:8px;background:var(--surface);border:1px solid var(--border)">
                                <span style="font-size:10px;font-weight:800;color:var(--text3);font-family:'DM Mono',monospace;min-width:22px">${si + 1}.</span>
                                <span style="font-size:12px;flex:1">${asama.ikon} ${asama.label}</span>
                                <button type="button" class="btn-pro btn-ghost-pro" style="padding:4px 8px;font-size:10px;min-width:36px;opacity:${upOk ? 1 : 0.35};pointer-events:${upOk ? 'auto' : 'none'}" onclick="uaAsamaSiraDegistir(${si},-1)" title="Yukarı">↑</button>
                                <button type="button" class="btn-pro btn-ghost-pro" style="padding:4px 8px;font-size:10px;min-width:36px;opacity:${downOk ? 1 : 0.35};pointer-events:${downOk ? 'auto' : 'none'}" onclick="uaAsamaSiraDegistir(${si},1)" title="Aşağı">↓</button>
                            </div>`;
                        }).join('')}
                    </div>
                </div>` : ''}
            </div>

            <!-- KUMAŞ TÜKETİM — telefonda gösterilmez (kullanıcı, 25.09.2026: şu an kullanılmıyor) -->
            ${window.ERP_MOBIL_LITE ? '' : `<div>
                <div class="text-[10px] font-bold uppercase tracking-widest mb-3">🏁 Kumaş Tüketim Oranı</div>
                <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
                    <div>
                        <label class="pro-label">Metre / Ürün</label>
                        <input id="ua-kumas-metre" type="number" step="0.01" class="pro-input" placeholder="1.35"
                            value="${ua.kumas_metre||''}"
                            oninput="uaFieldGuncelle('kumas_metre', this.value)">
                    </div>
                    <div>
                        <label class="pro-label">Tolerans (%)</label>
                        <input id="ua-kumas-tolerans" type="number" class="pro-input" placeholder="3"
                            value="${ua.kumas_tolerans||''}"
                            oninput="uaFieldGuncelle('kumas_tolerans', this.value)">
                    </div>
                </div>
                ${urun.miktar && ua.kumas_metre ? `
                <div class="mt-2 bg-indigo-50 rounded-xl px-4 py-2 text-[9px] font-bold text-indigo-700">
                    📐 Tahmini toplam kumaş: <b>${(parseFloat(ua.kumas_metre||0) * parseInt(urun.miktar||0) * (1 + parseFloat(ua.kumas_tolerans||0)/100)).toFixed(1)} metre</b>
                </div>` : ''}
            </div>`}

            <div style="padding:12px 14px;border-radius:10px;border:1px dashed var(--border);background:var(--surface2);font-size:10px;color:var(--text3);line-height:1.45">
                Genel aksesuar planını soldaki <b>Genel aksesuar planı</b> panelinden girin (sipariş geneli). Fason Takip bu değerleri fason kalemlerin adedi ile çarpar.
            </div>

            <!-- NOT -->
            <div>
                <label class="pro-label">Özel Not / Üretim Talimatı</label>
                <textarea id="ua-not" class="pro-input" rows="2" placeholder="Özel üretim talimatı..."
                    oninput="uaFieldGuncelle('not', this.value)">${ua.not||''}</textarea>
            </div>

        </div>
    </div>`;
}

// ── YARDIMCI FONKSİYONLAR ──
async function uaSecUrun(idx) {
    uaCalismaModu = 'URUN';
    uaSeciliUrunIdx = idx;
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    /* Telefonda düzenleyici kalem listesinin altına düşer — seçince ekran ona kaysın. */
    if (window.ERP_MOBIL_LITE) {
        requestAnimationFrame(() => document.getElementById('ua-editor-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
    }
}

async function uaAsamaToggle(id, checked) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    const ua = uaCloneAgacSnapshot(uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx));
    let list = Array.isArray(ua.asamalar) ? ua.asamalar.slice() : [];
    if (checked) {
        if (!list.includes(id)) list.push(id);
    } else {
        list = list.filter(a => a !== id);
    }
    ua.asamalar = uaNormalizeAsamalar(list, { forceSevk: false, preserveOrder: true });
    uaCacheAgacYaz(uaSeciliSiparisId, uaSeciliUrunIdx, ua);
    uaAgacKaydetErtele(uaSeciliSiparisId, uaSeciliUrunIdx);
    const editDiv = document.getElementById('ua-content');
    if (editDiv) editDiv.innerHTML = renderUrunAgaciIcerik();
}

async function uaAsamaKucukTikla(id) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx);
    const secili = (ua.asamalar || []).includes(id);
    await uaAsamaToggle(id, !secili);
}

/** Seçili aşamalar dizisinde sıra değiştir (delta: -1 yukarı, +1 aşağı) */
async function uaAsamaSiraDegistir(fromIndex, delta) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    const ua = uaCloneAgacSnapshot(uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx));
    const list = uaNormalizeAsamalar(ua.asamalar || [], { forceSevk: false, preserveOrder: true });
    const toIdx = fromIndex + delta;
    if (toIdx < 0 || toIdx >= list.length || fromIndex < 0 || fromIndex >= list.length) return;
    const t = list[fromIndex];
    list[fromIndex] = list[toIdx];
    list[toIdx] = t;
    ua.asamalar = list;
    uaCacheAgacYaz(uaSeciliSiparisId, uaSeciliUrunIdx, ua);
    uaAgacKaydetErtele(uaSeciliSiparisId, uaSeciliUrunIdx);
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
}

async function uaFieldGuncelle(alan, deger) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx);
    ua[alan] = deger;
    await uaSetAgac(uaSeciliSiparisId, uaSeciliUrunIdx, ua);
}

async function uaIsEmriFieldGuncelle(kart, alan, deger) {
    if (!uaSeciliSiparisId) return;
    const idx = uaCalismaModu === 'SIPARIS' ? 'SIPARIS' : uaSeciliUrunIdx;
    if (idx === null || idx === undefined) return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, idx);
    const isEmri = uaEnsureIsEmri(ua);
    if (!isEmri[kart]) isEmri[kart] = {};
    isEmri[kart][alan] = deger;
    ua.is_emri = isEmri;
    await uaSetAgac(uaSeciliSiparisId, idx, ua);
}

function uaRefreshPastalPreview(ua) {
    const preview = document.getElementById('ua-pastal-preview');
    if (!preview) return;
    const isEmri = uaEnsureIsEmri(ua);
    const pastal = isEmri.pastal || {};
    const sekiller = pastal.sekiller || [];
    preview.innerHTML = renderUaPastalSvg(sekiller, pastal);
}

function uaPastalStartDrag(evt, index) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null) return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx);
    const isEmri = uaEnsureIsEmri(ua);
    const pastal = isEmri.pastal || {};
    const sekiller = pastal.sekiller || [];
    const shape = sekiller[index];
    if (!shape) return;
    if (pastal.lock_all || shape.locked) return;

    const svg = document.getElementById('ua-pastal-svg');
    if (!svg) return;
    const rect = svg.getBoundingClientRect();
    uaPastalDragState = {
        index,
        startX: evt.clientX,
        startY: evt.clientY,
        shapeStartX: parseFloat(shape.x) || 0,
        shapeStartY: parseFloat(shape.y) || 0,
        rectW: rect.width || 1,
        rectH: rect.height || 1,
        snap: pastal.snap !== false,
        grid: Math.max(5, parseInt(pastal.grid) || 25),
    };
    evt.preventDefault();
}

async function uaPastalDragMove(evt) {
    if (!uaPastalDragState) return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx);
    const isEmri = uaEnsureIsEmri(ua);
    const sekiller = isEmri.pastal.sekiller || [];
    const s = sekiller[uaPastalDragState.index];
    if (!s) return;
    const dx = ((evt.clientX - uaPastalDragState.startX) * 1000) / uaPastalDragState.rectW;
    const dy = ((evt.clientY - uaPastalDragState.startY) * 420) / uaPastalDragState.rectH;
    let nx = uaPastalDragState.shapeStartX + dx;
    let ny = uaPastalDragState.shapeStartY + dy;
    if (uaPastalDragState.snap) {
        nx = Math.round(nx / uaPastalDragState.grid) * uaPastalDragState.grid;
        ny = Math.round(ny / uaPastalDragState.grid) * uaPastalDragState.grid;
    }
    s.x = Math.max(0, Math.min(960, nx));
    s.y = Math.max(0, Math.min(380, ny));
    uaRefreshPastalPreview(ua);
}

async function uaPastalDragEnd() {
    if (!uaPastalDragState) return;
    const ua = uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx);
    await uaSetAgac(uaSeciliSiparisId, uaSeciliUrunIdx, ua);
    uaPastalDragState = null;
}

if (!window.__uaPastalBound) {
    window.__uaPastalBound = true;
    document.addEventListener('mousemove', uaPastalDragMove);
    document.addEventListener('mouseup', uaPastalDragEnd);
}

async function uaAksesuarGenelGuncelle(akId, deger) {
    if (!uaSeciliSiparisId) return;
    const allKey = `KD_URUN_AGACI_${uaSeciliSiparisId}`;
    if (!_kdCache[allKey]) _kdCache[allKey] = {};
    const sipMeta = { ...(_kdCache[allKey].siparis || {}) };
    if (!sipMeta.aksesuar_genel) sipMeta.aksesuar_genel = {};
    sipMeta.aksesuar_genel[akId] = parseFloat(deger) || 0;
    _kdCache[allKey].siparis = sipMeta;
    await uaSetSiparisAgac(uaSeciliSiparisId, sipMeta);
    /* Yeniden çizim yazılan kutuyu da yeniler — odak ve imleç geri verilmezse her harften sonra
       kutuya yeniden dokunmak gerekiyordu. */
    const odakId = String(document.activeElement?.id || '');
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    if (odakId.startsWith('ua-ak-genel-')) {
        const el = document.getElementById(odakId);
        if (el) { el.focus(); const v = el.value; el.value = ''; el.value = v; }
    }
}

async function uaKaydet() {
    if (!uaSeciliSiparisId) return;
    try { await uaAgacBekleyenKaydiFlush(); } catch (e) { console.warn('uaKaydet flush', e); }
    const siparis = (dataCache.siparisler || []).find(s => s.id == uaSeciliSiparisId);
    const kalemler = uaSiparisKalemleriGetir(siparis);
    if (!kalemler.length) {
        alert('Bu siparişte ürün kalemi bulunamadı.');
        return;
    }

    const all = uaCloneAgacSnapshot((await sbKdGet(uaSeciliSiparisId, 'KD_URUN_AGACI', false)) || {});
    if (typeof uaAgacTruthIntoDoc === 'function') uaAgacTruthIntoDoc(uaSeciliSiparisId, all);
    let eksikSayisi = 0;
    for (let i = 0; i < kalemler.length; i++) {
        const key = `u_${i}`;
        const fromTruth = typeof uaGetCacheAgac === 'function' ? uaGetCacheAgac(uaSeciliSiparisId, i) : null;
        const ua = uaCloneAgacSnapshot(fromTruth && Object.keys(fromTruth).length ? fromTruth : (all[key] || {}));
        delete ua._ua_edit_seq;
        ua.asamalar = uaNormalizeAsamalar(ua.asamalar || [], { forceSevk: true });
        if (!ua.asamalar.length) {
            eksikSayisi += 1;
            continue;
        }
        uaStampKayitMeta(ua, { manual: true });
        all[key] = ua;
    }

    const dogrudanSevkMi = uaSiparisUretimYeriFromAll(all, kalemler) === 'DOGRUDAN_SEVK';
    let dogrudanTemizlenenKonfAdim = 0;
    if (dogrudanSevkMi) {
        for (let i = 0; i < kalemler.length; i++) {
            const key = `u_${i}`;
            const ua = all[key] || {};
            const onceki = Array.isArray(ua.asamalar) ? ua.asamalar : [];
            const temiz = onceki.filter(a => !UA_KONFEKSIYON_ASAMALARI.has(String(a || '').toLowerCase()));
            dogrudanTemizlenenKonfAdim += Math.max(0, onceki.length - temiz.length);
            ua.asamalar = uaNormalizeAsamalar(temiz, { forceSevk: true });
            const uretimAdimSayisi = ua.asamalar.filter(a => UA_URETIM_ASAMALARI.has(String(a || '').toLowerCase())).length;
            if (uretimAdimSayisi === 0) {
                alert(`Doğrudan sevk kuralı: kalem #${i + 1} için konfeksiyon dışı en az 1 üretim adımı (dokuma/boya/baskı) zorunlu.`);
                return;
            }
            const eksik = uaAsamaBagimlilikKontrol(ua.asamalar || [], { allowDirectSevkBypass: true });
            if (eksik.length) {
                alert(`Kalem #${i + 1} için aşama bağımlılığı eksik:\n- ${eksik.join('\n- ')}`);
                return;
            }
            all[key] = ua;
        }
    } else {
        for (let i = 0; i < kalemler.length; i++) {
            const key = `u_${i}`;
            const ua = all[key] || {};
            const eksik = uaAsamaBagimlilikKontrol(ua.asamalar || []);
            if (eksik.length) {
                alert(`Kalem #${i + 1} için aşama bağımlılığı eksik:\n- ${eksik.join('\n- ')}`);
                return;
            }
        }
    }
    if (eksikSayisi > 0) {
        alert(`Önce eksik ürün ağaçlarını tamamlayın. Tanımsız kalem: ${eksikSayisi}`);
        return;
    }

    const siparisAgac = all['siparis'] || {};
    siparisAgac.tamamlandi = true;
    siparisAgac.tamamlanma_tarihi = new Date().toLocaleString('tr-TR');
    all['siparis'] = siparisAgac;
    const kdWrite = await sbKdSet(uaSeciliSiparisId, 'KD_URUN_AGACI', all);
    if (kdWrite?.error) {
        alert(`Ürün ağacı kaydedilemedi: ${kdWrite.error.message || 'Bilinmeyen hata'}`);
        return;
    }
    const allVerify = await sbKdGet(uaSeciliSiparisId, 'KD_URUN_AGACI', true);
    const verifyTamam = !!(allVerify?.siparis?.tamamlandi);
    if (!verifyTamam) {
        alert('Ürün ağacı yazıldı ancak doğrulama başarısız. Lütfen tekrar kaydedin.');
        return;
    }

    const siparisUretimYeri = uaSiparisUretimYeriFromAll(all, kalemler);
    let uretimYeriNotu = '';
    const { data: sipYerRows, error: siparisYerErr } = await sb.from('siparisler')
        .update({ uretim_yeri: siparisUretimYeri })
        .select('id,uretim_yeri')
        .eq('id', uaSeciliSiparisId);
    if (siparisYerErr) {
        const msg = String(siparisYerErr.message || '');
        const kolonYok = msg.toLowerCase().includes("could not find") && msg.toLowerCase().includes("'uretim_yeri'");
        if (kolonYok) {
            // Şema eskiyse ürün ağacı kaydını bozma; sadece bilgi notu düş.
            uretimYeriNotu = '\nNot: siparisler.uretim_yeri kolonu bulunamadı, sipariş satırı güncellenmedi.';
        } else {
            alert(`Ürün ağacı kaydedildi; sipariş üretim yeri güncellenemedi: ${siparisYerErr.message}`);
            return;
        }
    } else {
        const yeniYer = String((sipYerRows || [])[0]?.uretim_yeri || '');
        if (yeniYer !== String(siparisUretimYeri)) {
            alert('Ürün ağacı kaydedildi; sipariş üretim yeri doğrulanamadı.');
            return;
        }
        const dcSip = (dataCache.siparisler || []).find(s => s.id == uaSeciliSiparisId);
        if (dcSip) dcSip.uretim_yeri = siparisUretimYeri;
    }

    const gorevOzet = '\nGörevler: «Siparişlerden Ata» ile manuel oluşturun (otomatik kapalı).';

    const btn = document.querySelector('button[onclick="uaKaydet()"]');
    if (btn) { const o=btn.innerHTML; btn.innerHTML='✅ KAYDEDİLDİ'; btn.classList.add('opacity-75'); setTimeout(()=>{btn.innerHTML=o;btn.classList.remove('opacity-75');},1500); }
    erpSyncTablesBackground(['siparisler']);
    if (typeof erpToast === 'function') {
        erpToast(`Ürün ağacı kaydedildi · ${siparis?.sno || ''} — tanımsız siparişler listeleniyor`, 'success', 3500);
    } else {
        alert(`✅ Ürün ağacı kaydedildi.\nSipariş: ${siparis?.sno || '-'}\nKalem sayısı: ${kalemler.length}\nÜretim yeri: ${siparisUretimYeri}${uretimYeriNotu}${gorevOzet}`);
    }

    /* Kayıttan sonra tanımsız (ürün ağacı girilmemiş) sipariş listesine dön */
    uaSeciliSiparisId = null;
    uaSeciliUrunIdx = null;
    uaCalismaModu = 'URUN';
    await renderUrunAgaci();
}

async function uaAgaciSifirla() {
    if (!uaSeciliSiparisId) return;
    if (!confirm('Ürün ağacı sıfırlansın mı?')) return;
    await uaSetSiparisAgac(uaSeciliSiparisId, {});
    const siparis = (dataCache.siparisler||[]).find(s=>s.id==uaSeciliSiparisId);
    let kalemler = [];
    try { kalemler = typeof siparis?.cins==='string'?JSON.parse(siparis.cins):(siparis?.cins||[]); } catch(e){}
    await sbKdDel(uaSeciliSiparisId, 'KD_URUN_AGACI');
    uaSeciliUrunIdx = null;
    renderUrunAgaci();
}

async function uaUygulaTumune(withConfirm = true) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    try { await uaAgacBekleyenKaydiFlush(); } catch (e) {}
    const siparis = (dataCache.siparisler || []).find(s => s.id == uaSeciliSiparisId);
    const kalemler = uaSiparisKalemleriGetir(siparis);
    const hedefler = kalemler.map((_, i) => i).filter(i => i !== uaSeciliUrunIdx);
    if (!hedefler.length) {
        if (typeof erpToast === 'function') erpToast('Uygulanacak başka kalem yok.', 'info', 2500);
        return;
    }
    const kaynakUa = uaAgacKopyaHazirla(uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx));
    if (!Array.isArray(kaynakUa.asamalar) || !kaynakUa.asamalar.length) {
        alert('Önce bu kalemde en az bir üretim aşaması seçin, sonra tümüne uygulayın.');
        return;
    }
    if (withConfirm && !confirm(`Bu ürün ağacı diğer ${hedefler.length} kaleme kopyalansın mı?`)) return;
    /* Kaynak kalem de dahil — tek yazımda herkes tanımlı görünsün */
    const tumIdx = [uaSeciliUrunIdx, ...hedefler];
    await uaSetAgacCoklu(
        uaSeciliSiparisId,
        tumIdx.map(i => ({ urunIdx: i, agac: uaCloneAgacSnapshot(kaynakUa) })),
        { replace: true }
    );
    if (typeof uaAgacTruthCacheSenkron === 'function') uaAgacTruthCacheSenkron(uaSeciliSiparisId);
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    if (typeof erpToast === 'function') erpToast(`${hedefler.length} kaleme uygulandı.`, 'success', 2800);
}
try { window.uaUygulaTumune = uaUygulaTumune; } catch (e) {}

async function uaUygulaSecilenlere(withConfirm = true) {
    if (!uaSeciliSiparisId || uaSeciliUrunIdx === null || uaSeciliUrunIdx === 'SIPARIS') return;
    try { await uaAgacBekleyenKaydiFlush(); } catch (e) {}
    const siparis = (dataCache.siparisler || []).find(s => s.id == uaSeciliSiparisId);
    const kalemler = uaSiparisKalemleriGetir(siparis);
    let secili = uaGetSeciliKalemler().filter(i => i !== uaSeciliUrunIdx && i >= 0 && i < kalemler.length);
    /* Tik yoksa UI'daki gibi tüm diğer kalemlere uygula */
    if (!secili.length) {
        secili = kalemler.map((_, i) => i).filter(i => i !== uaSeciliUrunIdx);
    }
    if (!secili.length) {
        alert('Uygulanacak başka kalem yok.');
        return;
    }
    const kaynakUa = uaAgacKopyaHazirla(uaGetCacheAgac(uaSeciliSiparisId, uaSeciliUrunIdx));
    if (!Array.isArray(kaynakUa.asamalar) || !kaynakUa.asamalar.length) {
        alert('Önce bu kalemde en az bir üretim aşaması seçin, sonra uygulayın.');
        return;
    }
    if (withConfirm && !confirm(`Seçili ${secili.length} kaleme mevcut ürün ağacı uygulansın mı?`)) return;
    const tumIdx = [uaSeciliUrunIdx, ...secili.filter(i => i !== uaSeciliUrunIdx)];
    await uaSetAgacCoklu(
        uaSeciliSiparisId,
        tumIdx.map(i => ({ urunIdx: i, agac: uaCloneAgacSnapshot(kaynakUa) })),
        { replace: true }
    );
    if (typeof uaAgacTruthCacheSenkron === 'function') uaAgacTruthCacheSenkron(uaSeciliSiparisId);
    const cont = document.getElementById('ua-content');
    if (cont) cont.innerHTML = renderUrunAgaciIcerik();
    if (typeof erpToast === 'function') erpToast(`${secili.length} kaleme uygulandı.`, 'success', 2800);
}
try { window.uaUygulaSecilenlere = uaUygulaSecilenlere; } catch (e) {}

// ── Fason Takip (ürün ağacında FASON_KONF — sipariş bazlı malzeme takibi) ──
let fasonTakipFiltre = { arama: '', firma: 'HEPSI', siparisDurum: 'AKTIF' };
let fasonTakipAcikSiparisId = null;
let dokumaFasonFiltre = { arama: '', firma: 'HEPSI', siparisDurum: 'AKTIF' };
let _dokumaFasonRenderGen = 0;
let hasilSeciliSiparisId = null;
const FASON_TAKIP_KOLON_BG = {
    kalem: 'rgba(99,102,241,0.07)',
    sip: 'rgba(100,116,139,0.09)',
    plan_kumas: 'rgba(59,130,246,0.07)',
    sevk_kumas: 'rgba(6,182,212,0.08)',
    kesim: 'rgba(245,158,11,0.09)',
    dikim: 'rgba(139,92,246,0.07)',
    kalite: 'rgba(16,185,129,0.08)',
    yukleme: 'rgba(249,115,22,0.08)',
    sevk: 'rgba(20,184,166,0.08)',
    elde_adet: 'rgba(244,63,94,0.06)',
    elde_kumas: 'rgba(14,165,233,0.07)',
    pct: 'rgba(148,163,184,0.12)',
};
function fasonTakipTdStil(colKey, extra) {
    const parts = ['padding:3px 5px', 'vertical-align:middle', extra || ''];
    if (FASON_TAKIP_KOLON_BG[colKey]) parts.push('background:' + FASON_TAKIP_KOLON_BG[colKey]);
    return parts.filter(Boolean).join(';');
}
function fasonTakipThStil(colKey, align) {
    const bg = FASON_TAKIP_KOLON_BG[colKey] || 'var(--surface2)';
    return [
        'text-align:' + (align || 'left'),
        'padding:5px 6px',
        'white-space:nowrap',
        'font-size:8px',
        'color:var(--text3)',
        'text-transform:uppercase',
        "font-family:'DM Mono',monospace",
        'position:sticky',
        'top:0',
        'z-index:2',
        'background:' + bg,
        'box-shadow:0 1px 0 var(--border)',
    ].join(';');
}
function fasonTakipKalemHucreHtml(k) {
    return `<div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;min-width:0;line-height:1.2;max-width:240px">
        <span style="font-weight:600;font-size:10px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px" title="${pdfEsc(k.kalemAd)}">${pdfEsc(k.kalemAd)}</span>
        <span style="font-size:9px;color:var(--text3);white-space:nowrap">${pdfEsc(k.renk)}</span>
        <span style="font-size:9px;color:var(--text2);font-family:'DM Mono',monospace;white-space:nowrap">${pdfEsc(k.ebat)}</span>
        <span style="font-size:8px;color:var(--amber-c);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:88px" title="${pdfEsc(k.fasonFirma)}">${pdfEsc(k.fasonFirma)}</span>
    </div>`;
}
let fasonTakipDraft = {};
let _fasonTakipRenderGen = 0;
let _fasonTakipKdHazir = false;

function fasonTakipNum(v, dec) {
    const n = parseFloat(String(v ?? '').replace(',', '.'));
    if (!Number.isFinite(n)) return 0;
    return dec != null ? Math.round(n * Math.pow(10, dec)) / Math.pow(10, dec) : n;
}
function fasonTakipInt(v) { return Math.max(0, Math.round(fasonTakipNum(v))); }

/** Hedefe göre: >= hedef yeşil, ~%85+ sarı, altı kırmızı; hedef yoksa nötr */
const FASON_TAKIP_HEDEF_YAKIN_ORAN = 0.85;
function fasonTakipHedefDurum(girilen, hedef, isMetre) {
    const g = isMetre ? fasonTakipNum(girilen, 2) : fasonTakipInt(girilen);
    const h = isMetre ? fasonTakipNum(hedef, 2) : fasonTakipInt(hedef);
    if (h <= 0) return 'neutral';
    if (g >= h) return 'ok';
    if (g >= h * FASON_TAKIP_HEDEF_YAKIN_ORAN) return 'warn';
    return 'bad';
}
function fasonTakipHedefRenkStil(durum) {
    const m = {
        ok: 'background:rgba(52,211,153,0.2);border:1px solid rgba(52,211,153,0.55)',
        warn: 'background:rgba(251,191,36,0.22);border:1px solid rgba(251,191,36,0.55)',
        bad: 'background:rgba(251,113,133,0.16);border:1px solid rgba(251,113,133,0.45)',
        neutral: 'border:1px solid var(--border)',
    };
    return m[durum] || m.neutral;
}
function fasonTakipHedefBaslik(hedef, birim) {
    const h = fasonTakipNum(hedef, birim === 'm' ? 2 : 0);
    if (h <= 0) return '';
    const fmt = birim === 'm'
        ? h.toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' m'
        : Math.round(h).toLocaleString('tr-TR') + ' adet';
    return 'Hedef: ' + fmt + ' — yeşil: eşit/geçer, sarı: yakın, kırmızı: uzak';
}

function fasonTakipFasonFirmaAl(siparis, allUa, kalemIdx) {
    const ua = (allUa || {})[`u_${kalemIdx}`] || {};
    const kalemFf = String(ua?.urun_teknik_genel?.fason_firma || ua?.teknik_genel?.fason_firma || '').trim();
    if (kalemFf) return kalemFf;
    const sipFoy = allUa.siparis_foy || {};
    const sipMeta = allUa.siparis || {};
    return String(
        sipFoy?.teknik_genel?.fason_firma ||
        sipMeta?.teknik_genel?.fason_firma ||
        sipMeta?.urun_teknik_genel?.fason_firma ||
        ''
    ).trim() || '—';
}

function fasonTakipFasonKalemleri(siparis) {
    const kalemler = uaSiparisKalemleriGetir(siparis);
    return kalemler.map((k, i) => ({ k, i })).filter(x => planlamaKalemUretimAlani(siparis.id, x.i) === 'FASON_KONF');
}

function fasonTakipKdCache(siparisId) {
    return _kdCache[`KD_FASON_TAKIP_${siparisId}`] || {};
}

function fasonTakipKalemVarsayilan(siparis, kalemIdx) {
    const kalem = (uaSiparisKalemleriGetir(siparis) || [])[kalemIdx] || {};
    const allUa = _kdCache[`KD_URUN_AGACI_${siparis.id}`] || {};
    const kd = _kdCache[`KD_KONFEKSIYON_${siparis.id}`] || {};
    const kdDok = _kdCache[`KD_DOKUMA_${siparis.id}`] || {};
    const ua = allUa[`u_${kalemIdx}`] || {};
    const kr = kd[`kalem_${kalemIdx}`] || {};
    const dokU = (kdDok.urunler || {})[kalemIdx] || (kdDok.urunler || {})[String(kalemIdx)] || {};
    const miktar = parseInt(kalem.miktar, 10) || 0;
    const birimMt = parseFloat(ua.kumas_metre) || 0;
    return {
        kumas_plan_metre: birimMt > 0 && miktar > 0 ? Math.round(birimMt * miktar * 10) / 10 : 0,
        kumas_sevk_metre: parseFloat(dokU.toplam_metre) || parseFloat(kd.kumas_metre) || 0,
        kesim_adet: parseInt(kr.kesilen, 10) || 0,
        dikim_adet: parseInt(kr.dikilen, 10) || 0,
        kalite_adet: parseInt(kr.kk_gecen, 10) || 0,
        yukleme_adet: parseInt(kr.kolide, 10) || 0,
        sevk_adet: parseInt(kr.sevk_edilen, 10) || 0,
        elde_kalan_adet: 0,
        elde_kalan_kumas_metre: 0,
        not: ''
    };
}

function fasonTakipAksesuarPlanTopla(siparis, fasonKalemler) {
    const kalemler = uaSiparisKalemleriGetir(siparis);
    const genel = uaSiparisAksesuarGenelOku(siparis.id, kalemler);
    const plan = {};
    fasonKalemler.forEach(({ k }) => {
        const miktar = parseInt(k.miktar, 10) || 0;
        UA_AKSESUARLAR.forEach(ak => {
            const birim = parseFloat(genel[ak.id]) || 0;
            if (birim <= 0 || miktar <= 0) return;
            if (!plan[ak.id]) plan[ak.id] = { key: ak.id, ad: ak.label, birim, plan_toplam: 0 };
            plan[ak.id].plan_toplam += birim * miktar;
        });
    });
    return Object.values(plan).map(p => ({
        ...p,
        plan_toplam: Math.round(p.plan_toplam * 10) / 10
    }));
}

function fasonTakipAksesuarKayitOlustur(siparis, ftKd, fasonKalemler) {
    const planList = fasonTakipAksesuarPlanTopla(siparis, fasonKalemler);
    const kd = _kdCache[`KD_KONFEKSIYON_${siparis.id}`] || {};
    const saved = Array.isArray(ftKd.aksesuar) ? ftKd.aksesuar : [];
    const byKey = {};
    saved.forEach(a => { if (a?.key) byKey[a.key] = { ...a }; });
    planList.forEach(p => {
        const konfGelen = parseInt(kd[`ak_${p.key}_gelen`], 10) || 0;
        const konfKul = parseInt(kd[`ak_${p.key}_kullanilan`], 10) || 0;
        const prev = byKey[p.key] || {};
        byKey[p.key] = {
            key: p.key,
            ad: p.ad,
            birim: p.birim,
            plan_toplam: p.plan_toplam,
            gonderilen: prev.gonderilen != null ? prev.gonderilen : konfGelen,
            kullanilan: prev.kullanilan != null ? prev.kullanilan : konfKul
        };
    });
    return Object.values(byKey);
}

function fasonTakipKayitOlustur(siparisId) {
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (!siparis) return { siparis_not: '', kalem: {}, aksesuar: [] };
    const ftKd = fasonTakipKdCache(siparisId);
    const fasonKalemler = fasonTakipFasonKalemleri(siparis);
    const kalem = {};
    fasonKalemler.forEach(({ i }) => {
        const def = fasonTakipKalemVarsayilan(siparis, i);
        const saved = (ftKd.kalem || {})[String(i)] || (ftKd.kalem || {})[i] || {};
        kalem[String(i)] = { ...def, ...saved };
        const k = kalem[String(i)];
        if (!k.elde_kalan_adet && (k.kesim_adet || k.yukleme_adet)) {
            k.elde_kalan_adet = Math.max(0, fasonTakipInt(k.kesim_adet) - fasonTakipInt(k.yukleme_adet));
        }
    });
    return {
        siparis_not: ftKd.siparis_not || '',
        kalem,
        aksesuar: fasonTakipAksesuarKayitOlustur(siparis, ftKd, fasonKalemler)
    };
}

function fasonTakipDraftGet(siparisId) {
    const sid = String(siparisId);
    if (!fasonTakipDraft[sid]) fasonTakipDraft[sid] = fasonTakipKayitOlustur(sid);
    return fasonTakipDraft[sid];
}

function fasonTakipKalemSatirOlustur(siparis, kalemIdx) {
    const kalem = (uaSiparisKalemleriGetir(siparis) || [])[kalemIdx] || {};
    const allUa = _kdCache[`KD_URUN_AGACI_${siparis.id}`] || {};
    const kd = _kdCache[`KD_KONFEKSIYON_${siparis.id}`] || {};
    const kr = kd[`kalem_${kalemIdx}`] || {};
    const draft = fasonTakipDraftGet(siparis.id);
    const rec = draft.kalem[String(kalemIdx)] || fasonTakipKalemVarsayilan(siparis, kalemIdx);
    const hedef = parseInt(kalem.miktar, 10) || 0;
    const sevk = fasonTakipInt(rec.sevk_adet) || parseInt(kr.sevk_edilen, 10) || 0;
    return {
        siparisId: siparis.id,
        kalemIdx,
        kalemAd: kalem.ad || kalem.kod || `Kalem ${kalemIdx + 1}`,
        renk: uaKalemRenkGetir(kalem) || kalem.renk || '—',
        ebat: uaKalemEbatGetir(kalem) || kalem.ebat || kalem.olcu || '—',
        miktar: hedef,
        fasonFirma: fasonTakipFasonFirmaAl(siparis, allUa, kalemIdx),
        rec,
        sevk,
        pct: hedef > 0 ? Math.min(100, Math.round((sevk / hedef) * 100)) : (sevk > 0 ? 100 : 0),
        tamam: hedef > 0 && sevk >= hedef
    };
}

function fasonTakipSiparisGruplariOlustur(siparisler) {
    const gruplar = [];
    (siparisler || []).forEach(s => {
        const fasonKalemler = fasonTakipFasonKalemleri(s);
        if (!fasonKalemler.length) return;
        const kalemler = fasonKalemler.map(({ i }) => fasonTakipKalemSatirOlustur(s, i));
        const firmalar = [...new Set(kalemler.map(k => k.fasonFirma).filter(f => f && f !== '—'))];
        const topAdet = kalemler.reduce((a, k) => a + k.miktar, 0);
        const topSevk = kalemler.reduce((a, k) => a + k.sevk, 0);
        const tamam = kalemler.every(k => k.tamam);
        const kismi = !tamam && kalemler.some(k => k.sevk > 0);
        gruplar.push({
            siparisId: s.id,
            sno: s.sno || '—',
            firma: s.firma || '—',
            termin: s.ttarih || s.termin || '',
            durum: s.durum || '',
            fasonFirma: firmalar.join(' · ') || '—',
            kalemSay: kalemler.length,
            topAdet,
            topSevk,
            pct: topAdet > 0 ? Math.min(100, Math.round((topSevk / topAdet) * 100)) : 0,
            tamam,
            kismi,
            kalemler
        });
    });
    return gruplar.sort((a, b) => {
        const ta = a.termin ? new Date(a.termin).getTime() : Infinity;
        const tb = b.termin ? new Date(b.termin).getTime() : Infinity;
        if (ta !== tb) return ta - tb;
        return String(a.sno).localeCompare(String(b.sno), 'tr');
    });
}

function fasonTakipFiltreUygulaGruplar(gruplar) {
    const f = fasonTakipFiltre || {};
    const q = String(f.arama || '').trim().toLocaleLowerCase('tr-TR');
    const firmaF = String(f.firma || 'HEPSI');
    return (gruplar || []).filter(g => {
        if (firmaF !== 'HEPSI' && !String(g.fasonFirma).includes(firmaF)) return false;
        if (!q) return true;
        const blob = [g.sno, g.firma, g.fasonFirma, ...(g.kalemler || []).map(k => [k.kalemAd, k.renk, k.ebat].join(' '))].join(' ').toLocaleLowerCase('tr-TR');
        return blob.includes(q);
    });
}

function fasonTakipFiltreGuncelle(key, val) {
    if (!fasonTakipFiltre) fasonTakipFiltre = { arama: '', firma: 'HEPSI', siparisDurum: 'AKTIF' };
    fasonTakipFiltre[key] = val;
    saveUiState({ fasonTakipFiltre });
    if (key === 'arama') debounce('fason-takip-arama', () => fasonTakipListeYenile(), 200);
    else renderFasonTakip();
}

async function fasonTakipSiparisKdYukle(siparisId) {
    const sid = String(siparisId || '');
    if (!sid) return;
    await Promise.all([
        sbKdGet(sid, 'KD_URUN_AGACI', true),
        sbKdGet(sid, 'KD_KONFEKSIYON', true),
        sbKdGet(sid, 'KD_DOKUMA', true),
        sbKdGet(sid, 'KD_FASON_TAKIP', true)
    ]);
}

function fasonTakipKdKonfBirlestir(siparisId, kdKonf, ftKd) {
    const out = { ...(kdKonf || {}) };
    if (!ftKd || typeof ftKd !== 'object') return out;
    Object.entries(ftKd.kalem || {}).forEach(([idx, k]) => {
        const key = `kalem_${idx}`;
        if (!out[key]) out[key] = {};
        const kr = out[key];
        if (k.kesim_adet != null && k.kesim_adet !== '') kr.kesilen = fasonTakipInt(k.kesim_adet);
        if (k.dikim_adet != null && k.dikim_adet !== '') kr.dikilen = fasonTakipInt(k.dikim_adet);
        if (k.kalite_adet != null && k.kalite_adet !== '') kr.kk_gecen = fasonTakipInt(k.kalite_adet);
        if (k.yukleme_adet != null && k.yukleme_adet !== '') kr.kolide = fasonTakipInt(k.yukleme_adet);
        if (k.sevk_adet != null && k.sevk_adet !== '') kr.sevk_edilen = fasonTakipInt(k.sevk_adet);
    });
    (ftKd.aksesuar || []).forEach(a => {
        if (!a?.key) return;
        if (a.gonderilen != null && a.gonderilen !== '') out[`ak_${a.key}_gelen`] = fasonTakipInt(a.gonderilen);
        if (a.kullanilan != null && a.kullanilan !== '') out[`ak_${a.key}_kullanilan`] = fasonTakipInt(a.kullanilan);
    });
    if (ftKd.siparis_not) out.fason_takip_not = String(ftKd.siparis_not);
    out._fason_takip = ftKd;
    return out;
}

async function fasonTakipKonfSenkronizeEt(siparisId, draft) {
    if (!siparisId || !draft) return;
    const kdK = await sbKdGet(siparisId, 'KD_KONFEKSIYON', true);
    const kdD = await sbKdGet(siparisId, 'KD_DOKUMA', true);
    if (!kdD.urunler) kdD.urunler = {};
    Object.entries(draft.kalem || {}).forEach(([idx, k]) => {
        const key = `kalem_${idx}`;
        if (!kdK[key]) kdK[key] = {};
        const kr = kdK[key];
        if (k.kesim_adet != null && k.kesim_adet !== '') kr.kesilen = fasonTakipInt(k.kesim_adet);
        if (k.dikim_adet != null && k.dikim_adet !== '') kr.dikilen = fasonTakipInt(k.dikim_adet);
        if (k.kalite_adet != null && k.kalite_adet !== '') kr.kk_gecen = fasonTakipInt(k.kalite_adet);
        if (k.yukleme_adet != null && k.yukleme_adet !== '') kr.kolide = fasonTakipInt(k.yukleme_adet);
        if (k.sevk_adet != null && k.sevk_adet !== '') kr.sevk_edilen = fasonTakipInt(k.sevk_adet);
        const sevkMt = fasonTakipNum(k.kumas_sevk_metre, 2);
        if (sevkMt > 0) {
            const ui = parseInt(idx, 10);
            if (!kdD.urunler[ui]) kdD.urunler[ui] = {};
            if (!kdD.urunler[String(ui)]) kdD.urunler[String(ui)] = kdD.urunler[ui];
            kdD.urunler[ui].toplam_metre = sevkMt;
            kdD.urunler[String(ui)].toplam_metre = sevkMt;
        }
    });
    (draft.aksesuar || []).forEach(a => {
        if (!a?.key) return;
        if (a.gonderilen != null && a.gonderilen !== '') kdK[`ak_${a.key}_gelen`] = fasonTakipInt(a.gonderilen);
        if (a.kullanilan != null && a.kullanilan !== '') kdK[`ak_${a.key}_kullanilan`] = fasonTakipInt(a.kullanilan);
    });
    if (draft.siparis_not) kdK.fason_takip_not = String(draft.siparis_not);
    await sbKdSet(siparisId, 'KD_KONFEKSIYON', kdK);
    await sbKdSet(siparisId, 'KD_DOKUMA', kdD);
    _kdCache[`KD_KONFEKSIYON_${siparisId}`] = kdK;
    _kdCache[`KD_DOKUMA_${siparisId}`] = kdD;
}

function fasonTakipSiparisIncelemeAc(siparisId) {
    const sid = String(siparisId || '');
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === sid);
    if (!siparis) { erpToast('Sipariş bulunamadı.', 'error'); return; }
    appMode = 'SIPARIS_LISTE';
    currentData = [...(dataCache.siparisler || [])];
    const idx = currentData.findIndex(s => String(s.id) === sid);
    if (idx < 0) { erpToast('Sipariş listesinde görünmüyor.', 'error'); return; }
    showDetail(idx);
    queueMicrotask(() => siparisDetailModalSetTab('durum'));
}

async function fasonTakipToggleSiparis(siparisId) {
    const sid = String(siparisId || '');
    if (!sid) return;
    fasonTakipAcikSiparisId = (fasonTakipAcikSiparisId === sid) ? null : sid;
    if (fasonTakipAcikSiparisId) {
        await fasonTakipSiparisKdYukle(fasonTakipAcikSiparisId);
        fasonTakipDraftGet(fasonTakipAcikSiparisId);
    }
    saveUiState({ fasonTakipAcikSiparisId });
    fasonTakipListeYenile();
}

function fasonTakipAlanDegistir(siparisId, kalemIdx, alan, val) {
    const draft = fasonTakipDraftGet(siparisId);
    const key = String(kalemIdx);
    if (!draft.kalem[key]) draft.kalem[key] = fasonTakipKalemVarsayilan((dataCache.siparisler || []).find(s => String(s.id) === String(siparisId)), kalemIdx);
    const k = draft.kalem[key];
    if (['kumas_plan_metre', 'kumas_sevk_metre', 'elde_kalan_kumas_metre'].includes(alan)) {
        k[alan] = fasonTakipNum(val, 2);
    } else {
        k[alan] = fasonTakipInt(val);
    }
    if (['kesim_adet', 'yukleme_adet', 'dikim_adet', 'kalite_adet'].includes(alan)) {
        k.elde_kalan_adet = Math.max(0, fasonTakipInt(k.kesim_adet) - fasonTakipInt(k.yukleme_adet));
    }
    fasonTakipListeYenile();
}

function fasonTakipAksDegistir(siparisId, aksKey, alan, val) {
    const draft = fasonTakipDraftGet(siparisId);
    const row = (draft.aksesuar || []).find(a => a.key === aksKey);
    if (!row) return;
    row[alan] = fasonTakipNum(val, alan === 'birim' ? 2 : 0);
    fasonTakipListeYenile();
}

function fasonTakipNotDegistir(siparisId, val) {
    fasonTakipDraftGet(siparisId).siparis_not = String(val || '');
}

async function fasonTakipKaydet(siparisId) {
    if (!siparisId) return;
    const draft = fasonTakipDraftGet(siparisId);
    draft.guncelleme = new Date().toISOString();
    await sbKdSet(siparisId, 'KD_FASON_TAKIP', draft);
    _kdCache[`KD_FASON_TAKIP_${siparisId}`] = draft;
    await fasonTakipKonfSenkronizeEt(siparisId, draft);
    delete fasonTakipDraft[String(siparisId)];
    erpToast('Fason takip kaydedildi — sipariş incelemede görünür.', 'success');
    fasonTakipListeYenile();
}

async function fasonTakipKonfSenkron(siparisId) {
    if (!siparisId) return;
    await sbKdGet(siparisId, 'KD_KONFEKSIYON', true);
    await sbKdGet(siparisId, 'KD_DOKUMA', true);
    delete fasonTakipDraft[String(siparisId)];
    fasonTakipDraftGet(siparisId);
    erpToast('Konfeksiyon / dokuma verileri çekildi.', 'success');
    fasonTakipListeYenile();
}

async function fasonTakipSiparisKonfAc(siparisId) {
    if (!siparisId) return;
    konfeksiyonYerFiltresi = 'FASON_KONF';
    await setAppMode('KONFEKSIYON_KESIM');
    await konfSelectSiparis(siparisId);
}

function fasonTakipInp(siparisId, kalemIdx, alan, val, step, hedef, birimTip) {
    const sid = JSON.stringify(String(siparisId));
    const v = val === '' || val == null ? '' : val;
    const isMetre = birimTip === 'metre' || ['kumas_sevk_metre', 'elde_kalan_kumas_metre'].includes(alan);
    const durum = hedef != null && hedef !== '' ? fasonTakipHedefDurum(v, hedef, isMetre) : 'neutral';
    const renk = fasonTakipHedefRenkStil(durum);
    const birim = isMetre ? 'm' : 'adet';
    const title = hedef != null ? pdfEsc(fasonTakipHedefBaslik(hedef, birim)) : '';
    const base = 'padding:3px 5px;font-size:9px;text-align:right;min-width:54px;width:100%;height:26px;box-sizing:border-box';
    return `<input type="number" step="${step || '1'}" class="pro-input fason-takip-kalem-inp" style="${base};${renk}" value="${v}" title="${title}"
        oninput="this.style.cssText='${base};'+fasonTakipHedefRenkStil(fasonTakipHedefDurum(this.value,${hedef != null ? hedef : 0},${isMetre}))"
        onchange="fasonTakipAlanDegistir(${sid},${kalemIdx},'${alan}',this.value)">`;
}
function fasonTakipAksInp(sid, aksKey, alan, val, hedef) {
    const v = val === '' || val == null ? '' : val;
    const durum = fasonTakipHedefDurum(v, hedef, false);
    const renk = fasonTakipHedefRenkStil(durum);
    const base = 'padding:4px 6px;font-size:10px;text-align:right;width:100%;box-sizing:border-box';
    const title = pdfEsc(fasonTakipHedefBaslik(hedef, 'adet'));
    return `<input type="number" step="1" class="pro-input" style="${base};${renk}" value="${v}" title="${title}"
        oninput="this.style.cssText='${base};'+fasonTakipHedefRenkStil(fasonTakipHedefDurum(this.value,${hedef},false))"
        onchange="fasonTakipAksDegistir(${sid},'${aksKey}','${alan}',this.value)">`;
}

function fasonTakipDetayHtml(grup) {
    const sid = JSON.stringify(String(grup.siparisId));
    const draft = fasonTakipDraftGet(grup.siparisId);
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(grup.siparisId));
    const kalemler = siparis
        ? (grup.kalemler || []).map(k => fasonTakipKalemSatirOlustur(siparis, k.kalemIdx))
        : (grup.kalemler || []);
    const fmt = n => (parseInt(n, 10) || 0).toLocaleString('tr-TR');
    const fmtM = n => (parseFloat(n) || 0).toLocaleString('tr-TR', { maximumFractionDigits: 2 });

    const kalemScrollStyle = 'overflow:auto;max-height:min(52vh,480px);margin-bottom:14px;-webkit-overflow-scrolling:touch';

    const kalemTbl = kalemler.map(k => {
        const r = k.rec;
        return `<tr style="border-top:1px solid var(--border)">
            <td style="${fasonTakipTdStil('kalem')}">${fasonTakipKalemHucreHtml(k)}</td>
            <td style="${fasonTakipTdStil('sip', 'text-align:right;font-family:\'DM Mono\',monospace;font-size:10px')}">${fmt(k.miktar)}</td>
            <td style="${fasonTakipTdStil('plan_kumas', 'text-align:right;font-size:9px;color:var(--text3)')}">${fmtM(r.kumas_plan_metre)} m</td>
            <td style="${fasonTakipTdStil('sevk_kumas')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'kumas_sevk_metre', r.kumas_sevk_metre, '0.01', r.kumas_plan_metre, 'metre')}</td>
            <td style="${fasonTakipTdStil('kesim')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'kesim_adet', r.kesim_adet, '1', k.miktar)}</td>
            <td style="${fasonTakipTdStil('dikim')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'dikim_adet', r.dikim_adet, '1', k.miktar)}</td>
            <td style="${fasonTakipTdStil('kalite')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'kalite_adet', r.kalite_adet, '1', k.miktar)}</td>
            <td style="${fasonTakipTdStil('yukleme')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'yukleme_adet', r.yukleme_adet, '1', k.miktar)}</td>
            <td style="${fasonTakipTdStil('sevk')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'sevk_adet', r.sevk_adet, '1', k.miktar)}</td>
            <td style="${fasonTakipTdStil('elde_adet')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'elde_kalan_adet', r.elde_kalan_adet, '1', Math.max(0, fasonTakipInt(r.kesim_adet) - fasonTakipInt(r.yukleme_adet)))}</td>
            <td style="${fasonTakipTdStil('elde_kumas')}">${fasonTakipInp(grup.siparisId, k.kalemIdx, 'elde_kalan_kumas_metre', r.elde_kalan_kumas_metre, '0.01', Math.max(0, fasonTakipNum(r.kumas_plan_metre, 2) - fasonTakipNum(r.kumas_sevk_metre, 2)), 'metre')}</td>
            <td style="${fasonTakipTdStil('pct', 'text-align:center;font-size:9px')}">${k.pct}%</td>
        </tr>`;
    }).join('');

    const aksRows = (draft.aksesuar || []).map(a => {
        const plan = fasonTakipNum(a.plan_toplam, 1);
        const gon = fasonTakipInt(a.gonderilen);
        const kul = fasonTakipInt(a.kullanilan);
        const kalan = gon - kul;
        const warn = gon > 0 && kalan < 0;
        return `<tr style="border-top:1px solid var(--border)">
            <td style="padding:8px 10px;font-weight:600">${pdfEsc(a.ad)}</td>
            <td style="padding:8px 10px;text-align:right;font-family:'DM Mono',monospace">${fmtM(plan)}</td>
            <td style="padding:4px">${fasonTakipAksInp(sid, a.key, 'gonderilen', gon, plan)}</td>
            <td style="padding:4px">${fasonTakipAksInp(sid, a.key, 'kullanilan', kul, plan)}</td>
            <td style="padding:8px 10px;text-align:right;font-weight:700;color:${warn?'var(--rose-c)':'var(--emerald-c)'}">${fmt(kalan)}</td>
        </tr>`;
    }).join('') || `<tr><td colspan="5" style="padding:12px;color:var(--text3);text-align:center">Ürün ağacında aksesuar tanımı yok.</td></tr>`;

    return `<div style="padding:14px 16px;background:rgba(99,102,241,0.04);border-top:2px solid var(--amber-c)" onclick="event.stopPropagation()">
        <div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px">
            <button type="button" class="btn-pro btn-primary-pro" style="padding:6px 14px;font-size:10px" onclick="fasonTakipKaydet(${sid})">💾 Kaydet</button>
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:6px 14px;font-size:10px" onclick="fasonTakipKonfSenkron(${sid})">↻ Konf / dokuma çek</button>
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:6px 14px;font-size:10px" onclick="fasonTakipSiparisIncelemeAc(${sid})">🔍 Sipariş inceleme</button>
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:6px 14px;font-size:10px" onclick="fasonTakipSiparisKonfAc(${sid})">✂️ Konfeksiyon</button>
        </div>
        <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;font-family:'DM Mono',monospace">Kalem bazlı malzeme & üretim</div>
        <div style="${kalemScrollStyle}">
            <table class="dt-table" style="width:100%;min-width:960px;font-size:10px;border-collapse:separate;border-spacing:0">
                <thead><tr>
                    <th style="${fasonTakipThStil('kalem','left')}">Kalem</th>
                    <th style="${fasonTakipThStil('sip','right')}">Sip.</th>
                    <th style="${fasonTakipThStil('plan_kumas','right')}">Plan kumaş</th>
                    <th style="${fasonTakipThStil('sevk_kumas','right')}">Sevk kumaş (m)</th>
                    <th style="${fasonTakipThStil('kesim','right')}">Kesim</th>
                    <th style="${fasonTakipThStil('dikim','right')}">Dikim</th>
                    <th style="${fasonTakipThStil('kalite','right')}">Kalite</th>
                    <th style="${fasonTakipThStil('yukleme','right')}">Yükleme</th>
                    <th style="${fasonTakipThStil('sevk','right')}">Sevk</th>
                    <th style="${fasonTakipThStil('elde_adet','right')}">Elde adet</th>
                    <th style="${fasonTakipThStil('elde_kumas','right')}">Elde kumaş</th>
                    <th style="${fasonTakipThStil('pct','center')}">%</th>
                </tr></thead>
                <tbody>${kalemTbl}</tbody>
            </table>
        </div>
        <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;font-family:'DM Mono',monospace">Aksesuar (plan · gönderilen · kullanılan · kalan)</div>
        <div style="overflow:auto;margin-bottom:12px">
            <table class="dt-table" style="width:100%;min-width:520px;font-size:10px">
                <thead><tr style="font-size:8px;color:var(--text3);text-transform:uppercase;font-family:'DM Mono',monospace">
                    <th style="text-align:left;padding:6px">Aksesuar</th>
                    <th style="text-align:right;padding:6px">Plan (ürün ağacı)</th>
                    <th style="text-align:right;padding:6px">Gönderilen</th>
                    <th style="text-align:right;padding:6px">Kullanılan</th>
                    <th style="text-align:right;padding:6px">Kalan</th>
                </tr></thead>
                <tbody>${aksRows}</tbody>
            </table>
        </div>
        <label class="pro-label">Sipariş notu (fason)</label>
        <textarea class="pro-input" rows="2" style="font-size:11px" placeholder="Fason atölye / sevkiyat notları…"
            oninput="fasonTakipNotDegistir(${sid}, this.value)">${pdfEsc(draft.siparis_not || '')}</textarea>
    </div>`;
}

function fasonTakipFiltreliSiparisler() {
    const durumF = String(fasonTakipFiltre?.siparisDurum || 'AKTIF');
    let siparisler = (dataCache.siparisler || []).slice();
    if (durumF === 'AKTIF') siparisler = siparisler.filter(s => s.durum !== 'TAMAMLANDI');
    else if (durumF === 'TAMAMLANDI') siparisler = siparisler.filter(s => s.durum === 'TAMAMLANDI');
    return siparisler;
}

function fasonTakipListeYenile() {
    if (appMode !== 'FASON_TAKIP') return;
    const list = document.getElementById('main-list');
    if (!list) return;
    const siparisler = fasonTakipFiltreliSiparisler();
    const tumGruplar = fasonTakipSiparisGruplariOlustur(siparisler);
    const gruplar = fasonTakipFiltreUygulaGruplar(tumGruplar);
    const firmaSet = [...new Set(tumGruplar.map(g => g.fasonFirma).flatMap(f => String(f).split(' · ')).filter(f => f && f !== '—'))].sort((a, b) => a.localeCompare(b, 'tr'));
    const fmt = n => (parseInt(n, 10) || 0).toLocaleString('tr-TR');
    const topSip = gruplar.length;
    const topKalem = gruplar.reduce((a, g) => a + g.kalemSay, 0);
    const durumPill = (g) => g.tamam
        ? '<span class="pill pill-green" style="font-size:8px">Tamam</span>'
        : g.kismi
            ? '<span class="pill pill-amber" style="font-size:8px">Kısmi</span>'
            : '<span class="pill pill-gray" style="font-size:8px">Bekliyor</span>';
    const listeHtml = gruplar.length ? gruplar.map(g => {
        const sidAttr = pdfEsc(String(g.siparisId));
        const acik = String(fasonTakipAcikSiparisId) === String(g.siparisId);
        return `<div class="panel-box" style="margin-bottom:8px;overflow:hidden;border:1px solid ${acik ? 'rgba(245,158,11,0.45)' : 'var(--border)'}">
            <div role="button" tabindex="0" data-siparis-id="${sidAttr}" style="display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer;background:${acik ? 'rgba(245,158,11,0.08)' : 'var(--surface)'};user-select:none"
                onclick="fasonTakipToggleSiparis(this.getAttribute('data-siparis-id'))">
                <span style="font-size:14px;color:var(--amber-c);width:20px">${acik ? '▼' : '▶'}</span>
                <div style="flex:1;min-width:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:8px;align-items:center">
                    <div><div style="font-family:'DM Mono',monospace;font-weight:700;color:var(--accent)">${pdfEsc(g.sno)}</div><div style="font-size:10px;color:var(--text2)">${pdfEsc(g.firma)}</div></div>
                    <div style="font-size:10px;color:var(--amber-c);font-weight:600">${pdfEsc(g.fasonFirma)}</div>
                    <div style="font-size:10px;font-family:'DM Mono',monospace">${g.kalemSay} kalem · ${fmt(g.topAdet)} adet</div>
                    <div style="font-size:10px">Sevk: <b>${g.pct}%</b> (${fmt(g.topSevk)})</div>
                    <div>${durumPill(g)}</div>
                    <div style="font-size:10px;color:var(--text3)">${g.termin ? new Date(g.termin).toLocaleDateString('tr-TR') : '—'}</div>
                </div>
            </div>
            ${acik ? fasonTakipDetayHtml(g) : ''}
        </div>`;
    }).join('') : `<div class="empty-pro" style="padding:40px"><div class="empty-pro-icon">🏭</div><div class="empty-pro-title">Fason sipariş yok</div><div class="empty-pro-sub">Ürün ağacında fason konfeksiyon seçili kalem bulunamadı.</div></div>`;
    list.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px">
        <div class="panel-box" style="padding:14px 16px;border-left:3px solid var(--amber-c)">
            <div style="font-size:10px;font-weight:800;color:var(--text);text-transform:uppercase;letter-spacing:0.06em">Fason Takip — Sipariş bazlı</div>
            <div style="font-size:9px;color:var(--text3);margin-top:6px;line-height:1.5">Sipariş satırına tıklayın: detay ve veri girişi açılır. <b>Kaydet</b> ile veriler sipariş inceleme ekranına da yansır.</div>
        </div>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
            <div class="panel-box" style="padding:12px 14px"><div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">SİPARİŞ</div><div style="font-size:22px;font-weight:700;color:var(--amber-c);margin-top:4px">${fmt(topSip)}</div></div>
            <div class="panel-box" style="padding:12px 14px"><div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">FASON KALEM</div><div style="font-size:22px;font-weight:700;color:var(--accent);margin-top:4px">${fmt(topKalem)}</div></div>
            <div class="panel-box" style="padding:12px 14px"><div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">LİSTEDE</div><div style="font-size:22px;font-weight:700;color:var(--text);margin-top:4px">${fmt(gruplar.length)}</div></div>
        </div>
        <div class="panel-box" style="padding:12px 16px">
            <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center">
                <input class="pro-input" placeholder="Ara: sipariş, firma, fason…" value="${pdfEsc(fasonTakipFiltre?.arama || '')}"
                    oninput="fasonTakipFiltreGuncelle('arama', this.value)" style="min-width:200px;flex:1;max-width:320px;padding:6px 10px">
                <select class="pro-input" onchange="fasonTakipFiltreGuncelle('firma', this.value)" style="min-width:160px;width:auto;padding:6px 10px">
                    <option value="HEPSI" ${fasonTakipFiltre?.firma==='HEPSI'?'selected':''}>Tüm fason firmalar</option>
                    ${firmaSet.map(f => `<option value="${pdfEsc(f)}" ${fasonTakipFiltre?.firma===f?'selected':''}>${pdfEsc(f)}</option>`).join('')}
                </select>
                <select class="pro-input" onchange="fasonTakipFiltreGuncelle('siparisDurum', this.value)" style="min-width:130px;width:auto;padding:6px 10px">
                    <option value="AKTIF" ${fasonTakipFiltre?.siparisDurum==='AKTIF'?'selected':''}>Aktif siparişler</option>
                    <option value="TAMAMLANDI" ${fasonTakipFiltre?.siparisDurum==='TAMAMLANDI'?'selected':''}>Tamamlanan</option>
                    <option value="HEPSI" ${fasonTakipFiltre?.siparisDurum==='HEPSI'?'selected':''}>Tümü</option>
                </select>
            </div>
        </div>
        ${listeHtml}
    </div>`;
}

async function renderFasonTakip() {
    if (appMode !== 'FASON_TAKIP') return;
    const list = document.getElementById('main-list');
    if (!list) return;
    const gen = ++_fasonTakipRenderGen;
    if (!(list.innerHTML || '').trim()) {
        list.innerHTML = `<div class="panel-box" style="padding:40px 20px;text-align:center;color:var(--text3)"><div style="font-size:28px;margin-bottom:8px">⏳</div><div style="font-size:13px;font-weight:600">Fason işler yükleniyor…</div></div>`;
    }
    const siparisler = fasonTakipFiltreliSiparisler();
    const eksik = siparisler.filter(s =>
        _kdCache[`KD_URUN_AGACI_${s.id}`] === undefined ||
        _kdCache[`KD_KONFEKSIYON_${s.id}`] === undefined ||
        _kdCache[`KD_DOKUMA_${s.id}`] === undefined ||
        _kdCache[`KD_FASON_TAKIP_${s.id}`] === undefined
    );
    if (eksik.length) {
        try {
            await Promise.all(eksik.flatMap(s => [
                sbKdGet(s.id, 'KD_URUN_AGACI', true),
                sbKdGet(s.id, 'KD_KONFEKSIYON', true),
                sbKdGet(s.id, 'KD_DOKUMA', true),
                sbKdGet(s.id, 'KD_FASON_TAKIP', true)
            ]));
        } catch (e) {}
    }
    if (gen !== _fasonTakipRenderGen) return;
    _fasonTakipKdHazir = true;
    if (fasonTakipAcikSiparisId) fasonTakipDraftGet(fasonTakipAcikSiparisId);
    fasonTakipListeYenile();
}

// ── DOKUMA FASON — kendi başına, ayrı tabloda dokuma sipariş kayıtları ──
// Müşteri siparişinin (`siparisler` tablosu) kalemlerine hiç dokunmaz — ayrı
// bir tabloda (dokuma_fason_siparisleri) yaşar, bu yüzden hiçbir sipariş
// listesini/picker'ını etkilemez. Bir dokuma işi ("23.000 metre müslin
// fason dokunacak" gibi) Dokuma Sipariş Formu'ndan tek kalem olarak girilir.
let dokumaFasonAcikSiparisId = null;
let dokumaFasonDraft = {};
let dokumaSiparisEditId = null;
let _dokumaFasonYuklendi = false;

async function dokumaFasonSiparisleriYukle(force) {
    if (_dokumaFasonYuklendi && !force) return;
    try {
        if (typeof sb === 'undefined' || !sb?.from) return;
        const { data, error } = await sb.from('dokuma_fason_siparisleri').select('*').order('created_at', { ascending: false });
        if (error) throw error;
        dataCache.dokumaFasonSiparisleri = data || [];
        _dokumaFasonYuklendi = true;
    } catch (e) {
        console.error('dokumaFasonSiparisleriYukle', e);
        if (!dataCache.dokumaFasonSiparisleri) dataCache.dokumaFasonSiparisleri = [];
    }
}

function dokumaFasonKayitlari() {
    const durumF = dokumaFasonFiltre?.siparisDurum || 'AKTIF';
    let list = (dataCache.dokumaFasonSiparisleri || []).slice();
    if (durumF === 'AKTIF') list = list.filter(s => s.durum !== 'TAMAMLANDI');
    else if (durumF === 'TAMAMLANDI') list = list.filter(s => s.durum === 'TAMAMLANDI');
    return list.sort((a, b) => {
        const ta = a.ttarih ? new Date(a.ttarih).getTime() : Infinity;
        const tb = b.ttarih ? new Date(b.ttarih).getTime() : Infinity;
        if (ta !== tb) return ta - tb;
        return String(a.sno || '').localeCompare(String(b.sno || ''), 'tr');
    });
}

function dokumaFasonVarsayilan() {
    return {
        hasil_giden_iplik_kg: 0,
        hasil_gelen_iplik_kg: 0,
        levent_cozulen_m: 0,
        dokunan_m: 0,
        dokunan_harcanan_iplik_kg: 0
    };
}

/** İplik metre/kg oranı — Ne (İngiliz numarası) ya da Nm (Metrik numara). */
function dokumaFasonIplikMetrePerKg(sistem, ipNo) {
    const no = parseFloat(ipNo) || 0;
    if (no <= 0) return 0;
    // Ne (İngiliz no): fabrikanın kendi Excel'iyle birebir eşleşen sabit — Gramaj = Sayı*60/İpNo*.../100000
    // formülünden geriye çözüldü: 1 Ne = 100000/60 ≈ 1666,67 m/kg (ders kitabı 840yd/lb değeri 1693,98 değil).
    return (String(sistem || 'NE').toUpperCase() === 'NM') ? no * 1000 : no * (100000 / 60);
}

/** Kumaş metrajı + teknik özelliklerden çözgü/atkı ipliği ihtiyacını hesaplar. */
function dokumaFasonHesapla(spec) {
    const metre = parseFloat(spec.metre) || 0;
    const cozguFireOrani = (parseFloat(spec.cozgu_fire_payi) || 0) / 100;
    const atkiFireOrani = (parseFloat(spec.atki_fire_payi) || 0) / 100;

    const cozguUzunlukM = metre * (1 + cozguFireOrani);
    const cozguTel = parseFloat(spec.cozgu_tel_sayisi) || 0;
    const toplamCozguM = cozguTel * cozguUzunlukM;
    const cozguMPerKg = dokumaFasonIplikMetrePerKg(spec.ip_no_sistemi, spec.cozgu_ip_no);
    const cozguKg = cozguMPerKg > 0 ? toplamCozguM / cozguMPerKg : 0;

    const atkiSiklik = parseFloat(spec.atki_sikligi) || 0;
    const tarakEniM = parseFloat(spec.tarak_eni_m) || 0;
    const toplamAtkiSayisiHam = atkiSiklik * metre * 100;
    const toplamAtkiM = toplamAtkiSayisiHam * tarakEniM * (1 + atkiFireOrani);
    const atkiMPerKg = dokumaFasonIplikMetrePerKg(spec.ip_no_sistemi, spec.atki_ip_no);
    const atkiKg = atkiMPerKg > 0 ? toplamAtkiM / atkiMPerKg : 0;

    return { cozguUzunlukM, cozguKg, atkiKg, toplamKg: cozguKg + atkiKg };
}

function dokumaFasonDraftGet(siparisId) {
    const sid = String(siparisId);
    if (!dokumaFasonDraft[sid]) {
        const rec = (dataCache.dokumaFasonSiparisleri || []).find(s => String(s.id) === sid) || {};
        dokumaFasonDraft[sid] = { ...dokumaFasonVarsayilan(), ...rec };
    }
    return dokumaFasonDraft[sid];
}

function dokumaFasonAlanDegistir(siparisId, alan, val) {
    const draft = dokumaFasonDraftGet(siparisId);
    draft[alan] = parseFloat(val) || 0;
}

function dokumaFasonFiltreGuncelle(key, val) {
    if (!dokumaFasonFiltre) dokumaFasonFiltre = { arama: '', firma: 'HEPSI', siparisDurum: 'AKTIF' };
    dokumaFasonFiltre[key] = val;
    if (key === 'arama') debounce('dokuma-fason-arama', () => dokumaFasonListeYenile(), 200);
    else dokumaFasonListeYenile();
}

function dokumaFasonToggleSiparis(siparisId) {
    const sid = String(siparisId || '');
    if (!sid) return;
    dokumaFasonAcikSiparisId = (dokumaFasonAcikSiparisId === sid) ? null : sid;
    if (dokumaFasonAcikSiparisId) dokumaFasonDraftGet(dokumaFasonAcikSiparisId);
    dokumaFasonListeYenile();
}

async function dokumaFasonKaydet(siparisId) {
    if (!siparisId) return;
    const draft = dokumaFasonDraftGet(siparisId);
    const patch = {
        iplik_ihtiyaci_kg: draft.iplik_ihtiyaci_kg || 0,
        cozgu_ihtiyaci_m: draft.cozgu_ihtiyaci_m || 0,
        hasil_giden_iplik_kg: draft.hasil_giden_iplik_kg || 0,
        hasil_gelen_iplik_kg: draft.hasil_gelen_iplik_kg || 0,
        levent_cozulen_m: draft.levent_cozulen_m || 0,
        dokunan_m: draft.dokunan_m || 0,
        dokunan_harcanan_iplik_kg: draft.dokunan_harcanan_iplik_kg || 0,
        updated_at: new Date().toISOString()
    };
    try {
        if (typeof sb === 'undefined' || !sb?.from) throw new Error('Bağlantı yok');
        const { error } = await sb.from('dokuma_fason_siparisleri').update(patch).eq('id', siparisId);
        if (error) throw error;
        const idx = (dataCache.dokumaFasonSiparisleri || []).findIndex(s => String(s.id) === String(siparisId));
        if (idx >= 0) Object.assign(dataCache.dokumaFasonSiparisleri[idx], patch);
        erpToast('Dokuma bilgileri kaydedildi.', 'success');
        dokumaFasonListeYenile();
    } catch (e) {
        erpToast('Kaydedilemedi: ' + (e?.message || e), 'error');
    }
}

function dokumaSiparisYeniAc() {
    dokumaSiparisEditId = null;
    setAppMode('DOKUMA_SIPARIS_GIRIS');
}

function dokumaSiparisDuzenle(siparisId) {
    dokumaSiparisEditId = String(siparisId);
    setAppMode('DOKUMA_SIPARIS_GIRIS');
}

function dokumaFasonDetayHtml(siparis) {
    const sid = JSON.stringify(String(siparis.id));
    const r = dokumaFasonDraftGet(siparis.id);
    const fmt = (n) => (parseFloat(n) || 0).toLocaleString('tr-TR', { maximumFractionDigits: 1 });
    const alan = (key, label, val, renk) => `<div>
        <label class="pro-label" style="${renk ? `color:${renk}` : ''}">${label}</label>
        <input type="number" step="0.1" min="0" class="pro-input" value="${val || ''}" onchange="dokumaFasonAlanDegistir(${sid},'${key}',this.value)">
    </div>`;
    const tile = (label, val, renk) => `<div class="panel-box" style="padding:10px 12px;text-align:center">
        <div style="font-size:8px;color:var(--text3)">${label}</div>
        <div style="font-size:16px;font-weight:700;color:${renk || 'var(--text)'}">${fmt(val)} kg</div>
    </div>`;
    const hesapVar = (parseFloat(siparis.cozgu_ipligi_kg) || 0) > 0 || (parseFloat(siparis.atki_ipligi_kg) || 0) > 0;
    const hasilHedef = parseFloat(siparis.cozgu_ipligi_kg) || 0;
    const hasilSevk = parseFloat(r.hasil_giden_iplik_kg) || 0;
    const hasilGelen = parseFloat(r.hasil_gelen_iplik_kg) || 0;
    const hasilBekleyen = Math.max(0, hasilSevk - hasilGelen);
    return `<div style="padding:14px 16px;background:rgba(99,102,241,0.04);border-top:2px solid var(--amber-c)" onclick="event.stopPropagation()">
        <div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px">
            <button type="button" class="btn-pro btn-primary-pro" style="padding:6px 14px;font-size:10px" onclick="dokumaFasonKaydet(${sid})">💾 Kaydet</button>
            <button type="button" class="btn-pro btn-ghost-pro" style="padding:6px 14px;font-size:10px" onclick="dokumaSiparisDuzenle(${sid})">✎ Siparişi düzenle (teknik özellikler)</button>
        </div>
        ${hesapVar ? `
        <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;font-family:'DM Mono',monospace">Hesaplanan ihtiyaç (teknik özelliklerden)</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin-bottom:16px">
            <div class="panel-box" style="padding:10px 12px;text-align:center"><div style="font-size:8px;color:var(--text3)">Çözgü uzunluğu</div><div style="font-size:16px;font-weight:700;color:var(--text)">${fmt(siparis.cozgu_ihtiyaci_m)} m</div></div>
            <div class="panel-box" style="padding:10px 12px;text-align:center"><div style="font-size:8px;color:var(--text3)">Çözgü ipliği</div><div style="font-size:16px;font-weight:700;color:var(--accent)">${fmt(siparis.cozgu_ipligi_kg)} kg</div></div>
            <div class="panel-box" style="padding:10px 12px;text-align:center"><div style="font-size:8px;color:var(--text3)">Atkı ipliği</div><div style="font-size:16px;font-weight:700;color:var(--accent)">${fmt(siparis.atki_ipligi_kg)} kg</div></div>
            <div class="panel-box" style="padding:10px 12px;text-align:center;background:rgba(245,158,11,0.08)"><div style="font-size:8px;color:var(--text3)">Toplam iplik</div><div style="font-size:16px;font-weight:700;color:var(--amber-c)">${fmt((parseFloat(siparis.cozgu_ipligi_kg)||0)+(parseFloat(siparis.atki_ipligi_kg)||0))} kg</div></div>
        </div>
        ` : `<div style="padding:10px 12px;border:1px dashed var(--border);border-radius:10px;font-size:10px;color:var(--text3);margin-bottom:16px">Teknik özellikler (sıklık/ip no/tarak eni) girilmemiş — "Siparişi düzenle" ile ekleyin, ihtiyaç otomatik hesaplansın.</div>`}
        <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;font-family:'DM Mono',monospace">🧶 Haşıl takibi (çözgü ipliği)</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin-bottom:16px">
            ${tile('Hedef', hasilHedef, 'var(--accent)')}
            ${alan('hasil_giden_iplik_kg', 'Haşıla sevk edilen (kg)', r.hasil_giden_iplik_kg, 'var(--amber-c)')}
            ${alan('hasil_gelen_iplik_kg', 'Haşıldan gelen (kg)', r.hasil_gelen_iplik_kg, 'var(--emerald-c)')}
            ${tile('Haşılda bekleyen', hasilBekleyen, 'var(--violet-c)')}
        </div>
        <div style="font-size:9px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;font-family:'DM Mono',monospace">🧵 Dokuma ilerlemesi (elle)</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px">
            ${alan('levent_cozulen_m', 'Levent çözülen (m)', r.levent_cozulen_m)}
            ${alan('dokunan_m', 'Dokunan (m)', r.dokunan_m)}
            ${alan('dokunan_harcanan_iplik_kg', 'Dokunan için harcanan iplik (kg)', r.dokunan_harcanan_iplik_kg)}
        </div>
    </div>`;
}

function dokumaFasonListeYenile() {
    if (appMode !== 'DOKUMA_FASON_TAKIP') return;
    const list = document.getElementById('main-list');
    if (!list) return;
    const kayitlar = dokumaFasonKayitlari();
    const f = dokumaFasonFiltre || {};
    const q = String(f.arama || '').trim().toLocaleLowerCase('tr-TR');
    const firmaSet = [...new Set(kayitlar.map(s => String(s.dokuma_fason_firma || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'tr'));
    const filtreli = kayitlar.filter(s => {
        if (f.firma && f.firma !== 'HEPSI' && String(s.dokuma_fason_firma || '') !== f.firma) return false;
        if (!q) return true;
        const hay = [s.sno, s.hangi_is, s.dokuma_fason_firma, s.kumas_adi, s.notlar].join(' ').toLocaleLowerCase('tr-TR');
        return hay.includes(q);
    });
    const fmt = (n) => (parseFloat(n) || 0).toLocaleString('tr-TR', { maximumFractionDigits: 1 });
    const toplamMetre = filtreli.reduce((a, s) => a + (parseFloat(s.metre) || 0), 0);
    const listeHtml = filtreli.length ? filtreli.map(s => {
        const sidAttr = pdfEsc(String(s.id));
        const acik = String(dokumaFasonAcikSiparisId) === String(s.id);
        const fasonMi = String(s.dokuma_uretim_yeri || '').toUpperCase() === 'FASON_DOKUMA';
        return `<div class="panel-box" style="margin-bottom:8px;overflow:hidden;border:1px solid ${acik ? 'rgba(245,158,11,0.45)' : 'var(--border)'}">
            <div role="button" tabindex="0" data-siparis-id="${sidAttr}" style="display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer;background:${acik ? 'rgba(245,158,11,0.08)' : 'var(--surface)'};user-select:none"
                onclick="dokumaFasonToggleSiparis(this.getAttribute('data-siparis-id'))">
                <span style="font-size:14px;color:var(--amber-c);width:20px">${acik ? '▼' : '▶'}</span>
                <div style="flex:1;min-width:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;align-items:center">
                    <div><div style="font-family:'DM Mono',monospace;font-weight:700;color:var(--accent)">${pdfEsc(s.sno || '—')}</div><div style="font-size:10px;color:var(--text2)">${pdfEsc(s.kumas_adi)}</div></div>
                    <div style="font-size:10px;font-family:'DM Mono',monospace;font-weight:700">${fmt(s.metre)} m</div>
                    <div style="font-size:10px;color:var(--amber-c);font-weight:600">${fasonMi ? pdfEsc(s.dokuma_fason_firma || '—') : 'Simteks Dokuma'}</div>
                    <div style="font-size:10px;color:var(--text2)">${pdfEsc(s.hangi_is || '—')}</div>
                    <div style="font-size:10px;color:var(--text3)">${s.ttarih ? new Date(s.ttarih).toLocaleDateString('tr-TR') : '—'}</div>
                </div>
            </div>
            ${acik ? dokumaFasonDetayHtml(s) : ''}
        </div>`;
    }).join('') : `<div class="empty-pro" style="padding:40px"><div class="empty-pro-icon">🧶</div><div class="empty-pro-title">Dokuma siparişi yok</div><div class="empty-pro-sub">"+ Yeni Dokuma Siparişi" ile ilk kaydı oluşturun.</div></div>`;
    list.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px">
        <div class="panel-box" style="padding:14px 16px;border-left:3px solid var(--amber-c);display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px">
            <div>
                <div style="font-size:10px;font-weight:800;color:var(--text);text-transform:uppercase;letter-spacing:0.06em">Dokuma Fason</div>
                <div style="font-size:9px;color:var(--text3);margin-top:6px;line-height:1.5">Her satır kendi başına bir dokuma siparişi (tek kalem, metre bazlı) — müşteri sipariş kalemlerinden bağımsız, ayrı tabloda tutulur. Satıra tıklayın: iplik/çözgü/haşıl/levent/dokunan ilerlemesini girin.</div>
            </div>
            <button type="button" class="btn-pro btn-primary-pro" style="padding:8px 16px;font-size:11px;white-space:nowrap" onclick="dokumaSiparisYeniAc()">＋ Yeni Dokuma Siparişi</button>
        </div>
        <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
            <div class="panel-box" style="padding:12px 14px"><div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">DOKUMA SİPARİŞİ</div><div style="font-size:22px;font-weight:700;color:var(--amber-c);margin-top:4px">${filtreli.length}</div></div>
            <div class="panel-box" style="padding:12px 14px"><div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">TOPLAM METRE</div><div style="font-size:22px;font-weight:700;color:var(--accent);margin-top:4px">${fmt(toplamMetre)}</div></div>
        </div>
        <div class="panel-box" style="padding:12px 16px">
            <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center">
                <input class="pro-input" placeholder="Ara: sipariş no, kumaş, firma…" value="${pdfEsc(dokumaFasonFiltre?.arama || '')}"
                    oninput="dokumaFasonFiltreGuncelle('arama', this.value)" style="min-width:200px;flex:1;max-width:320px;padding:6px 10px">
                <select class="pro-input" onchange="dokumaFasonFiltreGuncelle('firma', this.value)" style="min-width:160px;width:auto;padding:6px 10px">
                    <option value="HEPSI" ${dokumaFasonFiltre?.firma==='HEPSI'?'selected':''}>Tüm fason firmalar</option>
                    ${firmaSet.map(fv => `<option value="${pdfEsc(fv)}" ${dokumaFasonFiltre?.firma===fv?'selected':''}>${pdfEsc(fv)}</option>`).join('')}
                </select>
                <select class="pro-input" onchange="dokumaFasonFiltreGuncelle('siparisDurum', this.value)" style="min-width:130px;width:auto;padding:6px 10px">
                    <option value="AKTIF" ${dokumaFasonFiltre?.siparisDurum==='AKTIF'?'selected':''}>Aktif siparişler</option>
                    <option value="TAMAMLANDI" ${dokumaFasonFiltre?.siparisDurum==='TAMAMLANDI'?'selected':''}>Tamamlanan</option>
                    <option value="HEPSI" ${dokumaFasonFiltre?.siparisDurum==='HEPSI'?'selected':''}>Tümü</option>
                </select>
            </div>
        </div>
        ${listeHtml}
    </div>`;
}

async function renderDokumaFasonTakip() {
    if (appMode !== 'DOKUMA_FASON_TAKIP') return;
    const list = document.getElementById('main-list');
    if (!list) return;
    if (!(list.innerHTML || '').trim()) {
        list.innerHTML = `<div class="panel-box" style="padding:40px 20px;text-align:center;color:var(--text3)"><div style="font-size:28px;margin-bottom:8px">⏳</div><div style="font-size:13px;font-weight:600">Dokuma fason siparişleri yükleniyor…</div></div>`;
    }
    await dokumaFasonSiparisleriYukle();
    if (appMode !== 'DOKUMA_FASON_TAKIP') return;
    dokumaFasonListeYenile();
}

// ── Dokuma Sipariş Formu — yeni dokuma siparişi girişi/düzenlemesi ──
function dokumaSiparisYeriDegisti() {
    const fasonSecili = !!document.getElementById('dsp-yer-fason')?.checked;
    const wrap = document.getElementById('dsp-fason-firma-wrap');
    if (wrap) wrap.style.display = fasonSecili ? '' : 'none';
}

function renderDokumaSiparisGiris() {
    const list = document.getElementById('main-list');
    if (!list) return;
    const editing = dokumaSiparisEditId ? (dataCache.dokumaFasonSiparisleri || []).find(s => String(s.id) === String(dokumaSiparisEditId)) : null;
    const fasonMi = String(editing?.dokuma_uretim_yeri || '').toUpperCase() === 'FASON_DOKUMA';
    list.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px;max-width:640px">
        <div class="panel-box" style="padding:20px">
            <div style="font-size:9px;font-weight:700;color:var(--amber-c);text-transform:uppercase;letter-spacing:0.08em;font-family:'DM Mono',monospace;margin-bottom:16px">${editing ? '✎ Dokuma Siparişini Düzenle' : '＋ Yeni Dokuma Siparişi'}</div>

            <div class="field-req" style="margin-bottom:14px">
                <label class="pro-label" style="color:var(--accent)">KUMAŞ TÜRÜ / AÇIKLAMA <span class="req-star">★</span></label>
                <input id="dsp-kumas-ad" class="pro-input" placeholder="Örn. 4 Kat Müslin" value="${pdfEsc(editing?.kumas_adi || '')}" autofocus>
            </div>
            <div class="field-req" style="margin-bottom:14px">
                <label class="pro-label" style="color:var(--accent)">TOPLAM METRE İHTİYACI <span class="req-star">★</span></label>
                <input id="dsp-metre" type="number" min="0" step="0.1" class="pro-input" placeholder="Örn. 23000" value="${editing?.metre || ''}" oninput="dokumaSiparisHesaplaGuncelle()">
            </div>

            <div style="padding:14px;border:1px solid var(--border);border-radius:10px;background:var(--surface2);margin-bottom:14px">
                <div style="font-size:9px;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:0.06em;font-family:'DM Mono',monospace;margin-bottom:10px">Teknik özellikler <span style="font-weight:400;color:var(--text3);text-transform:none;letter-spacing:0">— doğru hesap için gerekli</span></div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
                    <div><label class="pro-label">Çözgü sıklığı (tel/cm)</label><input id="dsp-cozgu-sikligi" type="number" min="0" step="0.1" class="pro-input" value="${editing?.cozgu_sikligi || ''}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                    <div><label class="pro-label">Atkı sıklığı (atkı/cm)</label><input id="dsp-atki-sikligi" type="number" min="0" step="0.1" class="pro-input" value="${editing?.atki_sikligi || ''}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                    <div><label class="pro-label">Çözgü tel sayısı (toplam)</label><input id="dsp-cozgu-tel" type="number" min="0" step="1" class="pro-input" value="${editing?.cozgu_tel_sayisi || ''}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                    <div><label class="pro-label">Tarak eni / pis kenar (m)</label><input id="dsp-tarak-eni" type="number" min="0" step="0.01" class="pro-input" value="${editing?.tarak_eni_m || ''}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:10px">
                    <div><label class="pro-label">İplik no sistemi</label>
                        <select id="dsp-ip-sistemi" class="pro-input" onchange="dokumaSiparisHesaplaGuncelle()">
                            <option value="NE" ${(editing?.ip_no_sistemi || 'NE') === 'NE' ? 'selected' : ''}>Ne (İngiliz no)</option>
                            <option value="NM" ${editing?.ip_no_sistemi === 'NM' ? 'selected' : ''}>Nm (Metrik no)</option>
                        </select>
                    </div>
                    <div><label class="pro-label">Çözgü ip no</label><input id="dsp-cozgu-ipno" type="number" min="0" step="1" class="pro-input" value="${editing?.cozgu_ip_no || ''}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                    <div><label class="pro-label">Atkı ip no</label><input id="dsp-atki-ipno" type="number" min="0" step="1" class="pro-input" value="${editing?.atki_ip_no || ''}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px;max-width:340px">
                    <div><label class="pro-label">Çözgü firesi (%)</label>
                        <input id="dsp-cozgu-fire" type="number" min="0" step="0.5" class="pro-input" value="${editing?.cozgu_fire_payi ?? 10}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                    <div><label class="pro-label">Atkı firesi (%)</label>
                        <input id="dsp-atki-fire" type="number" min="0" step="0.5" class="pro-input" value="${editing?.atki_fire_payi ?? 3}" oninput="dokumaSiparisHesaplaGuncelle()"></div>
                </div>
                <div id="dsp-hesap-sonuc" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;padding-top:10px;border-top:1px dashed var(--border)"></div>
            </div>

            <div style="margin-bottom:14px">
                <label class="pro-label">DOKUMA YERİ</label>
                <div style="display:flex;gap:14px;padding-top:6px">
                    <label style="display:flex;align-items:center;gap:6px;font-size:11px;cursor:pointer">
                        <input type="radio" name="dsp-yer" id="dsp-yer-simteks" ${!fasonMi ? 'checked' : ''} onchange="dokumaSiparisYeriDegisti()" style="accent-color:var(--accent2)"> Simteks Dokuma
                    </label>
                    <label style="display:flex;align-items:center;gap:6px;font-size:11px;cursor:pointer">
                        <input type="radio" name="dsp-yer" id="dsp-yer-fason" ${fasonMi ? 'checked' : ''} onchange="dokumaSiparisYeriDegisti()" style="accent-color:var(--accent2)"> Fason Dokuma
                    </label>
                </div>
                <div id="dsp-fason-firma-wrap" style="${fasonMi ? '' : 'display:none'};margin-top:10px">
                    <label class="pro-label">Fason dokumacı firma</label>
                    <input id="dsp-fason-firma" class="pro-input" placeholder="Hangi dokumacıda dokunuyor" value="${pdfEsc(editing?.dokuma_fason_firma || '')}">
                </div>
            </div>
            <div style="margin-bottom:14px">
                <label class="pro-label">HANGİ İŞ / MÜŞTERİ SİPARİŞİ İÇİN</label>
                <input id="dsp-hangi-is" class="pro-input" placeholder="Örn. SP650 — Dormeo" value="${pdfEsc(editing?.hangi_is || '')}">
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px">
                <div>
                    <label class="pro-label">SİPARİŞ TARİHİ</label>
                    <input id="dsp-starih" type="date" class="pro-input" value="${editing?.starih || new Date().toISOString().slice(0, 10)}">
                </div>
                <div>
                    <label class="pro-label" style="color:var(--rose-c)">TERMİN</label>
                    <input id="dsp-ttarih" type="date" class="pro-input" value="${editing?.ttarih || ''}">
                </div>
            </div>
            <div style="margin-bottom:18px">
                <label class="pro-label">NOT</label>
                <textarea id="dsp-not" class="pro-input" rows="2" placeholder="Ek not…">${pdfEsc(editing?.notlar || '')}</textarea>
            </div>
            <div style="display:flex;gap:8px">
                <button type="button" onclick="dokumaSiparisKaydet()" class="btn-pro btn-primary-pro" style="flex:1;justify-content:center;padding:10px">${editing ? 'Güncelle' : 'Kaydet'}</button>
                <button type="button" onclick="setAppMode('DOKUMA_FASON_TAKIP')" class="btn-pro btn-ghost-pro" style="padding:10px 18px">İptal</button>
            </div>
        </div>
    </div>`;
    dokumaSiparisHesaplaGuncelle();
}

function dokumaSiparisFormDegerleriniOku() {
    return {
        metre: document.getElementById('dsp-metre')?.value,
        cozgu_tel_sayisi: document.getElementById('dsp-cozgu-tel')?.value,
        atki_sikligi: document.getElementById('dsp-atki-sikligi')?.value,
        tarak_eni_m: document.getElementById('dsp-tarak-eni')?.value,
        ip_no_sistemi: document.getElementById('dsp-ip-sistemi')?.value,
        cozgu_ip_no: document.getElementById('dsp-cozgu-ipno')?.value,
        atki_ip_no: document.getElementById('dsp-atki-ipno')?.value,
        cozgu_fire_payi: document.getElementById('dsp-cozgu-fire')?.value,
        atki_fire_payi: document.getElementById('dsp-atki-fire')?.value
    };
}

function dokumaSiparisHesaplaGuncelle() {
    const kutu = document.getElementById('dsp-hesap-sonuc');
    if (!kutu) return;
    const spec = dokumaSiparisFormDegerleriniOku();
    const h = dokumaFasonHesapla(spec);
    const fmt = (n) => (parseFloat(n) || 0).toLocaleString('tr-TR', { maximumFractionDigits: 1 });
    kutu.innerHTML = `
        <div style="text-align:center"><div style="font-size:8px;color:var(--text3)">Çözgü uzunluğu</div><div style="font-size:15px;font-weight:700;color:var(--text)">${fmt(h.cozguUzunlukM)} m</div></div>
        <div style="text-align:center"><div style="font-size:8px;color:var(--text3)">Çözgü ipliği</div><div style="font-size:15px;font-weight:700;color:var(--accent)">${fmt(h.cozguKg)} kg</div></div>
        <div style="text-align:center"><div style="font-size:8px;color:var(--text3)">Atkı ipliği</div><div style="font-size:15px;font-weight:700;color:var(--accent)">${fmt(h.atkiKg)} kg</div></div>
        <div style="text-align:center"><div style="font-size:8px;color:var(--text3)">Toplam iplik</div><div style="font-size:15px;font-weight:700;color:var(--amber-c)">${fmt(h.toplamKg)} kg</div></div>
    `;
}

async function dokumaSiparisKaydet() {
    const ad = String(document.getElementById('dsp-kumas-ad')?.value || '').trim();
    const metre = parseFloat(document.getElementById('dsp-metre')?.value || 0) || 0;
    if (!ad) { erpToast('Kumaş türü / açıklama girin.', 'error'); return; }
    if (metre <= 0) { erpToast('Toplam metre 0\'dan büyük olmalı.', 'error'); return; }
    const fasonMi = !!document.getElementById('dsp-yer-fason')?.checked;
    const fasonFirma = fasonMi ? String(document.getElementById('dsp-fason-firma')?.value || '').trim() : '';
    const hangiIs = String(document.getElementById('dsp-hangi-is')?.value || '').trim();
    const starih = document.getElementById('dsp-starih')?.value || null;
    const ttarih = document.getElementById('dsp-ttarih')?.value || null;
    const notVal = String(document.getElementById('dsp-not')?.value || '').trim();
    const spec = dokumaSiparisFormDegerleriniOku();
    const hesap = dokumaFasonHesapla({ ...spec, metre });

    const kayit = {
        kumas_adi: ad,
        metre,
        dokuma_uretim_yeri: fasonMi ? 'FASON_DOKUMA' : 'SIMTEKS_DOKUMA',
        dokuma_fason_firma: fasonFirma,
        hangi_is: hangiIs,
        starih,
        ttarih,
        notlar: notVal,
        cozgu_sikligi: parseFloat(document.getElementById('dsp-cozgu-sikligi')?.value || 0) || 0,
        atki_sikligi: parseFloat(spec.atki_sikligi) || 0,
        cozgu_tel_sayisi: parseFloat(spec.cozgu_tel_sayisi) || 0,
        tarak_eni_m: parseFloat(spec.tarak_eni_m) || 0,
        ip_no_sistemi: spec.ip_no_sistemi || 'NE',
        cozgu_ip_no: parseFloat(spec.cozgu_ip_no) || 0,
        atki_ip_no: parseFloat(spec.atki_ip_no) || 0,
        cozgu_fire_payi: parseFloat(spec.cozgu_fire_payi) || 0,
        atki_fire_payi: parseFloat(spec.atki_fire_payi) || 0,
        cozgu_ihtiyaci_m: hesap.cozguUzunlukM,
        cozgu_ipligi_kg: hesap.cozguKg,
        atki_ipligi_kg: hesap.atkiKg
    };
    try {
        if (typeof sb === 'undefined' || !sb?.from) throw new Error('Bağlantı yok');
        if (dokumaSiparisEditId) {
            kayit.updated_at = new Date().toISOString();
            const { error } = await sb.from('dokuma_fason_siparisleri').update(kayit).eq('id', dokumaSiparisEditId);
            if (error) throw error;
            const idx = (dataCache.dokumaFasonSiparisleri || []).findIndex(s => String(s.id) === String(dokumaSiparisEditId));
            if (idx >= 0) Object.assign(dataCache.dokumaFasonSiparisleri[idx], kayit);
            erpToast('Dokuma siparişi güncellendi.', 'success');
        } else {
            kayit.durum = 'BEKLEMEDE';
            kayit.sno = 'DK' + Date.now().toString().slice(-8);
            const ins = await sb.from('dokuma_fason_siparisleri').insert([kayit]).select('*');
            if (ins.error) throw ins.error;
            const newRow = ins.data?.[0];
            if (!dataCache.dokumaFasonSiparisleri) dataCache.dokumaFasonSiparisleri = [];
            if (newRow) dataCache.dokumaFasonSiparisleri.unshift(newRow);
            erpToast('Dokuma siparişi oluşturuldu.', 'success');
        }
        dokumaSiparisEditId = null;
        await setAppMode('DOKUMA_FASON_TAKIP');
    } catch (e) {
        erpToast('Kaydedilemedi: ' + (e?.message || e), 'error');
    }
}

// ── Haşıl Takip — çözgü ipliğinin haşıllanıp dokumaya hazır hale gelmesi ──
// Yıkama ekranıyla aynı basit desen: sipariş seç, sevk/gelen miktarını gir,
// bekleyen otomatik hesaplanır. KD_DOKUMA blob'unda saklanır (kendi kesim
// kuyruğu yok — Yıkama'nın "panel_yikama_sevk/gelen" alanlarının karşılığı).
async function renderHasilTakip() {
    if (appMode !== 'HASIL_TAKIP') return;
    const list = document.getElementById('main-list');
    if (!list) return;
    const siparisler = (dataCache.siparisler || []).filter(s => s.durum !== 'TAMAMLANDI');
    if (hasilSeciliSiparisId && !siparisler.some(s => String(s.id) === String(hasilSeciliSiparisId))) {
        hasilSeciliSiparisId = null;
    }
    if (hasilSeciliSiparisId) {
        try { await sbKdGet(hasilSeciliSiparisId, 'KD_DOKUMA', true); } catch (e) {}
    }
    hasilTakipListeYenile(siparisler);
}

function hasilSelectSiparis(id) {
    hasilSeciliSiparisId = id || null;
    renderHasilTakip();
}

function hasilTakipListeYenile(siparislerParam) {
    if (appMode !== 'HASIL_TAKIP') return;
    const list = document.getElementById('main-list');
    if (!list) return;
    const siparisler = siparislerParam || (dataCache.siparisler || []).filter(s => s.durum !== 'TAMAMLANDI');
    const seciliSiparis = siparisler.find(s => String(s.id) === String(hasilSeciliSiparisId));
    const kd = seciliSiparis ? (_kdCache[`KD_DOKUMA_${seciliSiparis.id}`] || {}) : {};
    const hSevk = parseFloat(kd.hasil_sevk || 0) || 0;
    const hGel = parseFloat(kd.hasil_gelen || 0) || 0;
    const hBek = Math.max(0, hSevk - hGel);
    const fmt = (n) => (parseFloat(n) || 0).toLocaleString('tr-TR', { maximumFractionDigits: 1 });
    const detayHtml = seciliSiparis ? `
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
            <div class="panel-box" style="padding:14px 16px;text-align:center">
                <div style="font-size:8px;color:var(--amber-c);font-family:'DM Mono',monospace;text-transform:uppercase">Haşıla sevk</div>
                <div style="font-family:'Instrument Serif',serif;font-size:22px;color:var(--amber-c)">${fmt(hSevk)}</div>
            </div>
            <div class="panel-box" style="padding:14px 16px;text-align:center">
                <div style="font-size:8px;color:var(--emerald-c);font-family:'DM Mono',monospace;text-transform:uppercase">Haşıldan gelen</div>
                <div style="font-family:'Instrument Serif',serif;font-size:22px;color:var(--emerald-c)">${fmt(hGel)}</div>
            </div>
            <div class="panel-box" style="padding:14px 16px;text-align:center">
                <div style="font-size:8px;color:var(--violet-c);font-family:'DM Mono',monospace;text-transform:uppercase">Bekleyen</div>
                <div style="font-family:'Instrument Serif',serif;font-size:22px;color:var(--violet-c)">${fmt(hBek)}</div>
            </div>
        </div>
        <div class="panel-box" style="padding:16px 20px">
            <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;color:var(--text2);margin-bottom:12px">🧶 Haşıl Durumu · ${pdfEsc(seciliSiparis.sno)}</div>
            <label style="display:flex;align-items:center;gap:8px;cursor:pointer;margin-bottom:10px">
                <input type="checkbox" id="hasil-yapildi" ${kd.hasil_yapildi ? 'checked' : ''} style="width:16px;height:16px;accent-color:var(--accent2)">
                <span style="font-size:11px;font-weight:700;color:var(--text)">Haşıla gönderildi</span>
            </label>
            <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
                <div><label class="pro-label">Haşıla sevk (kg/m)</label>
                    <input id="hasil-sevk" type="number" min="0" step="0.1" class="pro-input" value="${kd.hasil_sevk || ''}"></div>
                <div><label class="pro-label">Haşıldan gelen (kg/m)</label>
                    <input id="hasil-gelen" type="number" min="0" step="0.1" class="pro-input" value="${kd.hasil_gelen || ''}"></div>
            </div>
            <div style="margin-top:10px"><label class="pro-label">Haşılcı firma (fason ise)</label>
                <input id="hasil-firma" class="pro-input" placeholder="İç haşıl ise boş bırakın" value="${pdfEsc(kd.hasil_firma || '')}"></div>
            <div style="margin-top:10px"><label class="pro-label">Not</label>
                <textarea id="hasil-not" class="pro-input" rows="2" placeholder="Not…">${pdfEsc(kd.hasil_not || '')}</textarea></div>
            <button onclick="hasilKaydet()" class="btn-pro btn-primary-pro" style="width:100%;justify-content:center;padding:10px;margin-top:14px">💾 HAŞIL BİLGİLERİNİ KAYDET</button>
        </div>
    ` : `<div class="empty-pro" style="padding:60px 20px">
        <div class="empty-pro-icon">🧶</div>
        <div class="empty-pro-title">Haşıl Takip</div>
        <div class="empty-pro-sub">Üstten bir sipariş seçin</div>
    </div>`;
    list.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px">
        <div class="panel-box" style="padding:14px 16px;border-left:3px solid var(--accent2)">
            <div style="font-size:10px;font-weight:800;color:var(--text);text-transform:uppercase;letter-spacing:0.06em">Haşıl Takip</div>
            <div style="font-size:9px;color:var(--text3);margin-top:6px;line-height:1.5">Çözgü ipliğinin haşıla (kendi bölümünüz ya da fason haşılcı) sevk edilen ve dokumaya hazır dönen miktarını sipariş bazında kaydedin.</div>
        </div>
        <div class="panel-box" style="padding:12px 16px">
            <select id="hasil-siparis-sel" onchange="hasilSelectSiparis(this.value)" class="pro-input" style="min-width:240px;width:auto;padding:6px 10px">
                <option value="">— Sipariş seçin —</option>
                ${siparisler.map(s => `<option value="${s.id}" ${hasilSeciliSiparisId==s.id?'selected':''}>${pdfEsc(s.sno)} — ${pdfEsc(s.firma||'?')}</option>`).join('')}
            </select>
        </div>
        ${detayHtml}
    </div>`;
}

async function hasilKaydet() {
    if (!hasilSeciliSiparisId) return;
    const kd = await sbKdGet(hasilSeciliSiparisId, 'KD_DOKUMA');
    const yEl = document.getElementById('hasil-yapildi');
    const sEl = document.getElementById('hasil-sevk');
    const gEl = document.getElementById('hasil-gelen');
    const fEl = document.getElementById('hasil-firma');
    const nEl = document.getElementById('hasil-not');
    if (yEl) kd.hasil_yapildi = yEl.checked;
    if (sEl) kd.hasil_sevk = parseFloat(sEl.value || 0) || 0;
    if (gEl) kd.hasil_gelen = parseFloat(gEl.value || 0) || 0;
    if (fEl) kd.hasil_firma = String(fEl.value || '').trim();
    if (nEl) kd.hasil_not = nEl.value;
    await sbKdSet(hasilSeciliSiparisId, 'KD_DOKUMA', kd);
    erpToast('Haşıl bilgileri kaydedildi.', 'success');
    hasilTakipListeYenile();
}

async function renderKonfeksiyon() {
    const list = document.getElementById('main-list');
    if (!list) return;
    const altMod = konfIsAltMod();
    if (appMode === 'KONFEKSIYON_KESIM') {
        konfeksiyonTab = 'KESİM';
    } else if (appMode === 'KONFEKSIYON_YIKAMA') {
        konfeksiyonTab = 'YIKAMA';
    } else if (appMode === 'KONFEKSIYON_KALITE') {
        konfeksiyonTab = 'KALİTE';
    }
    if (konfPipelineModuMu()) {
        await konfLoadGlobalKumasGelis();
        if ((appMode === 'KONFEKSIYON_KESIM' || appMode === 'KONFEKSIYON_YIKAMA') && typeof konfLoadKesimGecmis === 'function') {
            await konfLoadKesimGecmis();
        }
        if (appMode === 'KONFEKSIYON_YIKAMA' && typeof konfLoadYikamaFisGecmis === 'function') {
            await konfLoadYikamaFisGecmis();
        }
    }
    const altBaslikMap = {
        KONFEKSIYON_KESIM: '✂️ Kesim',
        KONFEKSIYON_YIKAMA: '💧 Yıkama',
        KONFEKSIYON_KALITE: '◉ Kalite'
    };
    const siparisler = (dataCache.siparisler || []).filter(s => s.durum !== 'TAMAMLANDI');
    const siparisMeta = siparisler.map(s => {
        const kalemler = uaSiparisKalemleriGetir(s);
        const allUa = _kdCache[`KD_URUN_AGACI_${s.id}`] || {};
        const yer = uaNormalizeUretimYeri(s?.uretim_yeri || uaSiparisUretimYeriFromAll(allUa, kalemler));
        return { s, yer };
    });
    const filtreliSiparisler = siparisMeta
        .filter(r => {
            if (konfeksiyonYerFiltresi === 'SIMTEKS_KONF') return r.yer === 'SIMTEKS_KONF';
            if (konfeksiyonYerFiltresi === 'FASON_KONF') return r.yer === 'FASON_KONF';
            if (konfeksiyonYerFiltresi === 'DOGRUDAN_SEVK') return r.yer === 'DOGRUDAN_SEVK';
            return true;
        })
        .map(r => r.s);
    konfWarmupUaForKonfFilter(siparisler);
    if (konfeksiyonSiparisId && !filtreliSiparisler.some(s => String(s.id) === String(konfeksiyonSiparisId))) {
        konfeksiyonSiparisId = null;
        konfeksiyonTab = 'ÖZET';
    }
    const seciliSiparis = (filtreliSiparisler || []).find(s => String(s.id) === String(konfeksiyonSiparisId));
    const seciliKalemler = seciliSiparis ? uaSiparisKalemleriGetir(seciliSiparis) : [];
    const seciliKdUa = seciliSiparis ? (_kdCache[`KD_URUN_AGACI_${seciliSiparis.id}`] || {}) : {};
    const konfTabs = seciliSiparis
        ? konfTabsByUrunAgaci(seciliSiparis.id, seciliKalemler, seciliKdUa)
        : [
            { id: 'ÖZET', icon: '◎', label: 'Özet' },
            { id: 'KESİM', icon: '✦', label: 'Kesim' },
            { id: 'DİKİM', icon: '◈', label: 'Dikim' },
            { id: 'KALİTE', icon: '◉', label: 'Kalite' },
            { id: 'KOLİ', icon: '▣', label: 'Koli' },
            { id: 'KAPAMA', icon: '■', label: 'Kapama' }
        ];
    if (!konfTabs.some(t => t.id === konfeksiyonTab)) konfeksiyonTab = altMod ? (appMode === 'KONFEKSIYON_YIKAMA' ? 'YIKAMA' : appMode === 'KONFEKSIYON_KALITE' ? 'KALİTE' : 'KESİM') : 'ÖZET';
    const altModLabel = altBaslikMap[appMode] || '';
    const globalPanelMap = {
        KONFEKSIYON_KESIM: () => renderKonfGlobalKumasGelisPanel(),
        KONFEKSIYON_YIKAMA: () => renderKonfGlobalYikamaPanel(),
        KONFEKSIYON_KALITE: () => renderKonfGlobalKalitePanel()
    };
    const globalPanelHtml = globalPanelMap[appMode] ? globalPanelMap[appMode]() : '';
    const kesimUstBarKapali = ['KONFEKSIYON_KESIM', 'KONFEKSIYON_YIKAMA', 'KONFEKSIYON_KALITE'].includes(appMode);
    const icerikHtml = (konfeksiyonSiparisId && !kesimUstBarKapali)
        ? renderKonfIcerik()
        : (globalPanelHtml
            ? (['KONFEKSIYON_KESIM', 'KONFEKSIYON_YIKAMA', 'KONFEKSIYON_KALITE'].includes(appMode)
                ? globalPanelHtml
                : `${globalPanelHtml}<div class="empty-pro" style="padding:32px 20px;margin-top:8px"><div class="empty-pro-sub">Sipariş detayı için üstten sipariş seçin veya tablodaki <b>Sipariş</b> düğmesini kullanın.</div></div>`)
            : `<div class="empty-pro" style="padding:60px 20px">
                <div class="empty-pro-icon">✂️</div>
                <div class="empty-pro-title">${pdfEsc(altModLabel || 'Konfeksiyon')}</div>
                <div class="empty-pro-sub">Üstten bir sipariş seçin</div>
            </div>`);
    const ustBarHtml = kesimUstBarKapali ? '' : `
        <!-- BAR: SİPARİŞ SEÇ + TABLAR -->
        <div class="panel-box" style="padding:12px 16px">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                ${altMod ? `<div style="font-size:11px;font-weight:700;color:var(--rose-c);font-family:'DM Mono',monospace">${pdfEsc(altModLabel)}</div>` : `<div style="font-size:9px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace">Sipariş</div>`}
                <select id="konf-yer-filtre" onchange="konfSetYerFiltresi(this.value)" class="pro-input" style="min-width:170px;width:auto;padding:6px 10px">
                    <option value="HEPSI" ${konfeksiyonYerFiltresi==='HEPSI'?'selected':''}>Hepsi</option>
                    <option value="SIMTEKS_KONF" ${konfeksiyonYerFiltresi==='SIMTEKS_KONF'?'selected':''}>Simteks</option>
                    <option value="FASON_KONF" ${konfeksiyonYerFiltresi==='FASON_KONF'?'selected':''}>Fason</option>
                    <option value="DOGRUDAN_SEVK" ${konfeksiyonYerFiltresi==='DOGRUDAN_SEVK'?'selected':''}>Doğrudan Sevk</option>
                </select>
                <select id="konf-siparis-sel" onchange="konfSelectSiparis(this.value)" class="pro-input" style="min-width:200px;width:auto;padding:6px 10px">
                    <option value="">— Seçin —</option>
                    ${filtreliSiparisler.map(s => `<option value="${s.id}" ${konfeksiyonSiparisId==s.id?'selected':''}>${s.sno} — ${s.firma||'?'}</option>`).join('')}
                </select>
                <button onclick="openKonfIslemRaporu()" style="padding:6px 12px;font-size:10px;font-weight:700;border-radius:8px;border:1px solid rgba(236,72,153,0.35);background:rgba(236,72,153,0.1);color:#db2777;cursor:pointer;font-family:'DM Sans',sans-serif">📒 İşlem Raporu</button>

                ${altMod ? '' : `<!-- Tab Butonları -->
                <div style="margin-left:auto;display:flex;gap:3px;flex-wrap:wrap">
                    ${konfTabs.map(t => `
                    <button onclick="konfTab('${t.id}')" id="konf-tab-${t.id}"
                        style="font-size:10px;font-weight:500;padding:5px 12px;border-radius:7px;border:1px solid ${konfeksiyonTab===t.id?'transparent':'var(--border)'};cursor:pointer;transition:all 0.12s;font-family:'DM Sans',sans-serif;background:${konfeksiyonTab===t.id?'var(--rose-c)':'var(--surface2)'};color:${konfeksiyonTab===t.id?'#fff':'var(--text2)'}">
                        ${t.label}
                    </button>`).join('')}
                </div>`}
            </div>
        </div>`;
    list.innerHTML = `
    <div id="konf-root" style="display:flex;flex-direction:column;gap:12px;width:100%;min-width:0;box-sizing:border-box">

        ${ustBarHtml}

        <div id="konf-content" style="width:100%;min-width:0;box-sizing:border-box">
            ${altMod ? '' : `<div class="panel-box" style="margin-bottom:10px;padding:10px 14px;font-size:10px;color:var(--text2);line-height:1.5">
                Bu alan, <b>ürün ağacında tanımlanan</b> akışa göre konfeksiyon verilerinin girildiği ekrandır.
            </div>`}
            ${icerikHtml}
        </div>
    </div>`;
}

async function renderKonfeksiyonPlanlama() {
    const list = document.getElementById('main-list');
    if (!list) return;
    const siparisler = (dataCache.siparisler || []).filter(s => s.durum !== 'TAMAMLANDI');
    const siparisMeta = siparisler.map(s => {
        const kalemler = uaSiparisKalemleriGetir(s);
        const allUa = _kdCache[`KD_URUN_AGACI_${s.id}`] || {};
        const yer = uaNormalizeUretimYeri(s?.uretim_yeri || uaSiparisUretimYeriFromAll(allUa, kalemler));
        return { s, yer };
    });
    const konfDagilim = siparisMeta.reduce((acc, r) => {
        const yer = r.yer;
        if (yer === 'FASON_KONF') acc.fason += 1;
        else if (yer === 'DOGRUDAN_SEVK') acc.dogrudan += 1;
        else acc.simteks += 1;
        return acc;
    }, { simteks: 0, fason: 0, dogrudan: 0 });
    const filtreliSiparisler = siparisMeta
        .filter(r => {
            if (konfeksiyonYerFiltresi === 'SIMTEKS_KONF') return r.yer === 'SIMTEKS_KONF';
            if (konfeksiyonYerFiltresi === 'FASON_KONF') return r.yer === 'FASON_KONF';
            if (konfeksiyonYerFiltresi === 'DOGRUDAN_SEVK') return r.yer === 'DOGRUDAN_SEVK';
            return true;
        })
        .map(r => r.s);
    // Planlama seçiminde sadece henüz plana dahil edilmemiş siparişleri göster.
    /* 40'lık toplu çekim — sipariş başına ayrı istek atmak, her isteğin ~0,8 sn gecikmesi
       olduğu için ekran açılışını doğrudan uzatıyordu. */
    const eksikKonfIdler = filtreliSiparisler
        .filter(s => _kdCache[`KD_KONFEKSIYON_${s.id}`] === undefined)
        .map(s => s.id)
        .filter(Boolean);
    if (eksikKonfIdler.length) {
        if (typeof sbKdGetMany === 'function') {
            try { await sbKdGetMany(eksikKonfIdler, 'KD_KONFEKSIYON'); } catch (e) {}
        } else {
            try { await Promise.all(eksikKonfIdler.map(id => sbKdGet(id, 'KD_KONFEKSIYON'))); } catch (e) {}
        }
    }
    const planlanmisSiparisSet = new Set(
        filtreliSiparisler
            .filter(s => {
                const kdKonf = _kdCache[`KD_KONFEKSIYON_${s.id}`] || {};
                const rows = Array.isArray(kdKonf?.konf_plan_rows) ? kdKonf.konf_plan_rows : [];
                return rows.length > 0;
            })
            .map(s => String(s.id))
    );
    const planaDahilEdilmeyenSiparisler = filtreliSiparisler.filter(s => !planlanmisSiparisSet.has(String(s.id)));
    const planlamaSecimSiparisleri = konfPlanlamaPlanliGoster ? filtreliSiparisler : planaDahilEdilmeyenSiparisler;
    konfWarmupUaForKonfFilter(siparisler);
    if (konfeksiyonSiparisId && !planlamaSecimSiparisleri.some(s => String(s.id) === String(konfeksiyonSiparisId))) {
        konfeksiyonSiparisId = null;
    }
    list.innerHTML = `
    <div id="konf-plan-root" style="display:flex;flex-direction:column;gap:12px;width:100%;min-width:0;box-sizing:border-box">
        <div class="panel-box" style="padding:12px 16px">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                <div style="font-size:9px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;font-family:'DM Mono',monospace">Planlama siparişi</div>
                <span class="pill pill-cyan">Simteks: ${konfDagilim.simteks}</span>
                <span class="pill pill-amber">Fason: ${konfDagilim.fason}</span>
                <span class="pill pill-violet">Doğrudan Sevk: ${konfDagilim.dogrudan}</span>
                <span class="pill pill-gray">Plana dahil olmayan: ${planaDahilEdilmeyenSiparisler.length}</span>
                <label style="display:flex;align-items:center;gap:6px;padding:4px 8px;border:1px solid var(--border);border-radius:8px;background:var(--surface2);font-size:10px;color:var(--text2);cursor:pointer">
                    <input type="checkbox" ${konfPlanlamaPlanliGoster ? 'checked' : ''} onchange="konfPlanlamaPlanliGoster=this.checked; saveUiState({konfPlanlamaPlanliGoster:this.checked}); renderKonfeksiyonPlanlama()">
                    Planlı siparişleri de göster (revize)
                </label>
                <select id="konf-plan-yer-filtre" onchange="konfSetYerFiltresi(this.value)" class="pro-input" style="min-width:170px;width:auto;padding:6px 10px">
                    <option value="HEPSI" ${konfeksiyonYerFiltresi==='HEPSI'?'selected':''}>Hepsi</option>
                    <option value="SIMTEKS_KONF" ${konfeksiyonYerFiltresi==='SIMTEKS_KONF'?'selected':''}>Simteks</option>
                </select>
                <select id="konf-plan-siparis-sel" onchange="konfSelectSiparis(this.value)" class="pro-input" style="min-width:220px;width:auto;padding:6px 10px">
                    <option value="">— Seçin —</option>
                    ${planlamaSecimSiparisleri.map(s => `<option value="${s.id}" ${konfeksiyonSiparisId==s.id?'selected':''}>${s.sno} — ${s.firma||'?'}</option>`).join('')}
                </select>
                <button onclick="setAppMode('SIPARIS_GIRIS')" style="padding:6px 12px;font-size:10px;font-weight:500;border-radius:8px;border:1px solid rgba(251,113,133,0.3);background:rgba(251,113,133,0.1);color:var(--rose-c);cursor:pointer;font-family:'DM Sans',sans-serif">＋ Yeni Sipariş</button>
            </div>
        </div>
        <div id="konf-plan-content" style="width:100%;min-width:0;box-sizing:border-box">
            ${konfeksiyonSiparisId ? renderKonfPlanlamaIcerik() : `
            <div class="empty-pro" style="padding:60px 20px">
                <div class="empty-pro-icon">🗓️</div>
                <div class="empty-pro-title">Konfeksiyon Planlama</div>
                <div class="empty-pro-sub">Üstten bir sipariş seçin</div>
            </div>`}
        </div>
    </div>`;
}

function konfSetYerFiltresi(v) {
    konfeksiyonYerFiltresi = v || 'HEPSI';
    if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
    else renderKonfeksiyon();
}

async function konfWarmupUaForKonfFilter(siparisler) {
    if (konfUaFilterWarmupDone || konfUaFilterWarmupRunning) return;
    const eksik = (siparisler || []).filter(s => _kdCache[`KD_URUN_AGACI_${s.id}`] === undefined);
    if (!eksik.length) {
        konfUaFilterWarmupDone = true;
        return;
    }
    konfUaFilterWarmupRunning = true;
    try {
        /* Sipariş başına ayrı sorgu değil — 40'lık gruplarla toplu çekim */
        if (typeof sbKdGetMany === 'function') {
            await sbKdGetMany(eksik.map(s => s.id), 'KD_URUN_AGACI');
        } else {
            await Promise.allSettled(eksik.map(s => sbKdGet(s.id, 'KD_URUN_AGACI')));
        }
    } finally {
        konfUaFilterWarmupRunning = false;
        konfUaFilterWarmupDone = true;
        if (appMode === 'KONFEKSIYON') renderKonfeksiyon();
        if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
    }
}

async function konfSelectSiparis(id) {
    konfeksiyonSiparisId = id || null;
    if (!konfIsAltMod()) konfeksiyonTab = 'ÖZET';
    else if (appMode === 'KONFEKSIYON_KESIM') konfeksiyonTab = 'KESİM';
    else if (appMode === 'KONFEKSIYON_YIKAMA') konfeksiyonTab = 'YIKAMA';
    else if (appMode === 'KONFEKSIYON_KALITE') konfeksiyonTab = 'KALİTE';
    konfDraft = { kalem: {}, aksesuar: {}, ikiDetay: {} };
    saveUiState({ konfeksiyonSiparisId, konfeksiyonTab });
    if (konfeksiyonSiparisId) {
        /* Üç KD tipi tek sorguda — 3 round-trip yerine 1 */
        if (typeof sbKdGetTipler === 'function') {
            await sbKdGetTipler(konfeksiyonSiparisId, ['KD_KONFEKSIYON', 'KD_DOKUMA', 'KD_URUN_AGACI'], { force: true });
        } else {
            await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', true);
            await sbKdGet(konfeksiyonSiparisId, 'KD_DOKUMA', true);
            await sbKdGet(konfeksiyonSiparisId, 'KD_URUN_AGACI', true);
        }
        await konfLoadIslemLog(konfeksiyonSiparisId);
        /* Kesim adetleri konf_kesim_yikama'da, kalite/yıkama/sevk adetleri
           KUMAS_GELIS satırlarında. konfGetKdForSiparis bunları gösterimde
           birleştirdiği için alt mod olmasa da yüklenmeli — eskiden yalnız
           alt modlarda yükleniyordu ve Konfeksiyon Panel'den girilen kesim
           sipariş detayında hiç görünmüyordu. */
        await konfLoadKesimGecmis();
        await konfLoadGlobalKumasGelis();
    }
    if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
    else renderKonfeksiyon();
    konfStartLiveSync();
}

async function openKonfeksiyonPlanlama() {
    await setAppMode('KONFEKSIYON_PLANLAMA');
}

function konfTab(tab) {
    konfeksiyonTab = tab;
    saveUiState({ konfeksiyonTab });
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(konfeksiyonSiparisId));
    const kalemler = siparis ? uaSiparisKalemleriGetir(siparis) : [];
    const kdUa = siparis ? (_kdCache[`KD_URUN_AGACI_${siparis.id}`] || {}) : {};
    const activeTabIds = (siparis ? konfTabsByUrunAgaci(siparis.id, kalemler, kdUa) : []).map(t => t.id);
    (activeTabIds.length ? activeTabIds : ['ÖZET','KESİM','DİKİM','KALİTE','KOLİ','KAPAMA']).forEach(t => {
        const btn = document.getElementById('konf-tab-'+t);
        if (!btn) return;
        btn.style.background = t===tab ? 'var(--rose-c)' : 'var(--surface2)';
        btn.style.color = t===tab ? '#fff' : 'var(--text2)';
        btn.style.borderColor = t===tab ? 'transparent' : 'var(--border)';
    });
    const cont = document.getElementById('konf-content');
    if (cont) cont.innerHTML = renderKonfIcerik();
}

function konfGetKd() {
    if (!konfeksiyonSiparisId) return {};
    return konfGetKdForSiparis(konfeksiyonSiparisId);
}

function konfGetKalemler() {
    const siparis = (dataCache.siparisler || []).find(s => s.id == konfeksiyonSiparisId);
    return uaSiparisKalemleriGetir(siparis);
}

function konfGetKdUrunAgaci(siparisId) {
    if (!siparisId) return {};
    return _kdCache[`KD_URUN_AGACI_${siparisId}`] || {};
}

/** Tüm kalemlerdeki ürün aşamalarının birleşimi (ilk görülen sıra korunur) + sevk yoksa sonda eklenir */
function konfMergedUretimAsamalari(kalemler, kdUa) {
    const order = UA_ASAMALAR.map(a => a.id);
    const seen = new Set();
    const arr = [];
    (kalemler || []).forEach((_, i) => {
        const ua = (kdUa || {})[`u_${i}`] || {};
        (ua.asamalar || []).forEach(id => {
            const n = String(id || '').trim().toLowerCase();
            if (!order.includes(n) || seen.has(n)) return;
            seen.add(n);
            arr.push(n);
        });
    });
    if (!arr.length) {
        return ['dokuma', 'top_boya', 'baski', 'kesim', 'parca_boya', 'parca_yikama', 'parca_baski', 'nakis', 'dikim', 'kalite', 'sevk'];
    }
    return arr;
}

function konfTabsByUrunAgaci(siparisId, kalemler, kdUa) {
    const allUa = kdUa || konfGetKdUrunAgaci(siparisId);
    const asamalar = konfMergedUretimAsamalari(kalemler, allUa);
    const stageSet = new Set((asamalar || []).map(a => String(a || '').toLowerCase()));
    const tabs = [{ id: 'ÖZET', icon: '◎', label: 'Özet' }];
    if (stageSet.has('kesim')) tabs.push({ id: 'KESİM', icon: '✦', label: 'Kesim' });
    if (stageSet.has('dikim')) tabs.push({ id: 'DİKİM', icon: '◈', label: 'Dikim' });
    if (stageSet.has('kalite')) tabs.push({ id: 'KALİTE', icon: '◉', label: 'Kalite' });
    if (stageSet.has('paket') || stageSet.has('koli')) tabs.push({ id: 'KOLİ', icon: '▣', label: 'Koli' });
    tabs.push({ id: 'KAPAMA', icon: '■', label: 'Kapama' });
    return tabs;
}

function konfDokumaUrunToplamlari(kdDok, kalemler) {
    let dokMt = 0, dokKg = 0, dokAd = 0, dokIkinci = 0;
    let dokIkinciTip = null;
    const urunler = (kdDok && kdDok.urunler) ? kdDok.urunler : {};
    const list = Array.isArray(kalemler) ? kalemler : null;
    if (list && list.length) {
        list.forEach((k, i) => {
            const u = urunler[i] || urunler[String(i)] || {};
            const o = dokumaUrunIkinciOzet(u, k);
            dokMt += o.metre;
            dokKg += o.kg;
            dokAd += o.adet;
            dokIkinci += o.ikinci;
            if (!dokIkinciTip) dokIkinciTip = o.tip;
            else if (dokIkinciTip !== o.tip) dokIkinciTip = 'MIX';
        });
    } else {
        Object.values(urunler).forEach(u => {
            dokMt += parseFloat(u?.toplam_metre) || 0;
            dokKg += parseFloat(u?.toplam_kg) || 0;
            dokAd += parseInt(u?.toplam_adet, 10) || 0;
        });
        dokIkinci = dokAd > 0 ? dokAd : dokKg;
        dokIkinciTip = dokAd > 0 ? 'ADET' : (dokKg > 0 ? 'KG' : 'ADET');
    }
    return { dokMt, dokKg, dokAd, dokIkinci, dokIkinciTip: dokIkinciTip || 'ADET' };
}

function konfSiparisMetricForStage(stageId, kd, islemRows, kdDok, kalemler, siparisId) {
    const n = (v) => parseInt(v, 10) || 0;
    const sumAkis = (kodlar) => Math.round(uaIslemToplamTum(islemRows, kodlar));

    const uretimTop = () => konfSiparisUretimToplam(siparisId, kd, (kalemler || []).length);
    switch (stageId) {
        case 'dokuma': return konfDokumaUrunToplamlari(kdDok, kalemler).dokIkinci;
        case 'top_boya':
        case 'baski':
        case 'parca_boya':
        case 'parca_yikama':
        case 'parca_baski':
        case 'nakis': return 0;
        /* Kesim / yıkama / dikim / kalite / koli: tek kural (konfSiparisUretimToplam) — günlük toplamı girmez. */
        case 'kesim': return uretimTop().kesim;
        case 'yikama': return uretimTop().yikSevk + uretimTop().yikGel;
        case 'dikim': return uretimTop().dikim;
        case 'baskı':
        case 'ütü': return 0;
        case 'kalite': return uretimTop().kalite;
        case 'koli': return uretimTop().koli;
        case 'sevk': return Math.max(n(kd?.panel_sevk_toplam), sumAkis(['SEVK', 'KONF_SEVK']));
        default: return 0;
    }
}

function konfStageTamam(stageId, kd, metricVal, kdDok, kalemler) {
    if (stageId === 'yikama') return !!(kd?.yikama_yapildi) || metricVal > 0;
    if (stageId === 'dokuma') {
        const { dokMt, dokKg, dokAd } = konfDokumaUrunToplamlari(kdDok, kalemler);
        return dokMt > 0 || dokKg > 0 || dokAd > 0;
    }
    return metricVal > 0;
}

function renderKonfUretimAgaciBlok(siparis, kalemler, kd, kdUa, kdDok) {
    const islemRows = _konfIslemLogCache[siparis.id] || [];
    const stages = konfMergedUretimAsamalari(kalemler, kdUa);
    const sipTop = kalemler.reduce((a, k) => a + (parseInt(k.miktar, 10) || 0), 0);
    const gun = siparis.ttarih ? Math.ceil((new Date(siparis.ttarih) - new Date()) / 86400000) : null;
    const gunColor = gun === null ? 'var(--text3)' : gun < 0 ? 'var(--rose-c)' : gun <= 7 ? 'var(--amber-c)' : 'var(--emerald-c)';
    const { dokMt, dokKg, dokAd, dokIkinci, dokIkinciTip } = konfDokumaUrunToplamlari(kdDok, kalemler);
    const dokVar = dokMt > 0 || dokKg > 0 || dokAd > 0;
    const pct = (v) => (sipTop > 0 ? Math.min(100, Math.round((v / sipTop) * 100)) : 0);
    const hata = parseInt(kd?.hatali_toplam, 10) || 0;
    const yikTop = konfSiparisUretimToplam(siparis.id, kd, (kalemler || []).length);
    const yikamaSevk = yikTop.yikSevk;
    const yikamaGelen = yikTop.yikGel;
    const yikamaBekleyen = Math.max(0, yikamaSevk - yikamaGelen);

    const asamaSatir = stages.map((id, i) => {
        const meta = UA_ASAMALAR.find(a => a.id === id);
        if (!meta) return '';
        const mv = konfSiparisMetricForStage(id, kd, islemRows, kdDok, kalemler, siparis.id);
        const done = konfStageTamam(id, kd, mv, kdDok, kalemler);
        const son = i === stages.length - 1;
        return `<div style="display:flex;align-items:center;flex-shrink:0">
            <div style="display:flex;flex-direction:column;align-items:center;gap:4px">
                <div style="width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;border:2px solid ${done ? 'var(--emerald-c)' : 'var(--border)'};background:${done ? 'var(--emerald-c)' : 'var(--surface2)'};color:${done ? '#fff' : 'var(--text3)'};" title="${pdfEsc(meta.label)}">
                    ${done ? '✓' : meta.ikon}
                </div>
                <span style="font-size:7px;font-weight:700;color:${done ? 'var(--emerald-c)' : 'var(--text3)'};text-align:center;max-width:52px;line-height:1.25;font-family:'DM Mono',monospace">${pdfEsc(meta.label)}</span>
            </div>
            ${!son ? `<div style="width:20px;height:2px;margin-bottom:18px;flex-shrink:0;background:${done ? 'var(--emerald-c)' : 'var(--border)'}"></div>` : ''}
        </div>`;
    }).join('');

    const fmtDok = (n, fd) => {
        const x = parseFloat(n);
        if (!Number.isFinite(x) || x === 0) return '—';
        return x.toLocaleString('tr-TR', { maximumFractionDigits: fd });
    };
    const dokIkinciHtml = (() => {
        if (dokIkinciTip === 'KG') {
            return `<div style="font-size:10px;font-weight:600;color:var(--accent2);font-family:'DM Mono',monospace">${fmtDok(dokKg, 2)} kg</div>`;
        }
        if (dokIkinciTip === 'MIX') {
            return `<div style="font-size:10px;font-weight:600;color:var(--accent2);font-family:'DM Mono',monospace">${fmtDok(dokKg, 2)} kg</div>
            <div style="font-size:10px;font-weight:600;color:var(--emerald-c);font-family:'DM Mono',monospace">${dokAd ? dokAd.toLocaleString('tr-TR') : '—'} ad</div>`;
        }
        return `<div style="font-size:10px;font-weight:600;color:var(--emerald-c);font-family:'DM Mono',monospace">${dokAd ? dokAd.toLocaleString('tr-TR') : '—'} ad</div>`;
    })();
    const dokPctLabel = dokIkinciTip === 'KG' ? 'kg' : (dokIkinciTip === 'MT' ? 'm' : (dokIkinciTip === 'MIX' ? 'Σ' : 'ad'));

    const metrikKutular = [];
    const dokumaAgacta = stages.includes('dokuma');
    if (!dokumaAgacta) {
        metrikKutular.push(
            `<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px 10px;text-align:center;box-sizing:border-box;min-width:100px">
            <div style="font-size:9px;font-weight:800;color:var(--text3);text-transform:uppercase;font-family:'DM Mono',monospace;margin-bottom:6px">Dokuma (özet)</div>
            <div style="font-size:11px;font-weight:700;color:var(--cyan-c);font-family:'DM Mono',monospace">${fmtDok(dokMt, 1)} m</div>
            ${dokIkinciHtml}
            <div style="margin-top:6px;font-size:8px;color:var(--text3)">${dokVar ? 'Kayıt var' : 'Bekliyor'}</div>
        </div>`
        );
    }
    stages.forEach(id => {
        const meta = UA_ASAMALAR.find(a => a.id === id);
        if (!meta) return;
        if (id === 'dokuma') {
            metrikKutular.push(`
            <div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px 10px;text-align:center;box-sizing:border-box;min-width:108px">
                <div style="font-size:9px;font-weight:800;color:var(--text3);text-transform:uppercase;font-family:'DM Mono',monospace;margin-bottom:6px">${pdfEsc(meta.label)} <span style="font-size:7px;opacity:.85">(Ü.A.)</span></div>
                <div style="font-size:11px;font-weight:700;color:var(--cyan-c);font-family:'DM Mono',monospace">${fmtDok(dokMt, 1)} m</div>
                ${dokIkinciHtml}
                <div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace;margin-top:4px">${dokPctLabel} · %${pct(dokIkinci)}</div>
                <div style="margin-top:8px;background:var(--surface);border-radius:4px;height:2px;overflow:hidden">
                    <div style="height:100%;border-radius:4px;background:var(--cyan-c);width:${Math.min(pct(dokIkinci), 100)}%"></div>
                </div>
            </div>`);
            return;
        }
        const v = konfSiparisMetricForStage(id, kd, islemRows, kdDok, kalemler, siparis.id);
        const renk = id === 'sevk' ? '#7c3aed' : id === 'yikama' ? 'var(--cyan-c)' : id === 'kesim' ? 'var(--accent2)' : id === 'dikim' ? 'var(--rose-c)' : id === 'kalite' ? 'var(--amber-c)' : id === 'koli' ? 'var(--emerald-c)' : 'var(--text2)';
        metrikKutular.push(`
        <div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px 10px;text-align:center;box-sizing:border-box;min-width:92px">
            <div style="font-size:9px;font-weight:800;color:var(--text3);text-transform:uppercase;font-family:'DM Mono',monospace;margin-bottom:6px;white-space:nowrap">${pdfEsc(meta.label)}</div>
            <div style="font-family:'Instrument Serif',serif;font-size:22px;color:${renk};line-height:1">${v > 0 ? v.toLocaleString('tr-TR') : '—'}</div>
            <div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace;margin-top:4px">adet · %${pct(v)}</div>
            <div style="margin-top:8px;background:var(--surface);border-radius:4px;height:2px;overflow:hidden">
                <div style="height:100%;border-radius:4px;background:${renk};width:${Math.min(pct(v), 100)}%"></div>
            </div>
        </div>`);
    });
    if (hata > 0) {
        metrikKutular.push(`
        <div style="background:rgba(251,113,133,0.08);border:1px solid rgba(251,113,133,0.35);border-radius:10px;padding:12px 10px;text-align:center;box-sizing:border-box;min-width:92px">
            <div style="font-size:9px;font-weight:800;color:var(--rose-c);text-transform:uppercase;font-family:'DM Mono',monospace">Hatalı</div>
            <div style="font-family:'Instrument Serif',serif;font-size:22px;color:var(--rose-c);line-height:1">${hata.toLocaleString('tr-TR')}</div>
        </div>`);
    }
    metrikKutular.push(`
        <div style="background:rgba(34,211,238,0.08);border:1px solid rgba(34,211,238,0.35);border-radius:10px;padding:12px 10px;text-align:center;box-sizing:border-box;min-width:92px">
            <div style="font-size:9px;font-weight:800;color:var(--cyan-c);text-transform:uppercase;font-family:'DM Mono',monospace">Yıkamada Bekleyen</div>
            <div style="font-family:'Instrument Serif',serif;font-size:22px;color:${yikamaBekleyen > 0 ? 'var(--amber-c)' : 'var(--emerald-c)'};line-height:1">${yikamaBekleyen.toLocaleString('tr-TR')}</div>
            <div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace;margin-top:4px">Sevk ${yikamaSevk.toLocaleString('tr-TR')} · Gelen ${yikamaGelen.toLocaleString('tr-TR')}</div>
        </div>`);

    const uaEksik = (kalemler || []).length && (kalemler || []).some((_, i) => {
        const u = (kdUa || {})[`u_${i}`] || {};
        return !Array.isArray(u.asamalar) || u.asamalar.length === 0;
    });

    return `<div class="panel-box" style="padding:16px 18px;width:100%;box-sizing:border-box">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px">
            <div>
                <div style="font-size:9px;font-weight:800;color:var(--accent2);text-transform:uppercase;letter-spacing:0.08em;font-family:'DM Mono',monospace;margin-bottom:4px">Üretim ağacı (ürün ağacı)</div>
                <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                    <span style="font-family:'Instrument Serif',serif;font-size:20px;color:var(--text)">${pdfEsc(siparis.sno || '—')}</span>
                    <span class="pill pill-pink" style="font-size:9px">Konfeksiyon</span>
                </div>
                <div style="font-size:11px;color:var(--text3);margin-top:4px">${pdfEsc(siparis.firma || '—')}</div>
            </div>
            <div style="text-align:right">
                <div style="font-family:'Instrument Serif',serif;font-size:24px;color:var(--text);line-height:1">${sipTop.toLocaleString('tr-TR')}</div>
                <div style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">sipariş adedi</div>
                ${gun !== null ? `<div style="font-size:10px;font-weight:600;color:${gunColor};margin-top:4px">${gun < 0 ? Math.abs(gun) + 'g gecikti' : gun === 0 ? 'Termin bugün' : gun + 'g kaldı'}</div>` : ''}
            </div>
        </div>
        ${uaEksik ? `<div style="font-size:9px;color:var(--amber-c);padding:8px 10px;border-radius:8px;background:rgba(251,191,36,0.1);border:1px solid rgba(251,191,36,0.35);margin-bottom:12px">Bazı kalemlerde ürün ağacı tanımlı değil — aşağıdaki sıra varsayılan akış + <b>sevk</b> ile gösteriliyor. <b>Ürün Ağacı</b> modülünden tamamlayın.</div>` : ''}
        <div style="font-size:9px;color:var(--text3);margin-bottom:10px;line-height:1.4">Aşamalar, bu sipariş için kayıtlı <b>ürün ağacı</b> kalemlerinin birleşimidir; <b>dokuma takip</b> girişleri baz alınır ve <b>sevk</b> her siparişin son adımıdır. Alt kutular gerçek operasyon toplamlarıdır.</div>
        <div style="display:flex;align-items:center;gap:0;overflow-x:auto;padding:8px 4px 12px;border:1px solid var(--border);border-radius:10px;background:var(--surface2);margin-bottom:14px">
            ${asamaSatir}
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:10px;width:100%">
            ${metrikKutular.join('')}
        </div>
    </div>`;
}

function konfDayKeyFromDate(d) {
    if (!d || !Number.isFinite(d.getTime())) return null;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
}

function konfParseFlexibleDate(val) {
    if (val == null || val === '') return null;
    if (typeof val === 'number' && Number.isFinite(val)) {
        const d = new Date(val);
        return Number.isFinite(d.getTime()) ? d : null;
    }
    const s = String(val).trim();
    if (!s) return null;
    const d0 = new Date(s);
    if (Number.isFinite(d0.getTime())) return d0;
    const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/);
    if (m) return new Date(parseInt(m[3], 10), parseInt(m[2], 10) - 1, parseInt(m[1], 10));
    return null;
}

function konfFmtDayHeader(iso) {
    const p = String(iso || '').split('-');
    if (p.length !== 3) return iso;
    const d = new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
    return Number.isFinite(d.getTime()) ? d.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', weekday: 'short' }) : iso;
}

function renderKonfIsAkisGantt(siparisId) {
    const rows = _konfIslemLogCache[siparisId] || [];
    const kdDok = _kdCache[`KD_DOKUMA_${siparisId}`] || {};
    const urunler = kdDok.urunler || {};
    const daySet = new Set();
    const emptyBucket = () => ({ kesim: 0, yikama: 0, dikim: 0, kalite: 0, koli: 0, sevk: 0, dok_mt: 0, dok_kg: 0, dok_adet: 0 });
    const byDay = {};

    function touchDay(dk) {
        if (!dk) return;
        daySet.add(dk);
        if (!byDay[dk]) byDay[dk] = emptyBucket();
    }

    rows.forEach(r => {
        const d = konfParseFlexibleDate(r.ts || r.created_at);
        const dk = konfDayKeyFromDate(d);
        if (!dk) return;
        touchDay(dk);
        const m = parseFloat(r.miktar) || 0;
        /* İşlem adları platforma göre değişiyor: kalite masaüstü/mobilde
           'KK_GECEN', Konfeksiyon Panel'de 'KALİTE KONTROL' yazılır; sevk ise
           'SEVK' ya da 'KONF_SEVK'. Hepsi aynı kovaya girmeli. */
        const islem = konfNormTxt(r.islem).replace(/İ/g, 'I');
        if (islem === 'KESIM') byDay[dk].kesim += m;
        else if (islem === 'DIKIM') byDay[dk].dikim += m;
        else if (islem === 'KALITE' || islem === 'KALITE KONTROL' || islem === 'KK_GECEN') byDay[dk].kalite += m;
        else if (islem === 'PAKET' || islem === 'KOLI') byDay[dk].koli += m;
        else if (islem === 'YIKAMA_SEVK' || islem === 'YIKAMA_GELEN') byDay[dk].yikama += m;
        else if (islem === 'SEVK' || islem === 'KONF_SEVK') byDay[dk].sevk += m;
    });

    Object.keys(urunler).forEach(idx => {
        const u = urunler[idx] || {};
        (u.girisler || []).forEach(g => {
            const d = konfParseFlexibleDate(g.tarih);
            const dk = konfDayKeyFromDate(d);
            if (!dk) return;
            touchDay(dk);
            byDay[dk].dok_mt += parseFloat(g.metre) || 0;
            byDay[dk].dok_kg += parseFloat(g.kg) || 0;
            byDay[dk].dok_adet += parseInt(g.adet, 10) || 0;
        });
    });

    const days = [...daySet].sort();
    const acik = !!konfGanttAcik;
    const laneDefs = [
        { key: 'kesim', label: 'Kesim (adet)', color: '#6366f1' },
        { key: 'yikama', label: 'Yıkama (sevk+gelen)', color: '#22d3ee' },
        { key: 'dikim', label: 'Dikim (adet)', color: '#fb7185' },
        { key: 'kalite', label: 'Kalite (adet)', color: '#fbbf24' },
        { key: 'koli', label: 'Paket / Koli', color: '#34d399' },
        { key: 'sevk', label: 'Sevk (adet)', color: '#7c3aed' },
        { key: '_dok', label: 'Dokuma (Dokuma Takip)', color: '#a78bfa' },
    ];

    if (!days.length) {
        return `<div class="panel-box" style="margin-top:4px;width:100%;box-sizing:border-box;overflow:hidden">
            <div class="panel-head" role="button" tabindex="0" onclick="konfToggleGantt()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();konfToggleGantt();}"
                style="cursor:pointer;user-select:none;flex-wrap:wrap;gap:8px" title="Paneli aç / kapat">
                <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent)"></span>Günlük iş akışı</span>
                <span style="font-size:10px;font-weight:700;color:var(--accent2);font-family:'DM Mono',monospace;margin-left:auto">${acik ? '▼ Daralt' : '▶ Genişlet'}</span>
            </div>
            ${acik ? `<div style="padding:16px 20px;font-size:12px;color:var(--text3);line-height:1.5">Bu sipariş için henüz günlük kayıt yok. Konfeksiyon operasyon girişleri ve <b>Dokuma Takip</b> sipariş girişleri (mt/kg/adet) burada gün bazında görünür.</div>` : `<div style="padding:8px 16px 14px;font-size:10px;color:var(--text3)">Özet gizli — başlığa tıklayarak açın.</div>`}
        </div>`;
    }

    const fmtNum = (n) => (Number.isFinite(n) && n !== 0 ? n.toLocaleString('tr-TR', { maximumFractionDigits: 2 }) : '—');
    const cellDokuma = (dk) => {
        const b = byDay[dk] || emptyBucket();
        const parts = [];
        if (b.dok_mt) parts.push(`${fmtNum(b.dok_mt)} mt`);
        if (b.dok_kg) parts.push(`${fmtNum(b.dok_kg)} kg`);
        if (b.dok_adet) parts.push(`${fmtNum(b.dok_adet)} ad`);
        return parts.length ? parts.join(' · ') : '—';
    };

    const tableBody = laneDefs.map(ld => {
        if (ld.key === '_dok') {
            return `<tr style="border-bottom:1px solid var(--border)">
                <td style="position:sticky;left:0;background:var(--surface2);z-index:1;padding:10px 12px;font-size:11px;font-weight:700;color:var(--text2);font-family:'DM Mono',monospace;border-right:1px solid var(--border);white-space:nowrap">
                    <span style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${ld.color};margin-right:8px;vertical-align:middle"></span>${pdfEsc(ld.label)}
                </td>
                ${days.map(dk => `<td style="padding:10px 8px;text-align:center;font-size:11px;color:var(--text);vertical-align:middle;min-width:72px">${pdfEsc(cellDokuma(dk))}</td>`).join('')}
            </tr>`;
        }
        return `<tr style="border-bottom:1px solid var(--border)">
            <td style="position:sticky;left:0;background:var(--surface2);z-index:1;padding:10px 12px;font-size:11px;font-weight:700;color:var(--text2);font-family:'DM Mono',monospace;border-right:1px solid var(--border);white-space:nowrap">
                <span style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${ld.color};margin-right:8px;vertical-align:middle"></span>${pdfEsc(ld.label)}
            </td>
            ${days.map(dk => {
                const v = (byDay[dk] || emptyBucket())[ld.key] || 0;
                const show = v > 0 ? fmtNum(v) : '—';
                return `<td style="padding:10px 8px;text-align:center;font-size:12px;font-weight:600;font-family:'DM Mono',monospace;color:${v > 0 ? 'var(--text)' : 'var(--text3)'};min-width:56px">${show}</td>`;
            }).join('')}
        </tr>`;
    }).join('');

    const headRow = `<tr>
        <th style="position:sticky;left:0;z-index:2;background:var(--surface);padding:10px 12px;text-align:left;font-size:10px;font-weight:800;color:var(--text3);text-transform:uppercase;letter-spacing:0.06em;font-family:'DM Mono',monospace;border-right:1px solid var(--border)">Gün →</th>
        ${days.map(dk => `<th style="padding:10px 6px;text-align:center;font-size:10px;font-weight:700;color:var(--text2);font-family:'DM Mono',monospace;min-width:64px;white-space:nowrap">${pdfEsc(konfFmtDayHeader(dk))}</th>`).join('')}
    </tr>`;

    return `<div class="panel-box" style="margin-top:4px;width:100%;box-sizing:border-box;overflow:hidden">
        <div class="panel-head" role="button" tabindex="0" onclick="konfToggleGantt()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();konfToggleGantt();}"
            style="cursor:pointer;user-select:none;flex-wrap:wrap;gap:8px" title="Paneli aç / kapat">
            <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent)"></span>Günlük iş akışı</span>
            <span style="font-size:10px;color:var(--text3);font-family:'DM Mono',monospace;margin-right:auto">${days.length} gün · konf. operasyon + dokuma girişleri</span>
            <span style="font-size:10px;font-weight:700;color:var(--accent2);font-family:'DM Mono',monospace">${acik ? '▼ Daralt' : '▶ Genişlet'}</span>
        </div>
        ${acik ? `<div style="padding:12px 14px 18px;box-sizing:border-box">
            <div style="font-size:10px;color:var(--text3);margin-bottom:12px;line-height:1.45">Her hücre o gün girilen toplam miktarı gösterir. Dokuma satırı, <b>Dokuma Takip → Sipariş</b> ekranından kaydedilen mt/kg/adet girişlerini içerir.</div>
            <div style="width:100%;overflow-x:auto;border:1px solid var(--border);border-radius:12px;background:var(--surface)">
                <table class="dt-table" style="border-collapse:collapse;min-width:max(100%,${120 + days.length * 68}px);font-size:12px">
                    <thead>${headRow}</thead>
                    <tbody>${tableBody}</tbody>
                </table>
            </div>
        </div>` : `<div style="padding:8px 16px 14px;font-size:10px;color:var(--text3)">Özet gizli — başlığa tıklayarak açın.</div>`}
    </div>`;
}

function renderKonfIcerik() {
    const siparis = (dataCache.siparisler||[]).find(s=>s.id==konfeksiyonSiparisId);
    if (!siparis) return '<p class="text-slate-400 text-center p-8">Sipariş bulunamadı</p>';
    const kalemler = konfGetKalemler();
    const kd = konfGetKd();
    const kdUa = konfGetKdUrunAgaci(siparis.id);
    const kdDok = _kdCache[`KD_DOKUMA_${siparis.id}`] || {};
    const uretimBlok = appMode === 'KONFEKSIYON_KESIM' ? '' : renderKonfUretimAgaciBlok(siparis, kalemler, kd, kdUa, kdDok);
    const islemRows = (_konfIslemLogCache[siparis.id] || []);
    const aktifTab = appMode === 'KONFEKSIYON_KESIM' ? 'KESİM'
        : appMode === 'KONFEKSIYON_YIKAMA' ? 'YIKAMA'
        : appMode === 'KONFEKSIYON_KALITE' ? 'KALİTE'
        : konfeksiyonTab;
    const globalPipelinePanel = appMode === 'KONFEKSIYON_KESIM'
            ? renderKonfGlobalKumasGelisPanel(konfeksiyonSiparisId)
            : appMode === 'KONFEKSIYON_YIKAMA'
            ? renderKonfGlobalYikamaPanel(konfeksiyonSiparisId)
            : appMode === 'KONFEKSIYON_KALITE'
                ? renderKonfGlobalKalitePanel(konfeksiyonSiparisId)
                : '';
    const tabs = {
        'ÖZET': renderKonfOzet(siparis,kalemler,kd),
        'KESİM': renderKonfKesim(siparis,kalemler,kd),
        'YIKAMA': renderKonfYikama(siparis,kalemler,kd),
        'DİKİM': renderKonfDikim(siparis,kalemler,kd),
        'KALİTE': renderKonfKalite(siparis,kalemler,kd),
        'KOLİ': renderKonfKoli(siparis,kalemler,kd),
        'KAPAMA': renderKonfKapama(siparis,kalemler,kd),
    };
    const altBaslik = appMode === 'KONFEKSIYON_KESIM' ? 'Kesim operasyonu'
        : appMode === 'KONFEKSIYON_YIKAMA' ? 'Yıkama operasyonu'
        : appMode === 'KONFEKSIYON_KALITE' ? 'Kalite operasyonu'
        : 'Operasyon girişi';
    const pipelineOnly = ['KONFEKSIYON_KESIM', 'KONFEKSIYON_YIKAMA', 'KONFEKSIYON_KALITE'].includes(appMode);
    return `<div style="display:flex;flex-direction:column;gap:10px">
        ${globalPipelinePanel}
        ${pipelineOnly ? '' : uretimBlok}
        ${pipelineOnly ? '' : (kd?.konf_last_save_ts ? `<div class="panel-box" style="padding:10px 12px;border:1px solid rgba(16,185,129,0.35);background:rgba(16,185,129,0.06);font-size:10px;color:var(--text2)">
            <b>Son kayıt:</b> ${pdfEsc(String(kd.konf_last_save_user || '—'))} · ${pdfEsc(new Date(kd.konf_last_save_ts).toLocaleString('tr-TR'))} <span style="color:var(--text3)">(${pdfEsc(String(kd.konf_last_save_tip || ''))})</span>
        </div>` : '')}
        ${pipelineOnly ? '' : `<div class="konf-data-banner">
            <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
                <div style="font-size:10px;font-weight:800;color:var(--text)">${pdfEsc(altBaslik)}</div>
                <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">sekme: ${pdfEsc(aktifTab || '')} · renk/ebat kalem seçimi</span>
            </div>
            ${konfIsAltMod() ? '' : '<div style="margin-top:4px;font-size:10px;color:var(--text2)">Üstteki üretim ağacı ürün ağacı + sevk ile hizalıdır. Aşağıdaki formlar kalıcı operasyon kaydıdır.</div>'}
        </div>`}
        ${pipelineOnly ? '' : (tabs[aktifTab] || '')}
        ${konfIsAltMod() ? '' : renderKonfSonKayitlar(islemRows)}
    </div>`;
}

function renderKonfPlanlamaIcerik() {
    const siparis = (dataCache.siparisler||[]).find(s=>s.id==konfeksiyonSiparisId);
    if (!siparis) return '<p class="text-slate-400 text-center p-8">Sipariş bulunamadı</p>';
    const kalemler = konfGetKalemler();
    const kd = konfGetKd();
    return `<div style="display:flex;flex-direction:column;gap:10px">
        <div class="konf-data-banner">
            <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
                <div style="font-size:10px;font-weight:800;color:var(--text)">Konfeksiyon Planlama</div>
                <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">dokuma + konfeksiyon verileri ile bağlı plan</span>
            </div>
            <div style="margin-top:4px;font-size:10px;color:var(--text2)">Bu ekran bağımsızdır; plan satırları sipariş kartı ile eş zamanlı saklanır.</div>
        </div>
        ${renderKonfPlanlama(siparis, kalemler, kd)}
    </div>`;
}

function konfPlanVarsayilanSatir(siparis, kalem, idx) {
    const now = new Date();
    const gunluk = now.toISOString().slice(0, 10);
    const haftalik = `${now.getFullYear()}-W${String(Math.ceil((((now - new Date(now.getFullYear(),0,1)) / 86400000) + new Date(now.getFullYear(),0,1).getDay() + 1) / 7)).padStart(2, '0')}`;
    const aylik = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return {
        id: `p_${Date.now()}_${idx}_${Math.floor(Math.random()*1000)}`,
        musteri: siparis?.firma || '',
        siparis_no: siparis?.sno || '',
        urun: String(kalem?.ad || kalem?.kod || `Kalem ${idx + 1}`),
        adet: parseInt(kalem?.miktar || 0, 10) || 0,
        gunluk,
        haftalik,
        aylik,
        program_asama: 'KESIM',
        kesim_gun: gunluk,
        dikim_gun: '',
        kalite_gun: '',
        sevk_gun: '',
        kesim: false,
        dikim: false,
        kalite: false,
        sevk: false,
        not: ''
    };
}

function konfPlanHaftaAnahtariFromGun(gunStr) {
    const d = new Date(gunStr);
    if (Number.isNaN(d.getTime())) return '';
    const y = d.getFullYear();
    const hafta = Math.ceil((((d - new Date(y, 0, 1)) / 86400000) + new Date(y, 0, 1).getDay() + 1) / 7);
    return `${y}-W${String(hafta).padStart(2, '0')}`;
}

function konfPlanHaftaEslesir(gunStr, haftaKey) {
    const h = String(haftaKey || '').trim();
    if (!h) return true;
    return konfPlanHaftaAnahtariFromGun(String(gunStr || '').trim()) === h;
}

function konfPlanErtesiGun(gunStr) {
    const s = String(gunStr || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return '';
    const d = new Date(`${s}T00:00:00`);
    if (Number.isNaN(d.getTime())) return '';
    d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
}

function konfPlanSatirAnaGun(row = {}) {
    const asamalar = [
        { tamam: !!row.kesim, gun: String(row.kesim_gun || '').trim() },
        { tamam: !!row.dikim, gun: String(row.dikim_gun || '').trim() },
        { tamam: !!row.kalite, gun: String(row.kalite_gun || '').trim() },
        { tamam: !!row.sevk, gun: String(row.sevk_gun || '').trim() }
    ];
    const bekleyen = asamalar.find(a => !a.tamam && a.gun);
    if (bekleyen) return bekleyen.gun;
    const dolu = asamalar.map(a => a.gun).filter(Boolean).sort();
    if (dolu.length) return dolu[0];
    return String(row.gunluk || '').trim();
}

function konfPlanRowsGet(siparis, kalemler, kd) {
    const rows = Array.isArray(kd?.konf_plan_rows) ? kd.konf_plan_rows : [];
    if (rows.length) return rows;
    return (kalemler || []).map((k, i) => konfPlanVarsayilanSatir(siparis, k, i));
}

async function konfPlanAlanGuncelle(rowId, alan, value) {
    if (!konfeksiyonSiparisId) return;
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    if (String(rowId) === 'FILTER') {
        kd[alan] = value;
        await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
        if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
        else renderKonfeksiyon();
        return;
    }
    const rows = Array.isArray(kd.konf_plan_rows) ? kd.konf_plan_rows : [];
    const idx = rows.findIndex(r => String(r.id) === String(rowId));
    if (idx === -1) return;
    rows[idx][alan] = value;
    kd.konf_plan_rows = rows;
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
}

async function konfPlanSatirEkle() {
    if (!konfeksiyonSiparisId) return;
    const siparis = (dataCache.siparisler || []).find(s => s.id == konfeksiyonSiparisId);
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    const rows = Array.isArray(kd.konf_plan_rows) ? kd.konf_plan_rows : [];
    rows.push(konfPlanVarsayilanSatir(siparis, {}, rows.length));
    kd.konf_plan_rows = rows;
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
    if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
    else renderKonfeksiyon();
}

async function konfPlanSatirSil(rowId) {
    if (!konfeksiyonSiparisId) return;
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    kd.konf_plan_rows = (Array.isArray(kd.konf_plan_rows) ? kd.konf_plan_rows : []).filter(r => String(r.id) !== String(rowId));
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
    if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
    else renderKonfeksiyon();
}

async function konfPlanKaydet() {
    if (!konfeksiyonSiparisId) return;
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    kd.konf_plan_updated_at = new Date().toISOString();
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
    alert('Konfeksiyon planı kaydedildi.');
}

async function konfPlanTamamlanmayanlariErtesiGuneKaydir(gunStr) {
    if (!konfeksiyonSiparisId) return;
    const kaynakGun = String(gunStr || '').trim();
    if (!kaynakGun) {
        alert('Önce gün seçin.');
        return;
    }
    const hedefGun = konfPlanErtesiGun(kaynakGun);
    if (!hedefGun) {
        alert('Geçerli bir gün bulunamadı.');
        return;
    }
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    const rows = Array.isArray(kd.konf_plan_rows) ? kd.konf_plan_rows : [];
    let tasinanAsama = 0;
    let etkilenenSatir = 0;
    const yeniRows = rows.map(r => {
        const row = { ...(r || {}) };
        let satirDegisti = false;
        const asamalar = [
            { tamamKey: 'kesim', gunKey: 'kesim_gun' },
            { tamamKey: 'dikim', gunKey: 'dikim_gun' },
            { tamamKey: 'kalite', gunKey: 'kalite_gun' },
            { tamamKey: 'sevk', gunKey: 'sevk_gun' }
        ];
        asamalar.forEach(a => {
            const tamam = !!row[a.tamamKey];
            const gun = String(row[a.gunKey] || '').trim();
            if (!tamam && gun === kaynakGun) {
                row[a.gunKey] = hedefGun;
                tasinanAsama += 1;
                satirDegisti = true;
            }
        });
        if (!satirDegisti) return r;
        etkilenenSatir += 1;
        const anaGun = konfPlanSatirAnaGun(row) || hedefGun;
        row.gunluk = anaGun;
        row.haftalik = konfPlanHaftaAnahtariFromGun(anaGun);
        row.aylik = anaGun.slice(0, 7);
        return row;
    });
    if (!tasinanAsama) {
        alert('Seçili günde ertesi güne taşınacak açık iş bulunamadı.');
        return;
    }
    kd.konf_plan_rows = yeniRows;
    if (String(kd.konf_plan_filter_gun || '').trim() === kaynakGun) {
        kd.konf_plan_filter_gun = hedefGun;
    }
    kd.konf_plan_updated_at = new Date().toISOString();
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
    if (appMode === 'KONFEKSIYON_PLANLAMA') renderKonfeksiyonPlanlama();
    else renderKonfeksiyon();
    alert(`${etkilenenSatir} satırdaki ${tasinanAsama} açık operasyon ${kaynakGun} tarihinden ${hedefGun} tarihine taşındı.`);
}

function renderKonfPlanlama(siparis, kalemler, kd) {
    const rawRows = konfPlanRowsGet(siparis, kalemler, kd);
    const rows = rawRows.map(r => {
        const gunluk = String(r.gunluk || '').trim();
        const haftalik = String(r.haftalik || '').trim() || (gunluk ? konfPlanHaftaAnahtariFromGun(gunluk) : '');
        const aylik = String(r.aylik || '').trim() || (gunluk ? gunluk.slice(0, 7) : '');
        return { ...r, gunluk, haftalik, aylik };
    });
    const gunler = [...new Set(rows.map(r => String(r.gunluk || '').trim()).filter(Boolean))].sort();
    const haftalar = [...new Set(rows.map(r => String(r.haftalik || '').trim()).filter(Boolean))];
    const aylar = [...new Set(rows.map(r => String(r.aylik || '').trim()).filter(Boolean))];
    const bugun = new Date().toISOString().slice(0, 10);
    const aktifGun = String(kd?.konf_plan_filter_gun || '').trim();
    const gunlukPanelGun = aktifGun || bugun;
    const aktifHafta = String(kd?.konf_plan_filter_hafta || '').trim();
    const aktifAy = String(kd?.konf_plan_filter_ay || '').trim();
    const gorunum = String(kd?.konf_plan_gorunum || 'GUNLUK').toUpperCase();
    const weekKeysForYear = (y) => {
        const out = [];
        for (let w = 1; w <= 53; w++) out.push(`${y}-W${String(w).padStart(2, '0')}`);
        return out;
    };
    const monthKeysForYear = (y) => {
        const out = [];
        for (let m = 1; m <= 12; m++) out.push(`${y}-${String(m).padStart(2, '0')}`);
        return out;
    };
    const mevcutYillar = [...new Set([
        ...haftalar.map(h => parseInt(String(h).slice(0, 4), 10)),
        ...aylar.map(a => parseInt(String(a).slice(0, 4), 10))
    ].filter(y => Number.isFinite(y) && y >= 2000 && y <= 2100))];
    const bugunYil = new Date().getFullYear();
    const yilAdaylari = [...new Set([bugunYil - 1, bugunYil, bugunYil + 1, ...mevcutYillar])].sort((a, b) => a - b);
    const haftaOpsiyonlari = [...new Set([
        ...haftalar,
        ...yilAdaylari.flatMap(y => weekKeysForYear(y))
    ])].sort();
    const ayOpsiyonlari = [...new Set([
        ...aylar,
        ...yilAdaylari.flatMap(y => monthKeysForYear(y))
    ])].sort();
    const filtreli = rows.filter(r => {
        if (aktifGun && String(r.gunluk || '') !== aktifGun) return false;
        if (aktifHafta && String(r.haftalik || '') !== aktifHafta) return false;
        if (aktifAy && String(r.aylik || '') !== aktifAy) return false;
        return true;
    });
    const gunlukYapilacak = rows.flatMap(r => {
        const out = [];
        if (!r.kesim && String(r.kesim_gun || '') === gunlukPanelGun) out.push({ ...r, plan_asama: 'Kesim' });
        if (!r.dikim && String(r.dikim_gun || '') === gunlukPanelGun) out.push({ ...r, plan_asama: 'Dikim' });
        if (!r.kalite && String(r.kalite_gun || '') === gunlukPanelGun) out.push({ ...r, plan_asama: 'Kalite/Paket' });
        if (!r.sevk && String(r.sevk_gun || '') === gunlukPanelGun) out.push({ ...r, plan_asama: 'Sevk' });
        return out;
    });
    const gunlukToplam = gunlukYapilacak.reduce((a, r) => a + (parseInt(r.adet || 0, 10) || 0), 0);
    const seciliHafta = aktifHafta || konfPlanHaftaAnahtariFromGun(gunlukPanelGun);
    const haftalikRows = rows.filter(r => String(r.haftalik || '') === seciliHafta);
    const operasyonlar = ['KESIM', 'DIKIM', 'KALITE', 'SEVK'];
    const opEtiket = { KESIM: 'Kesim', DIKIM: 'Dikim', KALITE: 'Kalite', SEVK: 'Sevk' };
    const opRenk = {
        KESIM: { bg: 'rgba(99,102,241,0.14)', border: 'rgba(99,102,241,0.35)', text: '#4338ca' },
        DIKIM: { bg: 'rgba(236,72,153,0.14)', border: 'rgba(236,72,153,0.35)', text: '#be185d' },
        KALITE: { bg: 'rgba(245,158,11,0.16)', border: 'rgba(245,158,11,0.35)', text: '#b45309' },
        SEVK:  { bg: 'rgba(16,185,129,0.14)', border: 'rgba(16,185,129,0.35)', text: '#047857' }
    };
    const haftaGunleri = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma'];
    const haftalikGunIndex = (gunStr) => {
        const d = new Date(gunStr);
        if (Number.isNaN(d.getTime())) return -1;
        const js = d.getDay();
        if (js === 0 || js === 6) return -1;
        return js - 1;
    };
    const haftalikGridRows = haftaGunleri.map((gunLabel, idx) => {
        const cells = operasyonlar.map(op => {
            const satirlar = haftalikRows.filter(r => {
                const g = op === 'KESIM' ? r.kesim_gun : op === 'DIKIM' ? r.dikim_gun : op === 'KALITE' ? r.kalite_gun : r.sevk_gun;
                if (!konfPlanHaftaEslesir(g, seciliHafta)) return false;
                return haftalikGunIndex(g) === idx;
            });
            return { op, satirlar };
        });
        return { gunLabel, cells };
    });
    const haftalikToplam = rows
        .filter(r => !aktifHafta || String(r.haftalik || '') === aktifHafta)
        .reduce((a, r) => a + (parseInt(r.adet || 0, 10) || 0), 0);
    const aylikToplam = rows
        .filter(r => !aktifAy || String(r.aylik || '') === aktifAy)
        .reduce((a, r) => a + (parseInt(r.adet || 0, 10) || 0), 0);
    const seciliAy = aktifAy || gunlukPanelGun.slice(0, 7);
    const ayBase = /^\d{4}-\d{2}$/.test(seciliAy) ? new Date(`${seciliAy}-01T00:00:00`) : new Date(`${gunlukPanelGun.slice(0,7)}-01T00:00:00`);
    const ayYil = ayBase.getFullYear();
    const ayNo = ayBase.getMonth();
    const ayinSonGunu = new Date(ayYil, ayNo + 1, 0).getDate();
    const aylikGridRows = [];
    for (let d = 1; d <= ayinSonGunu; d++) {
        const dt = new Date(ayYil, ayNo, d);
        const w = dt.getDay();
        if (w === 0 || w === 6) continue; // hafta sonu yok
        const iso = `${ayYil}-${String(ayNo + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const label = `${String(d).padStart(2, '0')}.${String(ayNo + 1).padStart(2, '0')}.${ayYil}`;
        const cells = operasyonlar.map(op => {
            const satirlar = rows.filter(r => {
                const g = op === 'KESIM' ? r.kesim_gun : op === 'DIKIM' ? r.dikim_gun : op === 'KALITE' ? r.kalite_gun : r.sevk_gun;
                return String(g || '') === iso;
            });
            return { op, satirlar };
        });
        aylikGridRows.push({ dateIso: iso, dateLabel: label, cells });
    }
    return `<div class="panel-box" style="padding:12px 14px">
        <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px">
            <span class="pill pill-cyan">${pdfEsc(siparis?.sno || '—')}${siparis?.sno && siparis?.firma ? ' · ' : ''}${pdfEsc(siparis?.firma || '—')}</span>
            <span class="pill pill-gray">Satır: ${rows.length}</span>
            <span class="pill pill-amber">Toplam adet: ${rows.reduce((a,r)=>a+(parseInt(r.adet||0,10)||0),0).toLocaleString('tr-TR')}</span>
            <button onclick="konfPlanSatirEkle()" class="btn-pro btn-ghost-pro" style="margin-left:auto;padding:6px 10px;font-size:10px">＋ Satır Ekle</button>
            <button onclick="konfPlanKaydet()" class="btn-pro btn-primary-pro" style="padding:6px 10px;font-size:10px">💾 Planı Kaydet</button>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">
            <div style="display:flex;border:1px solid var(--border);border-radius:10px;overflow:hidden">
                <button onclick="konfPlanAlanGuncelle('FILTER','konf_plan_gorunum','GUNLUK')" class="btn-pro" style="padding:6px 10px;font-size:10px;border-radius:0;background:${gorunum==='GUNLUK'?'var(--accent2)':'var(--surface2)'};color:${gorunum==='GUNLUK'?'#fff':'var(--text2)'}">Günlük</button>
                <button onclick="konfPlanAlanGuncelle('FILTER','konf_plan_gorunum','HAFTALIK')" class="btn-pro" style="padding:6px 10px;font-size:10px;border-radius:0;background:${gorunum==='HAFTALIK'?'var(--accent2)':'var(--surface2)'};color:${gorunum==='HAFTALIK'?'#fff':'var(--text2)'}">Haftalık</button>
                <button onclick="konfPlanAlanGuncelle('FILTER','konf_plan_gorunum','AYLIK')" class="btn-pro" style="padding:6px 10px;font-size:10px;border-radius:0;background:${gorunum==='AYLIK'?'var(--accent2)':'var(--surface2)'};color:${gorunum==='AYLIK'?'#fff':'var(--text2)'}">Aylık</button>
            </div>
            <select class="pro-input" style="min-width:130px;padding:6px 8px;font-size:10px" onchange="konfPlanAlanGuncelle('FILTER','konf_plan_filter_gun',this.value)">
                <option value="">Tüm Günler</option>
                ${gunler.map(g=>`<option value="${erpAttr(g)}" ${aktifGun===g?'selected':''}>${pdfEsc(g)}</option>`).join('')}
            </select>
            <select class="pro-input" style="min-width:140px;padding:6px 8px;font-size:10px" onchange="konfPlanAlanGuncelle('FILTER','konf_plan_filter_hafta',this.value)">
                <option value="">Tüm Haftalar</option>
                ${haftaOpsiyonlari.map(h=>`<option value="${erpAttr(h)}" ${aktifHafta===h?'selected':''}>${pdfEsc(h)}</option>`).join('')}
            </select>
            <select class="pro-input" style="min-width:120px;padding:6px 8px;font-size:10px" onchange="konfPlanAlanGuncelle('FILTER','konf_plan_filter_ay',this.value)">
                <option value="">Tüm Aylar</option>
                ${ayOpsiyonlari.map(a=>`<option value="${erpAttr(a)}" ${aktifAy===a?'selected':''}>${pdfEsc(a)}</option>`).join('')}
            </select>
            <input type="week" class="pro-input" style="min-width:140px;padding:6px 8px;font-size:10px" value="${pdfEsc((aktifHafta || '').replace('-W', '-W'))}" onchange="konfPlanAlanGuncelle('FILTER','konf_plan_filter_hafta',this.value ? this.value.replace('-W','-W') : '')" title="Haftayı takvimden seç">
            <input type="month" class="pro-input" style="min-width:120px;padding:6px 8px;font-size:10px" value="${pdfEsc(aktifAy || '')}" onchange="konfPlanAlanGuncelle('FILTER','konf_plan_filter_ay',this.value)" title="Ayı takvimden seç">
        </div>
        <div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:10px">
            <div class="panel-box" style="padding:10px;background:var(--surface2)">
                <div style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">Günlük (${pdfEsc(gunlukPanelGun)})</div>
                <div style="font-size:18px;font-weight:800;color:var(--accent2)">${gunlukToplam.toLocaleString('tr-TR')}</div>
            </div>
            <div class="panel-box" style="padding:10px;background:var(--surface2)">
                <div style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">Haftalık (${pdfEsc(aktifHafta || 'Tümü')})</div>
                <div style="font-size:18px;font-weight:800;color:var(--cyan-c)">${haftalikToplam.toLocaleString('tr-TR')}</div>
            </div>
            <div class="panel-box" style="padding:10px;background:var(--surface2)">
                <div style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">Aylık (${pdfEsc(aktifAy || 'Tümü')})</div>
                <div style="font-size:18px;font-weight:800;color:var(--emerald-c)">${aylikToplam.toLocaleString('tr-TR')}</div>
            </div>
        </div>
        <div class="panel-box" style="padding:10px;margin-bottom:10px;background:rgba(109,113,255,0.08);display:${gorunum==='GUNLUK'?'block':'none'}">
            <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px">
                <div style="font-size:10px;font-weight:800;color:var(--text2)">Günlük yapılacaklar (${pdfEsc(gunlukPanelGun)})</div>
                <button onclick="konfPlanTamamlanmayanlariErtesiGuneKaydir('${erpAttr(gunlukPanelGun)}')" class="btn-pro" style="padding:5px 9px;font-size:10px">
                    Tamamlanmayanlari ertesi gune kaydir
                </button>
            </div>
            ${gunlukYapilacak.length ? `<div style="display:flex;flex-direction:column;gap:6px">
                ${gunlukYapilacak.map(r=>`<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;border:1px solid var(--border);background:var(--surface);border-radius:8px;padding:6px 8px">
                    <span style="font-size:10px;font-weight:700;color:var(--text)">${pdfEsc(r.urun || '-')}</span>
                    <span class="pill pill-gray">${(parseInt(r.adet||0,10)||0).toLocaleString('tr-TR')} adet</span>
                    <span style="font-size:10px;color:var(--text2)">${pdfEsc(r.musteri || '-')}</span>
                    <span style="font-size:9px;color:var(--rose-c);font-family:'DM Mono',monospace">Aşama: ${pdfEsc(r.plan_asama || '-')}</span>
                </div>`).join('')}
            </div>` : `<div style="font-size:10px;color:var(--text3)">Seçili gün için açık iş kalemi yok.</div>`}
        </div>
        <div class="panel-box" style="padding:10px;margin-bottom:10px;display:${gorunum==='HAFTALIK'?'block':'none'}">
            <div style="font-size:10px;font-weight:800;color:var(--text2);margin-bottom:8px">Haftalık operasyon programı (${pdfEsc(seciliHafta || 'Hafta seçin')})</div>
            <div style="font-size:10px;color:var(--text3);margin-bottom:8px">Solda günler, üstte operasyonlar vardır. Her kutuda o güne düşen işler listelenir.</div>
            <div style="overflow:auto;border:1px solid var(--border);border-radius:10px;background:var(--surface2)">
                <table class="dt-table" style="min-width:1100px;border-collapse:collapse">
                    <thead>
                        <tr>
                            <th style="min-width:130px">Gün</th>
                            ${operasyonlar.map(op => `<th style="min-width:220px;background:${opRenk[op].bg};color:${opRenk[op].text};border-bottom:1px solid ${opRenk[op].border}">${pdfEsc(opEtiket[op] || op)}</th>`).join('')}
                        </tr>
                    </thead>
                    <tbody>
                        ${haftalikGridRows.map(row => `<tr>
                            <td style="vertical-align:top;font-weight:800;color:var(--text2);font-size:11px;background:var(--surface)">${pdfEsc(row.gunLabel)}</td>
                            ${row.cells.map(cell => `<td style="vertical-align:top;background:${opRenk[cell.op].bg}">
                                ${cell.satirlar.length ? `<div style="display:flex;flex-direction:column;gap:6px">
                                    ${cell.satirlar.map(r=>`<div style="border:1px solid ${opRenk[cell.op].border};border-radius:6px;background:var(--surface);padding:6px">
                                        <div style="font-size:10px;font-weight:700;color:var(--text)">${pdfEsc(r.urun || '-')}</div>
                                        <div style="font-size:9px;color:var(--text2)">${pdfEsc(r.musteri || '-')} · ${(parseInt(r.adet||0,10)||0).toLocaleString('tr-TR')} adet</div>
                                        <div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">${pdfEsc(r.siparis_no || '-')}</div>
                                    </div>`).join('')}
                                </div>` : `<div style="font-size:9px;color:var(--text3)">—</div>`}
                            </td>`).join('')}
                        </tr>`).join('')}
                    </tbody>
                </table>
            </div>
        </div>
        <div class="panel-box" style="padding:10px;margin-bottom:10px;display:${gorunum==='AYLIK'?'block':'none'}">
            <div style="font-size:10px;font-weight:800;color:var(--text2);margin-bottom:8px">Aylık operasyon programı (${pdfEsc(seciliAy || 'Ay seçin')})</div>
            <div style="font-size:10px;color:var(--text3);margin-bottom:8px">Haftalık görünüm ile aynı tablo yapısı kullanılır. Cumartesi/Pazar görünmez.</div>
            <div style="overflow:auto;border:1px solid var(--border);border-radius:10px;background:var(--surface2)">
                <table class="dt-table" style="min-width:1100px;border-collapse:collapse">
                    <thead>
                        <tr>
                            <th style="min-width:130px">Tarih</th>
                            ${operasyonlar.map(op => `<th style="min-width:220px;background:${opRenk[op].bg};color:${opRenk[op].text};border-bottom:1px solid ${opRenk[op].border}">${pdfEsc(opEtiket[op] || op)}</th>`).join('')}
                        </tr>
                    </thead>
                    <tbody>
                        ${aylikGridRows.map(row => `<tr>
                            <td style="vertical-align:top;font-weight:800;color:var(--text2);font-size:11px;background:var(--surface)">${pdfEsc(row.dateLabel)}</td>
                            ${row.cells.map(cell => `<td style="vertical-align:top;background:${opRenk[cell.op].bg}">
                                ${cell.satirlar.length ? `<div style="display:flex;flex-direction:column;gap:6px">
                                    ${cell.satirlar.map(r=>`<div style="border:1px solid ${opRenk[cell.op].border};border-radius:6px;background:var(--surface);padding:6px">
                                        <div style="font-size:10px;font-weight:700;color:var(--text)">${pdfEsc(r.urun || '-')}</div>
                                        <div style="font-size:9px;color:var(--text2)">${pdfEsc(r.musteri || '-')} · ${(parseInt(r.adet||0,10)||0).toLocaleString('tr-TR')} adet</div>
                                        <div style="font-size:8px;color:var(--text3);font-family:'DM Mono',monospace">${pdfEsc(r.siparis_no || '-')}</div>
                                    </div>`).join('')}
                                </div>` : `<div style="font-size:9px;color:var(--text3)">—</div>`}
                            </td>`).join('')}
                        </tr>`).join('')}
                    </tbody>
                </table>
            </div>
        </div>
        <div style="overflow:auto;border:1px solid var(--border);border-radius:10px">
            <table class="dt-table" style="min-width:1380px;border-collapse:separate;border-spacing:2px">
                <thead>
                    <tr>
                        <th style="padding:4px 6px;font-size:9px;white-space:nowrap">Müşteri</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Sipariş</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Ürün</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Adet</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Kesim Günü</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Dikim Günü</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Kalite/Paket Günü</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Sevk Günü</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Hafta</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Ay</th>
                        <th style="padding:4px 6px;font-size:9px;white-space:nowrap">Kesim</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Dikim</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Kalite</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Sevk</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap">Not</th><th style="padding:4px 6px;font-size:9px;white-space:nowrap"></th>
                    </tr>
                </thead>
                <tbody>
                    ${filtreli.map(r=>`<tr>
                        <td><input class="pro-input" style="padding:2px 4px;font-size:10px;min-width:82px" value="${pdfEsc(r.musteri||'')}" oninput="konfPlanAlanGuncelle('${r.id}','musteri',this.value)"></td>
                        <td><input class="pro-input" style="padding:2px 4px;font-size:10px;min-width:72px" value="${pdfEsc(r.siparis_no||'')}" oninput="konfPlanAlanGuncelle('${r.id}','siparis_no',this.value)"></td>
                        <td><input class="pro-input" style="padding:2px 4px;font-size:10px;min-width:74px" value="${pdfEsc(r.urun||'')}" oninput="konfPlanAlanGuncelle('${r.id}','urun',this.value)"></td>
                        <td><input type="number" class="pro-input" style="padding:2px 4px;font-size:10px;min-width:96px;max-width:110px" value="${pdfEsc(r.adet||0)}" oninput="konfPlanAlanGuncelle('${r.id}','adet',parseInt(this.value||0,10)||0)"></td>
                        <td><input type="date" class="pro-input" style="padding:2px 4px;font-size:10px;max-width:116px" value="${pdfEsc(r.kesim_gun||'')}" oninput="konfPlanAlanGuncelle('${r.id}','kesim_gun',this.value)"></td>
                        <td><input type="date" class="pro-input" style="padding:2px 4px;font-size:10px;max-width:116px" value="${pdfEsc(r.dikim_gun||'')}" oninput="konfPlanAlanGuncelle('${r.id}','dikim_gun',this.value)"></td>
                        <td><input type="date" class="pro-input" style="padding:2px 4px;font-size:10px;max-width:122px" value="${pdfEsc(r.kalite_gun||'')}" oninput="konfPlanAlanGuncelle('${r.id}','kalite_gun',this.value)"></td>
                        <td><input type="date" class="pro-input" style="padding:2px 4px;font-size:10px;max-width:116px" value="${pdfEsc(r.sevk_gun||'')}" oninput="konfPlanAlanGuncelle('${r.id}','sevk_gun',this.value)"></td>
                        <td><input class="pro-input" style="padding:2px 4px;font-size:10px;max-width:92px" value="${pdfEsc(r.haftalik||'')}" placeholder="2026-W18" oninput="konfPlanAlanGuncelle('${r.id}','haftalik',this.value)"></td>
                        <td><input type="month" class="pro-input" style="padding:2px 4px;font-size:10px;max-width:96px" value="${pdfEsc(r.aylik||'')}" oninput="konfPlanAlanGuncelle('${r.id}','aylik',this.value)"></td>
                        <td><input type="checkbox" ${r.kesim?'checked':''} onchange="konfPlanAlanGuncelle('${r.id}','kesim',this.checked)"></td>
                        <td><input type="checkbox" ${r.dikim?'checked':''} onchange="konfPlanAlanGuncelle('${r.id}','dikim',this.checked)"></td>
                        <td><input type="checkbox" ${r.kalite?'checked':''} onchange="konfPlanAlanGuncelle('${r.id}','kalite',this.checked)"></td>
                        <td><input type="checkbox" ${r.sevk?'checked':''} onchange="konfPlanAlanGuncelle('${r.id}','sevk',this.checked)"></td>
                        <td><input class="pro-input" style="padding:2px 4px;font-size:10px;min-width:130px" value="${pdfEsc(r.not||'')}" oninput="konfPlanAlanGuncelle('${r.id}','not',this.value)"></td>
                        <td><button class="btn-pro btn-danger-pro" style="padding:3px 6px;font-size:10px" onclick="konfPlanSatirSil('${r.id}')">Sil</button></td>
                    </tr>`).join('')}
                </tbody>
            </table>
        </div>
    </div>`;
}

function renderKonfOzet(siparis,kalemler,kd) {
    const kdUa = konfGetKdUrunAgaci(siparis.id);
    const kdDok = _kdCache[`KD_DOKUMA_${siparis.id}`] || {};
    const islemRows = (_konfIslemLogCache[siparis.id] || []);
    return `<div style="display:flex;flex-direction:column;gap:12px;width:100%">
    <div class="panel-box" style="width:100%;overflow:hidden;box-sizing:border-box">
        <div class="panel-head">
            <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent2)"></span>Detaylı sipariş — ürün ağacı endeksli</span>
            <span style="font-size:9px;color:var(--text3);font-family:'DM Mono',monospace">kalem × aşama (Ü.A. + sevk) · dokuma · operasyon</span>
        </div>
        <div style="padding:12px 14px 16px;box-sizing:border-box;max-height:min(92vh,980px);overflow:auto">
            ${buildSiparisDurumIncelemeHtml(siparis, kd, kdDok, islemRows, kdUa)}
        </div>
    </div>
    ${renderKonfIsAkisGantt(siparis.id)}
    </div>`;
}

function renderKonfSonKayitlar(islemRows = []) {
    return `<div class="panel-box" style="width:100%;align-self:stretch;box-sizing:border-box;overflow:hidden">
        <div class="panel-head" style="flex-wrap:wrap;gap:10px;padding:14px 18px">
            <span class="panel-head-title"><span class="panel-head-dot" style="background:var(--accent2)"></span>Son kayıtlar</span>
            <span style="font-size:11px;color:var(--text3);font-family:'DM Mono',monospace">${islemRows.length} kayıt · miktar girişlerinde ↩ Sil ile geri alınır</span>
        </div>
        <div style="width:100%;overflow-x:auto;overflow-y:auto;max-height:min(85vh,960px);padding:12px 16px 20px;box-sizing:border-box">
            <table class="dt-table" style="min-width:1200px;width:max(100%,1200px);font-size:13px;border-collapse:collapse">
                <thead>
                    <tr>
                        <th style="text-align:left;padding:12px 14px;white-space:nowrap">Tarih / Saat</th>
                        <th style="text-align:left;padding:12px 14px;min-width:120px">Kullanıcı</th>
                        <th style="text-align:left;padding:12px 14px;min-width:100px">İşlem</th>
                        <th style="text-align:left;padding:12px 14px;min-width:180px">Kalem</th>
                        <th style="text-align:right;padding:12px 14px;white-space:nowrap">Miktar</th>
                        <th style="text-align:left;padding:12px 14px;min-width:280px">Not</th>
                        <th style="text-align:center;padding:12px 10px;white-space:nowrap;width:88px">Geri al</th>
                    </tr>
                </thead>
                <tbody>
                    ${islemRows.length ? islemRows.map(r => `
                    <tr style="border-bottom:1px solid var(--border)">
                        <td style="font-family:'DM Mono',monospace;color:var(--text2);padding:12px 14px;vertical-align:top;font-size:12px">${pdfEsc(new Date(r.ts || r.created_at).toLocaleString('tr-TR'))}</td>
                        <td style="font-weight:600;padding:12px 14px;vertical-align:top;line-height:1.4">${pdfEsc(r.kullanici || '-')}</td>
                        <td style="padding:12px 14px;vertical-align:top"><span class="pill" style="font-size:11px">${pdfEsc(r.islem || '-')}</span></td>
                        <td style="padding:12px 14px;vertical-align:top;word-break:break-word;line-height:1.45">${pdfEsc(r.kalem_ad || '-')}</td>
                        <td style="text-align:right;font-family:'DM Mono',monospace;padding:12px 14px;vertical-align:top;font-weight:600">${String(r.islem || '') === 'KONF_LOG' ? '-' : (parseFloat(r.miktar || 0) || 0).toLocaleString('tr-TR')}</td>
                        <td style="color:var(--text2);padding:12px 14px;vertical-align:top;line-height:1.5;word-break:break-word;max-width:480px">
                            <div>${pdfEsc(r.not || '-')}</div>
                            ${r.detay_text ? `<div style="margin-top:6px;font-size:11px;color:var(--text3);font-family:'DM Mono',monospace">${pdfEsc(r.detay_text)}</div>` : ''}
                        </td>
                        <td style="padding:12px 10px;vertical-align:top;text-align:center">
                            ${konfGirisKaydiSilinebilir(r) ? `<button type="button" class="btn-pro btn-danger-pro" style="padding:5px 10px;font-size:10px;white-space:nowrap" title="Bu girişi geri al" onclick="konfGirisKaydiSil('${erpAttr(String(r.id))}')">↩ Sil</button>` : '<span style="font-size:10px;color:var(--text3)">—</span>'}
                        </td>
                    </tr>`).join('') : `<tr><td colspan="7" style="padding:32px;text-align:center;color:var(--text3);font-size:13px">Henüz operasyon girişi yok.</td></tr>`}
                </tbody>
            </table>
        </div>
    </div>`;
}

function renderKonfKesim(siparis,kalemler,kd) {
    return `<div style="display:flex;flex-direction:column;gap:12px">
    <div class="panel-box" style="padding:16px 20px">
        <div class="text-[10px] font-bold uppercase tracking-widest mb-4">✂️ Kesim Bilgileri</div>
        <div class="space-y-3">
            <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
                <div><label class="pro-label">Kesim Tarihi</label>
                    <input id="kf-kesim-tarih" type="date" class="pro-input" value="${kd.kesim_tarih||''}"></div>
                <div><label class="pro-label">Operatör / Hat</label>
                    <input id="kf-kesim-operator" class="pro-input" placeholder="Operatör adı" value="${kd.kesim_operator||''}"></div>
            </div>
            <div><label class="pro-label">Kesim Notu</label>
                <textarea id="kf-kesim-not" class="pro-input" rows="3" placeholder="Not...">${kd.kesim_not||''}</textarea></div>
        </div>
    </div>
    <div class="panel-box">
        <div class="panel-head"><span class="panel-head-title"><span class="panel-head-dot" style="background:var(--text3)"></span>✂️ Beden Bazlı Kesim</span></div>
        <div class="p-4 space-y-2">
            ${kalemler.map((k,i)=>{const kkd=kd[`kalem_${i}`]||{}; const birim = siparisKalemBirim(k).toLowerCase(); return `
            <div class="flex items-center gap-4 p-3 rounded-xl flex-wrap konf-data-row">
                <div class="flex-1 min-w-0">
                    <span class="konf-data-kalem">${k.renk||'RENK YOK'} · ${k.ebat||'EBAT YOK'}</span><span class="font-bold">${k.ad||k.kod||'—'}</span>
                    <span class="text-[9px] text-slate-400 ml-2">${k.renk||''} ${k.ebat||''}</span>
                    <span class="text-[9px] text-slate-500 ml-2">· Sipariş: ${k.miktar||0} ${birim}</span>
                </div>
                <div class="flex flex-col items-end gap-0.5">
                    <label class="text-[9px] font-black text-violet-600">Kesilen ekle:</label>
                    <div class="flex items-center gap-1">
                        <input type="number" placeholder="+${birim}" min="0" data-kalem="${i}" data-alan="kesilen"
                            onchange="konfKalemGuncelle(${i},'kesilen',this.value)"
                            class="konf-num-input font-black text-violet-700 bg-white border border-violet-200 rounded-lg px-2 py-1 text-[10px] outline-none">
                        <span class="text-[9px] font-black text-violet-400 bg-violet-50 px-2 py-1 rounded-lg min-w-12 text-center">&#x2211; ${kkd.kesilen||0}</span>
                    </div>
                </div>
                <div class="flex flex-col items-end gap-0.5">
                    <label class="text-[9px] font-black text-rose-500">Fire ekle:</label>
                    <div class="flex items-center gap-1">
                        <input type="number" placeholder="+${birim}" min="0" data-kalem="${i}" data-alan="fire_kesim"
                            onchange="konfKalemGuncelle(${i},'fire_kesim',this.value)"
                            class="konf-num-input font-black text-rose-600 bg-white border border-rose-200 rounded-lg px-2 py-1 text-[10px] outline-none">
                        <span class="text-[9px] font-black text-rose-400 bg-rose-50 px-2 py-1 rounded-lg min-w-10 text-center">&#x2211; ${kkd.fire_kesim||0}</span>
                    </div>
                </div>
            </div>`;}).join('')}
        </div>
    </div>
    <button onclick="konfKaydet('kesim')" class="btn-pro btn-primary-pro" style="width:100%;justify-content:center;padding:10px">💾 KESİM BİLGİLERİNİ KAYDET</button>
    </div>`;
}

function renderKonfDikim(siparis,kalemler,kd) {
    const aksKalemler=[
        {id:'dugme',label:'Düğme',birim:'adet'},
        {id:'fermuar',label:'Fermuar',birim:'adet'},
        {id:'etiket',label:'Etiket',birim:'adet'},
        {id:'ipe',label:'İpe/Biye',birim:'mt'},
        {id:'diger_ak',label:'Diğer',birim:'adet'},
    ];
    return `<div style="display:flex;flex-direction:column;gap:12px">
    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px">
        <div class="panel-box" style="padding:16px 20px">
            <div class="text-[10px] font-bold uppercase tracking-widest mb-4">🧵 Dikim Bilgileri</div>
            <div class="space-y-3">
                <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
                    <div><label class="pro-label">Başlangıç</label>
                        <input id="kf-dikim-bas" type="date" class="pro-input" value="${kd.dikim_bas||''}"></div>
                    <div><label class="pro-label">Tahmini Bitiş</label>
                        <input id="kf-dikim-bit" type="date" class="pro-input" value="${kd.dikim_bit||''}"></div>
                </div>
                <div><label class="pro-label">Hat / Atölye</label>
                    <input id="kf-dikim-hat" class="pro-input" placeholder="Üretim hattı" value="${kd.dikim_hat||''}"></div>
                <div><label class="pro-label">Operatör Sayısı</label>
                    <input id="kf-dikim-operator-sayi" type="number" class="pro-input" placeholder="0" value="${kd.dikim_operator_sayi||''}"></div>
                <div><label class="pro-label">Not</label>
                    <textarea id="kf-dikim-not" class="pro-input" rows="2">${kd.dikim_not||''}</textarea></div>
            </div>
        </div>
        <div class="panel-box" style="padding:16px 20px">
            <div class="text-[10px] font-bold uppercase tracking-widest mb-4">📌 Aksesuar Takibi</div>
            <div class="space-y-2">
                <div class="grid grid-cols-4 gap-1 mb-1">
                    <span class="text-[8px] font-black text-slate-400 uppercase">Tür</span>
                    <span class="text-[8px] font-black text-slate-400 uppercase text-center">Gelen</span>
                    <span class="text-[8px] font-black text-pink-500 uppercase text-center">Kullanılan</span>
                    <span class="text-[8px] font-black text-emerald-500 uppercase text-center">Kalan</span>
                </div>
                ${aksKalemler.map(ak=>{
                    const g=parseInt(kd['ak_'+ak.id+'_gelen']||0);
                    const kk=parseInt(kd['ak_'+ak.id+'_kullanilan']||0);
                    return `<div class="grid grid-cols-4 gap-1 items-center">
                        <span class="text-[9px] font-black text-slate-600">${ak.label}</span>
                        <input type="number" value="${g||''}" placeholder="0"
                            onchange="konfAksesuarGuncelle('${ak.id}','gelen',this.value)"
                            class="text-center text-[10px] font-black bg-slate-50 border border-slate-200 rounded-lg px-1 py-1 outline-none">
                        <input type="number" value="${kk||''}" placeholder="0"
                            onchange="konfAksesuarGuncelle('${ak.id}','kullanilan',this.value)"
                            class="text-center text-[10px] font-black bg-pink-50 border border-pink-200 rounded-lg px-1 py-1 outline-none text-pink-700">
                        <div class="text-center text-[10px] font-black ${(g-kk)>0?'text-emerald-600':(g-kk)<0?'text-rose-600':'text-slate-400'} bg-emerald-50 border border-emerald-100 rounded-lg py-1">${(g-kk).toLocaleString()}</div>
                    </div>`;
                }).join('')}
            </div>
        </div>
    </div>
    <div class="panel-box">
        <div class="panel-head"><span class="panel-head-title"><span class="panel-head-dot" style="background:var(--text3)"></span>🧵 Beden Bazlı Dikim</span></div>
        <div class="p-4 space-y-2">
            ${kalemler.map((k,i)=>{const kkd=kd[`kalem_${i}`]||{}; const birim = siparisKalemBirim(k).toLowerCase(); return `
            <div class="flex items-center gap-4 p-3 rounded-xl flex-wrap konf-data-row">
                <div class="flex-1 min-w-0">
                    <span class="konf-data-kalem">${k.renk||'RENK YOK'} · ${k.ebat||'EBAT YOK'}</span><span class="font-bold">${k.ad||k.kod||'—'}</span>
                    <span class="text-[9px] text-slate-400 ml-2">${k.renk||''} ${k.ebat||''}</span>
                    <span class="text-[9px] text-violet-500 ml-2">· Kesilen: ${kkd.kesilen||0}</span>
                </div>
                <div class="flex flex-col items-end gap-0.5">
                    <label class="text-[9px] font-black text-pink-600">Dikilen ekle:</label>
                    <div class="flex items-center gap-1">
                        <input type="number" placeholder="+${birim}" min="0" data-kalem="${i}" data-alan="dikilen"
                            onchange="konfKalemGuncelle(${i},'dikilen',this.value)"
                            class="konf-num-input font-black text-pink-700 bg-white border border-pink-200 rounded-lg px-2 py-1 text-[10px] outline-none">
                        <span class="text-[9px] font-black text-pink-400 bg-pink-50 px-2 py-1 rounded-lg min-w-12 text-center">&#x2211; ${kkd.dikilen||0}</span>
                    </div>
                </div>
                <div class="flex flex-col items-end gap-0.5">
                    <label class="text-[9px] font-black text-rose-500">Fire ekle:</label>
                    <div class="flex items-center gap-1">
                        <input type="number" placeholder="+${birim}" min="0" data-kalem="${i}" data-alan="fire_dikim"
                            onchange="konfKalemGuncelle(${i},'fire_dikim',this.value)"
                            class="konf-num-input font-black text-rose-600 bg-white border border-rose-200 rounded-lg px-2 py-1 text-[10px] outline-none">
                        <span class="text-[9px] font-black text-rose-400 bg-rose-50 px-2 py-1 rounded-lg min-w-10 text-center">&#x2211; ${kkd.fire_dikim||0}</span>
                    </div>
                </div>
            </div>`;}).join('')}
        </div>
    </div>
    <button onclick="konfKaydet('dikim')" class="btn-pro btn-primary-pro" style="width:100%;justify-content:center;padding:10px">💾 DİKİM BİLGİLERİNİ KAYDET</button>
    </div>`;
}

function renderKonfKalite(siparis,kalemler,kd) {
    return `<div style="display:flex;flex-direction:column;gap:12px">
    <div class="panel-box" style="padding:16px 20px">
        <div class="text-[10px] font-bold uppercase tracking-widest mb-4">🔍 Kalite Kontrol Genel</div>
        <div style="margin-bottom:10px;padding:8px 10px;border:1px solid rgba(245,158,11,0.35);background:rgba(245,158,11,0.08);border-radius:10px;font-size:10px;color:var(--text2)">
            <b>2. Kalite:</b> Sebep seçin, adedi girin ve <b>Ekle</b> ile kaydedin.
        </div>
        <div class="grid grid-cols-2 lg:grid-cols-4 gap-3">
            <div><label class="pro-label">KK Tarihi</label>
                <input id="kf-kk-tarih" type="date" class="pro-input" value="${kd.kk_tarih||''}"></div>
            <div><label class="pro-label">Kontrol Eden</label>
                <input id="kf-kk-personel" class="pro-input" placeholder="Ad Soyad" value="${kd.kk_personel||''}"></div>
            <div><label class="pro-label">Yöntem</label>
                <select id="kf-kk-yontem" class="pro-input">
                    <option ${kd.kk_yontem==='%100'?'selected':''}>%100 Kontrol</option>
                    <option ${kd.kk_yontem==='Örnekleme'?'selected':''}>Örnekleme</option>
                    <option ${kd.kk_yontem==='AQL'?'selected':''}>AQL Standardı</option>
                </select></div>
            <div><label class="pro-label">Durum</label>
                <select id="kf-kk-durum" class="pro-input">
                    <option ${kd.kk_durum==='Devam Ediyor'?'selected':''}>Devam Ediyor</option>
                    <option ${kd.kk_durum==='Tamamlandı'?'selected':''}>Tamamlandı</option>
                </select></div>
        </div>
    </div>
    <div class="panel-box">
        <div class="panel-head"><span class="panel-head-title"><span class="panel-head-dot" style="background:var(--text3)"></span>🔍 Beden Bazlı Kalite Kontrol</span></div>
        <div class="overflow-x-auto"><table class="w-full text-[10px]">
            <thead style="background:var(--surface2)"><tr>
                <th class="text-left px-4 py-2 font-bold">Ürün</th>
                <th class="text-right px-4 py-2 font-bold">Dikilen</th>
                <th class="text-right px-4 py-2 font-black text-emerald-600">KK Geçen</th>
                <th class="text-right px-4 py-2 font-black text-amber-600">2. Kalite</th>
                <th class="text-right px-4 py-2 font-black text-blue-600">Tamire</th>
                <th class="text-right px-4 py-2 font-black text-rose-600">İmha</th>
                <th class="text-right px-4 py-2 font-black text-slate-400">Fire %</th>
            </tr></thead>
            <tbody >
                ${kalemler.map((k,i)=>{
                    const kkd=kd[`kalem_${i}`]||{};
                    const dik=parseInt(kkd.dikilen||0);
                    const ikiDet = konfIkinciKaliteDetayNorm(kkd.iki_kalite_detay || {});
                    const ikiTop = konfIkinciKaliteDetayToplam(ikiDet) || parseInt(kkd.iki_kalite||0);
                    const hatali=ikiTop+parseInt(kkd.tamir||0)+parseInt(kkd.imha||0);
                    const fp=dik>0?Math.round(hatali/dik*100):0;
                    return `<tr >
                        <td class="px-4 py-2"><div class="font-bold">${k.ad||k.kod||'—'}</div><div class="text-[8px] text-slate-400">${k.renk||''} ${k.ebat||''}</div></td>
                        <td class="px-4 py-2 text-right font-bold text-slate-600">${dik}</td>
                        <td class="px-4 py-2 text-right"><div class="flex flex-col items-end gap-0.5"><input type="number" placeholder="+ekle" min="0" data-kalem="${i}" data-alan="kk_gecen" onchange="konfKalemGuncelle(${i},'kk_gecen',this.value)" class="konf-num-input font-black text-emerald-700 bg-emerald-50 border border-emerald-200 rounded-lg px-1 py-0.5 outline-none"><span class="text-[8px] font-black text-emerald-400">&#x2211; ${kkd.kk_gecen||0}</span></div></td>
                        <td class="px-4 py-2 text-right">
                            <div class="flex flex-col items-end gap-1">
                                <span class="text-[8px] font-black text-amber-500 bg-amber-50 border border-amber-200 px-2 py-0.5 rounded-full">&#x2211; ${ikiTop}</span>
                                <div style="display:flex;gap:4px;align-items:center;max-width:230px">
                                    <select id="kk2-sebep-${i}" class="text-[9px] font-bold bg-amber-50 border border-amber-200 rounded-lg px-1 py-1 outline-none">
                                        <option value="dokuma">Dokuma</option>
                                        <option value="leke">Leke</option>
                                        <option value="ebat">Ebat</option>
                                        <option value="dikis">Dikiş</option>
                                        <option value="diger">Diğer</option>
                                    </select>
                                    <input id="kk2-adet-${i}" type="number" placeholder="adet" min="0" class="konf-num-input text-[9px] font-black text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-1 py-1 outline-none">
                                    <button onclick="konfIkinciKaliteDetayEkle(${i})" class="text-[9px] font-black text-white bg-amber-500 rounded-lg px-2 py-1 hover:bg-amber-600">Ekle</button>
                                </div>
                                <div class="text-[8px] text-amber-600">D:${ikiDet.dokuma} · L:${ikiDet.leke} · E:${ikiDet.ebat} · Di:${ikiDet.dikis} · X:${ikiDet.diger}</div>
                            </div>
                        </td>
                        <td class="px-4 py-2 text-right"><div class="flex flex-col items-end gap-0.5"><input type="number" placeholder="+ekle" min="0" data-kalem="${i}" data-alan="tamir" onchange="konfKalemGuncelle(${i},'tamir',this.value)" class="konf-num-input font-black text-blue-700 bg-blue-50 border border-blue-200 rounded-lg px-1 py-0.5 outline-none"><span class="text-[8px] font-black text-blue-400">&#x2211; ${kkd.tamir||0}</span></div></td>
                        <td class="px-4 py-2 text-right"><div class="flex flex-col items-end gap-0.5"><input type="number" placeholder="+ekle" min="0" data-kalem="${i}" data-alan="imha" onchange="konfKalemGuncelle(${i},'imha',this.value)" class="konf-num-input font-black text-rose-700 bg-rose-50 border border-rose-200 rounded-lg px-1 py-0.5 outline-none"><span class="text-[8px] font-black text-rose-400">&#x2211; ${kkd.imha||0}</span></div></td>
                        <td class="px-4 py-2 text-right font-black ${fp>5?'text-rose-600':fp>0?'text-amber-600':'text-emerald-600'}">%${fp}</td>
                    </tr>`;
                }).join('')}
            </tbody>
        </table></div>
    </div>
    <button onclick="konfKaydet('kk')" class="w-full bg-amber-500 text-white font-black py-3 rounded-2xl text-[10px] tracking-widest hover:bg-amber-600 transition-all">💾 KALİTE KONTROL KAYDET</button>
    </div>`;
}

function renderKonfKoli(siparis,kalemler,kd) {
    return `<div style="display:flex;flex-direction:column;gap:12px">
    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px">
        <div class="panel-box" style="padding:16px 20px">
            <div class="text-[10px] font-bold uppercase tracking-widest mb-4">📦 Koli Bilgileri</div>
            <div class="space-y-3">
                <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
                    <div><label class="pro-label">Koli Tarihi</label>
                        <input id="kf-koli-tarih" type="date" class="pro-input" value="${kd.koli_tarih||''}"></div>
                    <div><label class="pro-label">Toplam Koli Sayısı</label>
                        <input id="kf-koli-sayi" type="number" class="pro-input" placeholder="0" value="${kd.koli_sayi||''}"></div>
                </div>
                <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
                    <div><label class="pro-label">Koli Başı Adet</label>
                        <input id="kf-koli-basi-adet" type="number" class="pro-input" placeholder="0" value="${kd.koli_basi_adet||''}"></div>
                    <div><label class="pro-label">Ort. Koli Ağırlığı (kg)</label>
                        <input id="kf-koli-kg" type="number" class="pro-input" placeholder="0.0" value="${kd.koli_kg||''}"></div>
                </div>
                <div><label class="pro-label">Koli / Etiket Notu</label>
                    <textarea id="kf-koli-not" class="pro-input" rows="2">${kd.koli_not||''}</textarea></div>
            </div>
        </div>
        <div class="panel-box" style="padding:16px 20px">
            <div class="text-[10px] font-bold uppercase tracking-widest mb-4">📦 Beden Bazlı Koli Girişi</div>
            <div class="space-y-2">
                ${kalemler.map((k,i)=>{const kkd=kd[`kalem_${i}`]||{}; const birim = siparisKalemBirim(k).toLowerCase(); return `
                <div class="flex items-center gap-3 p-2.5 rounded-xl konf-data-row">
                    <div class="flex-1 min-w-0">
                        <span class="konf-data-kalem">${k.renk||'RENK YOK'} · ${k.ebat||'EBAT YOK'}</span><span class="font-bold text-[10px]">${k.ad||k.kod||'—'}</span>
                        <span class="text-[8px] text-slate-400 ml-1">${k.renk||''} ${k.ebat||''}</span>
                        <span class="text-[8px] text-amber-500 ml-1">· KK: ${kkd.kk_gecen||0}</span>
                    </div>
                    <div class="flex items-center gap-1.5">
                        <label class="text-[8px] font-black text-emerald-600">Kolide:</label>
                        <div class="flex items-center gap-1">
                            <input type="number" placeholder="+${birim}" min="0" data-kalem="${i}" data-alan="kolide"
                                onchange="konfKalemGuncelle(${i},'kolide',this.value)"
                                class="konf-num-input font-black text-emerald-700 bg-white border border-emerald-200 rounded-lg px-2 py-1 text-[10px] outline-none">
                            <span class="text-[9px] font-black text-emerald-400 bg-emerald-50 px-2 py-1 rounded-lg min-w-12 text-center">&#x2211; ${kkd.kolide||0}</span>
                        </div>
                    </div>
                </div>`;}).join('')}
            </div>
        </div>
    </div>
    <button onclick="konfKaydet('koli')" class="btn-pro btn-primary-pro" style="width:100%;justify-content:center;padding:10px">💾 KOLİ BİLGİLERİNİ KAYDET</button>
    </div>`;
}

function renderKonfKapama(siparis,kalemler,kd) {
    const top=kalemler.reduce((a,k)=>a+(parseInt(k.miktar)||0),0);
    let topK=0,topD=0,topKK=0,topKol=0,topH=0;
    kalemler.forEach((_,i)=>{const k=kd[`kalem_${i}`]||{};topK+=parseInt(k.kesilen||0);topD+=parseInt(k.dikilen||0);topKK+=parseInt(k.kk_gecen||0);topKol+=parseInt(k.kolide||0);topH+=parseInt(k.iki_kalite||0)+parseInt(k.tamir||0)+parseInt(k.imha||0);});
    const aksKalemler = siparisKapamaAksesuarSatirlari(kd, kalemler, siparis.id).map(a => ({ id: a.id, l: a.label, g: a.gelen, ku: a.kullanilan, ka: a.kalan }));
    // Ürün ağacı kontrolü
    const allUa = _kdCache[`KD_URUN_AGACI_${siparis.id}`] || {};
    const siparisAgac = allUa['siparis'] || {};
    const agacUyari = uaSiparisTanimsizMi(siparis, allUa);
    const agacOzet = kalemler.map((k,i) => {
        const ua = _kdCache[`KD_URUN_AGACI_${siparis.id}`]?.[`u_${i}`] || {};
        return { ad: k.ad||k.kod||'Ürün '+(i+1), asamalar: ua.asamalar||[], aksesuar: uaSiparisAksesuarGenelOku(siparis.id, kalemler), kumas_metre: ua.kumas_metre||0, miktar: parseInt(k.miktar||0) };
    });

    return `<div style="display:flex;flex-direction:column;gap:12px">
    ${agacUyari ? `
    <div class="bg-amber-50 border-2 border-amber-300 rounded-2xl p-4 flex items-start gap-3">
        <span class="text-2xl flex-shrink-0">⚠️</span>
        <div>
            <p class="font-black text-amber-800">Ürün ağacı tanımlanmamış!</p>
            <p class="text-[10px] text-amber-600 font-bold mt-0.5">Kapama yapılmadan önce ürün ağacının tanımlanması önerilir.</p>
            <button onclick="setAppMode('URUN_AGACI')" class="mt-2 text-[9px] font-black bg-amber-500 text-white px-3 py-1.5 rounded-lg hover:bg-amber-600 transition-all">
                🌿 Ürün Ağacına Git →
            </button>
        </div>
    </div>` : `
    <div class="bg-emerald-50 border border-emerald-200 rounded-2xl p-3 flex items-center gap-3">
        <span class="text-xl">✅</span>
        <div>
            <p class="font-black text-emerald-700 text-[10px]">Ürün ağacı tanımlı — ${new Date(siparisAgac.tamamlanma_tarihi||'').toLocaleDateString('tr-TR') || ''}</p>
            <p class="text-[9px] text-emerald-500">${kalemler.length} ürün kalemi için aşama ve aksesuar planı mevcut</p>
        </div>
    </div>`}

    ${!agacUyari && agacOzet.length > 0 ? `
    <div class="panel-box">
        <div class="panel-head"><span class="panel-head-title"><span class="panel-head-dot" style="background:var(--text3)"></span>🌿 Ürün Ağacı — Planlanan vs Gerçekleşen</span></div>
        <div class="overflow-x-auto"><table class="w-full text-[10px]">
            <thead style="background:var(--surface2)"><tr>
                <th class="text-left px-4 py-2 font-bold">Ürün</th>
                <th class="text-left px-4 py-2 font-bold">Planlanan Aşamalar</th>
                <th class="text-right px-4 py-2 font-black text-indigo-600">Plan Kumaş</th>
                <th class="text-right px-4 py-2 font-black text-violet-600">Planlanan Adet</th>
                <th class="text-right px-4 py-2 font-black text-emerald-600">Koliye Giren</th>
                <th class="text-right px-4 py-2 font-black text-rose-500">Fark</th>
            </tr></thead>
            <tbody >
                ${agacOzet.map((u,i)=>{
                    const kkd = kd['kalem_'+i]||{};
                    const giren = parseInt(kkd.kolide||0);
                    const fark = giren - u.miktar;
                    const planKumas = u.kumas_metre > 0 ? (u.kumas_metre * u.miktar).toFixed(1)+' m' : '—';
                    const asamaLabels = u.asamalar.map(id=>UA_ASAMALAR.find(a=>a.id===id)?.ikon||id).join(' ');
                    return '<tr ><td class="px-4 py-2 font-bold">'+u.ad+'</td><td class="px-4 py-2 text-slate-500">'+asamaLabels+'</td><td class="px-4 py-2 text-right font-bold text-indigo-600">'+planKumas+'</td><td class="px-4 py-2 text-right font-bold text-violet-600">'+u.miktar.toLocaleString()+'</td><td class="px-4 py-2 text-right font-bold text-emerald-600">'+giren.toLocaleString()+'</td><td class="px-4 py-2 text-right font-black '+(fark>=0?'text-emerald-600':'text-rose-600')+'">'+(fark>=0?'+':'')+fark.toLocaleString()+'</td></tr>';
                }).join('')}
            </tbody>
        </table></div>
    </div>` : ''}

    <div class="bg-gradient-to-r from-slate-800 to-slate-900 rounded-2xl p-5 text-white">
        <div class="flex items-center gap-2 mb-4"><span class="text-xl">🔒</span><span class="font-black text-sm">Kapama Özeti — ${siparis.sno}</span></div>
        <div class="grid grid-cols-3 lg:grid-cols-6 gap-3">
            ${[{l:'Sipariş',v:top,c:'text-white'},{l:'Kesilen',v:topK,c:'text-violet-300'},{l:'Dikilen',v:topD,c:'text-pink-300'},{l:'KK Geçen',v:topKK,c:'text-amber-300'},{l:'Kolide',v:topKol,c:'text-emerald-300'},{l:'Hatalı',v:topH,c:'text-rose-300'}].map(x=>`
            <div class="text-center bg-white/5 rounded-xl p-2">
                <div class="font-black text-xl ${x.c}">${x.v.toLocaleString()}</div>
                <div class="text-white/50 text-[8px] font-bold uppercase mt-0.5">${x.l}</div>
                <div class="text-white/30 text-[7px] font-bold">%${top>0?Math.round(x.v/top*100):0}</div>
            </div>`).join('')}
        </div>
        <div class="mt-4 pt-4 border-t border-white/10 grid grid-cols-3 gap-3 text-[10px]">
            <div><span class="text-white/40 font-bold">Verimlilik: </span><span class="font-black text-emerald-300">${top>0?Math.round(topKol/top*100):0}%</span></div>
            <div><span class="text-white/40 font-bold">Fire Oranı: </span><span class="font-black text-rose-300">${topD>0?Math.round(topH/topD*100):0}%</span></div>
            <div><span class="text-white/40 font-bold">Eksik: </span><span class="font-black text-amber-300">${(top-topKol).toLocaleString()} adet</span></div>
        </div>
    </div>
    <div class="panel-box" style="padding:16px 20px">
        <div class="text-[10px] font-bold uppercase tracking-widest mb-4">📌 Kalan Aksesuar Envanteri</div>
        <div class="space-y-2">
            ${aksKalemler.map(ak=>{
                const g=ak.g;const ku=ak.ku;const ka=ak.ka;
                return `<div class="flex items-center gap-4 p-3 rounded-xl bg-slate-50">
                    <span class="font-black text-slate-700 w-20 flex-shrink-0">${ak.l}</span>
                    <div class="flex-1 flex items-center gap-4 flex-wrap">
                        <span class="text-[9px] text-slate-400">Gelen: <b class="text-slate-700">${g.toLocaleString()}</b></span>
                        <span class="text-[9px] text-slate-400">Kullanılan: <b class="text-pink-600">${ku.toLocaleString()}</b></span>
                        <span class="text-[9px] text-slate-400">Kalan: <b class="${ka>0?'text-emerald-600':'text-slate-400'}">${ka.toLocaleString()}</b></span>
                    </div>
                    <div class="bg-slate-200 rounded-full h-1.5 w-20 flex-shrink-0">
                        <div class="h-1.5 rounded-full bg-pink-400" style="width:${g>0?Math.min(Math.round(ku/g*100),100):0}%"></div>
                    </div>
                </div>`;
            }).join('')}
        </div>
    </div>
    <div class="panel-box" style="padding:16px 20px">
        <div class="text-[10px] font-bold uppercase tracking-widest mb-3">🔒 Üretim kapama kaydı</div>
        <p class="text-[9px] text-slate-500 mb-3 leading-relaxed">Siparişi sistemde «Tamamlandı» yapmak için: <b>Siparişler → düzenle (Yeni Sipariş)</b> ekranındaki <b>Siparişi tamamla ve kapat</b> düğmesini kullanın. Burada sadece kapama tarihi/notu ve PDF raporu tutulur.</p>
        <div class="grid grid-cols-2 gap-3 mb-4">
            <div><label class="pro-label">Kapama Tarihi</label>
                <input id="kf-kapama-tarih" type="date" class="pro-input" value="${kd.kapama_tarih||new Date().toISOString().slice(0,10)}"></div>
            <div><label class="pro-label">Kapama Notu</label>
                <input id="kf-kapama-not" class="pro-input" placeholder="Genel üretim notu..." value="${kd.kapama_not||''}"></div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
            <button onclick="siparisKapamaRaporPdf(konfeksiyonSiparisId)" class="w-full bg-indigo-600 text-white font-black py-3 rounded-2xl text-[10px] tracking-widest hover:bg-indigo-700 transition-all">📄 SİPARİŞ KAPAMA RAPORU (PDF)</button>
            <button onclick="konfKapama()" class="w-full bg-slate-800 text-white font-black py-3.5 rounded-2xl text-[10px] tracking-widest hover:bg-slate-900 transition-all">💾 KAPAMA BİLGİSİNİ KAYDET</button>
        </div>
    </div>
    </div>`;
}

async function siparisKapamaVeriYukle(siparisId) {
    const sid = String(siparisId);
    await Promise.all([
        sbKdGet(sid, 'KD_KONFEKSIYON', true),
        sbKdGet(sid, 'KD_DOKUMA', true),
        sbKdGet(sid, 'KD_URUN_AGACI', true),
        sbKdGet(sid, 'KD_FASON_TAKIP', true),
        konfLoadIslemLog(sid),
    ]);
    const kdK0 = _kdCache[`KD_KONFEKSIYON_${sid}`] || {};
    const ftKd = _kdCache[`KD_FASON_TAKIP_${sid}`] || {};
    return {
        kdKonf: fasonTakipKdKonfBirlestir(sid, kdK0, ftKd),
        kdDok: _kdCache[`KD_DOKUMA_${sid}`] || {},
        kdUa: _kdCache[`KD_URUN_AGACI_${sid}`] || {},
        ftKd,
        islemRows: _konfIslemLogCache[sid] || [],
    };
}

function siparisKapamaAksesuarSatirlari(kdKonf, kalemler, siparisId) {
    const genel = uaSiparisAksesuarGenelOku(siparisId, kalemler);
    const fasonAdet = kalemler.reduce((a, k, i) => {
        if (planlamaKalemUretimAlani(siparisId, i) === 'FASON_KONF') return a + (parseInt(k.miktar, 10) || 0);
        return a;
    }, 0);
    const tumAdet = kalemler.reduce((a, k) => a + (parseInt(k.miktar, 10) || 0), 0);
    const rows = [];
    const seen = new Set();
    const push = (id, label, planBirim) => {
        if (seen.has(id)) return;
        seen.add(id);
        const g = parseInt(kdKonf[`ak_${id}_gelen`], 10) || 0;
        const ku = parseInt(kdKonf[`ak_${id}_kullanilan`], 10) || 0;
        const pb = parseFloat(planBirim) || 0;
        if (!pb && !g && !ku) return;
        rows.push({
            id, label, planBirim: pb,
            planToplam: Math.round(pb * (fasonAdet || tumAdet) * 10) / 10,
            gelen: g, kullanilan: ku, kalan: g - ku,
        });
    };
    UA_AKSESUARLAR.forEach(ak => push(ak.id, ak.label, genel[ak.id]));
    (kdKonf._fason_takip?.aksesuar || []).forEach(a => {
        if (a?.key) push(a.key, a.ad || a.key, a.birim);
    });
    if (parseInt(kdKonf.ak_diger_ak_gelen, 10) || parseInt(kdKonf.ak_diger_ak_kullanilan, 10)) {
        push('diger_ak', 'Diğer (eski kayıt)', 0);
    }
    return rows;
}

function buildSiparisKapamaRaporPdfHtml(siparis, bundle) {
    const { kdKonf, kdDok, kdUa, ftKd, islemRows } = bundle;
    const kalemler = uaSiparisKalemleriGetir(siparis);
    const urunler = kdDok.urunler || {};
    const kapamaTarih = kdKonf.kapama_tarih || new Date().toISOString().slice(0, 10);
    const pdfTd = 'padding:5px 6px;border-bottom:1px solid #e5e7eb;font-size:9px';
    const pdfTh = 'padding:6px;text-align:left;font-size:8px;background:#f1f5f9;border-bottom:1px solid #cbd5e1';

    let topSip = 0, topKes = 0, topDik = 0, topKK = 0, topKol = 0, topSevk = 0, topHata = 0;
    const sebepTop = { dokuma: 0, leke: 0, ebat: 0, dikis: 0, diger: 0 };

    const kalemRows = kalemler.map((k, i) => {
        const kk = kdKonf[`kalem_${i}`] || {};
        const u = urunler[i] || urunler[String(i)] || {};
        const ua = kdUa[`u_${i}`] || {};
        const ftK = (ftKd.kalem || {})[String(i)] || {};
        const sipAd = parseInt(k.miktar, 10) || 0;
        const kes = parseInt(kk.kesilen, 10) || parseInt(ftK.kesim_adet, 10) || 0;
        const dik = parseInt(kk.dikilen, 10) || parseInt(ftK.dikim_adet, 10) || 0;
        const kkG = parseInt(kk.kk_gecen, 10) || parseInt(ftK.kalite_adet, 10) || 0;
        const kol = parseInt(kk.kolide, 10) || parseInt(ftK.yukleme_adet, 10) || 0;
        const sevk = parseInt(kk.sevk_edilen, 10) || parseInt(ftK.sevk_adet, 10) || 0;
        const ikiDet = konfIkinciKaliteDetayNorm(kk.iki_kalite_detay || {});
        const ikiTop = konfIkinciKaliteDetayToplam(ikiDet) || (parseInt(kk.iki_kalite, 10) || 0);
        const tamir = parseInt(kk.tamir, 10) || 0;
        const imha = parseInt(kk.imha, 10) || 0;
        const hata = ikiTop + tamir + imha;
        const birimMt = parseFloat(ua.kumas_metre) || 0;
        const planMt = birimMt > 0 && sipAd > 0 ? Math.round(birimMt * sipAd * 10) / 10 : (parseFloat(ftK.kumas_plan_metre) || 0);
        const sevkMt = parseFloat(u.toplam_metre) || parseFloat(ftK.kumas_sevk_metre) || 0;
        const fasonMu = planlamaKalemUretimAlani(siparis.id, i) === 'FASON_KONF';

        topSip += sipAd; topKes += kes; topDik += dik; topKK += kkG; topKol += kol; topSevk += sevk; topHata += hata;
        sebepTop.dokuma += ikiDet.dokuma; sebepTop.leke += ikiDet.leke; sebepTop.ebat += ikiDet.ebat;
        sebepTop.dikis += ikiDet.dikis; sebepTop.diger += ikiDet.diger;

        const renkEbat = [uaKalemRenkGetir(k) || k.renk, uaKalemEbatGetir(k) || k.ebat].filter(Boolean).join(' · ');
        return `<tr>
            <td style="${pdfTd}">${fasonMu ? '🏭 ' : ''}${pdfEsc(k.ad || k.kod || 'Kalem ' + (i + 1))}${renkEbat ? '<br><span style="color:#64748b;font-size:8px">' + pdfEsc(renkEbat) + '</span>' : ''}</td>
            <td style="${pdfTd};text-align:right">${sipAd.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${planMt > 0 ? planMt.toLocaleString('tr-TR') + ' m' : '—'}</td>
            <td style="${pdfTd};text-align:right">${sevkMt > 0 ? sevkMt.toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' m' : '—'}</td>
            <td style="${pdfTd};text-align:right">${kes.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${dik.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${kkG.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${kol.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right;font-weight:700">${sevk.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${hata.toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${dik > 0 ? '%' + Math.round((hata / dik) * 100) : '—'}</td>
        </tr>`;
    }).join('');

    const fasonRows = kalemler.map((k, i) => {
        if (planlamaKalemUretimAlani(siparis.id, i) !== 'FASON_KONF') return '';
        const rec = (ftKd.kalem || {})[String(i)] || {};
        return `<tr>
            <td style="${pdfTd}">${pdfEsc(k.ad || k.kod || 'Kalem ' + (i + 1))}</td>
            <td style="${pdfTd};text-align:right">${(fasonTakipNum(rec.kumas_plan_metre, 1) || 0).toLocaleString('tr-TR')} m</td>
            <td style="${pdfTd};text-align:right">${(fasonTakipNum(rec.kumas_sevk_metre, 2) || 0).toLocaleString('tr-TR')} m</td>
            <td style="${pdfTd};text-align:right">${fasonTakipInt(rec.kesim_adet).toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${fasonTakipInt(rec.dikim_adet).toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${fasonTakipInt(rec.kalite_adet).toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${fasonTakipInt(rec.yukleme_adet).toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${fasonTakipInt(rec.sevk_adet).toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${fasonTakipInt(rec.elde_kalan_adet).toLocaleString('tr-TR')}</td>
            <td style="${pdfTd};text-align:right">${(fasonTakipNum(rec.elde_kalan_kumas_metre, 2) || 0).toLocaleString('tr-TR')} m</td>
        </tr>`;
    }).filter(Boolean).join('');

    const aksRows = siparisKapamaAksesuarSatirlari(kdKonf, kalemler, siparis.id).map(a => `<tr>
        <td style="${pdfTd}">${pdfEsc(a.label)}</td>
        <td style="${pdfTd};text-align:right">${a.planBirim > 0 ? a.planBirim.toLocaleString('tr-TR', { maximumFractionDigits: 2 }) : '—'}</td>
        <td style="${pdfTd};text-align:right">${a.planToplam > 0 ? a.planToplam.toLocaleString('tr-TR', { maximumFractionDigits: 1 }) : '—'}</td>
        <td style="${pdfTd};text-align:right">${a.gelen.toLocaleString('tr-TR')}</td>
        <td style="${pdfTd};text-align:right">${a.kullanilan.toLocaleString('tr-TR')}</td>
        <td style="${pdfTd};text-align:right;font-weight:700;color:${a.kalan < 0 ? '#e11d48' : '#059669'}">${a.kalan.toLocaleString('tr-TR')}</td>
    </tr>`).join('');

    const opRows = (islemRows || []).slice(-25).reverse().map(r => {
        const dt = konfParseFlexibleDate(r.ts || r.created_at);
        return `<tr>
            <td style="${pdfTd};white-space:nowrap">${pdfEsc(dt ? dt.toLocaleString('tr-TR') : '—')}</td>
            <td style="${pdfTd}">${pdfEsc(r.islem || '—')}</td>
            <td style="${pdfTd}">${pdfEsc(r.kalem || '—')}</td>
            <td style="${pdfTd};text-align:right">${pdfEsc(String(r.miktar ?? '—'))}</td>
            <td style="${pdfTd}">${pdfEsc(r.kullanici || '—')}</td>
        </tr>`;
    }).join('');

    const uretimYeri = uaSiparisUretimYeriFromAll(kdUa, kalemler);
    const verim = topSip > 0 ? Math.round((topKol / topSip) * 100) : 0;
    const eksik = Math.max(0, topSip - topSevk);

    return `
    <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin-bottom:10px">
        ${[
            { l: 'Sipariş adet', v: topSip },
            { l: 'Kesilen', v: topKes },
            { l: 'Dikilen', v: topDik },
            { l: 'Kolide', v: topKol },
            { l: 'Sevk', v: topSevk },
            { l: 'Verim %', v: '%' + verim },
        ].map(x => `<div style="border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center">
            <div style="font-size:9px;color:#64748b;text-transform:uppercase">${x.l}</div>
            <div style="font-size:16px;font-weight:800">${typeof x.v === 'string' ? x.v : x.v.toLocaleString('tr-TR')}</div>
        </div>`).join('')}
    </div>
    <div style="margin-bottom:10px;padding:10px;border:1px solid #e5e7eb;border-radius:8px;background:#f8fafc;font-size:10px;line-height:1.6;color:#334155">
        <b>Sipariş:</b> ${pdfEsc(siparis.sno || '—')} · <b>Müşteri:</b> ${pdfEsc(siparis.firma || '—')} ·
        <b>Termin:</b> ${siparis.ttarih ? pdfEsc(new Date(siparis.ttarih).toLocaleDateString('tr-TR')) : '—'} ·
        <b>Kapama:</b> ${pdfEsc(kapamaTarih)} · <b>Üretim yeri:</b> ${pdfEsc(uretimYeri)} ·
        <b>Eksik sevk:</b> ${eksik.toLocaleString('tr-TR')} adet
    </div>
    <div style="font-size:11px;font-weight:800;margin:8px 0 4px;color:#1e293b">Üretim özeti — kalem bazlı (dokuma · konfeksiyon · fason)</div>
    <table style="width:100%;border-collapse:collapse;margin-bottom:12px">
        <thead><tr>
            <th style="${pdfTh}">Kalem</th>
            <th style="${pdfTh};text-align:right">Sip.</th>
            <th style="${pdfTh};text-align:right">Plan kumaş</th>
            <th style="${pdfTh};text-align:right">Sevk kumaş</th>
            <th style="${pdfTh};text-align:right">Kesim</th>
            <th style="${pdfTh};text-align:right">Dikim</th>
            <th style="${pdfTh};text-align:right">Kalite</th>
            <th style="${pdfTh};text-align:right">Yükleme</th>
            <th style="${pdfTh};text-align:right">Sevk</th>
            <th style="${pdfTh};text-align:right">Hatalı</th>
            <th style="${pdfTh};text-align:right">Fire</th>
        </tr></thead>
        <tbody>${kalemRows || `<tr><td colspan="11" style="${pdfTd};text-align:center">Kalem yok</td></tr>`}</tbody>
    </table>
    ${fasonRows ? `
    <div style="font-size:11px;font-weight:800;margin:8px 0 4px;color:#b45309">Fason takip (kaydedilen)</div>
    <table style="width:100%;border-collapse:collapse;margin-bottom:12px">
        <thead><tr>
            <th style="${pdfTh}">Kalem</th>
            <th style="${pdfTh};text-align:right">Plan kumaş</th>
            <th style="${pdfTh};text-align:right">Sevk kumaş</th>
            <th style="${pdfTh};text-align:right">Kesim</th>
            <th style="${pdfTh};text-align:right">Dikim</th>
            <th style="${pdfTh};text-align:right">Kalite</th>
            <th style="${pdfTh};text-align:right">Yükleme</th>
            <th style="${pdfTh};text-align:right">Sevk</th>
            <th style="${pdfTh};text-align:right">Elde adet</th>
            <th style="${pdfTh};text-align:right">Elde kumaş</th>
        </tr></thead>
        <tbody>${fasonRows}</tbody>
    </table>` : ''}
    <div style="display:grid;grid-template-columns:1.2fr 1fr;gap:10px;margin-bottom:10px">
        <div style="border:1px solid #e5e7eb;border-radius:8px;padding:8px">
            <div style="font-size:10px;font-weight:700;margin-bottom:6px">2. kalite sebep dağılımı</div>
            <div style="font-size:10px;line-height:1.8">
                Dokuma: <b>${sebepTop.dokuma}</b> · Leke: <b>${sebepTop.leke}</b> · Ebat: <b>${sebepTop.ebat}</b> ·
                Dikiş: <b>${sebepTop.dikis}</b> · Diğer: <b>${sebepTop.diger}</b><br>
                Toplam hatalı: <b>${topHata.toLocaleString('tr-TR')}</b> · Fire: <b>%${topDik > 0 ? Math.round((topHata / topDik) * 100) : 0}</b>
            </div>
        </div>
        <div style="border:1px solid #e5e7eb;border-radius:8px;padding:8px">
            <div style="font-size:10px;font-weight:700;margin-bottom:6px">Aksesuar (plan · gelen · kullanılan · kalan)</div>
            <table style="width:100%;border-collapse:collapse">
                <thead><tr style="background:#f8fafc">
                    <th style="${pdfTh}">Tür</th><th style="${pdfTh};text-align:right">Plan/ürün</th>
                    <th style="${pdfTh};text-align:right">Plan toplam</th><th style="${pdfTh};text-align:right">Gelen</th>
                    <th style="${pdfTh};text-align:right">Kullanılan</th><th style="${pdfTh};text-align:right">Kalan</th>
                </tr></thead>
                <tbody>${aksRows || `<tr><td colspan="6" style="${pdfTd};text-align:center">Kayıt yok</td></tr>`}</tbody>
            </table>
        </div>
    </div>
    ${opRows ? `
    <div style="font-size:10px;font-weight:700;margin:8px 0 4px">Son operasyon kayıtları (max 25)</div>
    <table style="width:100%;border-collapse:collapse;margin-bottom:10px">
        <thead><tr style="background:#f8fafc">
            <th style="${pdfTh}">Tarih</th><th style="${pdfTh}">İşlem</th><th style="${pdfTh}">Kalem</th>
            <th style="${pdfTh};text-align:right">Miktar</th><th style="${pdfTh}">Kullanıcı</th>
        </tr></thead>
        <tbody>${opRows}</tbody>
    </table>` : ''}
    <div style="padding:10px;border:1px dashed #cbd5e1;border-radius:8px;font-size:10px;line-height:1.6">
        <b>Kapama notu:</b> ${pdfEsc(kdKonf.kapama_not || '—')}<br>
        <b>Fason notu:</b> ${pdfEsc(ftKd.siparis_not || kdKonf.fason_takip_not || '—')}
    </div>`;
}

async function siparisKapamaRaporPdf(siparisIdOpt) {
    try { await erpEnsureHtml2Pdf(); } catch (e) {}
    if (typeof html2pdf === 'undefined') { alert('PDF kütüphanesi yüklenemedi.'); return; }
    const sid = siparisIdOpt != null ? siparisIdOpt : konfeksiyonSiparisId;
    if (!sid) { alert('Önce bir sipariş seçin.'); return; }
    const siparis = (dataCache.siparisler || []).find(s => String(s.id) === String(sid));
    if (!siparis) { alert('Sipariş bulunamadı.'); return; }
    const bundle = await siparisKapamaVeriYukle(siparis.id);
    const bodyHtml = buildSiparisKapamaRaporPdfHtml(siparis, bundle);
    const shell = buildPdfShellElement({
        title: 'SİPARİŞ KAPAMA RAPORU',
        subtitle: 'Dokuma · konfeksiyon · fason takip · aksesuar özeti',
        docNo: `${siparis.sno || 'SIPARIS'}-KAPAMA-${new Date().toISOString().slice(0, 10)}`,
        bodyHtml,
        note: 'Ürün ağacı, konfeksiyon, dokuma, fason takip ve operasyon günlüğünden otomatik üretilmiştir.',
    });
    html2pdf().set({
        margin: [0, 0],
        filename: `siparis_kapama_${String(siparis.sno || 'siparis').replace(/[^\w\-]+/g, '_')}_${new Date().toLocaleDateString('tr-TR').replace(/[^\d]/g, '')}.pdf`,
        image: { type: 'jpeg', quality: 1 },
        html2canvas: { scale: 1.5, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' },
    }).from(shell).save();
}

async function konfKalemGuncelle(idx,alan,deger) {
    if (alan === 'sevk_edilen' && typeof erpSevkAdetYazmaKapaliMi === 'function' && erpSevkAdetYazmaKapaliMi()) {
        erpSevkAdetGirisAc({ toast: 'Sevk adedi yalnızca Sevkiyat’tan girilir.' });
        const inputEl = document.querySelector(`[data-kalem="${idx}"][data-alan="${alan}"]`);
        if (inputEl) inputEl.value = '';
        return;
    }
    const parsed = erpParseExcelNumberExpr(deger);
    const eklenecek = Number.isFinite(parsed) ? Math.trunc(parsed) : (parseInt(deger) || 0);
    if (eklenecek === 0) return;
    if (!konfDraft.kalem[idx]) konfDraft.kalem[idx] = {};
    const onceki = parseInt(konfDraft.kalem[idx][alan] || 0) || 0;
    const yeni = onceki + eklenecek;
    konfDraft.kalem[idx][alan] = yeni;
    const inputEl = document.querySelector(`[data-kalem="${idx}"][data-alan="${alan}"]`);
    if (inputEl) {
        inputEl.value = '';
        inputEl.placeholder = `+miktar (bekleyen: +${yeni})`;
    }
}

function konfIkinciKaliteDetayNorm(detay = {}) {
    const out = {
        dokuma: parseInt(detay.dokuma || 0) || 0,
        leke: parseInt(detay.leke || 0) || 0,
        ebat: parseInt(detay.ebat || 0) || 0,
        dikis: parseInt(detay.dikis || 0) || 0,
        diger: parseInt(detay.diger || 0) || 0,
    };
    return out;
}

function konfIkinciKaliteDetayToplam(detay = {}) {
    const d = konfIkinciKaliteDetayNorm(detay);
    return (d.dokuma + d.leke + d.ebat + d.dikis + d.diger);
}

async function konfIkinciKaliteDetayGuncelle(idx, sebep, deger) {
    if (!['dokuma','leke','ebat','dikis','diger'].includes(sebep)) return;
    const parsed = erpParseExcelNumberExpr(deger);
    const eklenecek = Number.isFinite(parsed) ? Math.trunc(parsed) : (parseInt(deger) || 0);
    if (eklenecek === 0) return;
    if (!konfDraft.ikiDetay[idx]) konfDraft.ikiDetay[idx] = {};
    const onceki = parseInt(konfDraft.ikiDetay[idx][sebep] || 0) || 0;
    const yeni = onceki + eklenecek;
    konfDraft.ikiDetay[idx][sebep] = yeni;
    const inputEl = document.querySelector(`[data-kalem="${idx}"][data-iki-sebep="${sebep}"]`);
    if (inputEl) {
        inputEl.value = '';
        inputEl.placeholder = `+adet (bekleyen: +${yeni})`;
    }
}

async function konfIkinciKaliteDetayEkle(idx) {
    const sebepEl = document.getElementById(`kk2-sebep-${idx}`);
    const adetEl = document.getElementById(`kk2-adet-${idx}`);
    if (!sebepEl || !adetEl) return;
    const sebep = String(sebepEl.value || 'dokuma');
    const parsed = erpParseExcelNumberExpr(adetEl.value || 0);
    const adet = Number.isFinite(parsed) ? Math.trunc(parsed) : (parseInt(adetEl.value || 0) || 0);
    if (adet <= 0) return;
    konfIkinciKaliteDetayGuncelle(idx, sebep, adet);
    adetEl.value = '';
}

async function konfAksesuarGuncelle(akId,alan,deger) {
    const parsed = erpParseExcelNumberExpr(deger);
    const val = Number.isFinite(parsed) ? Math.trunc(parsed) : (parseInt(deger) || 0);
    konfDraft.aksesuar[`${akId}_${alan}`] = val;
}

const KONF_GIRIS_ISLEM_SET = new Set(['KESIM', 'DIKIM', 'KALITE', 'KOLI', 'SEVK']);
const KONF_ISLEM_ANA_ALAN = { KESIM: 'kesilen', DIKIM: 'dikilen', KALITE: 'kk_gecen', KOLI: 'kolide', SEVK: 'sevk_edilen' };
const KONF_DETAY_ETIKET_ALAN = {
    'Kesilen': 'kesilen', 'Fire kesim': 'fire_kesim', 'Dikilen': 'dikilen', 'Fire dikim': 'fire_dikim',
    'Kalite geçen': 'kk_gecen', 'Tamir': 'tamir', 'İmha': 'imha', 'Kolide': 'kolide', 'Sevk edilen': 'sevk_edilen'
};

function konfNormIslemKod(islem) {
    return String(islem || '').toUpperCase().replace(/İ/g, 'I');
}

function konfRecalcPanelTotals(kd, kalemler) {
    let tK = 0, tD = 0, tKK = 0, tKol = 0, tH = 0, tSevk = 0;
    (kalemler || []).forEach((_, i) => {
        const k = kd[`kalem_${i}`] || {};
        tK += parseInt(k.kesilen, 10) || 0;
        tD += parseInt(k.dikilen, 10) || 0;
        tKK += parseInt(k.kk_gecen, 10) || 0;
        tKol += parseInt(k.kolide, 10) || 0;
        tSevk += parseInt(k.sevk_edilen, 10) || 0;
        tH += (parseInt(k.iki_kalite, 10) || 0) + (parseInt(k.tamir, 10) || 0) + (parseInt(k.imha, 10) || 0);
    });
    kd.kesim_toplam = tK;
    kd.dikim_toplam = tD;
    kd.kk_gecen = tKK;
    kd.koli_toplam = tKol;
    kd.hatali_toplam = tH;
    kd.panel_sevk_toplam = tSevk;
    return kd;
}

function konfAkisDeltasParse(j, islem, miktar) {
    if (j && typeof j.deltas === 'object' && j.deltas !== null && !Array.isArray(j.deltas)) {
        return { ...j.deltas };
    }
    const out = {};
    const alanlar = Array.isArray(j?.detay?.alanlar) ? j.detay.alanlar : [];
    const iki = {};
    alanlar.forEach((line) => {
        const s = String(line || '');
        const m2 = s.match(/^2\.kalite\s+(\w+):\s*\+(\d+)/i);
        if (m2) {
            const sebep = String(m2[1] || '').toLowerCase();
            if (['dokuma', 'leke', 'ebat', 'dikis', 'diger'].includes(sebep)) iki[sebep] = parseInt(m2[2], 10) || 0;
            return;
        }
        const m = s.match(/^(.+?):\s*\+(\d+)/);
        if (!m) return;
        const alan = KONF_DETAY_ETIKET_ALAN[m[1].trim()];
        if (alan) out[alan] = parseInt(m[2], 10) || 0;
    });
    if (Object.keys(iki).length) out._iki_kalite_detay = iki;
    const iso = konfNormIslemKod(islem);
    const ana = KONF_ISLEM_ANA_ALAN[iso];
    const m = Math.round(parseFloat(miktar) || 0);
    if (ana && out[ana] == null && m > 0) out[ana] = m;
    return out;
}

function konfAkisDeltasGeriAl(kd, kalemIdx, deltas) {
    if (kalemIdx == null || kalemIdx < 0 || !deltas) return;
    const key = `kalem_${kalemIdx}`;
    if (!kd[key]) kd[key] = {};
    Object.keys(deltas).forEach((alan) => {
        if (alan === '_iki_kalite_detay') {
            const det = konfIkinciKaliteDetayNorm(kd[key].iki_kalite_detay || {});
            const patch = deltas._iki_kalite_detay || {};
            ['dokuma', 'leke', 'ebat', 'dikis', 'diger'].forEach((sebep) => {
                const dv = parseInt(patch[sebep], 10) || 0;
                if (!dv) return;
                det[sebep] = Math.max(0, (parseInt(det[sebep], 10) || 0) - dv);
            });
            kd[key].iki_kalite_detay = det;
            kd[key].iki_kalite = konfIkinciKaliteDetayToplam(det);
            return;
        }
        const dv = parseInt(deltas[alan], 10) || 0;
        if (!dv) return;
        kd[key][alan] = Math.max(0, (parseInt(kd[key][alan], 10) || 0) - dv);
        const logKey = `log_${kalemIdx}_${alan}`;
        const logArr = Array.isArray(kd[logKey]) ? kd[logKey] : [];
        for (let li = logArr.length - 1; li >= 0; li--) {
            if ((parseInt(logArr[li]?.miktar, 10) || 0) === dv) {
                logArr.splice(li, 1);
                break;
            }
        }
        if (logArr.length) kd[logKey] = logArr;
        else delete kd[logKey];
    });
}

function konfGirisKaydiSilinebilir(r) {
    if (!r || r.id == null || String(r.id).startsWith('siparis-log-')) return false;
    if (!KONF_GIRIS_ISLEM_SET.has(konfNormIslemKod(r.islem))) return false;
    return (parseFloat(r.miktar) || 0) > 0;
}

async function konfGirisKaydiSil(akisId) {
    if (!konfeksiyonSiparisId || akisId == null || akisId === '') return;
    const rows = _konfIslemLogCache[konfeksiyonSiparisId] || [];
    const row = rows.find((r) => String(r.id) === String(akisId));
    if (!row || !konfGirisKaydiSilinebilir(row)) {
        erpToast('Bu kayıt silinemez (yalnızca konfeksiyon miktar girişleri).', 'error');
        return;
    }
    const miktar = parseFloat(row.miktar) || 0;
    const ozet = `${row.islem || '—'} · ${row.kalem_ad || '—'} · ${miktar.toLocaleString('tr-TR')} adet`;
    if (!confirm(`Bu konfeksiyon girişini geri almak istiyor musunuz?\n\n${ozet}\n\nKalem toplamlarından düşülecek.`)) return;

    let j = row.not_json && typeof row.not_json === 'object' ? row.not_json : {};
    if (!Object.keys(j).length) {
        const { data: dbRow, error: fetchErr } = await sb.from('siparis_akis').select('notlar').eq('id', akisId).maybeSingle();
        if (fetchErr) {
            erpToast('Kayıt okunamadı: ' + fetchErr.message, 'error');
            return;
        }
        try { j = JSON.parse(dbRow?.notlar || '{}') || {}; } catch (e) { j = {}; }
    }

    let kalemIdx = row.kalem_idx;
    if (kalemIdx == null || kalemIdx < 0) {
        const ki = parseInt(j.kalem_idx, 10);
        if (Number.isFinite(ki) && ki >= 0) kalemIdx = ki;
    }
    if (kalemIdx == null || kalemIdx < 0) {
        const kalemler = konfGetKalemler();
        if (j.kalem_key) {
            const mk = konfNormTxt(j.kalem_key);
            kalemIdx = kalemler.findIndex((k) => konfNormTxt(konfKalemKey(k)) === mk);
        }
        if (kalemIdx < 0) kalemIdx = konfFindKalemIndexEsnek(kalemler, row.kalem_ad_db || row.kalem_ad);
    }

    const deltas = konfAkisDeltasParse(j, row.islem, miktar);
    const deltaKeys = Object.keys(deltas).filter((k) => k !== '_iki_kalite_detay' || Object.keys(deltas._iki_kalite_detay || {}).length);
    if (!deltaKeys.length) {
        erpToast('Geri alınacak miktar bilgisi bulunamadı.', 'error');
        return;
    }

    try {
        const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
        const kalemler = konfGetKalemler();
        if (kalemIdx < 0 || kalemIdx >= kalemler.length) {
            erpToast('Kalem eşleşmedi; giriş geri alınamadı.', 'error');
            return;
        }
        konfAkisDeltasGeriAl(kd, kalemIdx, deltas);
        konfRecalcPanelTotals(kd, kalemler);
        const userLabel = String(erpCurrentUser?.display_name || erpCurrentUser?.username || 'Sistem').trim() || 'Sistem';
        kd.konf_last_save_ts = new Date().toISOString();
        kd.konf_last_save_user = userLabel;
        kd.konf_last_save_tip = 'GERI_AL';
        await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);

        const { error: delErr } = await sb.from('siparis_akis').delete().eq('id', akisId);
        if (delErr) throw delErr;

        try {
            await sb.from('siparis_akis').insert([{
                siparis_id: konfeksiyonSiparisId,
                kalem_ad: row.kalem_ad_db || row.kalem_ad || '—',
                islem: 'KONF_LOG',
                miktar: 0,
                notlar: JSON.stringify({
                    ts: new Date().toISOString(),
                    user: userLabel,
                    note: `Geri alındı: ${ozet}`,
                    geri_alinan_akis_id: akisId
                })
            }]);
        } catch (e) {}

        _kdCache[`KD_KONFEKSIYON_${konfeksiyonSiparisId}`] = kd;
        await konfLoadIslemLog(konfeksiyonSiparisId);
        konfLiveLastStamp = '';
        erpToast('Giriş geri alındı.', 'success');
        renderKonfeksiyon();
    } catch (err) {
        erpToast('Geri alma başarısız: ' + (err?.message || err), 'error', 4000);
    }
}

async function konfKaydet(tip) {
    try {
        if (!konfeksiyonSiparisId) return;
        const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
        const userLabel = String(erpCurrentUser?.display_name || erpCurrentUser?.username || 'Sistem').trim() || 'Sistem';
        const nowIso = new Date().toISOString();
        const fieldMap={
            kesim:['kf-kesim-tarih','kf-kesim-operator','kf-kesim-not'],
            dikim:['kf-dikim-bas','kf-dikim-bit','kf-dikim-hat','kf-dikim-operator-sayi','kf-dikim-not'],
            kk:['kf-kk-tarih','kf-kk-personel','kf-kk-yontem','kf-kk-durum'],
            koli:['kf-koli-tarih','kf-koli-sayi','kf-koli-basi-adet','kf-koli-kg','kf-koli-not'],
            sevk:['kf-sevk-tarih','kf-sevk-personel','kf-sevk-not'],
        };
        const checkMap={};
        (fieldMap[tip]||[]).forEach(id=>{const el=document.getElementById(id);if(el){kd[id.replace('kf-','').replace(/-/g,'_')]=el.value;}});
        (checkMap[tip]||[]).forEach(id=>{const el=document.getElementById(id);if(el){kd[id.replace('kf-','').replace(/-/g,'_')]=el.checked;}});

    /* Kalite sipariş aşımı uyarısı (kesim için uyarı konfKyInsert kapısında). Onaylanmazsa hiçbir şey yazılmaz. */
    if (tip === 'kk') {
        const asimSatir = Object.keys(konfDraft.kalem || {}).map((idx) => {
            const ek = konfDraft.kalem[idx] || {};
            return { siparisId: konfeksiyonSiparisId, kalemIdx: parseInt(idx, 10), asama: 'Kalite',
                eklenen: (parseInt(ek.kk_gecen || 0) || 0) + (parseInt(ek.tamir || 0) || 0) + (parseInt(ek.imha || 0) || 0) };
        });
        if (!(await konfSiparisAsimOnay(asimSatir))) { erpToast('Kayıt iptal edildi — hiçbir şey yazılmadı.', 'info', 3000); return; }
    }

    const kalemAlanMap = {
        kesim: ['kesilen','fire_kesim'],
        dikim: ['dikilen','fire_dikim'],
        kk: ['kk_gecen','tamir','imha'],
        koli: ['kolide'],
        sevk: ['sevk_edilen']
    };
    /* Sevk adedi tek kaynak: Sevkiyat menüsü */
    const hedefAlanlar = (tip === 'sevk' && typeof erpSevkAdetYazmaKapaliMi === 'function' && erpSevkAdetYazmaKapaliMi())
        ? []
        : (kalemAlanMap[tip] || []);
    Object.keys(konfDraft.kalem || {}).forEach(idx => {
        const ek = konfDraft.kalem[idx] || {};
        const key = `kalem_${idx}`;
        if (!kd[key]) kd[key] = {};
        hedefAlanlar.forEach(alan => {
            const artir = parseInt(ek[alan] || 0) || 0;
            if (!artir) return;
            const onceki = parseInt(kd[key][alan] || 0) || 0;
            kd[key][alan] = onceki + artir;
            const logKey = `log_${idx}_${alan}`;
            if (!kd[logKey]) kd[logKey] = [];
            kd[logKey].push({ tarih: new Date().toLocaleString('tr-TR'), miktar: artir, onceki });
        });
    });

    if (tip === 'kk') {
        Object.keys(konfDraft.ikiDetay || {}).forEach(idx => {
            const detayEk = konfDraft.ikiDetay[idx] || {};
            const key = `kalem_${idx}`;
            if (!kd[key]) kd[key] = {};
            const mevcutDetay = konfIkinciKaliteDetayNorm(kd[key].iki_kalite_detay || {});
            ['dokuma','leke','ebat','dikis','diger'].forEach(sebep => {
                const artir = parseInt(detayEk[sebep] || 0) || 0;
                if (!artir) return;
                mevcutDetay[sebep] = (parseInt(mevcutDetay[sebep] || 0) || 0) + artir;
                const logKey = `log_${idx}_iki_kalite_detay_${sebep}`;
                if (!kd[logKey]) kd[logKey] = [];
                kd[logKey].push({ tarih: new Date().toLocaleString('tr-TR'), miktar: artir, toplam: mevcutDetay[sebep] });
            });
            kd[key].iki_kalite_detay = mevcutDetay;
            kd[key].iki_kalite = konfIkinciKaliteDetayToplam(mevcutDetay);
        });
    }

    if (tip === 'dikim') {
        Object.keys(konfDraft.aksesuar || {}).forEach(k => {
            const [akId, alan] = String(k).split('_');
            const val = parseInt(konfDraft.aksesuar[k] || 0) || 0;
            if (akId && alan) kd[`ak_${akId}_${alan}`] = val;
        });
    }

    const kalemler=konfGetKalemler();
    let tK=0,tD=0,tKK=0,tKol=0,tH=0,tSevk=0;
    kalemler.forEach((_,i)=>{const k=kd[`kalem_${i}`]||{};tK+=parseInt(k.kesilen||0);tD+=parseInt(k.dikilen||0);tKK+=parseInt(k.kk_gecen||0);tKol+=parseInt(k.kolide||0);tSevk+=parseInt(k.sevk_edilen||0);tH+=parseInt(k.iki_kalite||0)+parseInt(k.tamir||0)+parseInt(k.imha||0);});
    kd.kesim_toplam=tK;kd.dikim_toplam=tD;kd.kk_gecen=tKK;kd.koli_toplam=tKol;kd.hatali_toplam=tH;
    kd.panel_sevk_toplam=tSevk;

    // Kullanıcı güveni: son kaydı kim/ne zaman yaptı bilgisini KD'ye yaz.
    kd.konf_last_save_ts = nowIso;
    kd.konf_last_save_user = userLabel;
    kd.konf_last_save_tip = String(tip || '').toUpperCase();

    /* Kesim sekmesinden girilen adet, kesim/yıkama kuyruğuna (konf_kesim_yikama)
       da yazılır. Önceden yalnızca KD'ye yazıyordu; bu yüzden buradan girilen
       kesim yıkama önünde görünmüyor, fişe eklenemiyordu. Tek toplanma noktası
       kuralı gereği diğer dört kesim girişiyle aynı tabloya düşüyor.
       KD yazımından ÖNCE yapılır ki ikiz uyarısında vazgeçilirse hiçbir şey
       yazılmasın ve iki taraf tutarsız kalmasın. */
    if (tip === 'kesim' && typeof konfKyInsert === 'function') {
        const sipK = (dataCache.siparisler || []).find(x => String(x.id) === String(konfeksiyonSiparisId));
        const kalemlerK = konfGetKalemler() || [];
        try {
            for (const idxStr of Object.keys(konfDraft.kalem || {})) {
                const i = parseInt(idxStr, 10);
                const artir = parseInt((konfDraft.kalem[idxStr] || {}).kesilen || 0, 10) || 0;
                if (artir <= 0) continue;
                const kalemK = kalemlerK[i] || {};
                const urunAdK = String(kalemK.ad || kalemK.kod || kalemK.cins || 'Ürün').trim();
                const rotaK = (typeof konfPipelineKesimRotaHazirla === 'function')
                    ? await konfPipelineKesimRotaHazirla(konfeksiyonSiparisId, i, urunAdK)
                    : 'YIKAMA';
                await konfKyInsert({
                    siparis_id: konfeksiyonSiparisId,
                    siparis_sno: sipK?.sno || '',
                    firma: sipK?.firma || '',
                    kalem_idx: i,
                    desen: urunAdK,
                    renk: String(kalemK.renk || '').trim(),
                    ebat: String(kalemK.ebat || kalemK.olcu || '').trim(),
                    kesilen_adet: artir,
                    rota: rotaK,
                    durum: rotaK === 'YIKAMA' ? 'YIKAMA_BEKLIYOR' : 'KALITE_BEKLIYOR',
                    kaynak: 'SIPARIS_DETAY_KESIM',
                    kesim_user: userLabel,
                    kesim_ts: nowIso
                });
            }
            if (typeof konfLoadKesimGecmis === 'function') await konfLoadKesimGecmis({ force: true });
        } catch (e) {
            if (e && e.ikizIptal) {
                erpToast('Kayıt yapılmadı — aynı ürüne aynı adet zaten girilmiş.', 'warn', 4500);
                return;
            }
            console.warn('siparis detay kesim -> kuyruk', e);
            erpToast('Kesim kuyruğa yazılamadı: ' + (e?.message || e), 'error', 5000);
            return;
        }
    }

    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);

    // Hareket tablosuna da yaz (raporlarda created_at bazlı net toplama için)
    try {
        const islemMap = { kesim: 'KESIM', dikim: 'DIKIM', kk: 'KALITE', koli: 'KOLI', sevk: 'SEVK' };
        const anaAlanMap = { kesim: 'kesilen', dikim: 'dikilen', kk: 'kk_gecen', koli: 'kolide', sevk: 'sevk_edilen' };
        const detayAlanEtiket = {
            kesilen: 'Kesilen',
            fire_kesim: 'Fire kesim',
            dikilen: 'Dikilen',
            fire_dikim: 'Fire dikim',
            kk_gecen: 'Kalite geçen',
            tamir: 'Tamir',
            imha: 'İmha',
            kolide: 'Kolide',
            sevk_edilen: 'Sevk edilen'
        };
        const anaAlan = anaAlanMap[tip];
        const islemKod = islemMap[tip];
        if (anaAlan && islemKod) {
            const akisRows = [];
            Object.keys(konfDraft.kalem || {}).forEach(idxStr => {
                const idx = parseInt(idxStr, 10);
                const satir = konfDraft.kalem[idxStr] || {};
                const artir = parseInt(satir[anaAlan] || 0, 10) || 0;
                if (artir <= 0) return;
                const detaylar = [];
                (hedefAlanlar || []).forEach(alan => {
                    const dv = parseInt(satir[alan] || 0, 10) || 0;
                    if (!dv) return;
                    detaylar.push(`${detayAlanEtiket[alan] || alan}: +${dv}`);
                });
                if (tip === 'kk') {
                    const kkDet = konfDraft.ikiDetay?.[idxStr] || {};
                    ['dokuma','leke','ebat','dikis','diger'].forEach(sebep => {
                        const dv = parseInt(kkDet[sebep] || 0, 10) || 0;
                        if (!dv) return;
                        detaylar.push(`2.kalite ${sebep}: +${dv}`);
                    });
                }
                const kalemRenk = kalemler[idx]?.renk || '';
                const kalemEbat = kalemler[idx]?.ebat || kalemler[idx]?.olcu || '';
                const kalemBaseAd = kalemler[idx]?.ad || kalemler[idx]?.kod || `Kalem ${idx + 1}`;
                const kalemDetayAd = [kalemRenk, kalemEbat].filter(Boolean).join(' · ');
                const kalemAd = kalemDetayAd ? `${kalemBaseAd} (${kalemDetayAd})` : kalemBaseAd;
                const deltas = {};
                (hedefAlanlar || []).forEach((alan) => {
                    const dv = parseInt(satir[alan] || 0, 10) || 0;
                    if (dv) deltas[alan] = dv;
                });
                if (tip === 'kk') {
                    const kkDet = konfDraft.ikiDetay?.[idxStr] || {};
                    const iki = {};
                    ['dokuma', 'leke', 'ebat', 'dikis', 'diger'].forEach((sebep) => {
                        const dv = parseInt(kkDet[sebep] || 0, 10) || 0;
                        if (dv) iki[sebep] = dv;
                    });
                    if (Object.keys(iki).length) deltas._iki_kalite_detay = iki;
                }
                const notPayload = {
                    ts: nowIso,
                    user: userLabel,
                    note: detaylar.length ? `Konfeksiyon panel kaydı (${detaylar.join(' · ')})` : 'Konfeksiyon panel kaydı',
                    kalem_idx: Number.isFinite(idx) ? idx : null,
                    kalem_key: kalemler[idx] ? konfKalemKey(kalemler[idx]) : '',
                    kalem_renk: kalemRenk,
                    kalem_ebat: kalemEbat,
                    konf_panel: true,
                    deltas,
                    detay: {
                        tip: String(tip || ''),
                        alanlar: detaylar
                    }
                };
                akisRows.push({
                    siparis_id: konfeksiyonSiparisId,
                    kalem_ad: kalemAd,
                    islem: islemKod,
                    miktar: artir,
                    notlar: JSON.stringify(notPayload)
                });
            });
            if (akisRows.length) await sb.from('siparis_akis').insert(akisRows);
        }
    } catch (e) {}

    /* Kalite sekmesinden girilen mal yıkamadan dönmüştür: "Yıkamada olan"dan düş.
       Kalite masasından geçen her şey sayılır (kk_gecen + 2. kalite + tamir + imha). */
    if (tip === 'kk' && typeof konfYikamadanDus === 'function') {
        let toplamDusen = 0;
        try {
            for (const idxStr of Object.keys(konfDraft.kalem || {})) {
                const i = parseInt(idxStr, 10);
                const satirK = konfDraft.kalem[idxStr] || {};
                const kkDetK = (konfDraft.ikiDetay || {})[idxStr] || {};
                const ikiTop = ['dokuma', 'leke', 'ebat', 'dikis', 'diger']
                    .reduce((t, sb2) => t + (parseInt(kkDetK[sb2] || 0, 10) || 0), 0);
                const donen = (parseInt(satirK.kk_gecen || 0, 10) || 0)
                    + (parseInt(satirK.tamir || 0, 10) || 0)
                    + (parseInt(satirK.imha || 0, 10) || 0)
                    + ikiTop;
                if (donen <= 0) continue;
                toplamDusen += await konfYikamadanDus(konfeksiyonSiparisId, i, donen, {
                    user: userLabel, kaynak: 'SIPARIS_DETAY_KALITE'
                });
            }
            if (toplamDusen > 0) {
                if (typeof konfLoadKesimGecmis === 'function') await konfLoadKesimGecmis({ force: true });
                erpToast(`Yıkamadan ${toplamDusen.toLocaleString('tr-TR')} ad düşüldü.`, 'info', 4000);
            }
        } catch (e) { console.warn('siparis detay kalite -> yikamadan dusum', e); }
    }

    // “Kaydettim mi?” şüphesini bitirmek için her kayıtta iz bırak.
    // miktar=0; metrik/toplam hesaplarını etkilemez, sadece geçmişte görünür.
    try {
        const tipLabelMap = { kesim: 'Kesim', dikim: 'Dikim', kk: 'Kalite', koli: 'Koli', sevk: 'Sevkiyat' };
        const tipLabel = tipLabelMap[tip] || String(tip || 'Konfeksiyon');
        const changedKalem = Object.keys(konfDraft.kalem || {}).length;
        const changedAks = Object.keys(konfDraft.aksesuar || {}).length;
        const changed2K = Object.keys(konfDraft.ikiDetay || {}).length;
        const note = `Kaydedildi: ${tipLabel} · kalem:${changedKalem} · aks:${changedAks} · 2.kalite:${changed2K}`;
        const notPayload = { ts: nowIso, user: userLabel, note, tip: String(tip || '') };
        await sb.from('siparis_akis').insert([{
            siparis_id: konfeksiyonSiparisId,
            kalem_ad: tipLabel,
            islem: 'KONF_LOG',
            miktar: 0,
            notlar: JSON.stringify(notPayload)
        }]);
    } catch (e) {}

        if (tip === 'dikim') konfDraft.aksesuar = {};
        if (tip === 'kk') konfDraft.ikiDetay = {};
        const yeniKalemDraft = {};
        Object.keys(konfDraft.kalem || {}).forEach(idx => {
            const satir = konfDraft.kalem[idx] || {};
            const kalan = {};
            Object.keys(satir).forEach(alan => {
                if (!hedefAlanlar.includes(alan)) kalan[alan] = satir[alan];
            });
            if (Object.keys(kalan).length) yeniKalemDraft[idx] = kalan;
        });
        konfDraft.kalem = yeniKalemDraft;

        const btnMap={kesim:'bg-violet-600',dikim:'bg-pink-600',kk:'bg-amber-500',koli:'bg-emerald-600',sevk:'bg-cyan-600'};
        const btn=document.querySelector(`button[onclick="konfKaydet('${tip}')"]`);
        if(btn){const orig=btn.innerHTML;btn.innerHTML='✅ KAYDEDİLDİ';btn.classList.add('opacity-75');setTimeout(()=>{btn.innerHTML=orig;btn.classList.remove('opacity-75');},1500);}
        erpToast('Kayıt başarıyla kaydedildi.', 'success');
        renderKonfeksiyon();
    } catch (err) {
        erpToast("Kayıt başarısız: " + (err?.message || err), 'error', 3600);
    }
}

async function konfKapama() {
    if (!konfeksiyonSiparisId) return;
    const kd = await sbKdGet(konfeksiyonSiparisId, 'KD_KONFEKSIYON');
    const t=document.getElementById('kf-kapama-tarih');const n=document.getElementById('kf-kapama-not');
    if(t)kd.kapama_tarih=t.value;if(n)kd.kapama_not=n.value;
    kd.kapama_yapildi=true;
    await sbKdSet(konfeksiyonSiparisId, 'KD_KONFEKSIYON', kd);
    alert('Kapama tarihi/notu kaydedildi.\n\nSiparişi «Tamamlandı» yapmak için: Siparişler → kaydı aç (düzenle) → «Siparişi tamamla ve kapat».');
    renderKonfeksiyon();
}

function initDashboardDrag() {
    const grid = document.getElementById('kpi-grid');
    if (!grid || grid.dataset.dragInit) return;
    grid.dataset.dragInit = '1';
    let dragging = null;
    grid.querySelectorAll(':scope > div').forEach(card => {
        card.setAttribute('draggable', true);
        card.addEventListener('dragstart', () => { dragging = card; card.style.opacity = '0.4'; });
        card.addEventListener('dragend',   () => { dragging = null; card.style.opacity = '1'; });
        card.addEventListener('dragover',  e => { e.preventDefault(); });
        card.addEventListener('drop', () => {
            if (dragging && dragging !== card) {
                const cards = [...grid.children];
                const fromIdx = cards.indexOf(dragging);
                const toIdx   = cards.indexOf(card);
                if (fromIdx < toIdx) grid.insertBefore(dragging, card.nextSibling);
                else grid.insertBefore(dragging, card);
            }
        });
    });
}

// --- SİDEBAR ---
function toggleTheme() {
    const isLight = document.body.classList.toggle('light-mode');
    const icon = isLight ? '☀️' : '🌙';
    ['theme-btn','dash-theme-btn'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = icon;
    });
    localStorage.setItem('erp_theme', isLight ? 'light' : 'dark');
}

function applyTheme() {
    const saved = localStorage.getItem('erp_theme');
    if (saved === 'light') {
        document.body.classList.add('light-mode');
        const icon = '☀️';
        ['theme-btn','dash-theme-btn'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.textContent = icon;
        });
    }
}

/** Arayüz kabuğu: simteks (varsayılan) | workcube — localStorage erp_ui_skin; geri dönüş için "Simteks" seçin */
function erpApplySkinFromStorage() {
    let v = 'simteks';
    try { v = localStorage.getItem('erp_ui_skin') || 'simteks'; } catch (e) {}
    document.body.classList.toggle('erp-skin-workcube', v === 'workcube');
    const sel = document.getElementById('erp-skin-select');
    if (sel) sel.value = v === 'workcube' ? 'workcube' : 'simteks';
}

function toggleChicSub(id) {
    const sub = document.getElementById('sub-' + id);
    if (!sub) return;
    const isOpen = sub.classList.contains('open');
    const parentGroup = sub.closest('.nav-group-body');
    closeAllNavAccordions();
    if (!isOpen) {
        sub.classList.add('open');
        if (parentGroup) parentGroup.classList.add('open');
    }
}

function closeAllSubs() {
    closeAllNavAccordions();
}

function sidebarFilterNav(term) {
    const nav = document.getElementById('main-nav');
    if (!nav) return;
    const q = (term || '').trim().toLocaleLowerCase('tr-TR');
    const directItems = Array.from(nav.querySelectorAll(':scope > .nav-pro, .nav-group .nav-pro'));
    const subAreas = Array.from(nav.querySelectorAll(':scope > .nav-pro-sub-area, .nav-group .nav-pro-sub-area'));
    const labels = Array.from(nav.querySelectorAll(':scope > .nav-pro-label, :scope > .nav-mini-label'));
    const navGroups = Array.from(nav.querySelectorAll(':scope > .nav-group'));

    if (!q) {
        labels.forEach(el => el.style.display = '');
        directItems.forEach(el => el.style.display = '');
        navGroups.forEach(g => g.style.display = '');
        subAreas.forEach(area => {
            area.style.display = '';
            area.querySelectorAll('.nav-pro-sub').forEach(sub => sub.style.display = '');
        });
        erpApplyNavPermissions();
        return;
    }

    directItems.forEach(el => {
        const txt = (el.textContent || '').toLocaleLowerCase('tr-TR');
        const isToggle = (el.id || '').endsWith('-toggle');
        if (!isToggle) {
            if (el.classList.contains('erp-nav-denied')) {
                el.style.display = 'none';
                return;
            }
            el.style.display = txt.includes(q) ? '' : 'none';
        }
    });

    subAreas.forEach(area => {
        const subItems = Array.from(area.querySelectorAll('.nav-pro-sub'));
        let hasSubMatch = false;
        subItems.forEach(sub => {
            if (sub.classList.contains('erp-nav-denied')) {
                sub.style.display = 'none';
                return;
            }
            const hit = (sub.textContent || '').toLocaleLowerCase('tr-TR').includes(q);
            sub.style.display = hit ? '' : 'none';
            if (hit) hasSubMatch = true;
        });

        const subId = area.id.replace('sub-', '');
        const parentToggle = document.getElementById('nav-' + subId + '-toggle');
        const parentHit = ((parentToggle?.textContent || '').toLocaleLowerCase('tr-TR')).includes(q);
        const areaVisible = hasSubMatch || parentHit;

        area.style.display = areaVisible ? '' : 'none';
        if (parentToggle) parentToggle.style.display = areaVisible ? '' : 'none';

        if (areaVisible) {
            area.classList.add('open');
            const chev = document.getElementById('chev-' + subId);
            if (chev) chev.style.transform = 'rotate(180deg)';
        }
    });

    navGroups.forEach(group => {
        const groupHead = group.querySelector('.nav-group-head');
        const groupBody = group.querySelector('.nav-group-body');
        const headHit = ((groupHead?.textContent || '').toLocaleLowerCase('tr-TR')).includes(q);
        const toggles = Array.from(group.querySelectorAll('.nav-pro[id$="-toggle"]'));
        const anyToggleVisible = toggles.some(t => t.style.display !== 'none');
        const groupVisible = headHit || anyToggleVisible;
        group.style.display = groupVisible ? '' : 'none';
        if (groupVisible && groupBody) {
            groupBody.classList.add('open');
            const groupChev = groupBody.id ? document.getElementById('chev-' + groupBody.id) : null;
            if (groupChev) groupChev.style.transform = 'rotate(180deg)';
        }
    });

    const children = Array.from(nav.children);
    let currentLabel = null;
    let hasVisibleAfterLabel = false;
    const flushLabel = () => {
        if (currentLabel) currentLabel.style.display = hasVisibleAfterLabel ? '' : 'none';
    };

    children.forEach(ch => {
        const isLabel = ch.classList?.contains('nav-pro-label') || ch.classList?.contains('nav-mini-label');
        if (isLabel) {
            flushLabel();
            currentLabel = ch;
            hasVisibleAfterLabel = false;
            return;
        }
        if (currentLabel && ch.style.display !== 'none') hasVisibleAfterLabel = true;
    });
    flushLabel();
}

