        'YAPILACAKLAR': 'Yapılacaklar Listesi',
        'URUN_AGACI': 'Ürün Ağacı',
        'RAPORLAR': 'Raporlar & Analiz',
        'DOKUMA_TAKIP': 'Dokuma Takip',
        'DOKUMA_DEPO': 'Dokuma Depo',
        'DOKUMA_SEVK_GECMIS': 'Dokuma Sevk Geçmişi',
