// --- İPLİK ARAMA (YENİ SİSTEM) — lot bazlı, depo ile aynı bakiye ---
function iplikSearchLotRows() {
    const map = new Map();
    const put = (row, preferHigher) => {
        const kod = String(row.stok_kodu || '').trim();
        if (!kod) return;
        const lotNo = String(row.lot_no || 'LOTSUZ').trim() || 'LOTSUZ';
        const marka = String(row.marka || 'GENEL').trim() || 'GENEL';
        const key = `${kod}||${lotNo}||${marka}`.toLowerCase();
        const bakiye = Number(row.bakiye) || 0;
        const next = {
            stok_kodu: kod,
            iplik_no: row.iplik_no || '',
            lot_no: lotNo === 'LOTSUZ' ? (row.lot_no || '') : lotNo,
            marka,
            cins: row.cins || '',
            kalite: row.kalite || '1. KALİTE',
            bakiye
        };
        const prev = map.get(key);
        if (!prev) {
            map.set(key, next);
            return;
        }
        if (preferHigher && Math.abs(bakiye) > Math.abs(prev.bakiye)) {
            map.set(key, { ...prev, ...next, bakiye });
        } else if (!preferHigher) {
            map.set(key, {
                ...prev,
                ...next,
                bakiye: prev.bakiye,
                iplik_no: next.iplik_no || prev.iplik_no,
                cins: next.cins || prev.cins
            });
        }
    };

    // 1) Depo listesi ile aynı kaynak (kart lot kg + gerçek hareket)
    if (typeof iplikStokListeGruplariOlustur === 'function') {
        const gruplar = iplikStokListeGruplariOlustur(
            (typeof dataCache !== 'undefined' ? dataCache.iplik_stok : null) || []
        ) || [];
        gruplar.forEach(g => {
            const lots = (g.lots && g.lots.length)
                ? g.lots
                : [{ lot_no: 'LOTSUZ', marka: g.marka, cins: g.cins, net_kg: g.net_kg || 0 }];
            lots.forEach(lot => {
                put({
                    stok_kodu: g.stok_kodu,
                    iplik_no: g.iplik_no,
                    lot_no: lot.lot_no,
                    marka: lot.marka || g.marka,
                    cins: lot.cins || g.cins,
                    bakiye: Number(lot.net_kg != null ? lot.net_kg : lot.total_kg) || 0
                }, true);
            });
        });
    }

    // 2) Karttaki tüm lotlar görünsün (22 lot vb. — depoda hareketi olmasa bile)
    const kartlar = typeof iplikKartlariListe === 'function' ? iplikKartlariListe() : [];
    (kartlar || []).forEach(k => {
        const kod = String(k.stok_kodu || '').trim();
        if (!kod) return;
        const lots = typeof iplikKartLotlariAl === 'function' ? iplikKartLotlariAl(k) : [];
        const list = (lots && lots.length)
            ? lots
            : [{ lot_no: k.lot_no || '', marka: k.marka, cins: k.cins, miktar_kg: 0 }];
        list.forEach(lot => {
            const lotNo = String(lot.lot_no || '').trim();
            const marka = String(lot.marka || k.marka || 'GENEL').trim() || 'GENEL';
            const key = `${kod}||${lotNo || 'LOTSUZ'}||${marka}`.toLowerCase();
            const kartKg = parseFloat(lot.miktar_kg) || 0;
            if (!map.has(key)) {
                put({
                    stok_kodu: kod,
                    iplik_no: k.iplik_no,
                    lot_no: lotNo,
                    marka,
                    cins: lot.cins || k.cins,
                    kalite: k.kalite || '1. KALİTE',
                    bakiye: kartKg
                }, true);
            } else {
                const cur = map.get(key);
                if (!(Math.abs(cur.bakiye) > 1e-9) && kartKg > 0) cur.bakiye = kartKg;
                if (!cur.iplik_no) cur.iplik_no = k.iplik_no || '';
                if (!cur.cins) cur.cins = lot.cins || k.cins || '';
            }
        });
    });

    // 3) Yedek: ham hareket (grup fonksiyonu yoksa)
    if (!map.size) {
        const tmp = {};
        ((typeof dataCache !== 'undefined' ? dataCache.iplik_stok : null) || []).forEach(x => {
            const kod = String(x.stok_kodu || '').trim();
            if (!kod) return;
            const lotNo = String(x.lot_no || 'LOTSUZ').trim() || 'LOTSUZ';
            const marka = String(x.marka || 'GENEL').trim() || 'GENEL';
            const key = `${kod}||${lotNo}||${marka}`.toLowerCase();
            if (!tmp[key]) {
                tmp[key] = {
                    stok_kodu: kod,
                    iplik_no: x.iplik_no || '',
                    lot_no: x.lot_no || '',
                    marka,
                    cins: x.cins || '',
                    kalite: x.kalite || '1. KALİTE',
                    bakiye: 0
                };
            }
            tmp[key].bakiye += parseFloat(x.miktar_kg) || 0;
        });
        Object.values(tmp).forEach(r => put(r, true));
    }

    return Array.from(map.values()).sort((a, b) =>
        String(a.stok_kodu).localeCompare(String(b.stok_kodu), 'tr', { numeric: true })
        || String(a.lot_no || '').localeCompare(String(b.lot_no || ''), 'tr', { numeric: true })
        || (b.bakiye - a.bakiye)
    );
}
window.iplikSearchLotRows = iplikSearchLotRows;

function iplikSearch(q) {
    const res = document.getElementById('iplik-search-results');
    if (!res) return;
    q = (q || '').trim().toLocaleLowerCase('tr-TR');
    if (q.length < 1) { res.style.display = 'none'; return; }

    const rows = iplikSearchLotRows();
    const uniq = rows.filter(x =>
        (x.stok_kodu || '').toLocaleLowerCase('tr-TR').includes(q) ||
        (x.iplik_no || '').toLocaleLowerCase('tr-TR').includes(q) ||
        (x.marka || '').toLocaleLowerCase('tr-TR').includes(q) ||
        (x.lot_no || '').toLocaleLowerCase('tr-TR').includes(q) ||
        (x.cins || '').toLocaleLowerCase('tr-TR').includes(q)
    ).slice(0, 40);

    if (uniq.length === 0) {
        const iplikInpE = document.getElementById('val-iplik-search');
        const searchQ = q;
        if (movementType === 'GİRİŞ') {
            showSearchDropdown('iplik-search-results', iplikInpE, `
            <div style="padding:14px 16px;display:flex;flex-direction:column;gap:10px">
                <div style="font-size:10px;color:var(--text3);text-align:center">
                    <span style="font-size:16px;display:block;margin-bottom:6px">🔍</span>
                    "<b>${searchQ}</b>" için iplik stok kartı bulunamadı
                </div>
                <button onclick="openKartGirisFromSearch('IPLIK','${searchQ}')"
                    style="width:100%;padding:10px;border:none;border-radius:10px;background:var(--accent2,#7c3aed);color:white;font-size:10px;font-weight:700;cursor:pointer;font-family:'DM Mono',monospace;letter-spacing:0.05em">
                    ➕ YENİ İPLİK KARTI OLUŞTUR
                </button>
            </div>`, 4500);
        } else {
            showSearchDropdown('iplik-search-results', iplikInpE, `
            <div style="padding:14px 16px;text-align:center">
                <div style="font-size:16px;margin-bottom:6px">⚠️</div>
                <div style="font-size:10px;font-weight:700;color:var(--rose-c);margin-bottom:4px">STOK KARTI BULUNAMADI</div>
                <div style="font-size:9px;color:var(--text3)">Çıkış için önce iplik stok kartı tanımlanmalıdır.</div>
                <button onclick="setAppMode('IPLIK_KART_GIRIS')" 
                    style="margin-top:10px;width:100%;padding:8px;border:none;border-radius:8px;background:var(--surface2);border:1px solid var(--border);color:var(--text);font-size:10px;font-weight:700;cursor:pointer">
                    🧶 İplik Kart Girişine Git
                </button>
            </div>`, 4500);
        }
        return;
    }

    window._iplikSearchData = uniq;
    const iplikInp = document.getElementById('val-iplik-search');
    const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
    showSearchDropdown('iplik-search-results', iplikInp, uniq.map((x, i) => {
        const lotYazi = x.lot_no ? `Lot ${esc(x.lot_no)}` : 'Lot —';
        const kg = Number(x.bakiye) || 0;
        const kgCls = kg < 0 ? 'var(--rose-c)' : (kg === 0 ? 'var(--text3)' : 'var(--emerald-c)');
        return `<div data-idx="${i}" onclick="iplikSelectItem(this)"
            style="padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:10px"
            onmouseover="this.style.background='var(--surface2)'" onmouseout="this.style.background='transparent'">
            <div style="min-width:0">
                <div>
                    <span style="font-family:'DM Mono',monospace;font-size:11px;font-weight:700;color:var(--accent2)">${esc(x.stok_kodu || '—')}</span>
                    <span style="font-size:11px;font-weight:700;color:#2563eb;margin-left:8px;font-family:'DM Mono',monospace">${lotYazi}</span>
                </div>
                <div style="font-size:10px;color:var(--text2);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">
                    ${esc(x.iplik_no || '—')}${x.marka ? ' · ' + esc(x.marka) : ''}${x.cins ? ' · ' + esc(x.cins) : ''}
                </div>
            </div>
            <div style="font-size:11px;font-weight:700;color:${kgCls};font-family:'DM Mono',monospace;flex-shrink:0">${kg.toLocaleString('tr-TR', { maximumFractionDigits: 1 })} kg</div>
        </div>`;
    }).join(''));
}

function iplikSelectItem(el) {
    const idx = parseInt(el.getAttribute('data-idx'));
    const x   = (window._iplikSearchData || [])[idx];
    if (!x) return;

    try { hideAllDropdowns(); } catch (e) {
        const elDrop = document.getElementById('iplik-search-results');
        if (elDrop) elDrop.style.display = 'none';
    }
    const inp = document.getElementById('val-iplik-search');
    if (inp) {
        const lotPart = x.lot_no ? ` · Lot ${x.lot_no}` : '';
        inp.value = (x.stok_kodu ? x.stok_kodu + ' — ' : '') + (x.iplik_no || '') + lotPart;
    }

    const fill = (id, v) => { const el = document.getElementById(id); if (el) el.value = v||''; };
    fill('val-stok-kodu', x.stok_kodu);
    fill('val-no',        x.iplik_no);
    fill('val-lot',       x.lot_no);
    fill('val-marka',     x.marka);
    fill('val-cins',      x.cins);
    const kalEl = document.getElementById('val-kalite');
    if (kalEl && x.kalite) kalEl.value = x.kalite;

    const card = document.getElementById('iplik-selected-card');
    if (card) {
        card.style.display = 'block';
        document.getElementById('isel-kod').textContent    = x.stok_kodu || '—';
        document.getElementById('isel-no').textContent     = x.iplik_no  || '—';
        document.getElementById('isel-lot').textContent    = (x.lot_no || '—') + (x.marka ? ' / ' + x.marka : '');
        document.getElementById('isel-bakiye').textContent = (Number(x.bakiye) || 0).toFixed(2) + ' kg';
    }

    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v||'—'; };
    set('prev-kod',   x.stok_kodu);
    set('prev-no',    x.iplik_no);
    set('prev-lot',   x.lot_no);
    set('prev-marka', x.marka);
    set('prev-cins',  x.cins);
    set('prev-kalite', x.kalite || '1. KALİTE');
}

function iplikClearSelection() {
    const card = document.getElementById('iplik-selected-card');
    if (card) card.style.display = 'none';
    const inp = document.getElementById('val-iplik-search');
    if (inp) inp.value = '';
    ['val-stok-kodu','val-no','val-lot','val-marka','val-cins'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
    });
    ['prev-kod','prev-no','prev-lot','prev-marka','prev-cins'].forEach(id => {
        const el = document.getElementById(id); if (el) el.textContent = '—';
    });
}

// --- İPLİK ARAMA (ESKİ - GERİ UYUM) ---
function searchIplikCards(el) {
    const list = document.getElementById('iplik-suggest-list');
    const val = el.value.toLocaleLowerCase('tr-TR').trim();
    if (val.length < 1) { list.style.display = 'none'; return; }

    const iplikVerileri = (dataCache.iplik_stok || []).filter(item => item.iplik_no);
    const cards = [];
    const seen = new Set();
    iplikVerileri.forEach(i => {
        const id = `${i.iplik_no}-${i.marka}-${i.cins}`.toLowerCase().trim();
        if (!seen.has(id)) { seen.add(id); cards.push(i); }
    });

    const filtered = cards.filter(c =>
        (String(c.iplik_no || '').toLocaleLowerCase('tr-TR').includes(val)) ||
        (String(c.lot_no || '').toLocaleLowerCase('tr-TR').includes(val))
    );

    if (filtered.length > 0) {
        list.innerHTML = filtered.map(c => `
            <div class="suggest-item border-b last:border-0 hover:bg-indigo-50 transition-colors p-3"
                 onclick="selectIplikCard('${c.iplik_no}', '${c.cins}', '${c.lot_no}', '${c.marka}', '${c.kalite}', '${c.stok_kodu || ''}')">
                <div class="flex justify-between items-center mb-1">
                    <div>
                        <span class="text-[9px] font-black text-indigo-500 uppercase">${c.stok_kodu || 'KODSUZ'}</span>
                        <p class="font-black text-xs text-slate-800">${c.iplik_no}</p>
                    </div>
                    <span class="text-[9px] bg-slate-800 text-white px-2 py-0.5 rounded-full font-bold">LOT: ${c.lot_no}</span>
                </div>
                <div class="text-[10px] text-slate-400 font-bold uppercase">${c.marka} - ${c.cins}</div>
            </div>`).join('');
        list.style.display = 'block';
    } else {
        if (movementType === 'GİRİŞ') {
            list.innerHTML = `
                <div class="p-4 text-center">
                    <p class="text-[10px] text-slate-400 font-bold mb-2 uppercase tracking-tight">Bu İplik Kayıtlı Değil</p>
                    <button type="button" onclick="prepareNewIplikCard('${val}')" class="w-full bg-indigo-600 text-white text-[10px] py-3 rounded-xl font-black shadow-lg hover:bg-indigo-700 transition-all uppercase tracking-widest">
                        + YENİ STOK KARTI OLARAK AÇ
                    </button>
                </div>`;
        } else {
            list.innerHTML = `
                <div class="p-4 text-center bg-rose-50 rounded-xl">
                    <p class="text-[11px] text-rose-600 font-black uppercase tracking-widest">⚠️ STOK BULUNAMADI</p>
                    <p class="text-[9px] text-rose-400 font-bold mt-1">Çıkış yapmak için önce ipliği sisteme girmelisiniz.</p>
                </div>`;
        }
        list.style.display = 'block';
    }
}

// --- YENİ İPLİK KARTI HAZIRLAMA (TEK TANIM) ---
async function prepareNewIplikCard(inputVal) {
    // Eski uyum: searchIplikCards içinden çağrılır
    // Doğrudan IPLIK_KART_GIRIS'e yönlendir
    openKartGirisFromSearch('IPLIK', inputVal);
    return;

    // --- Aşağısı artık kullanılmıyor (geriye dönük) ---
    const nextCode = await getNextIplikStokCode();

    document.getElementById('val-no') && (document.getElementById('val-no').value = inputVal.toUpperCase());
    document.getElementById('val-iplik-search') && (document.getElementById('val-iplik-search').value = inputVal.toUpperCase() + " (YENİ KAYIT)");
    document.getElementById('iplik-suggest-list') && (document.getElementById('iplik-suggest-list').style.display = 'none');

    const fields = ['val-no', 'val-lot', 'val-marka', 'val-cins', 'val-kalite'];
    fields.forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.readOnly = false; el.style.backgroundColor = 'transparent'; el.style.opacity = '1'; }
    });

    const infoBox = document.getElementById('selected-card-info');
    infoBox.classList.remove('hidden');
    infoBox.innerHTML = `
        <span class="text-[10px] font-black px-3 py-1 bg-rose-600 text-white rounded-full animate-pulse uppercase tracking-widest">
            ✨ YENİ KART: ${nextCode}
        </span>`;
    document.getElementById('val-stok-kodu').value = nextCode;
    document.getElementById('val-no').focus();
}

function selectIplikCard(no, cins, lot, marka, kalite, stokKodu) {
    document.getElementById('val-no').value = no || '';
    document.getElementById('val-cins').value = cins || '';
    document.getElementById('val-lot').value = lot || '';
    document.getElementById('val-marka').value = marka || '';
    document.getElementById('val-kalite').value = kalite || '1. KALİTE';
    document.getElementById('val-iplik-search').value = `${no} - LOT: ${lot}`;
    document.getElementById('iplik-suggest-list').style.display = 'none';

    const fields = ['val-no', 'val-lot', 'val-marka', 'val-cins', 'val-kalite'];
    fields.forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.readOnly = true; el.style.opacity = '0.6'; }
    });

    const infoBox = document.getElementById('selected-card-info');
    infoBox.classList.remove('hidden');
    infoBox.innerHTML = `
        <span class="text-[9px] font-black px-2 py-1 bg-indigo-600 text-white rounded-lg uppercase">
            ✅ KAYITLI KART: ${stokKodu || 'IP-XXXX'}
        </span>
        <input type="hidden" id="val-stok-kodu" value="${stokKodu || ''}">`;
}


// Arama'dan Kart Girişine yönlendirme
function openKartGirisFromSearch(tip, arananKod) {
    // Arama dropdown'ı kapat
    ['kumas-search-results','mamul-search-results','iplik-search-results'].forEach(id => {
        const el = document.getElementById(id); if (el) el.style.display = 'none';
    });

    // Tipe göre doğru kart modunu aç
    const modMap = { 'IPLIK': 'IPLIK_KART_GIRIS', 'KUMAS': 'KUMAS_KART_GIRIS', 'MAMUL': 'MAMUL_KART_GIRIS' };
    const hedefMod = modMap[tip] || 'KUMAS_KART_GIRIS';
    setAppMode(hedefMod);

    // İlgili alana aranan terimi otomatik doldur
    setTimeout(() => {
        let doldurulanAlan = null;
        if (tip === 'IPLIK') {
            // İplik kart girişi: iplik no alanına yaz
            const iplikNoEl = document.getElementById('val-iplik-no');
            if (iplikNoEl) { iplikNoEl.value = arananKod.toUpperCase(); iplikNoEl.focus(); doldurulanAlan = 'İplik No'; }
        } else if (tip === 'KUMAS') {
            // Kumaş kart girişi: kumaş cinsi veya desen adına yaz
            const kumasCinsEl = document.getElementById('val-kumas-cinsi');
            if (kumasCinsEl) { kumasCinsEl.value = arananKod.toUpperCase(); kumasCinsEl.focus(); doldurulanAlan = 'Kumaş Cinsi'; }
        } else if (tip === 'MAMUL') {
            // Mamül kart girişi: ürün adına yaz
            const urunAdiEl = document.getElementById('val-urun-adi');
            if (urunAdiEl) { urunAdiEl.value = arananKod.toUpperCase(); urunAdiEl.focus(); doldurulanAlan = 'Ürün Adı'; }
        }
        const tipAdi = tip === 'IPLIK' ? '🧶 İplik' : tip === 'KUMAS' ? '🏁 Kumaş' : '🧥 Mamül';
        showToast(`"${arananKod}" — ${tipAdi} kart girişi açıldı`, 'info');
    }, 300);
}

// Toast bildirimi
function showToast(msg, tip='info') {
    let t = document.getElementById('erp-toast');
    if (!t) {
        t = document.createElement('div');
        t.id = 'erp-toast';
        t.style.cssText = 'position:fixed;bottom:24px;right:24px;z-index:9999;padding:12px 18px;border-radius:12px;font-size:11px;font-weight:700;font-family:"DM Mono",monospace;max-width:280px;box-shadow:0 8px 24px rgba(0,0,0,0.15);transition:opacity 0.3s;pointer-events:none';
        document.body.appendChild(t);
    }
    const bg = tip==='info' ? 'var(--accent)' : tip==='success' ? 'var(--emerald-c)' : 'var(--rose-c)';
    t.style.cssText += `;background:${bg};color:white;opacity:1`;
    t.textContent = msg;
    clearTimeout(t._timer);
    t._timer = setTimeout(() => { t.style.opacity='0'; }, 3000);
}

// Dropdown portal — overflow:hidden sorununu aşmak için body'e taşı
// Tüm arama listeleri: scroll / dış tık / Escape / anchor kaybında kapanır (ortada asılı kalmaz)
const ERP_SEARCH_DROP_IDS = [
    'iplik-search-results',
    'kumas-search-results',
    'mamul-search-results',
    'mamul-toplu-kod-drop',
    'kumas-toplu-kod-drop'
];

function dropdownAnchorKaydet(drop) {
    if (!drop || drop._anchorParent) return;
    drop._anchorParent = drop.parentElement;
    drop._anchorNext = drop.nextSibling;
}

function dropdownStilSifirla(drop) {
    if (!drop) return;
    ['position', 'top', 'left', 'right', 'bottom', 'width', 'minWidth', 'maxWidth',
        'maxHeight', 'overflowY', 'overflowX', 'zIndex', 'paddingTop', 'marginTop',
        'pointerEvents', 'display'].forEach(k => {
        try { drop.style[k] = ''; } catch (e) {}
    });
}

function dropdownPortalTemizle(drop) {
    if (!drop) return;
    try { clearTimeout(drop._hideTimer); } catch (e) {}
    drop._anchorInput = null;
    drop._anchorIdx = null;
    try { drop.classList.remove('is-open'); } catch (e) {}
    drop.style.display = 'none';
    drop.style.pointerEvents = 'none';
    drop.innerHTML = '';
    dropdownStilSifirla(drop);
    drop.style.display = 'none';
    if (drop._anchorParent && drop._anchorParent.isConnected) {
        if (drop.parentElement !== drop._anchorParent) {
            try { drop._anchorParent.insertBefore(drop, drop._anchorNext || null); } catch (e) {}
        }
    } else if (drop.parentElement === document.body) {
        // Form yeniden çizildiyse body'de kalan hayalet listeleri kaldır
        try { drop.remove(); } catch (e) {}
    }
}

function positionDropdown(dropId, inputEl) {
    const drop = document.getElementById(dropId);
    if (!drop || !inputEl || !inputEl.isConnected) return false;
    const rect = inputEl.getBoundingClientRect();
    if (!rect.width && !rect.height) return false;
    // Ekran dışı / görünmez input → açma
    if (rect.bottom < 0 || rect.top > window.innerHeight || rect.right < 0 || rect.left > window.innerWidth) {
        return false;
    }
    dropdownAnchorKaydet(drop);
    const spaceBelow = window.innerHeight - rect.bottom - 10;
    const spaceAbove = rect.top - 10;
    const openUp = spaceBelow < 160 && spaceAbove > spaceBelow + 20;
    const avail = Math.max(120, openUp ? spaceAbove : spaceBelow);
    const maxH = Math.min(320, avail);
    const width = Math.min(Math.max(rect.width, 280), window.innerWidth - 16);
    const left = Math.max(8, Math.min(rect.left, window.innerWidth - 16 - width));
    const top = openUp
        ? Math.max(8, rect.top - maxH - 4)
        : (rect.bottom + 2);
    drop.style.position = 'fixed';
    drop.style.top = top + 'px';
    drop.style.left = left + 'px';
    drop.style.width = width + 'px';
    drop.style.zIndex = '200000';
    drop.style.maxHeight = maxH + 'px';
    drop.style.overflowY = 'auto';
    drop.style.paddingTop = '4px';
    drop.style.marginTop = '-4px';
    drop.style.pointerEvents = 'auto';
    if (drop.parentElement !== document.body) {
        document.body.appendChild(drop);
    }
    return true;
}

function showSearchDropdown(dropId, inputEl, html, autoHideMs = 0) {
    if (!inputEl || !inputEl.isConnected) {
        hideAllDropdowns();
        return;
    }
    // Aynı anda tek açık liste
    ERP_SEARCH_DROP_IDS.forEach(id => {
        if (id === dropId) return;
        document.querySelectorAll('#' + id).forEach(d => dropdownPortalTemizle(d));
    });
    try { if (dropId !== 'mamul-toplu-kod-drop' && typeof mamulTopluKodDropKapat === 'function') mamulTopluKodDropKapat(); } catch (e) {}
    try { if (dropId !== 'kumas-toplu-kod-drop' && typeof kumasTopluDropKapat === 'function') kumasTopluDropKapat(); } catch (e) {}

    const drop = document.getElementById(dropId);
    if (!drop) return;
    if (!positionDropdown(dropId, inputEl)) {
        hideAllDropdowns();
        return;
    }
    drop._anchorInput = inputEl;
    drop.innerHTML = html || '';
    drop.style.display = 'block';
    drop.classList.add('is-open');
    try { clearTimeout(drop._hideTimer); } catch (e) {}
    if (autoHideMs > 0) {
        drop._hideTimer = setTimeout(() => {
            try { dropdownPortalTemizle(drop); } catch (e) {}
        }, autoHideMs);
    }
}

function dropdownScrollIcerisindeMi(e) {
    const t = e && e.target;
    if (!t || t === document || t === document.documentElement) return false;
    const sel = ERP_SEARCH_DROP_IDS.map(id => '#' + id).join(', ');
    if (t.id && ERP_SEARCH_DROP_IDS.includes(t.id)) return true;
    if (typeof t.closest === 'function') return !!t.closest(sel);
    return false;
}

function dropdownAcikMi(drop) {
    if (!drop) return false;
    if (drop.classList.contains('is-open')) return true;
    const d = drop.style.display;
    return d && d !== 'none';
}

function repositionOpenDropdowns() {
    ERP_SEARCH_DROP_IDS.forEach(id => {
        document.querySelectorAll('#' + id).forEach(drop => {
            if (!dropdownAcikMi(drop)) return;
            const inp = drop._anchorInput;
            if (inp && inp.isConnected) {
                if (!positionDropdown(id, inp)) dropdownPortalTemizle(drop);
            } else {
                dropdownPortalTemizle(drop);
            }
        });
    });
}

function hideAllDropdowns() {
    ERP_SEARCH_DROP_IDS.forEach(id => {
        document.querySelectorAll('#' + id).forEach(drop => dropdownPortalTemizle(drop));
    });
    // Body'de kalan kopyalar (form yeniden çizilince)
    try {
        document.querySelectorAll('body > [id$="-search-results"], body > #mamul-toplu-kod-drop, body > #kumas-toplu-kod-drop')
            .forEach(drop => dropdownPortalTemizle(drop));
    } catch (e) {}
    try { if (typeof mamulTopluKodDropKapat === 'function') mamulTopluKodDropKapat(); } catch (e) {}
    try { if (typeof kumasTopluDropKapat === 'function') kumasTopluDropKapat(); } catch (e) {}
    try { erpOrphanAramaDropTemizle(); } catch (e) {}
}
try { window.hideAllDropdowns = hideAllDropdowns; } catch (e) {}
try { window.showSearchDropdown = showSearchDropdown; } catch (e) {}

function dropdownDisindaMi(target) {
    if (!target || !target.closest) return true;
    const dropSel = ERP_SEARCH_DROP_IDS.map(id => '#' + id).join(', ');
    if (target.closest(dropSel)) return false;
    const ids = ['val-iplik-search', 'val-kumas-search', 'mamul-search'];
    for (const id of ids) {
        const inp = document.getElementById(id);
        if (inp && (inp === target || inp.contains(target))) return false;
    }
    if (target.closest('[id^="mt-kod-"], [id^="kt-kod-"]')) return false;
    return true;
}

(function erpDropdownScrollResizeBind() {
    const onScroll = (e) => {
        try {
            if (dropdownScrollIcerisindeMi(e)) return;
            const ae = document.activeElement;
            const kodOdak = ae && ae.id && (String(ae.id).startsWith('kt-kod-') || String(ae.id).startsWith('mt-kod-'));
            const ktOpen = document.getElementById('kumas-toplu-kod-drop')?.classList.contains('is-open');
            const mtOpen = document.getElementById('mamul-toplu-kod-drop')?.classList.contains('is-open');
            const wrapKaydir = e && e.target && typeof e.target.closest === 'function'
                && e.target.closest('#depo-form-main-wrap, #form-container.sevkiyat-form-modal, .mamul-toplu-hareket-wrap');
            if (kodOdak || ((ktOpen || mtOpen) && wrapKaydir)) {
                try {
                    const kt = document.getElementById('kumas-toplu-kod-drop');
                    const mt = document.getElementById('mamul-toplu-kod-drop');
                    if (kt && kt.classList.contains('is-open') && typeof kumasTopluKodDropKonumla === 'function') {
                        kumasTopluKodDropKonumla(kt._anchorInput || ae, kt);
                    } else if (mt && mt.classList.contains('is-open') && typeof mamulTopluKodDropKonumla === 'function') {
                        mamulTopluKodDropKonumla(mt._anchorInput || ae, mt);
                    } else if (typeof repositionOpenDropdowns === 'function') {
                        repositionOpenDropdowns();
                    }
                } catch (err2) {}
                return;
            }
            hideAllDropdowns();
        } catch (err) {}
    };
    const onResize = () => { try { hideAllDropdowns(); } catch (e) {} };
    const scrollHandler = (typeof erpRafThrottle === 'function') ? erpRafThrottle(onScroll) : onScroll;
    const resizeHandler = (typeof erpDebounce === 'function') ? erpDebounce(onResize, 120) : onResize;
    window.addEventListener('scroll', scrollHandler, true);
    window.addEventListener('resize', resizeHandler);
})();

// Dışarı tıklanınca / dokunulunca kapat (capture — stopPropagation'ı aşar)
document.addEventListener('pointerdown', function (e) {
    try {
        if (!dropdownDisindaMi(e.target)) return;
        hideAllDropdowns();
    } catch (err) {}
}, true);

document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
        try { hideAllDropdowns(); } catch (err) {}
    }
});

// Eski click dinleyicisi yerine (çift kapanma zararsız)
document.addEventListener('click', function (e) {
    try {
        if (!dropdownDisindaMi(e.target)) return;
        hideAllDropdowns();
    } catch (err) {}
});

// Anchor input DOM'dan silinince (liste yenilenince) açık kalanları temizle
if (typeof MutationObserver !== 'undefined' && !window._erpDropAnchorObserver) {
    window._erpDropAnchorObsTimer = null;
    window._erpDropAnchorObserver = new MutationObserver(() => {
        try {
            clearTimeout(window._erpDropAnchorObsTimer);
            window._erpDropAnchorObsTimer = setTimeout(() => {
                try {
                    let dirty = false;
                    ERP_SEARCH_DROP_IDS.forEach(id => {
                        document.querySelectorAll('#' + id).forEach(drop => {
                            if (!dropdownAcikMi(drop)) return;
                            const inp = drop._anchorInput;
                            if (!inp || !inp.isConnected) dirty = true;
                        });
                    });
                    if (dirty) hideAllDropdowns();
                } catch (e) {}
            }, 80);
        } catch (e) {}
    });
    try {
        window._erpDropAnchorObserver.observe(document.body, { childList: true, subtree: true });
    } catch (e) {}
}

/** Yeni ayrılmış tablolara çift yazma — eski tablolar asıl kaynak kalır. Tablo yoksa sessiz geçer. */
function erpHareketKanalTablo(row) {
    if (typeof kumasStokHareketiMamulDepoMu === 'function' && kumasStokHareketiMamulDepoMu(row)) return 'mamul_hareket';
    const kb = String(row?.kaynak_birim || '').toUpperCase();
    if (kb === 'DOKUMA_TAKIP' || kb === 'DOKUMA_DEPO_SEVK') return 'dokuma_hareket';
    return 'kumas_hareket';
}
function erpDuzTabLoYokMu(msg) {
    return /PGRST205|schema cache|does not exist|Could not find the table/i.test(String(msg || ''));
}
async function erpDuzHareketYansit(row) {
    try {
        if (!row || row.id == null || typeof sb === 'undefined' || !sb) return;
        const t = erpHareketKanalTablo(row);
        const payload = { ...row, kaynak_kumas_stok_id: row.id };
        delete payload._tbl;
        delete payload._search_idx;
        const { error } = await sb.from(t).upsert(payload, { onConflict: 'kaynak_kumas_stok_id' });
        if (error && !erpDuzTabLoYokMu(error.message)) console.warn('duz hareket', t, error.message);
    } catch (e) {}
}
async function erpDuzSiparisKalemYansit(siparisId, kalemler, hamCins) {
    try {
        if (siparisId == null || typeof sb === 'undefined' || !sb) return;
        const sid = siparisId;
        const arr = Array.isArray(kalemler) ? kalemler : [];
        await sb.from('siparis_cins_ham').upsert({
            siparis_id: sid,
            ham_cins: hamCins == null ? null : String(hamCins),
            parse_ok: true,
            hata: null
        }, { onConflict: 'siparis_id' });
        const rows = arr.map((k, i) => ({
            siparis_id: sid,
            kalem_idx: i,
            stok_kodu: k.kod || null,
            desen: k.desen || null,
            urun_grup: k.grup || null,
            urun_adi: k.ad || null,
            ebat: k.ebat || null,
            renk: k.renk || null,
            rkod: k.rkod || null,
            rkod1: k.rkod1 || null,
            rkod2: k.rkod2 || null,
            rkod3: k.rkod3 || null,
            rkod4: k.rkod4 || null,
            rkod5: k.rkod5 || null,
            rkod6: k.rkod6 || null,
            miktar: parseFloat(k.miktar) || 0,
            birim: String(k.birim || 'ADET').toUpperCase(),
            ham_json: k
        }));
        if (rows.length) {
            const { error } = await sb.from('siparis_kalemleri').upsert(rows, { onConflict: 'siparis_id,kalem_idx' });
            if (error && !erpDuzTabLoYokMu(error.message)) console.warn('duz kalem', error.message);
        }
    } catch (e) {}
}
async function erpDuzUretimYansit(siparisId, tip, kd) {
    try {
        if (siparisId == null || typeof sb === 'undefined' || !sb) return;
        const t = String(tip || '');
        if (t !== 'KD_KONFEKSIYON' && t !== 'KD_DOKUMA') return;
        const obj = kd && typeof kd === 'object' ? kd : {};
        const idxs = new Set();
        Object.keys(obj).forEach((k) => {
            const m = /^kalem_(\d+)$/.exec(k);
            if (m) idxs.add(parseInt(m[1], 10));
        });
        const urunler = obj.urunler || {};
        if (urunler && typeof urunler === 'object' && !Array.isArray(urunler)) {
            Object.keys(urunler).forEach((k) => { if (/^\d+$/.test(k)) idxs.add(parseInt(k, 10)); });
        } else if (Array.isArray(urunler)) {
            urunler.forEach((_, i) => idxs.add(i));
        }
        if (!idxs.size) idxs.add(0);
        const rows = [...idxs].map((i) => {
            const krow = obj[`kalem_${i}`] || {};
            const drow = Array.isArray(urunler) ? (urunler[i] || {}) : (urunler[i] || urunler[String(i)] || {});
            const row = { siparis_id: siparisId, kalem_idx: i, updated_at: new Date().toISOString() };
            if (t === 'KD_KONFEKSIYON') {
                row.kesilen = Number(krow.kesilen || 0) || 0;
                row.dikilen = Number(krow.dikilen || 0) || 0;
                row.kk_gecen = Number(krow.kk_gecen || 0) || 0;
                row.kolide = Number(krow.kolide || 0) || 0;
                row.sevk_edilen = Number(krow.sevk_edilen || 0) || 0;
                row.sevk_adet = Number(krow.sevk_adet || 0) || 0;
                row.ham_konf = krow;
            } else {
                row.dokuma_mt = Number(drow.toplam_metre || 0) || 0;
                row.dokuma_kg = Number(drow.toplam_kg || 0) || 0;
                row.dokuma_adet = Number(drow.toplam_adet || 0) || 0;
                row.ham_dokuma = drow;
            }
            return row;
        });
        const { error } = await sb.from('siparis_kalem_uretim').upsert(rows, { onConflict: 'siparis_id,kalem_idx' });
        if (error && !erpDuzTabLoYokMu(error.message)) console.warn('duz uretim', error.message);
    } catch (e) {}
}
try {
    window.erpDuzHareketYansit = erpDuzHareketYansit;
    window.erpDuzSiparisKalemYansit = erpDuzSiparisKalemYansit;
    window.erpDuzUretimYansit = erpDuzUretimYansit;
} catch (e) {}

// ============================================================
// SUPABASE KD (Key-Data) YARDIMCI FONKSİYONLARI
// localStorage yerine siparis_akis tablosu kullanır
// tip: 'KD_DOKUMA' | 'KD_KONFEKSIYON' | 'KD_URUN_AGACI'
// ============================================================
const _kdCache = {};  // Bellek cache — aynı oturumda tekrar çekmemek için
const _kdCacheAt = {}; // key → Date.now() — soft TTL için
const KD_SOFT_TTL_MS = 90000;

function kdCacheStamp(key) {
    _kdCacheAt[key] = Date.now();
}
function kdCacheStaleMi(siparisId, tip, ttlMs) {
    const key = `${tip}_${siparisId}`;
    if (_kdCache[key] === undefined) return true;
    if (ttlMs === 0) return true; // zorla yenile
    const t = _kdCacheAt[key] || 0;
    return (Date.now() - t) > (Number.isFinite(ttlMs) ? ttlMs : KD_SOFT_TTL_MS);
}
function planlamaIhtiyacSatirCacheInvalidate() {
    try {
        if (typeof _planlamaIhtiyacSatirCache === 'object' && _planlamaIhtiyacSatirCache) {
            _planlamaIhtiyacSatirCache.key = '';
            _planlamaIhtiyacSatirCache.rows = null;
            _planlamaIhtiyacSatirCache.ver = (_planlamaIhtiyacSatirCache.ver || 0) + 1;
        }
    } catch (e) {}
}
try { window.planlamaIhtiyacSatirCacheInvalidate = planlamaIhtiyacSatirCacheInvalidate; } catch (e) {}
try { window.kdCacheStaleMi = kdCacheStaleMi; } catch (e) {}
try { window.erpTableSyncedAt = erpTableSyncedAt; } catch (e) {}
try { window.erpTableSyncedAtYaz = erpTableSyncedAtYaz; } catch (e) {}
try { window.sbKdGetMany = sbKdGetMany; } catch (e) {}
try { window.sbKdGetTipler = sbKdGetTipler; } catch (e) {}

function kdDataScore(v) {
    if (!v || typeof v !== 'object') return -1;
    let s = 0;
    const tops = ['kesim_toplam','dikim_toplam','kk_gecen','koli_toplam','hatali_toplam','panel_yikama_sevk','panel_yikama_gelen','panel_sevk_toplam'];
    tops.forEach(k => { if (Number(v[k] || 0) > 0) s += 2; });
    /* Yükleme toplamı ağırlıklı — boş yeni satır eski dolu KD'yi ezmesin */
    s += Math.min(40, Math.round(Number(v.panel_sevk_toplam || 0) || 0));
    Object.keys(v).forEach(k => {
        if (!k.startsWith('kalem_')) return;
        const row = v[k] || {};
        if (Number(row.kesilen || 0) > 0) s += 3;
        if (Number(row.dikilen || 0) > 0) s += 3;
        if (Number(row.kk_gecen || 0) > 0) s += 2;
        if (Number(row.kolide || 0) > 0) s += 2;
        const sevkN = Math.max(Number(row.sevk_edilen || 0) || 0, Number(row.sevk_adet || 0) || 0);
        if (sevkN > 0) s += 3 + Math.min(20, Math.round(sevkN));
    });
    return s;
}

function sbKdSatirlardanSec(rows, tip) {
    const t = String(tip || '');
    const candidates = (rows || [])
        .filter(r => !r?.kalem_ad || String(r.kalem_ad) === t)
        .map(r => {
            try {
                const parsed = JSON.parse(r?.notlar || '{}') || {};
                return { row: r, parsed, score: kdDataScore(parsed) };
            } catch (e) {
                return null;
            }
        })
        .filter(Boolean)
        .sort((a, b) => {
            const ds = (b.score || 0) - (a.score || 0);
            if (ds !== 0) return ds;
            const ta = new Date(a.row.created_at || 0).getTime();
            const tb = new Date(b.row.created_at || 0).getTime();
            if (tb !== ta) return tb - ta;
            return String(b.row.id || '').localeCompare(String(a.row.id || ''), 'tr', { numeric: true, sensitivity: 'base' });
        });
    return (candidates[0]?.parsed) || {};
}

function sbKdCacheYaz(siparisId, tip, val) {
    const key = `${tip}_${siparisId}`;
    const prev = _kdCache[key];
    const prevScore = prev !== undefined ? kdDataScore(prev) : null;
    const nextScore = kdDataScore(val);
    _kdCache[key] = val;
    kdCacheStamp(key);
    return prev === undefined || prevScore !== nextScore;
}

/**
 * Bir KD tipi için birden fazla siparişi tek (veya birkaç) sorguda çeker.
 * force:true verilen id’ler ağdan gelir; aksi halde TTL içi cache kullanılır.
 */
async function sbKdGetMany(siparisIds, tip, opts = {}) {
    const ids = [...new Set((siparisIds || []).map(id => String(id)).filter(Boolean))];
    const ttl = opts.ttl === 0 ? 0 : (Number.isFinite(opts.ttl) ? opts.ttl : KD_SOFT_TTL_MS);
    const force = !!opts.force;
    const need = force ? ids : ids.filter(id => kdCacheStaleMi(id, tip, ttl));
    const out = {};
    ids.forEach((id) => {
        const v = _kdCache[`${tip}_${id}`];
        if (v !== undefined) out[id] = v;
    });
    if (!need.length || typeof sb === 'undefined' || !sb) return out;
    let anyChange = false;
    const CHUNK = 40;
    for (let i = 0; i < need.length; i += CHUNK) {
        const chunk = need.slice(i, i + CHUNK);
        const lim = Math.min(1000, Math.max(40, chunk.length * 8));
        try {
            const { data, error } = await erpWithTimeout(
                sb.from('siparis_akis')
                    .select('id,siparis_id,kalem_ad,notlar,created_at')
                    .in('siparis_id', chunk)
                    .eq('islem', tip)
                    .order('created_at', { ascending: false })
                    .limit(lim),
                `siparis_akis:${tip}:batch`
            );
            if (error) throw error;
            const bySid = new Map();
            (data || []).forEach((r) => {
                const sid = String(r.siparis_id);
                if (!bySid.has(sid)) bySid.set(sid, []);
                bySid.get(sid).push(r);
            });
            chunk.forEach((id) => {
                const parsed = sbKdSatirlardanSec(bySid.get(id) || [], tip);
                if (sbKdCacheYaz(id, tip, parsed)) anyChange = true;
                out[id] = parsed;
            });
        } catch (e) {
            console.warn('sbKdGetMany fallback', tip, e);
            await Promise.all(chunk.map(id => sbKdGet(id, tip, true).catch(() => null)));
            chunk.forEach((id) => { out[id] = _kdCache[`${tip}_${id}`] || {}; });
        }
    }
    if (anyChange) planlamaIhtiyacSatirCacheInvalidate();
    return out;
}

/** Tek sipariş, birden fazla KD tipi — 4 ayrı sorgu yerine 1. */
async function sbKdGetTipler(siparisId, tips, opts = {}) {
    const sid = siparisId;
    const list = (tips || []).map(String).filter(Boolean);
    if (sid == null || !list.length) return {};
    const ttl = opts.ttl === 0 ? 0 : (Number.isFinite(opts.ttl) ? opts.ttl : KD_SOFT_TTL_MS);
    const need = opts.force ? list : list.filter(t => kdCacheStaleMi(sid, t, ttl));
    const out = {};
    list.forEach((t) => {
        const v = _kdCache[`${t}_${sid}`];
        if (v !== undefined) out[t] = v;
    });
    if (!need.length || typeof sb === 'undefined' || !sb) return out;
    try {
        const { data, error } = await erpWithTimeout(
            sb.from('siparis_akis')
                .select('id,siparis_id,islem,kalem_ad,notlar,created_at')
                .eq('siparis_id', sid)
                .in('islem', need)
                .order('created_at', { ascending: false })
                .limit(Math.min(80, need.length * 20)),
            `siparis_akis:tipler`
        );
        if (error) throw error;
        let anyChange = false;
        need.forEach((t) => {
            const rows = (data || []).filter(r => String(r.islem) === t);
            const parsed = sbKdSatirlardanSec(rows, t);
            if (sbKdCacheYaz(sid, t, parsed)) anyChange = true;
            out[t] = parsed;
        });
        if (anyChange) planlamaIhtiyacSatirCacheInvalidate();
    } catch (e) {
        await Promise.all(need.map(t => sbKdGet(sid, t, true).catch(() => null)));
        need.forEach((t) => { out[t] = _kdCache[`${t}_${sid}`] || {}; });
    }
    return out;
}

async function sbKdGet(siparisId, tip, forceReload = false) {
    const key = `${tip}_${siparisId}`;
    if (!forceReload && _kdCache[key] !== undefined) return _kdCache[key];
    if (forceReload) delete _kdCache[key];
    try {
        const { data, error } = await erpWithTimeout(
            sb.from('siparis_akis')
            .select('id,kalem_ad,notlar,created_at')
            .eq('siparis_id', siparisId)
            .eq('islem', tip)
            .order('created_at', { ascending: false })
            .limit(20),
            `siparis_akis:${tip}`
        );
        if (error) throw error;
        const val = sbKdSatirlardanSec(data || [], tip);
        if (sbKdCacheYaz(siparisId, tip, val)) planlamaIhtiyacSatirCacheInvalidate();
        return val;
    } catch(e) {
        console.error('sbKdGet error', tip, siparisId, e);
        return {};
    }
}

async function sbKdSet(siparisId, tip, kd) {
    const key = `${tip}_${siparisId}`;
    function kdIsPlainObject(v) {
        return !!v && typeof v === 'object' && !Array.isArray(v);
    }
    function kdDeepMerge(base, incoming) {
        if (!kdIsPlainObject(base)) base = {};
        if (!kdIsPlainObject(incoming)) return incoming;
        const out = { ...base };
        Object.keys(incoming).forEach((k) => {
            const b = base[k];
            const n = incoming[k];
            if (kdIsPlainObject(b) && kdIsPlainObject(n)) out[k] = kdDeepMerge(b, n);
            else out[k] = n;
        });
        return out;
    }

    // Coklu kullanicida stale veri ezmesini azaltmak icin en guncel KD ile birlestir.
    // (Gelen deger her zaman kazanir; sadece eksik alanlar korunur.)
    const keyAge = Date.now() - (_kdCacheAt[key] || 0);
    const cacheTaze = _kdCache[key] !== undefined && keyAge >= 0 && keyAge < 8000;
    const latestKd = cacheTaze
        ? (_kdCache[key] || {})
        : await sbKdGet(siparisId, tip, true);
    const mergedKd = kdDeepMerge(latestKd, kd || {});
    const json = JSON.stringify(mergedKd);
    // Önce var mı kontrol et (kalem_ad boş/eski satırlar da sayılır — yeni boş KD çoğalmasın)
    const { data: existingRows, error: selErr } = await sb.from('siparis_akis')
        .select('id')
        .eq('siparis_id', siparisId)
        .eq('islem', tip)
        .order('created_at', { ascending: false })
        .limit(50);
    if (selErr) {
        console.error('sbKdSet select error', tip, siparisId, selErr);
        if (typeof alert === 'function') alert('Supabase kayit okuma hatasi: ' + selErr.message);
        return { error: selErr };
    }
    if ((existingRows || []).length > 0) {
        // Aynı tipte mükerrer kayıtlar varsa hepsini aynı KD ile senkronla
        const { error: updErr } = await sb.from('siparis_akis')
            .update({ notlar: json, kalem_ad: tip, miktar: 0 })
            .eq('siparis_id', siparisId)
            .eq('islem', tip);
        if (updErr) {
            console.error('sbKdSet update error', tip, siparisId, updErr);
            if (typeof alert === 'function') alert('Supabase kaydetme hatasi: ' + updErr.message);
            return { error: updErr };
        }
    } else {
        const { error: insErr } = await sb.from('siparis_akis').insert([{ siparis_id: siparisId, islem: tip, kalem_ad: tip, miktar: 0, notlar: json }]);
        if (insErr) {
            console.error('sbKdSet insert error', tip, siparisId, insErr);
            if (typeof alert === 'function') alert('Supabase kaydetme hatasi: ' + insErr.message);
            return { error: insErr };
        }
    }
        _kdCache[key] = mergedKd;  // sadece DB basariliysa cache guncelle
    kdCacheStamp(key);
    planlamaIhtiyacSatirCacheInvalidate();
    try { if (typeof erpDuzUretimYansit === 'function') erpDuzUretimYansit(siparisId, tip, mergedKd); } catch (e) {}
    return { error: null };
}

async function sbKdDel(siparisId, tip) {
    const key = `${tip}_${siparisId}`;
    delete _kdCache[key];
    delete _kdCacheAt[key];
    planlamaIhtiyacSatirCacheInvalidate();
    await sb.from('siparis_akis').delete().eq('siparis_id', siparisId).eq('islem', tip);
}

function syncDepoHareketSecimStili() {
    const ta = document.getElementById('toggle-area');
    const bin = document.getElementById('btn-in');
    const bout = document.getElementById('btn-out');
    const act = document.getElementById('main-action-btn');
    if (!bin) return;
    // Depo Stok / depo hareket: çıkış butonu yok
    const stokSadeceGiris = (typeof isDepoStokModu === 'function' && isDepoStokModu() && appMode !== 'SEVKIYAT')
        || appMode === 'DEPO_HAREKET';
    if (stokSadeceGiris && movementType !== 'GİRİŞ' && appMode !== 'SEVKIYAT') movementType = 'GİRİŞ';
    const t = movementType;
    const base = 'flex:1;min-width:160px;text-align:left;padding:12px 14px;border-radius:10px;cursor:pointer;font-family:\'DM Sans\',sans-serif;transition:box-shadow 0.15s,background 0.15s,border-color 0.15s';
    if (bout) bout.style.display = 'none';
    const binBase = base + ';flex:1 1 100%';
    if (t === 'GİRİŞ' || stokSadeceGiris) {
        bin.style.cssText = binBase + ';border:1px solid rgba(16,185,129,0.5);background:linear-gradient(135deg,rgba(16,185,129,0.18),rgba(16,185,129,0.06));color:var(--text);box-shadow:0 2px 12px rgba(16,185,129,0.2)';
    } else {
        bin.style.cssText = binBase + ';border:1px solid var(--border);background:var(--surface2);color:var(--text2);box-shadow:none';
    }
    if (act && isDepoHareketModu() && !editingId) {
        if (depoHareketFormGrubu() === 'MAMUL_DEPO') {
            act.textContent = (appMode === 'SEVKIYAT') ? 'Toplu Sevkiyat Kaydet' : 'Toplu Kaydet';
        } else {
            act.textContent = (stokSadeceGiris || t === 'GİRİŞ' || appMode !== 'SEVKIYAT') ? 'Stok girişi kaydet' : 'Sevkiyat kaydet (stok düş)';
        }
    } else if (act && isDepoHareketModu() && editingId) {
        act.textContent = 'Kaydet';
    }
    if (ta && isDepoHareketModu()) {
        ta.style.flexDirection = 'column';
        ta.style.alignItems = 'stretch';
    }
}

function changeType(t) {
    if (t === 'ÇIKIŞ' && ((typeof isDepoStokModu === 'function' && isDepoStokModu()) || appMode === 'DEPO_HAREKET') && appMode !== 'SEVKIYAT') {
        if (typeof erpToast === 'function') erpToast('Çıkış Depo Stok’ta yok. Sevkiyat menüsüne yönlendiriliyorsunuz.', 'info');
        sevkiyatMerkezGrup = (typeof isDepoStokModu === 'function' && isDepoStokModu()) ? appMode : (depoKomutaHedef || 'MAMUL_DEPO');
        saveUiState({ sevkiyatMerkezGrup });
        setAppMode('SEVKIYAT');
        return;
    }
    movementType = t;
    renderInputs();
    syncDepoKomutaChrome();
    syncDepoHareketSecimStili();
}

function hideDetailModal() {
    siparisDurumPollStop();
    const modal = document.getElementById('detail-modal');
    if (!modal) return;
    modal.style.display = 'none';
    const mb = modal.querySelector('.modal-box');
    if (mb) mb.style.removeProperty('max-width');
    const bod = document.getElementById('modal-body');
    if (bod) {
        bod.className = 'modal-body-scroll';
        bod.style.cssText = '';
    }
    document.querySelectorAll('.kayit-gecmis-details').forEach(d => { d.open = false; });
    try { erpFlushDeferredUiRefresh(); } catch (e) {}
}

function closeModal(e) {
    if (!e || (e.target && e.target.id === 'detail-modal')) hideDetailModal();
}



function stokToNumber(v) {
    const raw = String(v ?? '').trim();
    if (!raw) return 0;
    const cleaned = raw
        .replace(/[^\d,.\-]/g, '')
        .replace(/\.(?=\d{3}(\D|$))/g, '')
        .replace(',', '.');
    const n = parseFloat(cleaned);
    return Number.isFinite(n) ? n : 0;
}


const KUMAS_META_RE = /\[\[KUMAS_META:([A-Za-z0-9+/=]+)\]\]/;
const KUMAS_META_ALL_RE = /\s*\[\[KUMAS_META:[A-Za-z0-9+/=]+\]\]\s*/g;

function kumasNotlarTemizle(txt) {
    return String(txt || '').replace(KUMAS_META_ALL_RE, '').trim();
}

function kumasMetaEncode(meta) {
    try {
        const json = JSON.stringify(meta || {});
        const b64 = btoa(unescape(encodeURIComponent(json)));
        return `[[KUMAS_META:${b64}]]`;
    } catch (e) {
        console.warn('kumasMetaEncode:', e?.message || e);
        return '';
    }
}

function kumasMetaDecode(txt) {
    const m = String(txt || '').match(KUMAS_META_RE);
    if (!m) return null;
    try {
        return JSON.parse(decodeURIComponent(escape(atob(m[1]))));
    } catch {
        return null;
    }
}

function kumasMetaDegerVarMi(v) {
    if (v == null) return false;
    if (Array.isArray(v)) return v.some(kumasMetaDegerVarMi);
    if (typeof v === 'object') return Object.keys(v).some(k => kumasMetaDegerVarMi(v[k]));
    return String(v).trim() !== '';
}

const KUMAS_KART_META_KEYS = [
    'terbiye', 'boya_not', 'cekme', 'ana_grup', 'cozgu_sikligi',
    'renk', 'renk_kodu',
    'tarak_no', 'tarak_eni', 'atki_sikligi', 'cozgu_no', 'cozgu_cinsi',
    'ham_en', 'ham_boy', 'ham_gramaj', 'ham_gsm',
    'mamul_en', 'mamul_boy', 'mamul_gramaj', 'mamul_gsm'
];

function kumasKartMetaTemizle(meta) {
    const src = meta && typeof meta === 'object' ? meta : {};
    const out = {};
    KUMAS_KART_META_KEYS.forEach(k => {
        const v = src[k];
        if (v !== undefined && v !== null && String(v).trim() !== '') out[k] = v;
    });
    if (Array.isArray(src.atki) && src.atki.length) out.atki = src.atki;
    if (Array.isArray(src.kumas_varyantlar) && src.kumas_varyantlar.length) out.kumas_varyantlar = src.kumas_varyantlar;
    if (Array.isArray(src.varyantlar) && src.varyantlar.length) out.varyantlar = src.varyantlar;
    return out;
}

function kumasNotlarOlustur(userNot, meta) {
    const clean = kumasNotlarTemizle(userNot);
    const metaObj = meta && typeof meta === 'object' ? { ...meta } : {};
    delete metaObj.fotograf;
    if (!kumasMetaDegerVarMi(metaObj)) return clean;
    let token = kumasMetaEncode(metaObj);
    if (!token && (metaObj.terbiye || metaObj.boya_not || metaObj.cekme || metaObj.renk || metaObj.renk_kodu)) {
        token = kumasMetaEncode({
            terbiye: metaObj.terbiye || '',
            renk: metaObj.renk || '',
            renk_kodu: metaObj.renk_kodu || '',
            boya_not: metaObj.boya_not || '',
            cekme: metaObj.cekme || ''
        });
    }
    if (!token) return clean;
    return clean ? `${clean}\n${token}` : token;
}

function kumasMetaAl(rec) {
    if (!rec) return null;
    const src = String(rec.notlar || '');
    if (rec._kumas_meta_src === src && Object.prototype.hasOwnProperty.call(rec, '_kumas_meta_cache')) {
        return rec._kumas_meta_cache;
    }
    rec._kumas_meta_src = src;
    rec._kumas_meta_cache = kumasMetaDecode(src);
    return rec._kumas_meta_cache;
}

function kumasAlan(rec, key, fallback = '') {
    const aliases = key === 'terbiye' ? ['terbiye', 'terbiye_turu', 'terbiye_tur', 'terbiye_turu_adi'] : [key];
    for (let i = 0; i < aliases.length; i++) {
        const k = aliases[i];
        const direct = rec?.[k];
        if (direct !== undefined && direct !== null && String(direct).trim() !== '') return direct;
    }
    const meta = kumasMetaAl(rec);
    for (let i = 0; i < aliases.length; i++) {
        const mv = meta?.[aliases[i]];
        if (mv !== undefined && mv !== null && String(mv).trim() !== '') return mv;
    }
    return fallback;
}

function kumasKartTerbiyeOku(rec) {
    return String(typeof kumasAlan === 'function' ? kumasAlan(rec, 'terbiye', '') : (rec?.terbiye || '')).trim();
}

/** Mamül deposu hareketleri — kumaş (SM-/KUMAS) ile karışmaz */
function kumasStokHareketiMamulDepoMu(x) {
    const kb = String(x?.kaynak_birim || '').toUpperCase();
    if (kb === 'DEPO_HAREKET_KUMAS' || kb === 'DEPO_HAREKET_KUMAS_TOPLU' || kb.startsWith('DEPO_HAREKET_KUMAS') || kb === 'DEPO_HAREKET_HAM_KUMAS' || kb === 'DEPO_HAREKET_MAMUL_KUMAS' || kb === 'KUMAS' || kb === 'HAM_KUMAS' || kb === 'MAMUL_KUMAS') return false;
    if (kb === 'MAMUL_DEPO' || kb === 'DEPO_HAREKET_MAMUL_DEPO') return true;
    const kod = String(x?.stok_kodu ?? '').trim().toUpperCase();
    if (!kod || kod === 'KODSUZ') return false;
    if (/^\d{4}-\d{1,4}(-\d+)?$/i.test(kod)) return true;
    const pref = kod.split(/[-\s]/)[0];
    if (pref === 'MA' || pref === 'MM') return true;
    if (String(x?.ana_grup || '').toUpperCase() === 'MAMUL') return true;
    return false;
}

function kumasStokHareketiKumasDepoMu(x) {
    return !kumasStokHareketiMamulDepoMu(x);
}

/** kumas_kutuphanesi kartı mamül mü (arama / liste ayrımı) */
function kumasKutuphanesiKartiMamulMu(k) {
    if (!k) return false;
    if (String(k.ana_grup || '').toUpperCase() === 'MAMUL') return true;
    const dc = String(k.desen_kodu || k.stok_kodu || '').trim().toUpperCase();
    if (!dc) return false;
    if (/^\d{7}(-\d+)?$/.test(dc)) return true;
    if (/^\d{4}-\d{1,4}(-\d+)?$/.test(dc)) return true;
    if (typeof mamulStokKoduFormatMi === 'function' && mamulStokKoduFormatMi(dc)) return true;
    const pref = dc.split(/[-\s]/)[0];
    return pref === 'MA' || pref === 'MM';
}




function siparisExcelNormHeader(h) {
    return String(h || '')
        .toLowerCase()
        .replace(/ı/g, 'i')
        .replace(/ğ/g, 'g')
        .replace(/ü/g, 'u')
        .replace(/ş/g, 's')
        .replace(/ö/g, 'o')
        .replace(/ç/g, 'c')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
}

function siparisExcelToDate(v) {
    if (v === null || v === undefined || v === '') return '';
    if (typeof v === 'number') {
        const d = XLSX.SSF.parse_date_code(v);
        if (d && d.y && d.m && d.d) return `${d.y}-${String(d.m).padStart(2, '0')}-${String(d.d).padStart(2, '0')}`;
    }
    const s = String(v).trim();
    if (!s) return '';
    const m = s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);
    if (m) {
        const yy = m[3].length === 2 ? `20${m[3]}` : m[3];
        return `${yy}-${String(m[2]).padStart(2, '0')}-${String(m[1]).padStart(2, '0')}`;
    }
    const dt = new Date(s);
    if (!Number.isNaN(dt.getTime())) return dt.toISOString().slice(0, 10);
    return '';
}

function siparisExcelPick(row, keys = []) {
    const normKeys = keys.map(k => siparisExcelNormHeader(k)).filter(Boolean);
    for (const k of keys) {
        if (Object.prototype.hasOwnProperty.call(row, k) && String(row[k] ?? '').trim() !== '') {
            return row[k];
        }
    }
    for (const [rk, rv] of Object.entries(row || {})) {
        const nk = siparisExcelNormHeader(rk);
        if (!String(rv ?? '').trim()) continue;
        const hit = normKeys.some(w => nk === w || nk.includes(w) || w.includes(nk));
        if (hit) return rv;
    }
    return '';
}

async function importSiparisExcel(input) {
    if (!erpIsAdmin()) { erpToast('Bu işlem yalnızca admin kullanıcıya açıktır.', 'error'); if (input) input.value = ''; return; }
    const file = input?.files?.[0];
    if (!file) return;
    try { await erpEnsureXLSX(); } catch (e) {}
    if (typeof XLSX === 'undefined') { alert("Excel kütüphanesi yüklenemedi."); return; }
    try {
        const buf = await file.arrayBuffer();
        const wb = XLSX.read(buf, { type: 'array' });
        const sheetName = wb.SheetNames[0];
        if (!sheetName) { alert("Excel içinde sayfa bulunamadı."); return; }
        const ws = wb.Sheets[sheetName];
        const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
        if (!aoa.length) { alert("Excel boş görünüyor."); return; }

        const headerScore = (row) => {
            const hs = (row || []).map(c => siparisExcelNormHeader(c));
            let s = 0;
            if (hs.some(x => x.includes('siparis no') || x === 'sno')) s += 2;
            if (hs.some(x => x.includes('musteri') || x.includes('firma'))) s += 1;
            if (hs.some(x => x.includes('urun adi') || x.includes('urun kod') || x === 'urun')) s += 2;
            if (hs.some(x => x.includes('adet') || x.includes('miktar') || x.includes('qty'))) s += 2;
            return s;
        };
        let headerIdx = 0;
        let best = -1;
        aoa.slice(0, Math.min(25, aoa.length)).forEach((r, i) => {
            const sc = headerScore(r);
            if (sc > best) { best = sc; headerIdx = i; }
        });
        const headers = (aoa[headerIdx] || []).map(h => siparisExcelNormHeader(h));
        const rows = aoa.slice(headerIdx + 1).map(r => {
            const out = {};
            headers.forEach((h, i) => { if (h) out[h] = r[i]; });
            return out;
        }).filter(r => Object.values(r).some(v => String(v ?? '').trim() !== ''));

        const groups = {};
        rows.forEach((r, idx) => {
            const sno = String(siparisExcelPick(r, ['siparis no', 'siparisno', 'sno', 'order no', 'order']) || '').trim();
            if (!sno) return;
            if (!groups[sno]) {
                groups[sno] = {
                    sno,
                    firma: String(siparisExcelPick(r, ['musteri', 'firma', 'cari', 'customer']) || '').toUpperCase(),
                    starih: siparisExcelToDate(siparisExcelPick(r, ['siparis tarihi', 'starih', 'order date', 'tarih'])),
                    ttarih: siparisExcelToDate(siparisExcelPick(r, ['termin', 'termin tarihi', 'teslim tarihi', 'ttarih', 'due date'])),
                    durum: String(siparisExcelPick(r, ['durum', 'status']) || 'BEKLEMEDE').toUpperCase(),
                    kalemler: [],
                    firstRowIdx: idx
                };
            }
            const ad = String(siparisExcelPick(r, ['urun adi', 'urun adi 1', 'urun', 'model', 'kalem adi']) || '').trim();
            const kod = String(siparisExcelPick(r, ['urun kod', 'urun kodu', 'kod', 'stok kodu']) || '').trim();
            const grup = String(siparisExcelPick(r, ['grup', 'urun grup', 'kategori']) || '').trim();
            const renk = String(siparisExcelPick(r, ['renk', 'color']) || '').trim();
            const ebat = String(siparisExcelPick(r, ['ebat', 'olcu', 'beden', 'size']) || '').trim();
            const rkod1 = String(siparisExcelPick(r, ['renk kodu 1', 'renk kod 1', 'rk1', 'rkod1']) || '').trim();
            const rkod2 = String(siparisExcelPick(r, ['renk kodu 2', 'renk kod 2', 'rk2', 'rkod2']) || '').trim();
            const rkod3 = String(siparisExcelPick(r, ['renk kodu 3', 'renk kod 3', 'rk3', 'rkod3']) || '').trim();
            const rkod4 = String(siparisExcelPick(r, ['renk kodu 4', 'renk kod 4', 'rk4', 'rkod4']) || '').trim();
            const rkod5 = String(siparisExcelPick(r, ['renk kodu 5', 'renk kod 5', 'rk5', 'rkod5']) || '').trim();
            const rkod6 = String(siparisExcelPick(r, ['renk kodu 6', 'renk kod 6', 'rk6', 'rkod6']) || '').trim();
            const rkod = [rkod1, rkod2, rkod3, rkod4, rkod5, rkod6].filter(Boolean).join(' | ');
            const miktarRaw = siparisExcelPick(r, ['adet miktar', 'adet mt', 'adet', 'miktar', 'mt', 'qty', 'quantity']);
            const miktar = parseFloat(String(miktarRaw || '').replace(',', '.')) || 0;
            if (ad || kod || miktar > 0 || renk || ebat || grup || rkod) {
                groups[sno].kalemler.push({ kod, grup, ad, renk, ebat, rkod, rkod1, rkod2, rkod3, rkod4, rkod5, rkod6, miktar });
            }
        });

        const existingMap = {};
        (dataCache.siparisler || []).forEach(s => {
            const key = normalizeSiparisNo(s.sno);
            if (key) existingMap[key] = s;
        });
        const toInsert = [];
        const toUpdate = [];
        Object.values(groups).forEach(g => {
            const kalemler = g.kalemler.filter(k => (k.ad || k.kod) && (parseFloat(k.miktar || 0) > 0));
            const snoNorm = normalizeSiparisNo(g.sno);
            if (!snoNorm) return;
            const record = {
                sno: snoNorm,
                firma: g.firma || 'BELIRSIZ MUSTERI',
                starih: g.starih || new Date().toISOString().slice(0, 10),
                ttarih: g.ttarih || null,
                durum: g.durum || 'BEKLEMEDE',
                uretim_yeri: 'SIMTEKS_KONF',
                cins: JSON.stringify(kalemler),
                miktar: kalemler.reduce((a, k) => a + (parseFloat(k.miktar || 0) || 0), 0),
                updated_by: 'Excel Import',
                kaynak_birim: 'SIPARIS_EXCEL_IMPORT',
                islem_gecmisi: `✨ ${new Date().toLocaleString('tr-TR')} — [Excel Import]: Toplu sipariş aktarımı`
            };
            const mevcut = existingMap[snoNorm];
            if (!mevcut) {
                toInsert.push(record);
            } else if (kalemler.length) {
                toUpdate.push({ id: mevcut.id, data: record });
            }
        });

        // Import süresi içinde başka kullanıcı/ekran aynı sipariş no'yu açmış olabilir.
        // Insert öncesi DB'den son kez kontrol edip çakışanları update akışına alırız.
        if (toInsert.length) {
            const { data: existingDbRows, error: existingDbErr } = await sb.from('siparisler').select('id,sno').limit(10000);
            if (existingDbErr) throw existingDbErr;
            const dbMap = {};
            (existingDbRows || []).forEach(s => {
                const key = normalizeSiparisNo(s?.sno);
                if (key && !dbMap[key]) dbMap[key] = s;
            });
            const nextToInsert = [];
            toInsert.forEach(rec => {
                const key = normalizeSiparisNo(rec.sno);
                const hit = dbMap[key];
                if (hit?.id) {
                    toUpdate.push({ id: hit.id, data: rec });
                } else {
                    nextToInsert.push(rec);
                }
            });
            toInsert.length = 0;
            toInsert.push(...nextToInsert);
        }

        if (!toInsert.length && !toUpdate.length) {
            alert("İçe aktarılacak geçerli sipariş kalemi bulunamadı. Şablon başlıklarını kontrol edin.");
            input.value = '';
            return;
        }

        if (toInsert.length) {
            const { error } = await sb.from('siparisler').insert(toInsert);
            if (error) throw error;
        }
        if (toUpdate.length) {
            for (const u of toUpdate) {
                const { error } = await sb.from('siparisler').update(u.data).eq('id', u.id);
                if (error) throw error;
            }
        }
        erpSyncTablesBackground(['siparisler']);
        if (appMode === 'SIPARIS_LISTE') loadData();
        alert(`✅ Excel aktarımı tamamlandı. ${toInsert.length} yeni sipariş eklendi, ${toUpdate.length} sipariş güncellendi.`);
    } catch (err) {
        alert("Excel aktarımı başarısız: " + (err?.message || err));
    } finally {
        input.value = '';
    }
}


function handleImageUpload(el) {
    const file = el.files && el.files[0];
    if (!file) return;
    const uygula = (src) => {
        if (!src) return;
        currentImageBase64 = src;
        const img = document.getElementById('img-preview');
        const ph = document.getElementById('foto-placeholder');
        if (img) { img.src = currentImageBase64; img.style.display = ''; }
        if (ph) ph.style.display = 'none';
    };
    const sikistir = (typeof siparisFotoDosyaSikistir === 'function')
        ? siparisFotoDosyaSikistir
        : null;
    if (sikistir) {
        sikistir(file).then(src => {
            if (src) uygula(src);
            else {
                const reader = new FileReader();
                reader.onloadend = () => uygula(reader.result);
                reader.readAsDataURL(file);
            }
        }).catch(() => {
            const reader = new FileReader();
            reader.onloadend = () => uygula(reader.result);
            reader.readAsDataURL(file);
        });
        return;
    }
    const reader = new FileReader();
    reader.onloadend = () => uygula(reader.result);
    reader.readAsDataURL(file);
}

function siparisFotoLsOku(siparisId) {
    try {
        const raw = localStorage.getItem(SIPARIS_FOTO_LS_KEY);
        if (!raw) return [];
        const all = JSON.parse(raw);
        return siparisFotograflarFromRaw(all[String(siparisId)] || all[siparisId]);
    } catch (e) { return []; }
}

function siparisFotoLsKaydet(siparisId, list) {
    if (!siparisId || !list?.length) return;
    try {
        const raw = localStorage.getItem(SIPARIS_FOTO_LS_KEY);
        const all = raw ? JSON.parse(raw) : {};
        all[String(siparisId)] = list.map(x => ({ src: x.src, aciklama: x.aciklama || '' }));
        localStorage.setItem(SIPARIS_FOTO_LS_KEY, JSON.stringify(all));
    } catch (e) { console.warn('siparisFotoLsKaydet', e); }
}

function siparisFotoDosyaSikistirLegacy(file) {
    return new Promise((resolve) => {
        if (!file) { resolve(''); return; }
        const tip = String(file.type || '');
        if (tip && !tip.startsWith('image/')) { resolve(''); return; }
        const reader = new FileReader();
        reader.onload = () => {
            const img = new Image();
            img.onload = () => {
                let w = img.naturalWidth || img.width;
                let h = img.naturalHeight || img.height;
                const max = SIPARIS_FOTO_MAX_PX;
                if (w > max || h > max) {
                    if (w >= h) { h = Math.round(h * max / w); w = max; }
                    else { w = Math.round(w * max / h); h = max; }
                }
                const canvas = document.createElement('canvas');
                canvas.width = Math.max(1, w);
                canvas.height = Math.max(1, h);
                const ctx = canvas.getContext('2d');
                if (!ctx) { resolve(String(reader.result || '')); return; }
                ctx.drawImage(img, 0, 0, w, h);
                try { resolve(canvas.toDataURL('image/jpeg', SIPARIS_FOTO_JPEG_Q)); }
                catch (e) { resolve(String(reader.result || '')); }
            };
            img.onerror = () => resolve('');
            img.src = String(reader.result || '');
        };
        reader.onerror = () => resolve('');
        reader.readAsDataURL(file);
    });
}

async function siparisFotoDosyaSikistir(file) {
    if (!file) return '';
    const tip = String(file.type || '');
    if (tip && !tip.startsWith('image/') && !/\.(jpe?g|png|gif|webp|bmp|heic|heif)$/i.test(file.name || '')) return '';
    try {
        if (typeof createImageBitmap === 'function') {
            const bitmap = await createImageBitmap(file);
            let w = bitmap.width;
            let h = bitmap.height;
            const max = SIPARIS_FOTO_MAX_PX;
            let tw = w;
            let th = h;
            if (w > max || h > max) {
                if (w >= h) { tw = max; th = Math.round(h * max / w); }
                else { th = max; tw = Math.round(w * max / h); }
            }
            const canvas = document.createElement('canvas');
            canvas.width = Math.max(1, tw);
            canvas.height = Math.max(1, th);
            const ctx = canvas.getContext('2d', { alpha: false });
            if (!ctx) { bitmap.close?.(); return ''; }
            ctx.imageSmoothingQuality = 'medium';
            ctx.drawImage(bitmap, 0, 0, tw, th);
            bitmap.close?.();
            return canvas.toDataURL('image/jpeg', SIPARIS_FOTO_JPEG_Q);
        }
    } catch (e) { /* legacy */ }
    return siparisFotoDosyaSikistirLegacy(file);
}

function siparisFotoNormalizeItem(x) {
    if (typeof x === 'string') {
        const src = x.trim();
        return src ? { src, aciklama: '' } : null;
    }
    if (x && typeof x === 'object') {
        const src = String(x.src || x.url || x.data || '').trim();
        if (!src) return null;
        return { src, aciklama: String(x.aciklama || x.caption || '').trim() };
    }
    return null;
}

function siparisFotograflarFromRaw(raw) {
    if (raw == null || raw === '') return [];
    if (Array.isArray(raw)) {
        return raw.map(siparisFotoNormalizeItem).filter(Boolean);
    }
    if (typeof raw === 'object') {
        const one = siparisFotoNormalizeItem(raw);
        return one ? [one] : [];
    }
    const s = String(raw).trim();
    if (!s || s === '[object Object]') return [];
    try {
        const parsed = JSON.parse(s);
        return siparisFotograflarFromRaw(parsed);
    } catch (e) {}
    return s.startsWith('data:image/') ? [{ src: s, aciklama: '' }] : [];
}

/** Form belleği + kayıt fotograf alanından sipariş foto listesi */
function siparisFotografListesiAl(kayit) {
    const bellek = Array.isArray(siparisFotograflar) ? siparisFotograflar.filter(f => f?.src) : [];
    if (appMode === 'SIPARIS_GIRIS' && bellek.length) return bellek;
    if (editingId && kayit && String(kayit.id) === String(editingId) && bellek.length) return bellek;
    const db = siparisFotograflarFromRaw(siparisKayitFotoAlani(kayit));
    if (db.length) return db;
    const cached = kayit?.id ? siparisFotoLsOku(kayit.id) : [];
    if (cached.length) return cached;
    return bellek;
}

function siparisFotoSrcHttpMi(src) {
    return /^https?:\/\//i.test(String(src || '').trim());
}

function siparisFotoSrcDataUrlMi(src) {
    return /^data:image\//i.test(String(src || '').trim());
}

function siparisFotoDataUrlToBlob(dataUrl) {
    const s = String(dataUrl || '');
    const m = s.match(/^data:([^;]+);base64,(.+)$/i);
    if (!m) return null;
    try {
        const bin = atob(m[2]);
        const len = bin.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
        return new Blob([bytes], { type: m[1] || 'image/jpeg' });
    } catch (e) {
        return null;
    }
}

/** data:/blob → Storage public URL. Başarısızsa null (çağıran data URL tutar). */
async function siparisFotoStorageYukle(srcOrBlob, pathHint) {
    if (!sb?.storage?.from) return null;
    let blob = null;
    if (srcOrBlob instanceof Blob) blob = srcOrBlob;
    else if (siparisFotoSrcDataUrlMi(srcOrBlob)) blob = siparisFotoDataUrlToBlob(srcOrBlob);
    if (!blob || !blob.size) return null;
    const folder = String(pathHint || 'pending').replace(/[^\w\-./]/g, '_').slice(0, 80) || 'pending';
    const path = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2, 9)}.jpg`;
    try {
        const { error } = await sb.storage.from(SIPARIS_FOTO_BUCKET).upload(path, blob, {
            contentType: blob.type || 'image/jpeg',
            upsert: false,
            cacheControl: '31536000'
        });
        if (error) {
            if (!_siparisFotoStorageUyariVerildi) {
                _siparisFotoStorageUyariVerildi = true;
                console.warn('siparisFotoStorageYukle', error.message);
                erpToast('Foto Storage yüklenemedi (bucket/policy). SQL: siparis_foto_storage.sql — şimdilik yerel yedek kullanılıyor.', 'warn', 9000);
            }
            return null;
        }
        const { data } = sb.storage.from(SIPARIS_FOTO_BUCKET).getPublicUrl(path);
        return data?.publicUrl || null;
    } catch (e) {
        console.warn('siparisFotoStorageYukle', e?.message || e);
        return null;
    }
}

const KUMAS_FOTO_BUCKET = 'kumas-fotograflar';
let _kumasFotoStorageUyariVerildi = false;

/** data URL → Storage public URL. Başarısızsa null (çağıran base64'ü aynen tutar). */
async function kumasFotoStorageYukle(srcOrBlob, pathHint) {
    if (!sb?.storage?.from) return null;
    let blob = null;
    if (srcOrBlob instanceof Blob) blob = srcOrBlob;
    else if (siparisFotoSrcDataUrlMi(srcOrBlob)) blob = siparisFotoDataUrlToBlob(srcOrBlob);
    if (!blob || !blob.size) return null;
    const folder = String(pathHint || 'pending').replace(/[^\w\-./]/g, '_').slice(0, 80) || 'pending';
    const path = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2, 9)}.jpg`;
    try {
        const { error } = await sb.storage.from(KUMAS_FOTO_BUCKET).upload(path, blob, {
            contentType: blob.type || 'image/jpeg',
            upsert: false,
            cacheControl: '31536000'
        });
        if (error) {
            if (!_kumasFotoStorageUyariVerildi) {
                _kumasFotoStorageUyariVerildi = true;
                console.warn('kumasFotoStorageYukle', error.message);
                erpToast('Foto Storage yüklenemedi (bucket/policy). SQL: kumas_foto_storage.sql — şimdilik veritabanına gömülü kaydediliyor.', 'warn', 9000);
            }
            return null;
        }
        const { data } = sb.storage.from(KUMAS_FOTO_BUCKET).getPublicUrl(path);
        return data?.publicUrl || null;
    } catch (e) {
        console.warn('kumasFotoStorageYukle', e?.message || e);
        return null;
    }
}
window.kumasFotoStorageYukle = kumasFotoStorageYukle;

/** Kayıt öncesi: data URL'leri Storage'a taşı; HTTP URL'leri olduğu gibi bırak. */
async function siparisFotograflariStorageHazirla(list, siparisIdHint) {
    const arr = Array.isArray(list) ? list : [];
    if (!arr.length) return arr;
    const hint = siparisIdHint ? `siparis/${siparisIdHint}` : `pending/${Date.now()}`;
    const out = await Promise.all(arr.map(async (f) => {
        const src = String(f?.src || '').trim();
        const aciklama = String(f?.aciklama || '').trim();
        if (!src) return null;
        if (siparisFotoSrcHttpMi(src)) return { src, aciklama };
        if (!siparisFotoSrcDataUrlMi(src)) return { src, aciklama };
        const url = await siparisFotoStorageYukle(src, hint);
        return { src: url || src, aciklama };
    }));
    return out.filter(Boolean);
}

/** Supabase jsonb kolonuna yazılacak dizi */
function siparisFotografDbDeger(list) {
    const arr = (list || [])
        .map(x => ({ src: String(x?.src || ''), aciklama: String(x?.aciklama || '').trim() }))
        .filter(x => x.src);
    if (!arr.length) return null;
    if (JSON.stringify(arr).length > 4_500_000) {
        erpToast('Fotoğraflar çok büyük; daha az veya daha küçük görsel deneyin.', 'error', 7000);
        return null;
    }
    return arr;
}

/** DB boş kalan siparişlerde cihazdaki foto yedegini önbelleğe yansıt */
function siparisFotoLsCacheBirlestir() {
    for (const s of (dataCache.siparisler || [])) {
        if (!s?.id || siparisFotograflarFromRaw(siparisKayitFotoAlani(s)).length) continue;
        const ls = siparisFotoLsOku(s.id);
        if (ls.length) s[SIPARIS_FOTO_DB_COL] = ls;
    }
}


function siparisFotografHtmlGrid(rawOrList, opts) {
    opts = opts || {};
    const list = Array.isArray(rawOrList) ? rawOrList : siparisFotograflarFromRaw(rawOrList);
    if (!list.length) return opts.emptyHtml || '';
    const minW = opts.minW || 160;
    const imgH = opts.imgH || 150;
    return '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(' + minW + 'px,1fr));gap:10px">' +
        list.map((f, idx) => '<div style="border:1px solid var(--border);border-radius:10px;overflow:hidden;background:var(--surface2)">' +
            '<img src="' + f.src + '" alt="Foto ' + (idx + 1) + '" style="width:100%;height:' + imgH + 'px;object-fit:cover;display:block">' +
            (String(f.aciklama || '').trim() ? '<div style="padding:8px 10px;font-size:10px;color:var(--text2);line-height:1.35">' + pdfEsc(f.aciklama) + '</div>' : '') +
        '</div>').join('') + '</div>';
}

function siparisFotograflarSerialize(list) {
    const arr = siparisFotografDbDeger(list);
    return arr ? JSON.stringify(arr) : '';
}

function siparisFotoKayitSonrasiOnbellek(siparisId, fotolar) {
    if (!siparisId || !fotolar?.length) return;
    const idx = (dataCache.siparisler || []).findIndex(s => String(s.id) === String(siparisId));
    if (idx !== -1) dataCache.siparisler[idx][SIPARIS_FOTO_DB_COL] = fotolar;
}

/* ── SİPARİŞE FOTOĞRAF EKLE (açıklamalı) ─────────────────────────────────
   Kullanıcı, 24.09.2026: "mobilden siparişe foto ekleyebilelim, açıklamasıyla
   birlikte — ama yalnız izin verilen kullanıcılar". Yetki: SIPARIS_FOTO_EKLE
   (yönetici her zaman). Masaüstü ve mobil AYNI fonksiyonu kullanır.
   - Fotoğraf önce Storage'a (siparis-fotograflar) yüklenir; yüklenemezse KAYIT
     YAPILMAZ (veritabanına base64 gömülmez).
   - Mevcut fotoğraflar veritabanından TAZE okunur ve yenisi SONA eklenir —
     başka cihazın az önce eklediği fotoğraf silinmez.
   - Kim / ne zaman / hangi açıklamayla eklediği sipariş geçmişine (islem_gecmisi) yazılır.
   Mobil salt okunur kapısı yalnız bu işlem sürerken (window.__erpSiparisFotoYazma)
   ve yalnız bu alanları yazan güncellemeye izin verir (assets/mobil/mobil-app.js). */
const SIPARIS_FOTO_EKLE_ALANLAR = ['siparis_fotograflar', 'islem_gecmisi', 'updated_by', 'updated_at'];
let _siparisFotoEkleSecilen = [];
let _siparisFotoEkleSid = null;
let _siparisFotoEkleDetaydan = false;

function siparisFotoEkleYetkiliMi() {
    return typeof erpUserCan === 'function' && erpUserCan('SIPARIS_FOTO_EKLE');
}

function siparisFotoEkleKaldir() {
    const ov = document.getElementById('siparis-foto-ekle-modal');
    if (ov) ov.remove();
    document.removeEventListener('keydown', siparisFotoEkleEsc);
    _siparisFotoEkleSecilen.forEach(x => { try { URL.revokeObjectURL(x.onizleme); } catch (e) {} });
    _siparisFotoEkleSecilen = [];
    _siparisFotoEkleSid = null;
}
function siparisFotoEkleEsc(e) { if (e && e.key === 'Escape') siparisFotoEkleKaldir(); }

function siparisFotoEkleAc(siparisId) {
    if (!siparisFotoEkleYetkiliMi()) { erpToast('Siparişe fotoğraf ekleme yetkiniz yok.', 'error'); return; }
    const sip = (dataCache.siparisler || []).find(s => String(s.id) === String(siparisId));
    if (!sip) { erpToast('Sipariş bulunamadı.', 'error'); return; }
    siparisFotoEkleKaldir();
    _siparisFotoEkleSid = sip.id;
    _siparisFotoEkleDetaydan = document.getElementById('detail-modal')?.style.display === 'flex';
    const ov = document.createElement('div');
    ov.id = 'siparis-foto-ekle-modal';
    ov.style.cssText = 'position:fixed;inset:0;z-index:9100;background:rgba(2,6,23,0.62);display:flex;align-items:center;justify-content:center;padding:12px';
    ov.addEventListener('click', (e) => { if (e.target === ov) siparisFotoEkleKaldir(); });
    ov.innerHTML = `
    <div style="width:100%;max-width:520px;max-height:92vh;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--border);border-radius:14px;overflow:hidden;box-shadow:0 20px 50px rgba(0,0,0,.35)">
        <div style="display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--border)">
            <div style="flex:1;min-width:0">
                <div style="font-size:13px;font-weight:800;color:var(--text)">📷 Fotoğraf ekle</div>
                <div style="font-size:10px;color:var(--text3)">${pdfEsc(sip.sno || '')} · ${pdfEsc(sip.firma || '')}</div>
            </div>
            <button type="button" class="btn-pro btn-ghost-pro" onclick="siparisFotoEkleKaldir()" style="padding:6px 10px;font-size:11px">✕ Kapat</button>
        </div>
        <div style="padding:12px 14px;overflow:auto;-webkit-overflow-scrolling:touch;flex:1">
            <label style="display:flex;align-items:center;justify-content:center;gap:8px;padding:14px;border:2px dashed var(--border);border-radius:12px;cursor:pointer;font-size:12px;font-weight:700;color:var(--cyan-c)">
                ➕ Fotoğraf seç / çek
                <input id="siparis-foto-ekle-input" type="file" accept="image/*" multiple style="display:none" onchange="siparisFotoEkleSecildi(this)">
            </label>
            <div style="font-size:10px;color:var(--text3);margin:8px 2px 10px;line-height:1.4">Her fotoğrafın altına ne olduğunu yazın (ör. "etiket yeri", "renk farkı"). Fotoğraflar siparişe eklenir, mevcutlar silinmez.</div>
            <div id="siparis-foto-ekle-liste" style="display:flex;flex-direction:column;gap:10px"></div>
        </div>
        <div style="display:flex;gap:8px;padding:12px 14px;border-top:1px solid var(--border)">
            <button type="button" class="btn-pro btn-ghost-pro" onclick="siparisFotoEkleKaldir()" style="flex:1;justify-content:center">Vazgeç</button>
            <button type="button" id="siparis-foto-ekle-kaydet" class="btn-pro btn-primary-pro" onclick="siparisFotoEkleKaydet()" style="flex:2;justify-content:center" disabled>Kaydet</button>
        </div>
    </div>`;
    document.body.appendChild(ov);
    document.addEventListener('keydown', siparisFotoEkleEsc);
}

function siparisFotoEkleListeCiz() {
    const host = document.getElementById('siparis-foto-ekle-liste');
    const btn = document.getElementById('siparis-foto-ekle-kaydet');
    if (btn) {
        btn.disabled = !_siparisFotoEkleSecilen.length;
        btn.textContent = _siparisFotoEkleSecilen.length ? `Kaydet (${_siparisFotoEkleSecilen.length} fotoğraf)` : 'Kaydet';
    }
    if (!host) return;
    host.innerHTML = _siparisFotoEkleSecilen.map((x, n) => `
        <div style="display:flex;gap:10px;align-items:flex-start;border:1px solid var(--border);border-radius:10px;padding:8px;background:var(--surface2)">
            <img src="${x.onizleme}" alt="" style="width:72px;height:72px;object-fit:cover;border-radius:8px;flex-shrink:0">
            <textarea rows="3" placeholder="Açıklama" oninput="siparisFotoEkleAciklama(${n}, this.value)" style="flex:1;min-width:0;resize:vertical;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:7px 9px;font-size:12px;color:var(--text)">${pdfEsc(x.aciklama)}</textarea>
            <button type="button" onclick="siparisFotoEkleCikar(${n})" title="Çıkar" style="border:none;background:none;color:var(--rose-c);font-size:16px;cursor:pointer;padding:2px 4px">✕</button>
        </div>`).join('');
}

function siparisFotoEkleSecildi(input) {
    const dosyalar = [...(input?.files || [])].filter(f => /^image\//.test(f.type || '') || /\.(jpe?g|png|gif|webp|heic|heif)$/i.test(f.name || ''));
    dosyalar.forEach(f => _siparisFotoEkleSecilen.push({ dosya: f, onizleme: URL.createObjectURL(f), aciklama: '' }));
    if (input) input.value = '';
    siparisFotoEkleListeCiz();
}
function siparisFotoEkleAciklama(n, deger) {
    if (_siparisFotoEkleSecilen[n]) _siparisFotoEkleSecilen[n].aciklama = String(deger || '');
}
function siparisFotoEkleCikar(n) {
    const x = _siparisFotoEkleSecilen[n];
    if (x) { try { URL.revokeObjectURL(x.onizleme); } catch (e) {} }
    _siparisFotoEkleSecilen.splice(n, 1);
    siparisFotoEkleListeCiz();
}

async function siparisFotoEkleKaydet() {
    if (!siparisFotoEkleYetkiliMi()) { erpToast('Siparişe fotoğraf ekleme yetkiniz yok.', 'error'); return; }
    const sid = _siparisFotoEkleSid;
    const secilen = _siparisFotoEkleSecilen.slice();
    if (!sid || !secilen.length) return;
    const btn = document.getElementById('siparis-foto-ekle-kaydet');
    const btnYaz = (t) => { if (btn) { btn.disabled = true; btn.textContent = t; } };
    const user = String((typeof erpCurrentUser !== 'undefined' && (erpCurrentUser?.display_name || erpCurrentUser?.username)) || '').trim() || '—';
    window.__erpSiparisFotoYazma = true;
    try {
        const eklenenler = [];
        for (let n = 0; n < secilen.length; n++) {
            btnYaz(`Yükleniyor ${n + 1}/${secilen.length}…`);
            const dataUrl = await siparisFotoDosyaSikistir(secilen[n].dosya);
            if (!dataUrl) throw new Error(`${n + 1}. dosya okunamadı (resim değil ya da bozuk).`);
            const url = await siparisFotoStorageYukle(dataUrl, `siparis/${sid}`);
            if (!url) throw new Error(`${n + 1}. fotoğraf sunucuya yüklenemedi — bağlantıyı kontrol edip tekrar deneyin.`);
            eklenenler.push({ src: url, aciklama: String(secilen[n].aciklama || '').trim() });
        }
        btnYaz('Kaydediliyor…');
        const { data: sip, error: e0 } = await sb.from('siparisler')
            .select('id,sno,siparis_fotograflar,islem_gecmisi').eq('id', sid).single();
        if (e0) throw e0;
        const tumu = siparisFotograflarFromRaw(sip.siparis_fotograflar).concat(eklenenler);
        const dbDeger = siparisFotografDbDeger(tumu);
        if (!dbDeger) throw new Error('Fotoğraf listesi kaydedilemedi.');
        const zaman = new Date().toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' });
        const yer = window.ERP_MOBIL_LITE ? 'Mobil' : 'Masaüstü';
        const gecmis = String(sip.islem_gecmisi || '')
            + `\n═══════════════════════════════\n📷 ${zaman} — [${user}] ${yer} · ${eklenenler.length} fotoğraf eklendi`
            + eklenenler.map((f, n) => `\n  • Fotoğraf ${n + 1}: ${f.aciklama ? `"${f.aciklama}"` : '(açıklama yok)'}`).join('');
        const yama = { siparis_fotograflar: dbDeger, islem_gecmisi: gecmis, updated_by: user, updated_at: new Date().toISOString() };
        const { error } = await sb.from('siparisler').update(yama).eq('id', sid);
        if (error) throw error;

        const yerel = (dataCache.siparisler || []).find(x => String(x.id) === String(sid));
        if (yerel) Object.assign(yerel, yama);
        try {
            /* Liste canlı senkronla arkada yeniden çizilmiş olabilir — currentData[selectedIndex]
               artık başka sipariş olabilir; yalnız aynı kayıtsa ona yaz. Detay ise her hâlde
               bu siparişi gösteriyor (düğme o detaydan açıldı), onu yenile. */
            const acik = (typeof currentData !== 'undefined' && typeof selectedIndex !== 'undefined') ? currentData?.[selectedIndex] : null;
            const ayni = acik && String(acik.id) === String(sid);
            if (ayni) Object.assign(acik, yama);
            if (_siparisFotoEkleDetaydan && (ayni || yerel)) siparisFotoEkleDetayYenile(ayni ? acik : yerel);
        } catch (e) {}
        siparisFotoEkleKaldir();
        erpToast(`${sip.sno || 'Sipariş'}: ${eklenenler.length} fotoğraf eklendi.`, 'success');
    } catch (e) {
        erpToast('Fotoğraf eklenemedi: ' + (e?.message || e), 'error', 7000);
        if (btn) { btn.disabled = false; btn.textContent = `Kaydet (${secilen.length} fotoğraf)`; }
    } finally {
        window.__erpSiparisFotoYazma = false;
    }
}

/** Açık sipariş penceresini yeni fotoğraflarla yeniden çizer (açık sekmeyi korur). */
function siparisFotoEkleDetayYenile(i) {
    const modal = document.getElementById('detail-modal');
    const body = document.getElementById('modal-body');
    if (!modal || modal.style.display !== 'flex' || !body || typeof buildSiparisDetailModalHtml !== 'function') return;
    if (typeof siparisDetailModalAcikSekme === 'function' && siparisDetailModalAcikSekme() === 'durum') {
        const oz = document.getElementById('siparis-modal-tab-ozet');
        if (oz) oz.innerHTML = buildSiparisDetailModalHtml(i, { embedKonf: true });
        return;
    }
    body.innerHTML = buildSiparisDetailModalHtml(i);
    if (typeof siparisDetailModalBaslatDurumTab === 'function') siparisDetailModalBaslatDurumTab(i);
}

function siparisFotoDropOver(e) {
    e.preventDefault();
    e.stopPropagation();
    const z = document.getElementById('siparis-foto-drop');
    if (z) {
        z.style.borderColor = 'var(--cyan-c)';
        z.style.background = 'rgba(34,211,238,0.12)';
    }
}
function siparisFotoDropLeave(e) {
    e.preventDefault();
    e.stopPropagation();
    const z = document.getElementById('siparis-foto-drop');
    if (z) {
        z.style.borderColor = 'rgba(34,211,238,0.4)';
        z.style.background = 'rgba(255,255,255,0.25)';
    }
}
function siparisFotoDrop(e) {
    e.preventDefault();
    e.stopPropagation();
    siparisFotoDropLeave(e);
    const files = Array.from(e.dataTransfer?.files || []).filter(f => String(f.type || '').startsWith('image/') || /\.(jpe?g|png|gif|webp|bmp)$/i.test(f.name || ''));
    if (!files.length) {
        erpToast('Sürüklenen dosyada görsel yok.', 'warn', 2500);
        return;
    }
    siparisFotoUploadFromFiles(files);
}

function siparisFotoRenderList() {
    const host = document.getElementById('siparis-foto-list');
    const countEl = document.getElementById('siparis-foto-sayi');
    if (!host) return;
    const list = Array.isArray(siparisFotograflar) ? siparisFotograflar : [];
    if (countEl) countEl.textContent = `${list.length} görsel`;
    if (!list.length) {
        host.innerHTML = `<div style="padding:10px;border:1px dashed rgba(34,211,238,0.3);border-radius:10px;font-size:10px;color:var(--text3);line-height:1.45">Henüz görsel eklenmedi.<br><span style="font-size:9px;opacity:.85">Görsel zorunlu değildir; yazılı not yeterliyse kaydedebilirsiniz.</span></div>`;
        return;
    }
    host.innerHTML = list.map((f, i) => `
        <div style="display:grid;grid-template-columns:70px 1fr auto;gap:8px;align-items:center;padding:8px;border:1px solid rgba(34,211,238,0.25);border-radius:10px;background:var(--surface2)">
            <img src="${f.src}" alt="Not görseli" style="width:70px;height:70px;object-fit:cover;border-radius:8px;border:1px solid var(--border)">
            <input class="pro-input" value="${pdfEsc(f.aciklama || '')}" placeholder="Görsel açıklaması (opsiyonel)…" oninput="siparisFotoAciklamaGuncelle(${i}, this.value)" style="padding:7px 9px;font-size:10px">
            <button type="button" onclick="siparisFotoSil(${i})" class="btn-pro btn-danger-pro" style="padding:6px 9px;font-size:10px">Sil</button>
        </div>
    `).join('');
}

function siparisFotoAciklamaGuncelle(idx, val) {
    if (!Array.isArray(siparisFotograflar) || !siparisFotograflar[idx]) return;
    siparisFotograflar[idx].aciklama = String(val || '');
    updateSiparisPreview();
}

function siparisFotoSil(idx) {
    if (!Array.isArray(siparisFotograflar)) return;
    siparisFotograflar = siparisFotograflar.filter((_, i) => i !== idx);
    siparisFotoRenderList();
    updateSiparisPreview();
}

function siparisFotoUpload(el) {
    const files = Array.from(el?.files || []);
    try { if (el) el.value = ''; } catch (e) {}
    if (!files.length) return;
    siparisFotoUploadFromFiles(files);
}

function siparisFotoUploadFromFiles(files) {
    const list = Array.from(files || []).filter(Boolean);
    if (!list.length) return;
    if (!Array.isArray(siparisFotograflar)) siparisFotograflar = [];
    const total = list.length;
    let done = 0;
    let okCount = 0;
    const busyId = 'siparis-foto-busy-' + Date.now();
    const host = document.getElementById('siparis-foto-list');
    if (host) {
        host.insertAdjacentHTML('beforeend', `<div id="${busyId}" style="padding:8px;font-size:10px;color:var(--accent2);text-align:center">Görsel hazırlanıyor 0/${total}…</div>`);
    }
    const tasks = list.map(file => siparisFotoDosyaSikistir(file).then(async (src) => {
        done++;
        const busy = document.getElementById(busyId);
        if (busy) busy.textContent = `Görsel hazırlanıyor ${done}/${total}…`;
        if (!src) return '';
        const idx = siparisFotograflar.push({ src, aciklama: '' }) - 1;
        okCount++;
        const hint = editingId ? `siparis/${editingId}` : `pending/${(document.getElementById('val-sno')?.value || 'yeni').replace(/[^\w-]/g, '')}`;
        siparisFotoStorageYukle(src, hint).then(url => {
            if (url && siparisFotograflar[idx] && siparisFotograflar[idx].src === src) {
                siparisFotograflar[idx].src = url;
                try { siparisFotoRenderList(); updateSiparisPreview(); } catch (e) {}
            }
        }).catch(() => {});
        return src;
    }).catch(() => {
        done++;
        return '';
    }));
    siparisFotoOkumaPromise = Promise.resolve(siparisFotoOkumaPromise).catch(() => {}).then(() => Promise.all(tasks)).then(() => {
        document.getElementById(busyId)?.remove();
        if (okCount) {
            siparisFotoRenderList();
            try { updateSiparisPreview(); } catch (e) { console.warn('updateSiparisPreview', e); }
            erpToast(okCount === 1 ? 'Görsel eklendi.' : `${okCount} görsel eklendi.`, 'success', 2800);
        }
        if (okCount < total) {
            erpToast(`${total - okCount} görsel işlenemedi. JPG/PNG deneyin.`, 'warn', 5000);
        }
    }).catch(err => {
        document.getElementById(busyId)?.remove();
        console.error(err);
        erpToast('Görsel eklenirken hata: ' + (err?.message || err), 'error', 5000);
    });
}

function erpParseExcelNumberExpr(raw) {
    const s = String(raw ?? '').trim();
    if (!s) return null;
    // Excel benzeri: 20+20+50+... (bosluklari ve virgulu tolere et)
    if (!s.includes('+')) {
        const v = parseFloat(s.replaceAll(',', '.'));
        return Number.isFinite(v) ? v : null;
    }
    const parts = s
        .split('+')
        .map(x => x.trim())
        .filter(Boolean);
    if (!parts.length) return null;
    let sum = 0;
    let any = false;
    for (const p of parts) {
        const v = parseFloat(p.replaceAll(',', '.'));
        if (!Number.isFinite(v)) continue;
        sum += v;
        any = true;
    }
    return any ? sum : null;
}

function erpNormalizeExcelNumberInput(el) {
    if (!el || typeof el.value !== 'string') return;
    const raw = String(el.value || '').trim();
    if (!raw) return;
    if (!raw.includes('+')) return;
    const v = erpParseExcelNumberExpr(raw);
    if (v == null) return;
    // type=number input'lar artı işaretini kabul etmediği için sonucu yazıyoruz
    el.value = String(v);
    try { el.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {}
    try { el.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
}

// type=number alanlarda "+" yazılamadığı için fokus sırasında text'e çevirip
// blur'da sonucu hesaplayıp tekrar number'a döndürürüz.
document.addEventListener('focusin', (e) => {
    const el = e?.target;
    if (!el) return;
    const tag = String(el.tagName || '').toUpperCase();
    if (tag !== 'INPUT') return;
    const type = String(el.getAttribute('type') || '').toLowerCase();
    if (type !== 'number') return;
    try {
        el.dataset.erpExcelWasNumber = '1';
        el.setAttribute('type', 'text');
        el.setAttribute('inputmode', 'decimal');
        // mobil/IME için: number klavyesi + serbest karakter
    } catch (x) {}
}, true);

document.addEventListener('focusout', (e) => {
    const el = e?.target;
    if (!el) return;
    const tag = String(el.tagName || '').toUpperCase();
    if (tag !== 'INPUT') return;
    const type = String(el.getAttribute('type') || '').toLowerCase();
    // Sayısal giriş alanlarında (number dahil) excel toplama desteği
    if (type === 'number' || type === 'text' || type === '') {
        erpNormalizeExcelNumberInput(el);
    }
    // focusin'de number->text yaptıysak geri al
    try {
        if (el.dataset && el.dataset.erpExcelWasNumber === '1') {
            delete el.dataset.erpExcelWasNumber;
            el.setAttribute('type', 'number');
            el.removeAttribute('inputmode');
        }
    } catch (x) {}
}, true);

document.addEventListener('keydown', (e) => {
    if (!e || e.key !== 'Enter') return;
    const el = e.target;
    if (!el) return;
    const tag = String(el.tagName || '').toUpperCase();
    // textarea'da Enter yeni satır olmalı
    if (tag === 'TEXTAREA') return;
    if (tag !== 'INPUT' && tag !== 'SELECT') return;
    // Önce varsa expression'ı normalize et
    if (tag === 'INPUT') erpNormalizeExcelNumberInput(el);
    // İstek: Enter ile otomatik kayıt yok. Sadece Kaydet butonu ile kayıt.
}, true);

